#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit register from the ADS1115
int16_t read_ads1115_register(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cWriteByteData(handle, reg, 0) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115_register(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read the current from the MLX91219 sensor
float read_current(int handle)
{
    uint16_t raw_value = read_ads1115_register(handle, ADS1115_REG_CONVERT);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading raw value from ADS1115\n");
        return -1.0;
    }

    // Convert raw value to voltage (assuming PGA ±4.096V)
    float voltage = (float)raw_value * 4.096 / 32768.0;

    // Convert voltage to current (MLX91219 sensitivity: 40mV/A)
    float current = voltage / 0.040;

    return current;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        float current = read_current(i2c_handle);
        if (current >= 0) {
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }
        gpioDelay(500); // Wait 500ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

