#include <unistd.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_I2C_BUS 1
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_GAIN_4_096 0x0003
#define ADS1115_SINGLE_SHOT 0x8000
#define ADS1115_DATA_RATE_128 0x0080
#define ADS1115_VREF 3.3
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY 50 // milliseconds
#define BUZZER_DURATION 2000 // milliseconds

