    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(ADS1115_I2C_BUS, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    uint16_t config = ADS1115_SINGLE_SHOT | ADS1115_GAIN_4_096 | ADS1115_DATA_RATE_128;
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "ADS1115 configuration failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read ADS1115
int read_ads1115(int16_t *value) {
    char buf[1];
    buf[0] = ADS1115_CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "ADS1115 write conversion register failed: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "ADS1115 read conversion failed: %d\n", result);
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

