int read_flame_sensor() {
    static uint32_t last_debounce_time = 0;
    int current_time = gpioTick();

    if (gpioRead(FLAME_SENSOR_GPIO) == 0) { // Flame detected (LOW signal)
        if (current_time - last_debounce_time > DEBOUNCE_DELAY * 1000) { // Debounce
            last_debounce_time = current_time;
            return 1; // Flame detected
        }
    }
    return 0; // No flame detected
