    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL);

    int16_t raw_temperature;
    float temperature;
    int flame_detected;

    // Main loop
    while (running) {
        // Read flame sensor
        flame_detected = read_flame_sensor();

        // Read temperature
        if (read_ads1115(&raw_temperature) == 0) {
            temperature = convert_to_temperature(raw_temperature);
        } else {
            temperature = -100.0; // Indicate error
        }

        // Check for events
        if (flame_detected && temperature > TEMPERATURE_THRESHOLD) {
            log_event("Flame and temperature above threshold!");
            activate_buzzer();
            gpioDelay(BUZZER_DURATION);
            deactivate_buzzer();
        } else if (flame_detected) {
            log_event("Flame detected!");
        } else if (temperature > TEMPERATURE_THRESHOLD) {
            char temp_str[50];
            snprintf(temp_str, sizeof(temp_str), "Temperature: %.2f°C", temperature);
            log_event(temp_str);
        }

        gpioDelay(100); // 100ms delay
    }

    return 0;
}

