        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC to voltage conversion function
double adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Voltage to current conversion function
double voltage_to_current(double voltage) {
    return voltage / sensitivity;
}

// Fan control function
void control_fan(double current) {
    if (current > threshold) {
        gpio_set_value(gpio_line, 1); // Turn fan ON
    } else {
        gpio_set_value(gpio_line, 0); // Turn fan OFF
    }
}

// Data logging function
void log_data(double current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.3f A\n", timestamp, current);
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// GPIO initialization function
int gpio_init(const char *chip_name, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "current_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// GPIO close function
void gpio_close(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP_NAME, GPIO_PIN) < 0) {
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t tx_buf[3] = {0x01, 0x80, 0x00}; // MCP3008 single-ended channel 0
        uint8_t rx_buf[3];
        int adc_value;

        // Perform SPI transfer
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Extract ADC value
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Check for sensor absence (all-zero or all-ones)
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or ADC reading invalid, skipping...\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to voltage and current
        double voltage = adc_to_voltage(adc_value);
        double current = voltage_to_current(voltage);

        // Control the fan
        control_fan(current);

        // Log the data
        log_data(current);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    gpio_set_value(gpio_line, 0); // Turn fan OFF
    gpio_close(gpio_chip, gpio_line);
    close(spi_fd);

    return 0;
}

