// Configuration
#define I2C_BUS 1
#define IMP23ABSU_ADDR_1 0x48
#define IMP23ABSU_ADDR_2 0x49
#define SAMPLE_INTERVAL_MS 100
#define SENSITIVITY_DBV_PA -38.0
#define REFERENCE_PRESSURE_PA 20e-6
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_value;
    float sound_pressure_level;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_imp23absu(int i2c_handle, int address);
float calculate_sound_pressure(int16_t raw_value);
void log_data(float avg_db);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, IMP23ABSU_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", IMP23ABSU_ADDR_1, i2c_handle_1);
        return -1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, IMP23ABSU_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", IMP23ABSU_ADDR_2, i2c_handle_2);
        i2cClose(i2c_handle_1);
        return -1;
    }

    return 0;
}

// Read data from IMP23ABSU sensor
int read_imp23absu(int i2c_handle, int address) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device at address 0x%02x: %d\n", address, result);
        return -999; // Error value
    }

    int16_t raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Calculate sound pressure level in dB
float calculate_sound_pressure(int16_t raw_value) {
    float voltage = (float)raw_value / 32767.0 * 3.3; // Assuming 16-bit ADC and 3.3V reference
    float pressure = voltage / 20e-6; // Convert voltage to pressure (assuming 20e-6 Pa = 1V)
    float db = 20 * log10(pressure / 1e-6); // Convert pressure to dB
    return db;
}

// Log data to file
void log_data(float avg_db) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, avg_db);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file, exiting\n");
        cleanup();
        return 1;
    }

    printf("Acoustic leak detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_value_1 = read_imp23absu(i2c_handle_1, IMP23ABSU_ADDR_1);
        int16_t raw_value_2 = read_imp23absu(i2c_handle_2, IMP23ABSU_ADDR_2);

        float sound_pressure_1 = 0.0;
        float sound_pressure_2 = 0.0;

        if (raw_value_1 != -999) {
            sound_pressure_1 = calculate_sound_pressure(raw_value_1);
        } else {
            fprintf(stderr, "Error reading sensor 1, using -999.0 dB\n");
        }

        if (raw_value_2 != -999) {
            sound_pressure_2 = calculate_sound_pressure(raw_value_2);
        } else {
            fprintf(stderr, "Error reading sensor 2, using -999.0 dB\n");
        }

        float avg_db = (sound_pressure_1 + sound_pressure_2) / 2.0;

        log_data(avg_db);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    cleanup();
    return 0;
}

