#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 0.7
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_MS 100
#define NUM_SAMPLES (WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS)
#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float calculate_rms(int *samples, int num_samples);
void log_data(float mic1_rms, float mic2_rms);
void control_led(int on);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int led_gpio;
    float rms_threshold;
    int sample_interval_ms;
    int window_duration_ms;
    int num_samples;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    LED_GPIO,
    RMS_THRESHOLD,
    SAMPLE_INTERVAL_MS,
    WINDOW_DURATION_MS,
    NUM_SAMPLES
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        spiClose(spi_handle);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int mic1_samples[NUM_SAMPLES];
        int mic2_samples[NUM_SAMPLES];
        float mic1_rms, mic2_rms;

        // Read microphone samples
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_mcp3008(ADC_CHANNEL_0);
            mic2_samples[i] = read_mcp3008(ADC_CHANNEL_1);
            gpioDelay(config.sample_interval_ms * 1000); // Delay for 1ms
        }

        // Calculate RMS values
        mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Check for threshold exceedance
        if (mic1_rms > config.rms_threshold || mic2_rms > config.rms_threshold) {
            control_led(1); // Turn on LED
            gpioDelay(500000); // Delay for 500ms
            control_led(0); // Turn off LED
        }

        // Log data
        log_data(mic1_rms, mic2_rms);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// Initialize SPI
int initialize_spi() {
