#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_LED 17
#define OVERCURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *value) {
    char config[3];
    char convert[2];
    int result;

    // Configure ADS1115 for single-ended A0, +/- 4.096V, continuous conversion, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x43; // 0b01000011 (Single-shot mode, A0, +/-4.096V, 128 SPS)
    config[2] = 0x83; // 0b10000011 (Start single conversion)

    result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    convert[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, convert, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, convert, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *value = (int16_t)((convert[0] << 8) | convert[1]);
    return 0;
}

// Convert raw ADC value to current (A)
float convert_to_current(int16_t raw_value) {
    // Assuming ADS1115 gain is 1 (±4.096V), and 12-bit resolution
    float voltage = (float)raw_value / 32767.0 * 4.096; // 2^12 = 4096, but ADS1115 is 12-bit
    return (voltage - 0.5) / 4.0 * 100.0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the LED based on the average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);   // Close I2C connection
    gpioTerminate();        // Terminate pigpio
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        // Read sensor value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to current
            current = convert_to_current(raw_value);

            // Add to circular buffer
            add_to_buffer(&current_buffer, current);

            // Calculate average current
            average_current = calculate_average(&current_buffer);

            // Control LED
            control_led(average_current);

            printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay to achieve 10Hz sampling rate
        gpioDelay(100000); // 100ms = 10Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

