// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_color_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_color_data(FILE *log_file, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// TCS34725 initialization function
int tcs34725_init(int i2c_handle) {
    // Enable power and ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01 | 0x02) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set gain (CONTROL)
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
int tcs34725_read_color_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data\n");
        return -1;
    }

    *clear = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];
    *red   = (uint16_t)buffer[3] << 8 | (uint16_t)buffer[2];
    *green = (uint16_t)buffer[5] << 8 | (uint16_t)buffer[4];
    *blue  = (uint16_t)buffer[7] << 8 | (uint16_t)buffer[6];

    return 0;
}

// Function to log color data to a CSV file
int log_color_data(FILE *log_file, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

