    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handler for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t clear, red, green, blue;
    int read_attempts = 0;
    while (!terminate) {
        if (tcs34725_read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_color_data(log_file, clear, red, green, blue);
            read_attempts = 0; // Reset attempts on success
        } else {
            read_attempts++;
