#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define PRESSURE_REG 0x00 // Example register address, adjust as needed
#define TEMP_REG 0x02 // Example register address, adjust as needed
#define GPIO_WARNING_LED 17
#define PRESSURE_THRESHOLD 105.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} SensorData;

// Function prototypes
int init_i2c();
int read_ads1115(int reg);
float convert_pressure(int adc_value);
float convert_temperature(int adc_value);
void display_data(SensorData data);
void control_warning_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from ADS1115 with retry
int read_ads1115(int reg) {
    int handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error re-opening I2C for read: %d\n", handle);
        return -1;
    }
    int retries = 0;
    int adc_value = -1;
    while (retries < RETRY_COUNT) {
        adc_value = i2cReadWordData(handle, reg);
        if (adc_value >= 0) {
            i2cClose(handle);
            return adc_value;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retry %d\n", reg, retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "Failed to read from ADS1115 after %d retries (reg 0x%02X)\n", RETRY_COUNT, reg);
    i2cClose(handle);
    return -1;
}

// Function to convert ADC value to pressure (kPa)
float convert_pressure(int adc_value) {
    // Assuming ADS1115 is configured for ±6.144V and single-ended AIN0
    // and the MLX90834 is connected to AIN0.
    // Linear transfer function: 0V = 0 kPa, 5V = 400 kPa
    float voltage = (float)adc_value * 6.144 / 32767.0; // Assuming 16-bit ADC
    return voltage * 400.0;
}

// Function to convert ADC value to temperature (Celsius)
float convert_temperature(int adc_value) {
    // Simplified NTC approximation: 1V = 0°C, 2V = 100°C
    // Assuming ADS1115 is configured for ±6.144V and single-ended AIN1
    float voltage = (float)adc_value * 6.144 / 32767.0; // Assuming 16-bit ADC
    return (voltage - 1.0) * 100.0; // Linear approximation
}

// Function to display pressure and temperature
void display_data(SensorData data) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", data.pressure_kPa, data.temperature_C);
}

// Function to control the warning LED
void control_warning_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_WARNING_LED, 1); // Set HIGH
    } else {
        gpioWrite(GPIO_WARNING_LED, 0); // Set LOW
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(GPIO_WARNING_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_WARNING_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int pressure_adc = read_ads1115(PRESSURE_REG);
        int temp_adc = read_ads1115(TEMP_REG);

        if (pressure_adc == -1 || temp_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC values to pressure and temperature
        SensorData data;
        data.pressure_kPa = convert_pressure(pressure_adc);
        data.temperature_C = convert_temperature(temp_adc);

        // Display data
        display_data(data);

        // Control warning LED
        control_warning_led(data.pressure_kPa);

        // Wait 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

