#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define GPIO_SHUTDOWN 27
#define CURRENT_THRESHOLD 10.0 // Amperes
#define VREF 3.3 // Reference voltage
#define SENSITIVITY 0.066 // 66 mV/A
#define ZERO_CURRENT_VOLTAGE (VREF / 2.0)
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void shutdown_motor();
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int gpio_shutdown;
    float current_threshold;
    float vref;
    float sensitivity;
    float zero_current_voltage;
    char log_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    GPIO_SHUTDOWN,
    CURRENT_THRESHOLD,
    VREF,
    SENSITIVITY,
    ZERO_CURRENT_VOLTAGE,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC. Retrying.\n");
            gpioDelay(100000); // 100ms
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        log_current(current);

        if (current > config.current_threshold) {
            shutdown_motor();
            break; // Exit the loop after shutdown
        }

        gpioDelay(100000); // 100ms
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.gpio_shutdown, PI_OUTPUT);
    gpioWrite(config.gpio_shutdown, 0); // Ensure it starts LOW

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Zero pad

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return (float)adc_value * config.vref / 1024.0;
}

float voltage_to_current(float voltage) {
    if (voltage < 0 || voltage > config.vref) {
        fprintf(stderr, "Invalid voltage: %f\n", voltage);
        return -1.0;
    }
    return (voltage - config.zero_current_voltage) / config.sensitivity;
}

void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

void shutdown_motor() {
    gpioWrite(config.gpio_shutdown, 1); // Set GPIO HIGH
    log_current(-1.0); // Log OVERCURRENT event
    fprintf(stderr, "OVERCURRENT detected! Shutting down motor.\n");
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.gpio_shutdown, 0); // Reset GPIO to LOW
    gpioTerminate();
    printf("Cleanup complete.\n");
}

