#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003
#define VREF 4.096  // ADS1115 Vref
#define OFFSET 0.5  // V
#define SENSITIVITY 0.1 // V/kPa
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int16_t *value);
float convert_to_voltage(int16_t raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int16_t *value) {
    char buf[3];
    int16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    buf[0] = ADS1115_REG_CONFIG >> 8;
    buf[1] = ADS1115_REG_CONFIG & 0xFF;
    buf[2] = (config >> 8) & 0xFF;
    buf[3] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 4) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    buf[0] = ADS1115_REG_CONVERT >> 8;
    buf[1] = ADS1115_REG_CONVERT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    return ((float)raw_value / 32767.0) * VREF;
}

// Convert voltage to pressure using linear transfer function
float convert_to_pressure(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Log pressure reading to file
int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int16_t raw_value;
    float voltage, pressure;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_adc(&raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value);

            // Convert to pressure
            pressure = convert_to_pressure(voltage);

            // Validate pressure range
            if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
                // Log pressure reading
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(1000); // 1 Hz
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

