#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz
#define MCP3208_CS_GPIO 8
#define VREF 3.3
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_RATE_HZ 1

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t max_speed_hz);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3208_channel(int fd, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_celsius(float voltage);
int log_temperature(const char *filename, float temperature_celsius);
void signal_handler(int sig);
int gpio_init(int gpio_pin);
void gpio_set_value(struct gpiod_line *line, int value);
void gpio_release(struct gpiod_chip *chip, struct gpiod_line *line);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t max_speed_hz) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits_val = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed_val = max_speed_hz;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read a specific channel from the MCP3208
int read_mcp3208_channel(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3208 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer for channel %d\n", channel);
        return -1;
    }

    // Extract the 12-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value * vref) / 4095.0;
}

// Function to convert voltage to Celsius
float voltage_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Function to log temperature data to a file
int log_temperature(const char *filename, float temperature_celsius) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }

        // Check if the file is newly created and write the header if needed
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,temperature_celsius\n");
        }
        rewind(log_file);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(int gpio_pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(cs_line, "temperature_sensor", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    gpio_set_value(cs_line, 1); // Initialize CS high
    return 0;
}

// Function to set the GPIO value
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// Function to release GPIO resources
void gpio_release(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO for CS line
    if (gpio_init(MCP3208_CS_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3208_channel(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Validate ADC reading
        if (adc_value < 0 || adc_value > 4095) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue; // Skip logging
        }

        // Convert ADC value to voltage and Celsius
        float voltage = adc_to_voltage(adc_value, VREF);
        float temperature_celsius = voltage_to_celsius(voltage);

        // Log temperature data
        if (log_temperature(LOG_FILE, temperature_celsius) < 0) {
            fprintf(stderr, "Error logging temperature data\n");
        }

        // Wait for the next sample
        struct timespec sleep_time;
        sleep_time.tv_sec = 1; // 1 second
        sleep_time.tv_nsec = 0; // 0 nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources
    gpio_set_value(cs_line, 1); // Set CS high before closing
    gpio_release(gpio_chip, cs_line);
    close(spi_fd);
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

