// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define SAMPLE_RATE 100 // Hz
#define IMPACT_THRESHOLD 2.0 // g
#define SUPPLY_VOLTAGE 3.3 // V
#define ADXL335_SENSITIVITY 0.3 // V/g
#define ADC_RESOLUTION 1024.0 // 2^10 - 1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize();
int read_adc(int channel);
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z);
void log_data(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Activate chip select
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate chip select

    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", spi_result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

