float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z) {
    // Convert ADC values to voltage
    float x_voltage = (float)x / ADC_RESOLUTION * SUPPLY_VOLTAGE;
    float y_voltage = (float)y / ADC_RESOLUTION * SUPPLY_VOLTAGE;
    float z_voltage = (float)z / ADC_RESOLUTION * SUPPLY_VOLTAGE;

    // Calculate acceleration in g
    float x_acceleration = (x_voltage - 1.65) / ADXL335_SENSITIVITY;
    float y_acceleration = (y_voltage - 1.65) / ADXL335_SENSITIVITY;
    float z_acceleration = (z_voltage - 1.65) / ADXL335_SENSITIVITY;

    // Calculate magnitude
    float magnitude = sqrt(x_acceleration * x_acceleration + y_acceleration * y_acceleration + z_acceleration * z_acceleration);

    return magnitude;
}

