void log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values
        int x_adc = read_adc(ADC_CHANNEL_X);
        int y_adc = read_adc(ADC_CHANNEL_Y);
        int z_adc = read_adc(ADC_CHANNEL_Z);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Data validation
        if (x_adc < 0 || x_adc > 1023 || y_adc < 0 || y_adc > 1023 || z_adc < 0 || z_adc > 1023) {
            fprintf(stderr, "ADC value out of range\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to signed 16-bit integers
        int16_t x = (int16_t)x_adc;
        int16_t y = (int16_t)y_adc;
        int16_t z = (int16_t)z_adc;

        // Calculate acceleration magnitude
        float magnitude = calculate_acceleration_magnitude(x, y, z);

        // Log data
        accelerometer_data_t data = {x, y, z};
        log_data(data, magnitude);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
            fflush(log_file);
        }

