        fprintf(stderr, "Invalid HR value: %d\n", data.hr);
        data.error_flag = 1;
    }
    if (data.spo2 < 70 || data.spo2 > 100) {
        fprintf(stderr, "Invalid SpO2 value: %d\n", data.spo2);
        data.error_flag = 1;
    }

    return data;
}

