#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845
#define CSV_FILE "environmental_data.csv"
#define RETRY_DELAY 5 // seconds

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Calibration parameters (replace with actual values from your sensor)
const float T0 = 25.0; // Example value
const float T1 = 0.0;  // Example value
const float P0 = 101325.0; // Example value
const float P1 = 0.0;  // Example value
const float B1 = 0.0;  // Example value
const float B2 = 0.0;  // Example value
const float SENS_T = 0.0; // Example value
const float SENS_P = 0.0; // Example value

// Function prototypes
int i2c_open(int bus, int address);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t *data, int len);
int i2c_close(int fd);
int read_sensor_data(int fd, uint8_t *data);
float convert_temperature(uint16_t raw_temperature);
float convert_pressure(uint32_t raw_pressure, float temperature);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);

// I2C open function
int i2c_open(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;
    if (write(fd, buffer, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_write(fd, MEASUREMENT_COMMAND) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for conversion (adjust delay as needed)
    usleep(10000); // 10 ms

    if (i2c_read(fd, data, 6) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    float temperature = T0 + (T1 * (raw_temperature - 2048.0));
    return temperature;
}

// Convert raw pressure to Pascals
float convert_pressure(uint32_t raw_pressure, float temperature) {
    float pressure = P0 + (P1 * (raw_pressure - 2048.0)) + (B1 * (temperature - 25.0)) + (B2 * (temperature - 25.0) * (temperature - 25.0));
    return pressure;
}

// Log data to CSV file
int log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            perror("Error opening CSV file");
            return -1;
        }
        fprintf(csv_file, "Timestamp,Temperature(C),Pressure(Pa)\n");
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(csv_file); // Ensure data is written to disk
    return 0;
}

// Display data on console
void display_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        uint8_t data[6];
        float temperature, pressure;

        if (read_sensor_data(i2c_fd, data) == 0) {
            // Combine pressure and temperature data
            uint32_t raw_pressure = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | (uint32_t)data[2];
            uint16_t raw_temperature = ((uint16_t)data[3] << 8) | (uint16_t)data[4];

            // Convert raw data to temperature and pressure
            temperature = convert_temperature(raw_temperature);
            pressure = convert_pressure(raw_pressure, temperature);

            // Log data to CSV file
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            // Display data on console
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
            continue; // Retry the loop
        }

        sleep(5); // Sample every 5 seconds
    }

    // Close I2C device and CSV file
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    return 0;
}

