            uint16_t raw_temperature = ((uint16_t)data[3] << 8) | (uint16_t)data[4];

            // Convert raw data to temperature and pressure
            temperature = convert_temperature(raw_temperature);
            pressure = convert_pressure(raw_pressure, temperature);

            // Log data to CSV file
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            // Display data on console
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
            continue; // Retry the loop
        }

        sleep(5); // Sample every 5 seconds
    }

    // Close I2C device and CSV file
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    return 0;
}

