#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define SAMPLE_RATE 16000
#define BUFFER_SIZE 1024
#define NUM_CHANNELS 2

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t data[NUM_CHANNELS][BUFFER_SIZE];
} AudioBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
void noise_cancellation(AudioBuffer *buffer);
void gain_control(AudioBuffer *buffer, float gain);
void output_data(AudioBuffer *buffer);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Noise cancellation algorithm
void noise_cancellation(AudioBuffer *buffer) {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer->data[0][i] = buffer->data[0][i] - buffer->data[1][i];
    }
}

// Gain control algorithm
void gain_control(AudioBuffer *buffer, float gain) {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer->data[0][i] = (int16_t)(buffer->data[0][i] * gain);
    }
}

// Output data to CSV file
void output_data(AudioBuffer *buffer) {
    FILE *fp = fopen("audio_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening audio_data.csv for writing\n");
        return;
    }

    fprintf(fp, "Time,Channel0,Channel1\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fprintf(fp, "%d,%d,%d\n", i, buffer->data[0][i], buffer->data[1][i]);
    }

    fclose(fp);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

