    float gain = 1.0; // Default gain

    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Invalid gain value. Using default gain (1.0)\n");
            gain = 1.0;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    AudioBuffer audio_buffer;
    // Main loop
    while (!terminate) {
        // Read audio data from microphones
        for (int i = 0; i < NUM_CHANNELS; i++) {
            for (int j = 0; j < BUFFER_SIZE; j++) {
                int adc_value = read_mcp3008(i);
                if (adc_value < 0) {
                    fprintf(stderr, "Error reading ADC value from channel %d\n", i);
                    terminate = 1; // Exit loop on error
                    break;
                }
                audio_buffer.data[i][j] = (int16_t)adc_value;
            }
            if (terminate) break;
        }

        if (terminate) break;

        // Apply noise cancellation
        noise_cancellation(&audio_buffer);

        // Apply gain control
        gain_control(&audio_buffer, gain);

        // Output data (optional)
        //output_data(&audio_buffer);

        // Delay to achieve desired sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

