// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi(config_t config);
int read_mcp3008(int channel);
int log_data(FILE *fp, int adc_value);
void signal_handler(int signal);
