        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value >= 0) {
            if (log_data(log_file, adc_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

