#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_GPIO 18
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VOLTAGE_REF 3.3
#define ADC_MAX 1023.0
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
static volatile int running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_transfer(int channel, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int channel);
float compensate_voltage(int raw_adc, float ambient_temp);
int read_temperature(float *ambient_temp);
void log_data(int raw_adc, float voltage, float compensated_voltage, float ambient_temp, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int sig);
int initialize_gpio(void);
void cleanup(void);

// SPI transfer function
int spi_transfer(int channel, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct gpiod_line_request_config config;
    int ret;

    // Configure GPIO line for SPI communication
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(buzzer_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        return -1;
    }

    // Set GPIO line to output mode
    ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }

    // Perform SPI transfer
    ret = gpiod_chip_xfer(gpio_chip, channel, tx_buf, rx_buf, len);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int raw_adc = -1;
    int retries = 0;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    while (retries < 3) {
        if (spi_transfer(0, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value
            raw_adc = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            break;
        } else {
            retries++;
            usleep(1000); // Wait before retrying
        }
    }

    if (raw_adc < 0 || raw_adc > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", raw_adc);
        return -1;
    }

    return raw_adc;
}

// Compensate voltage with temperature
float compensate_voltage(int raw_adc, float ambient_temp) {
    float voltage = (float)raw_adc / ADC_MAX * VOLTAGE_REF;
    return voltage + (ambient_temp - 25.0) * 0.001;
}

// Read ambient temperature from file
int read_temperature(float *ambient_temp) {
    FILE *fp;
    char line[256];
    char *token;
    int temp_int;
    float temp_float;

    fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        *ambient_temp = 25.0; // Default temperature
        return -1;
    }

