#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void control_led(float water_level);
void log_water_level(float water_level);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int led_gpio;
    int water_level_threshold_high;
    int water_level_threshold_low;
    char json_file[64];
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    LED_GPIO,
    WATER_LEVEL_THRESHOLD_HIGH,
    WATER_LEVEL_THRESHOLD_LOW,
    JSON_FILE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Open JSON file
    json_file = fopen(config.json_file, "a+");
    if (json_file == NULL) {
        fprintf(stderr, "Failed to open JSON file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Write opening bracket if the file is newly created
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
    } else {
        // If the file is not empty, go back to the last character and check if it's a closing bracket
        fseek(json_file, file_size - 1, SEEK_SET);
        char last_char;
        fread(&last_char, 1, 1, json_file);
        if (last_char == ']') {
            // The file is not empty and ends with a closing bracket, so we can safely append a comma
            fprintf(json_file, ",");
        } else {
            // The file is not empty and does not end with a closing bracket, so we need to add a comma
            fprintf(json_file, ",");
        }
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping.\n");
            gpioDelay(5000000); // Sleep for 5 seconds
            continue;
        }

        // Convert to percentage
        float water_level = convert_to_percentage(adc_value);

        // Control LED
        control_led(water_level);

        // Log water level
        log_water_level(water_level);

        // Sleep for 5 seconds
        gpioDelay(5000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Parse ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Control LED based on water level
void control_led(float water_level) {
    if (water_level > config.water_level_threshold_high) {
        gpioWrite(config.led_gpio, 1); // Turn LED ON
    } else if (water_level < config.water_level_threshold_low) {
        gpioWrite(config.led_gpio, 0); // Turn LED OFF
    }
}

// Log water level to JSON file
void log_water_level(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", (long)(rawtime % 1000));
    strcat(timestamp, milliseconds);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);
    fflush(json_file); // Flush to ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Close SPI
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(config.led_gpio, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close JSON file
    if (json_file != NULL) {
        // Find the last comma and replace it with a closing bracket
        fseek(json_file, -1, SEEK_END);
        char last_char;
        fread(&last_char, 1, 1, json_file);
        if (last_char == ',') {
            fseek(json_file, -1, SEEK_END);
            fprintf(json_file, "]");
        }
        fclose(json_file);
    }
}

