    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Parse ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Control LED based on water level
void control_led(float water_level) {
    if (water_level > config.water_level_threshold_high) {
        gpioWrite(config.led_gpio, 1); // Turn LED ON
    } else if (water_level < config.water_level_threshold_low) {
        gpioWrite(config.led_gpio, 0); // Turn LED OFF
    }
}

// Log water level to JSON file
void log_water_level(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", (long)(rawtime % 1000));
    strcat(timestamp, milliseconds);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);
    fflush(json_file); // Flush to ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Close SPI
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(config.led_gpio, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close JSON file
    if (json_file != NULL) {
        // Find the last comma and replace it with a closing bracket
        fseek(json_file, -1, SEEK_END);
        char last_char;
        fread(&last_char, 1, 1, json_file);
        if (last_char == ',') {
            fseek(json_file, -1, SEEK_END);
            fprintf(json_file, "]");
        }
        fclose(json_file);
    }
}

