    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to LPM
float convert_to_lpm(int adc_value) {
    // AWM7300V: 0V = 0 LPM, 5V = 200 LPM
    // Assuming 3.3V reference
    float voltage = (3.3 * adc_value) / 1024.0;
    float flow_rate = (voltage / 5.0) * 200.0; // Linear conversion
    return flow_rate;
}

