            } else if (strcmp(key, "adc_channel") == 0) {
                config->adc_channel = atoi(value);
            } else if (strcmp(key, "min_raw") == 0) {
                config->min_raw = atoi(value);
            } else if (strcmp(key, "max_raw") == 0) {
                config->max_raw = atoi(value);
            } else if (strcmp(key, "moisture_threshold") == 0) {
                config->moisture_threshold = atoi(value);
            } else if (strcmp(key, "logging_frequency") == 0) {
                config->logging_frequency = atoi(value);
            } else if (strcmp(key, "recipient_email") == 0) {
                config->recipient_email = strdup(value); // Allocate memory for the string
            } else if (strcmp(key, "msmtp_config_file") == 0) {
                config->msmtp_config_file = strdup(value); // Allocate memory for the string
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize SPI
int initialize_spi(int channel) {
    spi_handle = spiOpen(channel, 500000, 0); // SPI channel, baud rate, flags
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    // Ensure raw_value is within the calibration range
    if (raw_value < min_raw) raw_value = min_raw;
    if (raw_value > max_raw) raw_value = max_raw;

    // Calculate percentage based on linear interpolation
    float percentage = 100.0 - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0;
    return percentage;
}

// Function to log data to file
int log_data(float moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

// Function to send email alert
int send_email_alert(float moisture_percentage, const char *recipient_email, const char *msmtp_config_file) {
    if (moisture_percentage < config.moisture_threshold) {
        char command[512];
        snprintf(command, sizeof(command), "echo \"Subject: Low Plant Moisture\n\nMoisture level: %.2f%%\" | msmtp -t -a default -c %s %s",
                 moisture_percentage, msmtp_config_file, recipient_email);

        FILE *fp = popen(command, "r");
        if (fp == NULL) {
            perror("Error executing msmtp command");
            return -1;
        }

        int status = pclose(fp);
        if (status != 0) {
            fprintf(stderr, "msmtp command failed with status: %d\n", status);
            return -1;
        }
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main(int argc, char *argv[]) {
    // Default configuration values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw = 300;
    config.max_raw = 700;
    config.moisture_threshold = 30;
    config.logging_frequency = 60;
    config.recipient_email = NULL;
    config.msmtp_config_file = NULL;

    // Read configuration from file
    if (read_config("plant_monitor.conf", &config) != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Command-line argument parsing
    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:M:t:f:e:c:")) != -1) {
        switch (opt) {
            case 's':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_raw = atoi(optarg);
                break;
            case 'M':
                config.max_raw = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atoi(optarg);
                break;
            case 'f':
                config.logging_frequency = atoi(optarg);
                break;
            case 'e':
                config.recipient_email = strdup(optarg);
                break;
            case 'c':
                config.msmtp_config_file = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] [-m min_raw] [-M max_raw] [-t moisture_threshold] [-f logging_frequency] [-e recipient_email] [-c msmtp_config_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Validate command-line arguments
    if (config.recipient_email == NULL) {
        fprintf(stderr, "Error: recipient_email is required.\n");
        exit(EXIT_FAILURE);
    }
    if (config.msmtp_config_file == NULL) {
        fprintf(stderr, "Error: msmtp_config_file is required.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config.spi_channel) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant monitoring started. Logging every %d seconds. Threshold: %d%%\n", config.logging_frequency, config.moisture_threshold);

    // Main loop
    while (running) {
        // Read ADC value
        int raw_value = read_mcp3008(config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(raw_value, config.min_raw, config.max_raw);

        // Log data
        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Send email alert if necessary
        if (send_email_alert(moisture_percentage, config.recipient_email, config.msmtp_config_file) != 0) {
            fprintf(stderr, "Error sending email alert.\n");
        }

        printf("Moisture: %.2f%%\n", moisture_percentage);

        // Wait for the specified logging frequency
        sleep(config.logging_frequency);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    if (config.recipient_email != NULL) {
        free(config.recipient_email);
    }
    if (config.msmtp_config_file != NULL) {
        free(config.msmtp_config_file);
    }

    printf("Plant monitoring stopped.\n");
    return 0;
}

