        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE) * 100.0);

    // Clamp percentage between 0 and 100
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 5 seconds.\n");
            sleep(5);
