#define PRESSURE_MIN 10.0  // Minimum pressure in kPa
#define PRESSURE_MAX 150.0 // Maximum pressure in kPa
#define VOLTAGE_MIN 0.5    // Minimum voltage in V
#define VOLTAGE_MAX 4.5    // Maximum voltage in V
#define ADC_MIN 0          // Minimum ADC value
#define ADC_MAX 1023       // Maximum ADC value
#define LOG_INTERVAL 1      // Logging interval in seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float pressure_min;
    float pressure_max;
    float voltage_min;
    float voltage_max;
    int adc_min;
    int adc_max;
    int log_interval;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    PRESSURE_MIN,
    PRESSURE_MAX,
    VOLTAGE_MIN,
    VOLTAGE_MAX,
    ADC_MIN,
    ADC_MAX,
    LOG_INTERVAL
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", config.log_interval);
            sleep(config.log_interval);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Validate voltage
        if (voltage < config.voltage_min || voltage > config.voltage_max) {
