            log_pressure(-1.0); // Log error
            sleep(config.log_interval);
            continue;
        }

        // Map voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log pressure
        log_pressure(pressure);

        // Wait for the next interval
        sleep(config.log_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

