#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_SENSORS 4
#define SAMPLE_INTERVAL_SEC 1

// GPIO pin for chip select (CE0)
#define CS_PIN 8

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
float read_mcp3008_channel(int channel);
void log_data(float voltages[NUM_SENSORS]);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read a specific channel from the MCP3008
float read_mcp3008_channel(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer for channel %d\n", channel);
        return -1.0; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Convert ADC value to voltage
    float voltage = (float)adc_value * VREF / 1024.0;

    return voltage;
}

// Function to log data to a CSV file
void log_data(float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2], voltages[3]);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod for GPIO control
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request(cs_line, "voltage_monitor", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Voltage0,Voltage1,Voltage2,Voltage3\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        float voltages[NUM_SENSORS];

        // Read voltage from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            voltages[i] = read_mcp3008_channel(i);
            if (voltages[i] < 0) {
                fprintf(stderr, "Error reading channel %d, skipping\n", i);
                voltages[i] = -1.0; // Indicate error in log
            }
        }

        // Log the data
        log_data(voltages);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

