#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for log entries
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int read_moisture_level();
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read moisture level from MCP3008
int read_moisture_level() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 command: start bit (1), single-ended (1), channel 0 (000), don't care (0)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value from the response
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
    } else if (moisture_level > HIGH_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("-------------------\n\n");
}

