        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Control buzzer based on gas threshold
        if (adc_value < GAS_THRESHOLD) {
            control_buzzer(0); // Turn buzzer OFF
