#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_DIFF_0_1 0x0000
#define ADS1115_CONFIG_PGA_4_096V 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0000
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003
#define RELAY_GPIO 17
#define REED_GPIO 27
#define LOG_FILE "/var/log/door_events.log"
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_DELAY_MS 50
#define RELAY_ON_TIME_S 3
#define POLLING_INTERVAL_MS 200

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_ads1115(int16_t *value);
float calibrate_threshold(int16_t *baseline_samples, int num_samples);
int control_relay(int state);
int read_reed_sensor();
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    reed_line = gpiod_chip_get_line(gpio_chip, REED_GPIO);
    if (!reed_line) {
        perror("Error getting reed GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_control", 0) < 0) {
        perror("Error requesting relay GPIO line as output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        return -1;
    }

    if (gpiod_line_request_input(reed_line, "door_control") < 0) {
        perror("Error requesting reed GPIO line as input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        return -1;
    }

    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    return 0;
}

// Read ADS1115 ADC value
int read_ads1115(int16_t *value) {
    uint8_t write_buf[3];
    uint8_t read_buf[2];

    // Configure ADS1115 for single conversion, AIN0, +/-4.096V, 128 SPS
    write_buf[0] = ADS1115_REG_CONFIG;
    write_buf[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_DIFF_0_1 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE);
    write_buf[2] = 0x00; // Dummy byte

    if (write(i2c_fd, write_buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    write_buf[0] = ADS1115_REG_CONVERT;
    if (write(i2c_fd, write_buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, read_buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *value = (int16_t)((read_buf[0] << 8) | read_buf[1]);

    return 0;
}

// Calibrate threshold
float calibrate_threshold(int16_t *baseline_samples, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += baseline_samples[i];
    }
    return sum / num_samples * 0.8; // 80% of the average
}

// Control relay
int control_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Error setting relay state");
        return -1;
    }
    return 0;
}

// Read reed sensor
int read_reed_sensor() {
    int value = gpiod_line_get_value(reed_line);
    if (value < 0) {
        perror("Error reading reed sensor");
        return -1;
    }
    return value;
}

// Log event
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // De-energize relay
        gpiod_line_release(relay_line);
    }

    if (reed_line) {
        gpiod_line_release(reed_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    if (init_logging() < 0) {
        fprintf(stderr, "Logging initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Baseline sampling
    int16_t baseline_samples[NUM_BASELINE_SAMPLES];
    printf("Taking baseline samples...\n");
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        if (read_ads1115(&baseline_samples[i]) < 0) {
            fprintf(stderr, "Error reading ADC during baseline sampling. Continuing.\n");
            continue; // Continue to the next sample
        }
        usleep(BASELINE_SAMPLE_DELAY_MS * 1000); // Wait 50ms
    }

    float threshold = calibrate_threshold(baseline_samples, NUM_BASELINE_SAMPLES);
    printf("Calibrated threshold: %.2f\n", threshold);

    // Main loop
    while (!terminate) {
        int16_t adc_value;
        if (read_ads1115(&adc_value) < 0) {
            fprintf(stderr, "Error reading ADC. Continuing.\n");
            usleep(POLLING_INTERVAL_MS * 1000); // Wait before next poll
            continue;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Continuing.\n");
            usleep(POLLING_INTERVAL_MS * 1000); // Wait before next poll
            continue;
        }

        if (adc_value < (int16_t)(threshold * 1.2)) { // Release if below 80% and 20% below threshold
            printf("Distance below threshold. Activating relay.\n");
            if (control_relay(1) < 0) {
                fprintf(stderr, "Error activating relay. Continuing.\n");
            }
            sleep(RELAY_ON_TIME_S);
            if (control_relay(0) < 0) {
                fprintf(stderr, "Error deactivating relay. Continuing.\n");
            }

            int reed_value = read_reed_sensor();
            if (reed_value < 0) {
                fprintf(stderr, "Error reading reed sensor. Continuing.\n");
            } else {
                if (reed_value == 0) {
                    log_event("Door opened");
                } else {
                    log_event("Door not opened");
                }
            }
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Wait before next poll
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

