#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25
#define LOG_FILE "soil_moisture_log.csv"
#define LOG_INTERVAL 5 // seconds

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs0_line = NULL;
static struct gpiod_line *cs1_line = NULL;
static struct gpiod_line *cs2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int chip_select_pin, int channel);
int log_data(int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int sig);
int cleanup(void);
int write_csv_header(FILE *fp);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int chip_select_pin, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Build SPI command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0; // Delay after each transfer

    // Chip select
    if (chip_select_pin == CS0_PIN) {
        ret = gpiod_line_set_value(cs0_line, 0); // Assert CS
        if (ret < 0) {
            perror("Error asserting CS0");
            return -1;
        }
    } else if (chip_select_pin == CS1_PIN) {
        ret = gpiod_line_set_value(cs1_line, 0); // Assert CS
        if (ret < 0) {
            perror("Error asserting CS1");
            return -1;
        }
    } else if (chip_select_pin == CS2_PIN) {
        ret = gpiod_line_set_value(cs2_line, 0); // Assert CS
        if (ret < 0) {
            perror("Error asserting CS2");
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid chip select pin: %d\n", chip_select_pin);
        return -1;
    }

    // Perform SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("Error performing SPI transfer");
        if (chip_select_pin == CS0_PIN) {
            gpiod_line_set_value(cs0_line, 1); // Deassert CS
        } else if (chip_select_pin == CS1_PIN) {
            gpiod_line_set_value(cs1_line, 1); // Deassert CS
        } else if (chip_select_pin == CS2_PIN) {
            gpiod_line_set_value(cs2_line, 1); // Deassert CS
        }
        return -1;
    }

    // Chip deselect
    if (chip_select_pin == CS0_PIN) {
        ret = gpiod_line_set_value(cs0_line, 1); // Deassert CS
        if (ret < 0) {
            perror("Error deasserting CS0");
            return -1;
        }
    } else if (chip_select_pin == CS1_PIN) {
        ret = gpiod_line_set_value(cs1_line, 1); // Deassert CS
        if (ret < 0) {
            perror("Error deasserting CS1");
            return -1;
        }
    } else if (chip_select_pin == CS2_PIN) {
        ret = gpiod_line_set_value(cs2_line, 1); // Deassert CS
        if (ret < 0) {
            perror("Error deasserting CS2");
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid chip select pin: %d\n", chip_select_pin);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
int cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        if (cs0_line) gpiod_line_release(cs0_line);
        if (cs1_line) gpiod_line_release(cs1_line);
        if (cs2_line) gpiod_line_release(cs2_line);
        gpiod_chip_close(chip);
    }
    return 0;
}

// Function to write CSV header
int write_csv_header(FILE *fp) {
    if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
        perror("Error writing CSV header");
        return -1;
    }
    return 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs0_line = gpiod_chip_get_line(chip, CS0_PIN);
    cs1_line = gpiod_chip_get_line(chip, CS1_PIN);
    cs2_line = gpiod_chip_get_line(chip, CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    int ret = gpiod_line_request(cs0_line, "sensor0", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for CS0");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request(cs1_line, "sensor1", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for CS1");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request(cs2_line, "sensor2", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for CS2");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (write_csv_header(log_file) < 0) {
            cleanup();
            return 1;
        }
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int sensor1_value = read_mcp3008(CS0_PIN, 0);
        int sensor2_value = read_mcp3008(CS1_PIN, 0);
        int sensor3_value = read_mcp3008(CS2_PIN, 0);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        } else {
            if (log_data(sensor1_value, sensor2_value, sensor3_value) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(LOG_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

