    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
int cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        if (cs0_line) gpiod_line_release(cs0_line);
        if (cs1_line) gpiod_line_release(cs1_line);
        if (cs2_line) gpiod_line_release(cs2_line);
        gpiod_chip_close(chip);
    }
    return 0;
}

// Function to write CSV header
