    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs0_line = gpiod_chip_get_line(chip, CS0_PIN);
    cs1_line = gpiod_chip_get_line(chip, CS1_PIN);
    cs2_line = gpiod_chip_get_line(chip, CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    int ret = gpiod_line_request(cs0_line, "sensor0", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for CS0");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request(cs1_line, "sensor1", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for CS1");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request(cs2_line, "sensor2", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for CS2");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (write_csv_header(log_file) < 0) {
            cleanup();
            return 1;
        }
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int sensor1_value = read_mcp3008(CS0_PIN, 0);
        int sensor2_value = read_mcp3008(CS1_PIN, 0);
        int sensor3_value = read_mcp3008(CS2_PIN, 0);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        } else {
            if (log_data(sensor1_value, sensor2_value, sensor3_value) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(LOG_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

