#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

// Global variables
static volatile int running = 1;
static int pump_state = 0; // 0 = off, 1 = on
static int dry_value = 200;
static int wet_value = 800;
static int moisture_threshold = 30;
static int irrigation_duration = 10;
static int sleep_interval = 60;
static int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value, int dry_value, int wet_value);
void control_pump(int state);
void log_data(int adc_value, float moisture, int pump_state);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (channel %d), retry %d\n", channel, retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI read failed after %d retries (channel %d)\n", MAX_RETRIES, channel);
    return -1; // Indicate failure
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value, int dry_value, int wet_value) {
    if (adc_value < dry_value) {
        return 0.0;
    } else if (adc_value > wet_value) {
        return 100.0;
    } else {
        return (float)(adc_value - dry_value) / (float)(wet_value - dry_value) * 100.0;
    }
}

// Function to control the water pump
void control_pump(int state) {
    if (state != pump_state) {
        gpioWrite(PUMP_GPIO, state);
        pump_state = state;
        printf("Pump %s\n", state ? "ON" : "OFF");
    }
}

// Function to log data to file
void log_data(int adc_value, float moisture, int pump_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%, Pump: %s\n", timestamp, adc_value, moisture, pump_state ? "ON" : "OFF");
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

// Cleanup function to turn off pump and close SPI
void cleanup() {
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                moisture_threshold = atoi(optarg);
                break;
            case 'd':
                irrigation_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting irrigation system...\n");

    while (running) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Map ADC value to moisture percentage
        float moisture = map_adc_to_moisture(adc_value, dry_value, wet_value);

        // Log data
        log_data(adc_value, moisture, pump_state);

        // Check moisture threshold and activate pump if needed
        if (moisture < moisture_threshold) {
            printf("Moisture below threshold (%.2f%% < %d%%), activating pump for %d seconds\n", moisture, moisture_threshold, irrigation_duration);
            control_pump(1); // Turn on pump
            gpioDelay(irrigation_duration * 1000000); // Delay for irrigation duration (microseconds)
            control_pump(0); // Turn off pump
            printf("Pump deactivated\n");
        }

        // Sleep for the specified interval
        gpioDelay(sleep_interval * 1000000); // Sleep for sleep_interval seconds (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

