#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
double calculate_ema(double current_value, double previous_ema);
double calculate_threshold(double ema_value);
int log_event(double raw_value, double ema_value, double threshold);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI communication failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate exponential moving average
double calculate_ema(double current_value, double previous_ema) {
    return EMA_ALPHA * current_value + (1 - EMA_ALPHA) * previous_ema;
}

// Function to calculate the threshold
double calculate_threshold(double ema_value) {
    return ema_value * (1 + THRESHOLD_MARGIN);
}

// Function to log sound event to file
int log_event(double raw_value, double ema_value, double threshold) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s, Raw: %.0f, EMA: %.0f, Threshold: %.0f\n", timestamp, raw_value, ema_value, threshold);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double ema_value = 0.0; // Initial EMA value

    printf("Sound event detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate EMA
        ema_value = calculate_ema((double)adc_value, ema_value);

        // Calculate threshold
        double threshold = calculate_threshold(ema_value);

        // Check for peak
        if (adc_value > threshold) {
            printf("Peak detected! Raw: %.0f, EMA: %.0f, Threshold: %.0f\n", adc_value, ema_value, threshold);
            if (log_event((double)adc_value, ema_value, threshold) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Sound event detection stopped.\n");
    return 0;
}

