#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Define the control byte for AIN0 (single-ended, no analog output)
#define CONTROL_BYTE 0x40

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read the analog value from PCF8591
int read_pcf8591(int fd) {
    uint8_t data[2];
    int result;

    // Write the control byte to the I2C device
    result = write(fd, &CONTROL_BYTE, 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read two bytes from the I2C device
    result = read(fd, data, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Return the second byte, which contains the analog value
    return data[1];
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the analog value from the PCF8591
        int analog_value = read_pcf8591(i2c_fd);
        if (analog_value < 0) {
            fprintf(stderr, "Error reading analog value, exiting...\n");
            close(i2c_fd);
            return 1;
        }

        // Print the analog value to stdout
        printf("AIN0: %d\n", analog_value);

        // Wait for 100 milliseconds
        usleep(100000);
    }

    return 0;
}

