#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_SHUTDOWN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define VCC 3.3
#define SENSITIVITY 0.0014 // 1.4 mV/Gauss = 0.0014 V/Gauss
#define ZERO_FIELD_VOLTAGE 2.5
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_gauss(int16_t raw_value);
float calculate_rolling_average();
void signal_handler(int signal);
void cleanup();
void log_message(int priority, const char *message);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "I2C open failed");
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char buffer[2];
    int result;

    // Configure ADS1115 for single-ended AIN0, 4.096V range, single conversion
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // 0b11000011
    config[2] = 0x83; // 0b10000011

    result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        log_message(LOG_ERR, "I2C write failed");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms)
    gpioDelay(10000); // 10ms

    // Read conversion result
    config[0] = 0x00; // Conversion register address
    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        log_message(LOG_ERR, "I2C write failed (address)");
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        log_message(LOG_ERR, "I2C read failed");
        return -1;
    }

    *raw_value = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to convert raw ADC value to Gauss
float convert_to_gauss(int16_t raw_value) {
    float voltage = (float)raw_value / 32767.0 * VCC; // Assuming 16-bit ADC
    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        log_message(LOG_WARNING, "Invalid voltage reading");
        return NAN; // Not a Number
    }
    return (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY;
}

// Function to calculate rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(GPIO_SHUTDOWN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

// Logging function
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("hall_effect_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Initially LOW

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        float gauss_value;
        float rolling_average;

        // Read from ADS1115
        if (read_ads1115(&raw_value) == 0) {
            // Convert to Gauss
            gauss_value = convert_to_gauss(raw_value);

            // Store in circular buffer
            buffer[buffer_index] = gauss_value;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate rolling average
            rolling_average = calculate_rolling_average();

            // Log data
            char log_buffer[256];
            snprintf(log_buffer, sizeof(log_buffer), "Raw: %d, Gauss: %.2f, Rolling Average: %.2f", raw_value, gauss_value, rolling_average);
            log_message(LOG_INFO, log_buffer);

            // Check threshold
            if (rolling_average > THRESHOLD_GAUSS) {
                log_message(LOG_WARNING, "Threshold exceeded, shutting down motor!");
                gpioWrite(GPIO_SHUTDOWN, 1); // Set HIGH
            } else {
                gpioWrite(GPIO_SHUTDOWN, 0); // Set LOW
            }
        } else {
            log_message(LOG_WARNING, "Failed to read sensor data");
        }

        // Delay for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

