#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1; // Indicate an error
    }

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log watering events
void log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0 CE0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off initially

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Soil moisture monitoring and watering system started.\n");

    while (program_running) {
        // Read soil moisture
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_event(-1); // Log error
        } else {
            printf("Moisture level: %d\n", moisture_level);

            // Check if watering is needed
            if (moisture_level < MOISTURE_THRESHOLD) {
                printf("Moisture level below threshold, activating pump.\n");
                control_pump(1); // Turn on pump
                gpioDelay(WATERING_DURATION * 1000000); // Wait for watering duration (microseconds)
                control_pump(0); // Turn off pump
                printf("Pump deactivated.\n");
            }

            // Log the event
            log_event(moisture_level);
        }

        gpioDelay(60000000); // Wait 60 seconds (microseconds)
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

