// Define GPIO pins
#define MOTOR_PIN 18
#define SPI_CE 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
void set_motor_duty_cycle(int duty_cycle);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor duty cycle using PWM
void set_motor_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 1023) {
        fprintf(stderr, "Error: Invalid duty cycle %d\n", duty_cycle);
        return;
    }

    gpioPWM(MOTOR_PIN, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure motor pin as output
    gpioSetMode(MOTOR_PIN, PI_OUTPUT);

    // Configure PWM frequency and range
    gpioSetPWMfrequency(MOTOR_PIN, 1000); // 1 kHz
    gpioSetPWMrange(MOTOR_PIN, 1024);    // Range 0-1023

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Set motor duty cycle
        set_motor_duty_cycle(adc_value);

        // Print ADC and duty cycle values
        printf("ADC Value: %d, Duty Cycle: %d\n", adc_value, adc_value);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and exit
    spiClose(spi_handle);
    gpioPWM(MOTOR_PIN, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

