#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int16_t *value);
double convert_to_gauss(int16_t raw_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double threshold;
} config_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int16_t *value) {
    char buf[2];
    int result;

    // Configure ADS1115 for single-ended AIN0, 4.096V gain, continuous conversion
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    result = i2cWriteDevice(i2c_handle, config_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write config: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion: %d\n", result);
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    // Assuming 0.001 V/Gauss sensitivity
    double voltage = (double)raw_value * 0.0000078125; // 3.3V / 4096
    return voltage / 0.001;
}

// Blink LED on GPIO17
void blink_led(int duration_ms) {
    gpioWrite(GPIO_LED, 1); // Turn LED on
    gpioDelay(duration_ms);
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioDelay(duration_ms);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_value;
    double gauss;

    // Main loop
    while (!terminate) {
        if (read_ads1115(&raw_value) == 0) {
            gauss = convert_to_gauss(raw_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                blink_led(50);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

