#define PUMP_OFF_TOPIC "pump_control/pump_off"
#define MOISTURE_TOPIC "soil_moisture"
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_monitor_rpi"
#define MAX_RECONNECT_DELAY 60 // Maximum reconnect delay in seconds

// Global variables
