float calculate_moisture(int adc_value);
void control_relay(int state);
void publish_moisture(float moisture);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);
int mqtt_connect_and_subscribe();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023 (10-bit)
    // HL-69 output is 0-5V, corresponding to 0-100% moisture
    // Linear relationship: moisture = (adc_value / 1023) * 100
    float moisture = (float)adc_value / 1023.0 * 100.0;
    return moisture;
}

