void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    syslog(LOG_INFO, "Relay set to state: %d", state);
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MOISTURE_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %.2f", moisture);
    }
}

