#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define SAMPLE_INTERVAL_MS 10

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_adc(int channel);
void set_motor_speed(int gpio, int speed);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char buffer[3];
    int adc_value = -1; // Initialize to an invalid value

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI data read failed\n");
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int gpio, int speed) {
    gpioPWM(gpio, speed);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop motors
    set_motor_speed(MOTOR1_GPIO, 0);
    set_motor_speed(MOTOR2_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);

        if (adc_value == -1) {
            // Error reading ADC, skip to the next iteration
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            // Map ADC value to PWM duty cycle (0-255)
            int duty_cycle = (int)(((float)adc_value / 1023.0) * 255.0);

            // Set motor speeds
            set_motor_speed(MOTOR1_GPIO, duty_cycle);
            set_motor_speed(MOTOR2_GPIO, duty_cycle);

            // Log event
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Noise detected: ADC value = %d, Duty cycle = %d", adc_value, duty_cycle);
            log_event(log_message);
        } else {
            // Turn off motors
            set_motor_speed(MOTOR1_GPIO, 0);
            set_motor_speed(MOTOR2_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    return 0;
}

