#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x11
#define LOG_FILE "tamper_log.csv"

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_sound_level(int adc_value);
float read_bh1750();
void log_data(float sound_level, float light_level, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate sound level in dB
float calculate_sound_level(int adc_value) {
    // Simple linear conversion (adjust as needed)
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float sound_level = 20 * log10(voltage / 0.1); // Example: 0.1V = 0 dB
    return sound_level;
}

// Function to read light level from BH1750 sensor
float read_bh1750() {
    char buf[2];
    int lux = 0;

    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error: Failed to set BH1750 mode\n");
        return -1.0;
    }
    gpioDelay(180); // Wait for measurement (at least 180ms)

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data\n");
        return -1.0;
    }

    lux = (buf[0] << 8) | buf[1];
    return (float)lux / 1.2; // Convert to lux
}

// Function to log data to CSV file
void log_data(float sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // I2C bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        float sound_level = 0.0;
        float light_level = 0.0;
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            error_code = -1; // ADC read error
        } else {
            sound_level = calculate_sound_level(adc_value);
        }

        light_level = read_bh1750();
        if (light_level < 0) {
            fprintf(stderr, "Error: Failed to read light level\n");
            error_code = -2; // BH1750 read error
        }

        log_data(sound_level, light_level, error_code);

        sleep(5);
    }

    cleanup();
    return 0;
}

