void log_event(const char *event);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to distance (cm)
float adc_to_distance(int adc_value) {
    // Calibration curve for GP2Y0A21YK0F (example values)
    // This is a simplified linear approximation.  A proper calibration
    // would involve a lookup table or a more complex curve fitting.
    // The actual sensor's datasheet provides the correct calibration curve.
    // This is just a placeholder for demonstration purposes.

    // Example: Assuming a linear relationship between ADC value and distance.
    // Adjust the constants based on your sensor's characteristics.
    float distance = 100.0 / (adc_value / 10.0); // Inverted relationship for demonstration

    // Clamp the distance to a reasonable range
    if (distance < 2) {
        distance = 2; // Minimum distance
    } else if (distance > 80) {
        distance = 80; // Maximum distance
    }

    return distance;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

