            // Deactivate relay if distance is greater than 20cm
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Proximity cleared, relay deactivated");
                printf("Proximity cleared, relay deactivated\n");
            }
        }

        // Print current sensor readings
        printf("ADC Value: %d, Distance: %.2f cm, Relay State: %s\n", adc_value, distance, relay_state ? "ON" : "OFF");

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

