#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_FREQUENCY 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_valve(float adc_value);
void set_valve_position(float valve_position);
void log_data(int sensor1, int sensor2, int sensor3, float average, float valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to valve position (0-100%)
float map_adc_to_valve(float adc_value) {
    // Invert the mapping: lower ADC value -> higher valve opening
    return 100.0 - (adc_value / 1023.0) * 100.0;
}

// Function to set the valve position using PWM
void set_valve_position(float valve_position) {
    if (valve_position < 0.0) valve_position = 0.0;
    if (valve_position > 100.0) valve_position = 100.0;

    // Convert percentage to duty cycle (0-100)
    int duty_cycle = (int)(valve_position / 100.0 * 100.0);

    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int sensor1, int sensor2, int sensor3, float average, float valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %.2f\n", timestamp, sensor1, sensor2, sensor3, average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Close valve
    gpioPWM(VALVE_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, 100); // Range 0-100 for duty cycle

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_FREQUENCY, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor1_value = read_mcp3008(0);
        int sensor2_value = read_mcp3008(1);
        int sensor3_value = read_mcp3008(2);

        float average_adc = 0.0;
        int valid_sensor_count = 0;

        if (sensor1_value != -1) {
            average_adc += sensor1_value;
            valid_sensor_count++;
        }
        if (sensor2_value != -1) {
            average_adc += sensor2_value;
            valid_sensor_count++;
        }
        if (sensor3_value != -1) {
            average_adc += sensor3_value;
            valid_sensor_count++;
        }

        if (valid_sensor_count > 0) {
            average_adc /= valid_sensor_count;
        } else {
            fprintf(stderr, "Error: No valid sensor readings\n");
            average_adc = 0.0; // Or some other default value
        }

        float valve_position = map_adc_to_valve(average_adc);
        set_valve_position(valve_position);
        log_data(sensor1_value, sensor2_value, sensor3_value, average_adc, valve_position);

        sleep(5);
    }

    return 0;
}

