#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CONFIG_FILE "theremin_config.txt"
#define MAX_DISTANCE 200.0 // Maximum measurable distance in cm
#define MIN_DISTANCE 2.0   // Minimum measurable distance in cm
#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY 880.0
#define MIN_DUTY_CYCLE 0.0
#define MAX_DUTY_CYCLE 100.0
#define DEFAULT_CALIBRATION 1.0 // Default calibration factor

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float calibration_factor = DEFAULT_CALIBRATION;
static int last_valid_distance = 0; // Store the last valid distance reading
static int last_valid_duty_cycle = 0; // Store the last valid duty cycle

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_pwm();
int init_spi();
float read_distance();
float read_ldr();
float map_distance_to_frequency(float distance);
float map_ldr_to_duty_cycle(float ldr_value);
void set_pwm_frequency(float frequency);
void set_pwm_duty_cycle(float duty_cycle);
void log_data(float distance, float frequency, float duty_cycle);
void load_calibration();
void save_calibration();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    return 0;
}

// Initialize PWM using sysfs
int init_pwm() {
    FILE *fp;
    char buffer[64];

    // Export PWM0
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/export");
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening PWM export file\n");
        return -1;
    }
    fprintf(fp, "0");
    fclose(fp);

    // Set PWM period (e.g., 100 kHz)
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/period");
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening PWM period file\n");
        return -1;
    }
    fprintf(fp, "100000"); // 100 kHz = 100000 us
    fclose(fp);

    // Enable PWM
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening PWM enable file\n");
        return -1;
    }
    fprintf(fp, "1");
    fclose(fp);

    return 0;
}

// Initialize SPI using wiringPi
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPi SPI setup failed\n");
        return -1;
    }
    return 0;
}

// Read distance from HC-SR04 sensor
float read_distance() {
    long start_time, end_time, pulse_width;

    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > 50000) { // Timeout after 50ms
            fprintf(stderr, "Timeout waiting for ECHO start\n");
            return -1.0; // Indicate timeout error
        }
    }
    start_time = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > 50000) { // Timeout after 50ms
            fprintf(stderr, "Timeout waiting for ECHO end\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_time = gpioTick();

    pulse_width = end_time - start_time;

    if (pulse_width <= 0) {
        fprintf(stderr, "Invalid pulse width: %ld\n", pulse_width);
        return -1.0; // Indicate invalid reading
    }

    float distance = (pulse_width / 2.0) * 0.0343; // Speed of sound: 0.0343 cm/us

    if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0; // Indicate out-of-range reading
    }

    return distance;
}

// Read LDR value from MCP3008 ADC
float read_ldr() {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed\n");
        return -1.0; // Indicate SPI error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return (float)adc_value;
}

// Map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < 0) return MIN_FREQUENCY; // Handle error case
    return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Map LDR value to duty cycle
float map_ldr_to_duty_cycle(float ldr_value) {
    if (ldr_value < 0) return MIN_DUTY_CYCLE; // Handle error case
    return MIN_DUTY_CYCLE + (ldr_value - 0) * (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE) / (1023.0 - 0); // Assuming 10-bit ADC
}

// Set PWM frequency
void set_pwm_frequency(float frequency) {
    // This is a placeholder.  The actual PWM frequency control is handled by the sysfs interface.
    // The frequency is set in init_pwm() and cannot be changed dynamically.
    // A more complete implementation would involve writing to the sysfs file directly.
    (void)frequency; // Suppress unused parameter warning
}

// Set PWM duty cycle
void set_pwm_duty_cycle(float duty_cycle) {
    FILE *fp;
    char buffer[64];

    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening PWM duty_cycle file\n");
        return;
    }
    fprintf(fp, "%d", (int)(duty_cycle * 1000)); // Duty cycle is a percentage
    fclose(fp);

    last_valid_duty_cycle = (int)(duty_cycle * 1000);
}

// Log data to file
void log_data(float distance, float frequency, float duty_cycle) {
    if (log_file == NULL) return; // Check if log file is open

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Frequency: %.2f Hz, Duty Cycle: %.2f%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, frequency, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file, using default calibration: %f\n", DEFAULT_CALIBRATION);
        calibration_factor = DEFAULT_CALIBRATION;
        return;
    }

    if (fscanf(fp, "%f", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from config file, using default calibration: %f\n", DEFAULT_CALIBRATION);
        calibration_factor = DEFAULT_CALIBRATION;
    }

    fclose(fp);
    printf("Calibration factor loaded: %f\n", calibration_factor);
}

// Save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file for writing\n");
        return;
    }

    fprintf(fp, "%f", calibration_factor);
    fclose(fp);
    printf("Calibration factor saved: %f\n", calibration_factor);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize logging
    log_file = fopen("theremin.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Load calibration data
    load_calibration();

    // Main loop
    while (running) {
        float distance = read_distance();
        float ldr_value = read_ldr();

        if (distance > 0) {
            last_valid_distance = (int)distance;
        } else {
            distance = last_valid_distance; // Use last valid distance
        }

        if (ldr_value >= 0) {
            last_valid_duty_cycle = (int)map_ldr_to_duty_cycle(ldr_value);
        } else {
            ldr_value = last_valid_duty_cycle / 1000.0; // Use last valid duty cycle
        }

        float frequency = map_distance_to_frequency(distance);
        set_pwm_frequency(frequency);
        set_pwm_duty_cycle(ldr_value / 1000.0); // Map ldr_value to duty cycle percentage

        log_data(distance, frequency, ldr_value);

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    gpioTerminate();
    fclose(log_file);

    return 0;
}

