    if (log_file == NULL) return; // Check if log file is open

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Frequency: %.2f Hz, Duty Cycle: %.2f%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, frequency, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file, using default calibration: %f\n", DEFAULT_CALIBRATION);
        calibration_factor = DEFAULT_CALIBRATION;
        return;
    }

    if (fscanf(fp, "%f", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from config file, using default calibration: %f\n", DEFAULT_CALIBRATION);
        calibration_factor = DEFAULT_CALIBRATION;
    }

    fclose(fp);
    printf("Calibration factor loaded: %f\n", calibration_factor);
}

// Save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file for writing\n");
        return;
    }

    fprintf(fp, "%f", calibration_factor);
    fclose(fp);
    printf("Calibration factor saved: %f\n", calibration_factor);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize logging
    log_file = fopen("theremin.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Load calibration data
    load_calibration();

    // Main loop
    while (running) {
        float distance = read_distance();
        float ldr_value = read_ldr();

        if (distance > 0) {
            last_valid_distance = (int)distance;
        } else {
            distance = last_valid_distance; // Use last valid distance
        }

        if (ldr_value >= 0) {
            last_valid_duty_cycle = (int)map_ldr_to_duty_cycle(ldr_value);
        } else {
            ldr_value = last_valid_duty_cycle / 1000.0; // Use last valid duty cycle
        }

        float frequency = map_distance_to_frequency(distance);
        set_pwm_frequency(frequency);
        set_pwm_duty_cycle(ldr_value / 1000.0); // Map ldr_value to duty cycle percentage

        log_data(distance, frequency, ldr_value);

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    gpioTerminate();
    fclose(log_file);

    return 0;
}

