    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value = -1; // Initialize to an invalid value

    // Construct SPI command
    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (spiXfer(spi_handle, tx, rx, 3) == 3) {
            // Extract ADC value
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d), retrying...\n", i + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read ADC after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    return adc_value;
