    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        return 1;
    }

    fprintf(stderr, "Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MQ3_CHANNEL);
        if (adc_value >= 0) {
            float ppm = adc_to_ppm(adc_value);
