            } else if (ppm < 20.0) {
                fprintf(stderr, "Sobriety confirmed.\n");
            } else {
                fprintf(stderr, "Alcohol level within acceptable range.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        sleep(1); // Sample every 1 second
    }

    cleanup();
    return 0;
}

