#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Motor 1 GPIOs
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIOs
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channel Definitions
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed Scaling Function Parameters
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion Profile Constants
#define ACCELERATION_TIME 1.0  // seconds
#define DECELERATION_TIME 1.0  // seconds
#define HOLD_TIME 2.0          // seconds
#define PAUSE_TIME 5.0         // seconds

// Global Variables
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int read_mcp3008(int channel);
float map_pot_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void move_motors(int pot1_value, int pot2_value);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map potentiometer value to speed factor using logarithmic function
float map_pot_to_speed(int pot_value) {
    float speed_factor = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * (1.0 - log10((float)pot_value + 1) / log10(1024.0));
    if (speed_factor < MIN_SPEED) speed_factor = MIN_SPEED;
    if (speed_factor > MAX_SPEED) speed_factor = MAX_SPEED;
    return speed_factor;
}

// Function to set motor speed using pigpio
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    }
}

// Function to move motors based on potentiometer values
void move_motors(int pot1_value, int pot2_value) {
    float speed1 = map_pot_to_speed(pot1_value);
    float speed2 = map_pot_to_speed(pot2_value);

    // Acceleration
    for (float i = MIN_SPEED; i <= speed1; i += (speed1 - MIN_SPEED) / (ACCELERATION_TIME * 10.0)) {
        set_motor_speed(1, (int)i);
        set_motor_speed(2, (int)i);
        gpioDelay(10000); // 10ms delay
    }

    // Hold
    gpioDelay(HOLD_TIME * 1000000); // Hold for 2 seconds

    // Deceleration
    for (float i = speed1; i >= MIN_SPEED; i -= (speed1 - MIN_SPEED) / (DECELERATION_TIME * 10.0)) {
        set_motor_speed(1, (int)i);
        set_motor_speed(2, (int)i);
        gpioDelay(10000); // 10ms delay
    }

    gpioDelay(PAUSE_TIME * 1000000); // Pause for 5 seconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(MOTOR1_ENABLE, 1000);
    gpioSetPWMfrequency(MOTOR2_ENABLE, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        printf("Potentiometer 1: %d, Potentiometer 2: %d\n", pot1_value, pot2_value);

        // Move motors
        move_motors(pot1_value, pot2_value);
    }

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Release resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

