#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CS 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_handle;
volatile int led_state = 0; // 0 = off, 1 = on
volatile unsigned long last_led_change = 0; // Time of last LED change

// Function prototypes
int read_mcp3008(int channel);
float calibrate_noise(int num_samples);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(SPI_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(SPI_CS, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate the noise level
float calibrate_noise(int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value during calibration\n");
            return -1.0; // Indicate error
        }
        sum += adc_value;
        gpioDelay(10000); // 10 ms delay
    }
    return sum / num_samples;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Calibrate noise level
    float noise_level = calibrate_noise(5000); // Calibrate for 5 seconds
    if (noise_level == -1.0) {
        fprintf(stderr, "Error: Noise calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    float threshold = noise_level * 1.10; // 10% above average

    printf("Noise level: %.2f, Threshold: %.2f\n", noise_level, threshold);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Debounce the LED
        unsigned long now = gpioTick();
        if (adc_value > threshold && (now - last_led_change) > 100000) { // 100 ms debounce
            gpioWrite(LED_PIN, 1); // Turn on LED
            led_state = 1;
            last_led_change = now;
        } else if (adc_value <= threshold && (now - last_led_change) > 100000) { // 100 ms debounce
            gpioWrite(LED_PIN, 0); // Turn off LED
            led_state = 0;
            last_led_change = now;
        }

        printf("ADC Value: %d, LED State: %d\n", adc_value, led_state);
        gpioDelay(10000); // 10 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

