int read_adc(int channel);
float voltage_to_slpm(int adc_value);
void log_data(float airflow);
void timer_callback();
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float vref;
    float slpm_min;
    float slpm_max;
    char log_file[64];
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    VREF,
    SLPM_MIN,
    SLPM_MAX,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

