#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define SAMPLE_RATE 1000         // 1 kHz
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8
#define LOG_FILE "audio_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_init(void);
int gpio_set_output(int chip, int line);
int gpio_set_value(int line, int value);
int gpio_get_value(int line);
int read_mcp3008(int channel);
void log_data(uint32_t timestamp_ns, int16_t raw_adc_value);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
  spi_fd = open(SPI_DEVICE, O_RDWR);
  if (spi_fd < 0) {
    perror("Error opening SPI device");
    return -1;
  }

  uint8_t mode = SPI_MODE;
  if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
    perror("Error setting SPI mode");
    close(spi_fd);
    return -1;
  }

  uint8_t bits = SPI_BITS_PER_WORD;
  if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
    perror("Error setting SPI bits per word");
    close(spi_fd);
    return -1;
  }

  uint32_t speed = SPI_MAX_SPEED_HZ;
  if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
    perror("Error setting SPI max speed");
    close(spi_fd);
    return -1;
  }

  return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
  struct spi_ioc_transfer tr = {
      .tx_buf = (unsigned long)tx_buf,
      .rx_buf = (unsigned long)rx_buf,
      .len = len,
      .speed_hz = SPI_MAX_SPEED_HZ,
      .bits_per_word = SPI_BITS_PER_WORD,
  };

  if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
    perror("Error during SPI transfer");
    return -1;
  }

  return 0;
}

// GPIO initialization function
int gpio_init(void) {
  gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
  if (!gpio_chip) {
    perror("Error opening GPIO chip");
    return -1;
  }

  cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_LINE);
  if (!cs_line) {
    perror("Error getting GPIO line");
    gpiod_chip_close(gpio_chip);
    return -1;
  }

  struct gpiod_line_request_config config;
  memset(&config, 0, sizeof(config));
  config.consumer = "audio_capture";
  config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

  if (gpiod_line_request(cs_line, &config, 0) < 0) {
    perror("Error requesting GPIO line");
    gpiod_chip_close(gpio_chip);
    return -1;
  }

  return 0;
}

// GPIO set output function
int gpio_set_output(int chip, int line) {
  struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name(chip);
  if (!chip_ptr) {
    perror("Error opening GPIO chip for output");
    return -1;
  }

  struct gpiod_line *line_ptr = gpiod_chip_get_line(chip_ptr, line);
  if (!line_ptr) {
    perror("Error getting GPIO line for output");
    gpiod_chip_close(chip_ptr);
    return -1;
  }

  struct gpiod_line_request_config config;
  memset(&config, 0, sizeof(config));
  config.consumer = "audio_capture";
  config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

  if (gpiod_line_request(line_ptr, &config, 0) < 0) {
    perror("Error requesting GPIO line for output");
    gpiod_chip_close(chip_ptr);
    return -1;
  }

  gpiod_chip_close(chip_ptr);
  return 0;
}

// GPIO set value function
int gpio_set_value(int line, int value) {
  if (gpiod_line_set_value(cs_line, value) < 0) {
    perror("Error setting GPIO value");
    return -1;
  }
  return 0;
}

// GPIO get value function
int gpio_get_value(int line) {
  int value = gpiod_line_get_value(cs_line);
  if (value < 0) {
    perror("Error getting GPIO value");
    return -1;
  }
  return value;
}

// Read MCP3008 function
int read_mcp3008(int channel) {
  uint8_t tx_buf[3];
  uint8_t rx_buf[3];

  // Construct SPI command
  tx_buf[0] = 0x01;                           // Start bit
  tx_buf[1] = (0x08 | channel) << 4;          // Single-ended, channel select
  tx_buf[2] = 0x00;                           // Dummy byte

  gpio_set_value(CS_GPIO_LINE, 0); // Assert CS
  if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
    gpio_set_value(CS_GPIO_LINE, 1); // De-assert CS
    return -1;
  }
  gpio_set_value(CS_GPIO_LINE, 1); // De-assert CS

  // Extract 10-bit ADC value
  int16_t adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
  return adc_value;
}

// Log data function
void log_data(uint32_t timestamp_ns, int16_t raw_adc_value) {
  if (log_file == NULL) {
    fprintf(stderr, "Log file not opened\n");
    return;
  }

  fprintf(log_file, "%u|%d\n", timestamp_ns, raw_adc_value);
  fflush(log_file); // Ensure data is written to disk
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, terminating...\n");
  terminate = 1;
}

// Cleanup function
void cleanup(void) {
  if (spi_fd != -1) {
    close(spi_fd);
  }
  if (gpio_chip) {
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);
  }
  if (log_file) {
    fclose(log_file);
  }
}

int main(void) {
  // Install signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize GPIO
  if (gpio_init() < 0) {
    fprintf(stderr, "GPIO initialization failed\n");
    cleanup();
    return 1;
  }

  // Initialize SPI
  if (spi_init() < 0) {
    fprintf(stderr, "SPI initialization failed\n");
    cleanup();
    return 1;
  }

  // Open log file
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Error opening log file");
    cleanup();
    return 1;
  }

  // Main loop
  struct timespec sleep_time;
  sleep_time.tv_sec = 0;
  sleep_time.tv_nsec = 1000000; // 1 ms

  while (!terminate) {
    // Read ADC value
    int16_t raw_adc_value = read_mcp3008(0);
    if (raw_adc_value < 0) {
      fprintf(stderr, "Error reading MCP3008\n");
      break; // Exit loop on error
    }

    // Get timestamp
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
      perror("Error getting timestamp");
      break; // Exit loop on error
    }
    uint32_t timestamp_ns = (uint32_t)ts.tv_sec * 1000000000 + (uint32_t)ts.tv_nsec;

    // Log data
    log_data(timestamp_ns, raw_adc_value);

    // Sleep for 1 ms
    nanosleep(&sleep_time, NULL);
  }

  // Cleanup and exit
  cleanup();
  return 0;
}

