    return;
  }

  fprintf(log_file, "%u|%d\n", timestamp_ns, raw_adc_value);
  fflush(log_file); // Ensure data is written to disk
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, terminating...\n");
  terminate = 1;
}

// Cleanup function
void cleanup(void) {
  if (spi_fd != -1) {
    close(spi_fd);
  }
  if (gpio_chip) {
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);
  }
  if (log_file) {
    fclose(log_file);
  }
}

int main(void) {
  // Install signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize GPIO
  if (gpio_init() < 0) {
    fprintf(stderr, "GPIO initialization failed\n");
    cleanup();
    return 1;
  }

  // Initialize SPI
  if (spi_init() < 0) {
    fprintf(stderr, "SPI initialization failed\n");
    cleanup();
    return 1;
  }

  // Open log file
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Error opening log file");
    cleanup();
    return 1;
  }

  // Main loop
  struct timespec sleep_time;
  sleep_time.tv_sec = 0;
  sleep_time.tv_nsec = 1000000; // 1 ms

  while (!terminate) {
    // Read ADC value
    int16_t raw_adc_value = read_mcp3008(0);
    if (raw_adc_value < 0) {
      fprintf(stderr, "Error reading MCP3008\n");
      break; // Exit loop on error
    }

    // Get timestamp
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
      perror("Error getting timestamp");
      break; // Exit loop on error
    }
    uint32_t timestamp_ns = (uint32_t)ts.tv_sec * 1000000000 + (uint32_t)ts.tv_nsec;

    // Log data
    log_data(timestamp_ns, raw_adc_value);

    // Sleep for 1 ms
    nanosleep(&sleep_time, NULL);
  }

  // Cleanup and exit
  cleanup();
  return 0;
}

