#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel numbers
#define MCP3008_X_CHANNEL 0
#define MCP3008_Y_CHANNEL 1
#define MCP3008_Z_CHANNEL 2

// Define CS pin for MCP3008
#define MCP3008_CS 8

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G 1.5 // 1.5V

// Define Kalman filter parameters
#define Q 0.01  // Process noise covariance
#define R 0.1   // Measurement noise covariance
#define P 1.0   // Initial error covariance

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
double x_state = 0.0;
double y_state = 0.0;
double z_state = 0.0;
double x_error_covariance = P;
double y_error_covariance = P;
double z_error_covariance = P;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_g(double voltage);
double kalman_filter(double measurement, double *state, double *error_covariance);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transaction failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC reading to voltage
double adc_to_voltage(int adc_value) {
    return (double)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to g-force
double voltage_to_g(double voltage) {
    return (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
}

// Function to apply Kalman filter
double kalman_filter(double measurement, double *state, double *error_covariance) {
    // Prediction step
    double predicted_state = *state;
    double predicted_error_covariance = *error_covariance + Q;

    // Update step
    double kalman_gain = predicted_error_covariance / (predicted_error_covariance + R);
    *state = predicted_state + kalman_gain * (measurement - predicted_state);
    *error_covariance = (1 - kalman_gain) * predicted_error_covariance;

    return *state;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(MCP3008_X_CHANNEL);
        int y_adc = read_mcp3008(MCP3008_Y_CHANNEL);
        int z_adc = read_mcp3008(MCP3008_Z_CHANNEL);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to voltage
        double x_voltage = adc_to_voltage(x_adc);
        double y_voltage = adc_to_voltage(y_adc);
        double z_voltage = adc_to_voltage(z_adc);

        // Convert voltage to g-force
        double x_g = voltage_to_g(x_voltage);
        double y_g = voltage_to_g(y_voltage);
        double z_g = voltage_to_g(z_voltage);

        // Apply Kalman filter
        double x_filtered = kalman_filter(x_g, &x_state, &x_error_covariance);
        double y_filtered = kalman_filter(y_g, &y_state, &y_error_covariance);
        double z_filtered = kalman_filter(z_g, &z_state, &z_error_covariance);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100); // 100 ms delay
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

