#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO4 4
#define GPIO17 17
#define GPIO27 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define VCC and sensitivity
#define VCC 3.3
#define SENSITIVITY 0.025 // 25 mV/mT

// Define quiescent voltage
#define V_QUIESCENT (VCC / 2.0)

// Define magnetic field range
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define log file name
#define LOG_FILE "magnetic_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line4 = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line27 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
float calculate_magnetic_field(int sensor_value);
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read sensor value from a GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to calculate magnetic field strength in milliteslas
float calculate_magnetic_field(int sensor_value) {
    if (sensor_value == 1) {
        return (V_QUIESCENT - VCC) / SENSITIVITY; // Assuming HIGH is 3.3V
    } else {
        return (V_QUIESCENT - 0.0) / SENSITIVITY; // Assuming LOW is 0V
    }
}

// Function to log data to a file
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Function to setup GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return -1;
    }

    line4 = gpiod_chip_get_line(chip, GPIO4);
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);

    if (!line4 || !line17 || !line27) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO4);
        if (line4) gpiod_line_release(line4);
