#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CSV_FILE "sensor_data.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_channel(int channel);
int log_data(FILE *fp, int channel, int value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from a specific channel
int spi_read_channel(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = 0x80 | (channel << 4);          // Single-ended mode + channel
    tx_buf[2] = 0x00;                           // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to a CSV file
int log_data(FILE *fp, int channel, int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d\n", timestamp, channel, value) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to close files and release resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel,ADC_Value\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < 3; channel++) {
            int adc_value = spi_read_channel(channel);
            if (adc_value >= 0) {
                if (log_data(csv_file, channel, adc_value) != 0) {
                    fprintf(stderr, "Error logging data for channel %d\n", channel);
                }
            } else {
                fprintf(stderr, "Error reading channel %d\n", channel);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

