#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int sig);
int mqtt_connect_with_reconnect(struct mosquitto **mosq);
int mqtt_subscribe(struct mosquitto *mosq, const char *topic);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
void set_led_state(int led_state);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        running = 0;
    }
}

// MQTT reconnect with exponential backoff
int mqtt_connect_with_reconnect(struct mosquitto **mosq) {
    int rc = 0;
    int reconnect_delay = 1;

    while (running) {
        rc = mosquitto_connect(*mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Connected to MQTT broker\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
            fprintf(stderr, "Reconnecting in %d seconds...\n", reconnect_delay);
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        }
    }
    return -1; // Shutdown requested
}

// MQTT subscribe
int mqtt_subscribe(struct mosquitto *mosq, const char *topic) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    printf("Subscribed to topic: %s\n", topic);
    return 0;
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        printf("Received message on topic: %s\n", message->topic);
        int led_state;
        if (parse_json_payload((const char *)message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            fprintf(stderr, "Error parsing JSON payload\n");
        }
    } else {
        fprintf(stderr, "Empty message received on topic: %s\n", message->topic);
    }
}

// Parse JSON payload
int parse_json_payload(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error parsing JSON: %s\n", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(led_state_json)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean\n");
        cJSON_Delete(json);
        return -1;
    }

    *led_state = cJSON_IsTrue(led_state_json);
    cJSON_Delete(json);
    return 0;
}

// Set LED state using pigpio
void set_led_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    printf("Setting LED state to: %d\n", led_state);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED initially

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create mosquitto instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        gpioTerminate();
        return 1;
    }

    // Set message callback
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker with reconnect
    if (mqtt_connect_with_reconnect(&mosq) != 0) {
        fprintf(stderr, "Failed to connect to MQTT broker after multiple retries\n");
        cleanup();
        return 1;
    }

    // Subscribe to topic
    if (mqtt_subscribe(mosq, MQTT_TOPIC) != 0) {
        cleanup();
        return 1;
    }

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Main loop (wait for signals)
    while (running) {
        sleep(1);
    }

    // Stop MQTT loop
    mosquitto_loop_stop(mosq, false);

    // Cleanup resources
    cleanup();

    return 0;
}

