float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * MCP3008_VREF;
    float temperature = voltage / LM35_VOLTAGE_PER_CELSIUS;
    return temperature;
}

// Add temperature reading to circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Write circular buffer to file
void write_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", LOG_FILE);
        return;
    }

    // Truncate file to BUFFER_SIZE * sizeof(float)
    fseek(fp, 0, SEEK_SET);
    fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    fflush(fp);
    fclose(fp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping this reading.\n");
            sleep(5);
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Add temperature to circular buffer
        add_to_buffer(temperature);

        // Log temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Write buffer to file every 5 seconds
        if (buffer_index == 0) {
            write_buffer_to_file();
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

