#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define BH1750_ADDR 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"

// Global variables for cleanup
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int addr);
int init_spi(const char *device);
int read_bh1750(int fd);
int read_mcp3008(int fd);
void log_data(FILE *fp, int light, int sound);
void signal_handler(int sig);

// Structure to hold sensor data
typedef struct {
    int light;
    int sound;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize SPI
int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read light level from BH1750
int read_bh1750(int fd) {
    uint8_t cmd = 0x10; // High resolution mode
    uint8_t buffer[2];
    int lux = -1; // Default error value

    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }

    usleep(180000); // Wait for measurement (at least 180ms)

    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Function to read sound level from MCP3008
int read_mcp3008(int fd) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message (MCP3008 single-ended channel 0)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to file
void log_data(FILE *fp, int light, int sound) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        sensor_data_t data;

        // Read sensor data
        data.light = read_bh1750(i2c_fd);
        data.sound = read_mcp3008(spi_fd);

        // Log data
        if (data.light != -1 && data.sound != -1) {
            log_data(log_file, data.light, data.sound);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log.\n");
        }

        sleep(1); // Sample every 1 second
    }

    return 0;
}

