#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x62
#define VREF 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
float map_temperature_to_voltage(float temperature);
int write_mcp4725(int i2c_handle, float voltage);
int log_data(float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to map temperature to DAC voltage
float map_temperature_to_voltage(float temperature) {
    float voltage = (temperature / 50.0) * VREF;
    if (voltage < 0.0) voltage = 0.0;
    if (voltage > VREF) voltage = VREF;
    return voltage;
}

// Function to write to MCP4725 DAC
int write_mcp4725(int i2c_handle, float voltage) {
    int dac_value = (int)(voltage / VREF * 4095.0);
    if (dac_value < 0) dac_value = 0;
    if (dac_value > 4095) dac_value = 4095;

    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write DAC value command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    tx_buffer[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    if (i2cWriteDevice(i2c_handle, tx_buffer, 3) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, voltage, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %.2f, %.2f, %.2f\n", timestamp, temperature, voltage, voltage);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        float temperature = convert_to_celsius(adc_value);
        float voltage = map_temperature_to_voltage(temperature);

        if (write_mcp4725(i2c_handle, voltage) != 0) {
            fprintf(stderr, "Error: Failed to write to DAC, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        if (log_data(temperature, voltage) != 0) {
            fprintf(stderr, "Error: Failed to log data, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(500); // Sample every 0.5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

