#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define CLAP_SENSOR_PIN 26
#define LED_PIN 16

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define LED on time in milliseconds
#define LED_ON_TIME 500

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int state);
void print_timestamped_message();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(CLAP_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set CLAP_SENSOR_PIN to input mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN to output mode\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    gpioSetMode(CLAP_SENSOR_PIN, PI_INPUT); // Ensure pin is in input mode

    // Read 10 bits of data
    for (i = 0; i < 10; i++) {
        // Set the clock pin high
        gpioSetMode(CLAP_SENSOR_PIN, PI_OUTPUT);
        gpioWrite(CLAP_SENSOR_PIN, 1);
        gpioDelay(1); // Small delay

        // Read the data pin
        gpioSetMode(CLAP_SENSOR_PIN, PI_INPUT);
        adc_value = adc_value << 1; // Shift the previous bits
        if (gpioRead(CLAP_SENSOR_PIN) == 1) {
            adc_value++;
        }

        // Set the clock pin low
        gpioSetMode(CLAP_SENSOR_PIN, PI_OUTPUT);
        gpioWrite(CLAP_SENSOR_PIN, 0);
        gpioDelay(1); // Small delay
    }

    return adc_value;
}

// Function to detect a clap based on the ADC value
int detect_clap(int adc_value) {
    // Define the threshold (700 out of 1023)
    int threshold = 700;

    // Check if the ADC value exceeds the threshold
    if (adc_value > threshold) {
        return 1; // Clap detected
    } else {
        return 0; // No clap detected
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to print a timestamped message
void print_timestamped_message() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: Clap detected!\n", timestamp);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the ADC value
        int adc_value = read_adc();

        // Detect a clap
        if (detect_clap(adc_value)) {
            // Debounce
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds

            // Re-read the ADC value after debounce
            adc_value = read_adc();

            // Re-detect the clap after debounce
            if (detect_clap(adc_value)) {
                // Turn on the LED
                control_led(1);

                // Print the timestamped message
                print_timestamped_message();

                // Turn off the LED
                control_led(0);

                // Delay for LED_ON_TIME
                gpioDelay(LED_ON_TIME * 1000); // Convert ms to microseconds
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    return 0;
}

