#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200.0 // mm

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read_value(int pin);
float voltage_to_distance(float voltage);
int log_distance(float distance);
void check_proximity(float distance);
void signal_handler(int signal);

// Structure to hold GPIO file paths
typedef struct {
    char export_path[64];
    char unexport_path[64];
    char direction_path[64];
    char value_path[64];
} gpio_paths_t;

// Function to generate GPIO paths
void generate_gpio_paths(int pin, gpio_paths_t *paths) {
    snprintf(paths->export_path, sizeof(paths->export_path), "%s/export", GPIO_PATH);
    snprintf(paths->unexport_path, sizeof(paths->unexport_path), "%s/unexport", GPIO_PATH);
    snprintf(paths->direction_path, sizeof(paths->direction_path), "%s/gpio%d/direction", GPIO_PATH, pin);
    snprintf(paths->value_path, sizeof(paths->value_path), "%s/gpio%d/value", GPIO_PATH, pin);
}

int main() {
    gpio_paths_t gpio_paths;
    generate_gpio_paths(GPIO_PIN, &gpio_paths);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Exiting.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read GPIO value
        int gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert GPIO value to voltage (0V or 3.3V)
        float voltage = (float)gpio_value;

        // Convert voltage to distance
