#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30.0
#define PUMP_GPIO_PIN 17
#define LOG_FILE "soil_moisture.log"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pump_line = NULL;
static FILE *log_file = NULL;
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_adc(int channel);
float calibrate_adc(int adc_value);
int control_pump(float moisture_percentage);
int log_data(float moisture_percentage, int pump_status);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calibrate ADC value to moisture percentage
float calibrate_adc(int adc_value) {
    float moisture_percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE)) * 100.0;
    if (moisture_percentage < 0.0) moisture_percentage = 0.0;
    if (moisture_percentage > 100.0) moisture_percentage = 100.0;
    return moisture_percentage;
}

// Function to control the water pump
int control_pump(float moisture_percentage) {
    int pump_status = 0; // 0 = OFF, 1 = ON

    if (moisture_percentage < MOISTURE_THRESHOLD) {
        if (gpiod_line_set_value(pump_line, 1) < 0) {
            perror("Error setting pump GPIO high");
            return -1;
        }
        pump_status = 1;
    } else {
        if (gpiod_line_set_value(pump_line, 0) < 0) {
            perror("Error setting pump GPIO low");
            return -1;
        }
        pump_status = 0;
    }
    return pump_status;
}

// Function to log data to file
int log_data(float moisture_percentage, int pump_status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f%%, %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");

    // Turn off the pump
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Release GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    pump_line = gpiod_chip_get_line(gpio_chip, PUMP_GPIO_PIN);
    if (!pump_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in 60 seconds...\n");
            sleep(60);
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d, skipping...\n", adc_value);
            sleep(60);
            continue;
        }

        // Calibrate ADC value
        float moisture_percentage = calibrate_adc(adc_value);

        // Control pump
        int pump_status = control_pump(moisture_percentage);

        // Log data
        log_data(moisture_percentage, pump_status);

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

