#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint32_t mode, uint8_t bits_per_word, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(const char *chip, int line);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_release(struct gpiod_chip *chip, struct gpiod_line *line);
int log_data(FILE *fp, time_t timestamp, float magnetic_field);
void signal_handler(int sig);
float adc_to_magnetic_field(int adc_value);

// SPI initialization function
int spi_init(const char *device, uint32_t mode, uint8_t bits_per_word, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode_data = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_data) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits_data = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_data) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed_data = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_data) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(const char *chip, int line) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip, strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", line, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "magnetic_field_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", line, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, time_t timestamp, float magnetic_field) {
    char timestamp_str[30];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(fp, "%s,%.2f\n", timestamp_str, magnetic_field) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// ADC to magnetic field conversion function
float adc_to_magnetic_field(int adc_value) {
    float vout_mV = (adc_value * 3300.0) / 1023.0;
    float magnetic_field_mt = (vout_mV - 1650.0) / 100.0;
    return magnetic_field_mt;
}

int main() {
