    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_LINE) < 0) {
        close(spi_fd);
        return 1;
    }

