    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpio_release(gpio_chip, gpio_line);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set CS low
        if (gpio_set_value(gpio_line, 0) < 0) {
