        uint8_t tx_buf[3];
        uint8_t rx_buf[3];
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = 0x80; // Single-ended, channel 0
        tx_buf[2] = 0x00; // Dummy byte

        // Perform SPI transfer
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "Error during SPI transfer, skipping sample.\n");
            // Attempt to set CS high before retrying
            gpio_set_value(gpio_line, 1);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
            continue;
        }

        // Set CS high
        if (gpio_set_value(gpio_line, 1) < 0) {
            break; // Exit loop on error
        }

        // Extract ADC value
        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Convert ADC value to magnetic field
        float magnetic_field = adc_to_magnetic_field(adc_value);

        // Get current timestamp
        time_t now = time(NULL);

        // Log data
        if (log_data(log_file, now, magnetic_field) < 0) {
            break; // Exit loop on error
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    gpio_set_value(gpio_line, 1); // Ensure CS is high
    gpio_release(gpio_chip, gpio_line);
    close(spi_fd);
    fclose(log_file);

    return 0;
}

