    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float voltage = voltage_from_adc(adc_value);
        float field_strength = magnetic_field_from_voltage(voltage);

        log_data(field_strength);
        control_led(field_strength);

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

