#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define LOG_FILE "current_log.txt"
#define SLEEP_DURATION_SEC 1

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip_ptr = NULL;
static struct gpiod_line *gpio_line_ptr = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float adc_to_current(int adc_value);
int gpio_init(int chip, int line);
int gpio_set_direction(int line, const char *direction);
int gpio_export(int chip, int line);
int gpio_unexport(int chip, int line);
int log_data(float current);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    // Assuming 10-bit ADC (0-1023) and 5V reference
    // MLX91209 sensitivity: 100 mV/A = 0.1 V/A
    // 5V / 0.1V/A = 50 A
    // 1023 / 50 A = 20.46 A/ADC
    return (float)adc_value / 20.46;
}

// GPIO initialization function
int gpio_init(int chip, int line) {
    gpio_chip_ptr = gpiod_chip_open_by_number(chip);
    if (!gpio_chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line_ptr = gpiod_chip_get_line(gpio_chip_ptr, line);
    if (!gpio_line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip_ptr);
        return -1;
    }

    return 0;
}

// GPIO set direction function
int gpio_set_direction(int line, const char *direction) {
    int ret = gpiod_line_set_direction(gpio_line_ptr, direction);
    if (ret < 0) {
        perror("Error setting GPIO direction");
        return -1;
    }
    return 0;
}

// GPIO export function
int gpio_export(int chip, int line) {
    int ret = gpiod_chip_export(gpio_chip_ptr, line);
    if (ret < 0) {
        perror("Error exporting GPIO line");
        return -1;
    }
    return 0;
}

// GPIO unexport function
int gpio_unexport(int chip, int line) {
    int ret = gpiod_chip_unexport(gpio_chip_ptr, line);
    if (ret < 0) {
        perror("Error unexporting GPIO line");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line_ptr) {
        gpio_unexport(GPIO_CHIP, GPIO_LINE);
    }
    if (gpio_chip_ptr) {
        gpiod_chip_close(gpio_chip_ptr);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("SPI initialized successfully.\n");

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_LINE) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }
    if (gpio_export(GPIO_CHIP, GPIO_LINE) < 0) {
        fprintf(stderr, "GPIO export failed. Exiting.\n");
        cleanup();
        return 1;
    }
    if (gpio_set_direction(GPIO_LINE, "in") < 0) {
        fprintf(stderr, "GPIO direction setting failed. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("GPIO initialized successfully.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", SLEEP_DURATION_SEC);
            sleep(SLEEP_DURATION_SEC);
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log data
        if (log_data(current) < 0) {
            fprintf(stderr, "Error logging data. Retrying in %d seconds.\n", SLEEP_DURATION_SEC);
        }

        printf("Current: %.2f A\n", current);

        // Sleep for 1 second
        sleep(SLEEP_DURATION_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

