#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    char *log_file;
    int sample_interval_ms;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
float voltage_conversion(int raw_value);
float current_conversion(float voltage);
int log_current_data(float current);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int raw_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return raw_value;
}

// Convert raw ADC value to voltage
float voltage_conversion(int raw_value) {
    return (raw_value / 1023.0) * 5.0;
}

// Convert voltage to current using MLX91211 datasheet formula
float current_conversion(float voltage) {
    if (voltage < 0.0 || voltage > 5.0) {
        fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
        return -1.0; // Indicate error
    }
    return (voltage - 2.5) * (50.0 / 2.5);
}

// Log current data to file
int log_current_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(SPI_CHANNEL, SPI_SPEED)) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_value = read_mcp3008(0);
        if (raw_value >= 0) {
            float voltage = voltage_conversion(raw_value);
            float current = current_conversion(voltage);

            if (current >= 0.0) {
                if (log_current_data(current)) {
                    fprintf(stderr, "Failed to log current data\n");
                }
            } else {
                fprintf(stderr, "Invalid current reading\n");
            }
        } else {
            fprintf(stderr, "Failed to read MCP3008 data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

