#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP 0
#define SENSOR1_LINE 4
#define SENSOR2_LINE 17

// Debounce samples
#define DEBOUNCE_SAMPLES 5

// Structure to hold GPIO chip and lines
struct gpio_data {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor1_line;
    struct gpiod_line *sensor2_line;
};

// Global variable to store GPIO data
struct gpio_data gpio_data_global;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_data_global.sensor1_line) {
        if (gpiod_line_release(gpio_data_global.sensor1_line) < 0) {
            fprintf(stderr, "Error releasing sensor 1 line\n");
        }
    }
    if (gpio_data_global.sensor2_line) {
        if (gpiod_line_release(gpio_data_global.sensor2_line) < 0) {
            fprintf(stderr, "Error releasing sensor 2 line\n");
        }
    }

    // Close GPIO chip
    if (gpio_data_global.chip) {
        if (gpiod_chip_close(gpio_data_global.chip) < 0) {
            fprintf(stderr, "Error closing GPIO chip\n");
        }
    }

    exit(0);
}

// Function to read sensor value with debouncing
int read_sensor(struct gpiod_line *line) {
    int samples[DEBOUNCE_SAMPLES];
    int i;

    // Sample the line DEBOUNCE_SAMPLES times
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            return -1; // Indicate error
        }
        samples[i] = value;
        usleep(2000); // 2 ms delay
    }

    // Count the number of LOW readings (object present)
    int low_count = 0;
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (samples[i] == 0) {
            low_count++;
        }
    }

    // Return 0 if majority of readings are LOW, 1 otherwise
    return (low_count > DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_data_global.chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!gpio_data_global.chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    gpio_data_global.sensor1_line = gpiod_chip_get_line(gpio_data_global.chip, SENSOR1_LINE);
    if (!gpio_data_global.sensor1_line) {
        fprintf(stderr, "Error getting sensor 1 line\n");
        gpiod_chip_close(gpio_data_global.chip);
        return 1;
    }

    gpio_data_global.sensor2_line = gpiod_chip_get_line(gpio_data_global.chip, SENSOR2_LINE);
    if (!gpio_data_global.sensor2_line) {
        fprintf(stderr, "Error getting sensor 2 line\n");
        gpiod_chip_close(gpio_data_global.chip);
        gpiod_line_release(gpio_data_global.sensor1_line);
        return 1;
    }

    // Request lines as input
    if (gpiod_line_request_input(gpio_data_global.sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting sensor 1 line as input\n");
        gpiod_chip_close(gpio_data_global.chip);
        gpiod_line_release(gpio_data_global.sensor1_line);
        gpiod_line_release(gpio_data_global.sensor2_line);
        return 1;
    }

    if (gpiod_line_request_input(gpio_data_global.sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting sensor 2 line as input\n");
        gpiod_chip_close(gpio_data_global.chip);
        gpiod_line_release(gpio_data_global.sensor1_line);
        gpiod_line_release(gpio_data_global.sensor2_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(gpio_data_global.sensor1_line);
        int sensor2_value = read_sensor(gpio_data_global.sensor2_line);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting\n");
            break; // Exit loop on error
        }

        // Log sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

        // Check for alert condition
        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_data_global.sensor1_line);
    gpiod_line_release(gpio_data_global.sensor2_line);
    gpiod_chip_close(gpio_data_global.chip);

    return 0;
}

