#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <stdbool.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60 // seconds
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
volatile sig_atomic_t terminate = 0;
int spi_handle = -1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value = -1; // Initialize to an invalid value

    // Construct SPI message
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = 0x80 | (channel << 4);          // Single-ended mode + channel
    tx_buf[2] = 0x00;                           // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Extract ADC value
    adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to calculate moisture level as a percentage
double calculate_moisture_level(int adc_value) {
    double moisture_percentage = 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }
    return moisture_percentage;
}

// Function to log data to a file
void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];
    FILE *fp;

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Format log entry
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f\n", timestamp, moisture_level);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    // Write log entry to file
    if (fputs(log_entry, fp) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
    }

    // Close log file
    fclose(fp);

    // Print to console
    printf("%s,%.2f\n", timestamp, moisture_level);
}

int spi_setup(spi_config_t config) {
    int handle = spiOpen(config.channel, config.baud, config.flags);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, handle);
        return -1;
    }
    return handle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .flags = 0 // No special flags needed for basic SPI
    };

    // Open SPI channel
    spi_handle = spi_setup(spi_config);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue; // Retry the loop
        }

        // Calculate moisture level
        double moisture_level = calculate_moisture_level(adc_value);

        // Log data
        log_data(moisture_level);

        // Delay
        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

