#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200 // milliseconds
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define ISO 8601
#define TARGET_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"

// Global variables
static volatile int running = 1;
static int last_state = 0; // Store the last known state

// Function prototypes
int initialize_pigpio();
int configure_gpio(int gpio_pin);
int read_gpio(int gpio_pin);
int capture_image(const char *filename);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");
    return 0;
}

// Function to configure GPIO pin as input with pull-down resistor
int configure_gpio(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN);
    syslog(LOG_INFO, "GPIO %d configured as input with pull-down resistor", gpio_pin);
    return 0;
}

// Function to read the state of the GPIO pin
int read_gpio(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -w %d -h %d --iso %d --immediate", filename, IMAGE_WIDTH, IMAGE_HEIGHT, ISO);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execl failed");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "Fork failed");
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            syslog(LOG_INFO, "Image captured successfully: %s", filename);
            return 0;
        } else {
            syslog(LOG_ERR, "Image capture failed with exit status: %d", WEXITSTATUS(status));
            return -1;
        }
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down...", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
    closelog();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO
    if (configure_gpio(GPIO_PIN) != 0) {
        cleanup();
        return 1;
    }

    // Create target directory if it doesn't exist
    struct stat st = {0};
    if (stat(TARGET_DIR, &st) == -1) {
        if (mkdir(TARGET_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create directory: %s", TARGET_DIR);
            cleanup();
            return 1;
        }
        syslog(LOG_INFO, "Directory created: %s", TARGET_DIR);
    }

    log_event("System started");

    // Main loop
    while (running) {
        int current_state = read_gpio(GPIO_PIN);

        if (current_state != last_state) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
            int debounced_state = read_gpio(GPIO_PIN);

            if (debounced_state == current_state) {
                last_state = current_state;

                if (current_state == 1) {
                    // Motion detected
                    time_t rawtime;
                    struct tm *timeinfo;
                    char filename[256];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(filename, sizeof(filename), TARGET_DIR "motion_%Y%m%d_%H%M%S.jpg", timeinfo);

                    if (capture_image(filename) != 0) {
                        log_event("Image capture failed");
                    } else {
                        log_event("Motion detected and image captured");
                    }
                }
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    cleanup();
    return 0;
}

