// Structure to hold V4L2 device information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
    char *filename;
    int frame_count;
} v4l2_device;

// Global variables
v4l2_device *devices = NULL;
int num_devices = 0;
int running = 1;

// Function prototypes
int init_device(v4l2_device *dev, const char *device_name);
int start_capturing(v4l2_device *dev);
int capture_frame(v4l2_device *dev);
int stop_capturing(v4l2_device *dev);
int uninit_device(v4l2_device *dev);
void signal_handler(int sig);
void cleanup();
int create_filename(const char *filename_template, int frame_number, char *filename, size_t filename_size);

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received (%d). Stopping streaming...\n", sig);
    running = 0;
}

// Function to create a filename based on the frame number
int create_filename(const char *filename_template, int frame_number, char *filename, size_t filename_size) {
    return snprintf(filename, filename_size, filename_template, frame_number);
}

// Function to initialize a V4L2 device
int init_device(v4l2_device *dev, const char *device_name) {
    dev->fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (dev->fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }

    if (ioctl(dev->fd, VIDIOC_QUERYCAP, &dev->cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(dev->fd);
        return -1;
    }

    if (!(dev->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(dev->fd);
        return -1;
    }

    if (!(dev->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device_name);
        close(dev->fd);
        return -1;
    }

    memset(&dev->fmt, 0, sizeof(dev->fmt));
    dev->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->fmt.fmt.pix.width = DEFAULT_WIDTH;
    dev->fmt.fmt.pix.height = DEFAULT_HEIGHT;
    dev->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    dev->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(dev->fd, VIDIOC_S_FMT, &dev->fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(dev->fd);
        return -1;
    }

    memset(&dev->req, 0, sizeof(dev->req));
    dev->req.count = 1; // Single buffer
    dev->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev->fd, VIDIOC_REQBUFS, &dev->req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(dev->fd);
        return -1;
    }

    memset(&dev->buf, 0, sizeof(dev->buf));
    dev->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->buf.memory = V4L2_MEMORY_MMAP;
    dev->buf.index = 0;

    if (ioctl(dev->fd, VIDIOC_QUERYBUF, &dev->buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(dev->fd);
        return -1;
    }

    dev->buffer_size = dev->buf.length;
    dev->buffer = mmap(NULL, dev->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, dev->fd, dev->buf.m.offset);
    if (dev->buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(dev->fd);
        return -1;
    }

    return 0;
}

// Function to start capturing frames
int start_capturing(v4l2_device *dev) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(dev->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(v4l2_device *dev) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(dev->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(dev->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(dev->fd, VIDIOC_DQBUF, &dev->buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Simulate processing (e.g., applying a filter)
    // In a real application, this would be replaced with actual image processing
    // For grayscale, we just need to ensure the data is valid
    if (dev->buf.bytesused > dev->buffer_size) {
        fprintf(stderr, "Error: Frame size exceeds buffer size\n");
        return -1;
    }

    // Save the frame to a file
    char filename[256];
    if (create_filename(dev->filename, dev->frame_count, filename, sizeof(filename)) < 0) {
        fprintf(stderr, "Error creating filename\n");
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fwrite(dev->buffer, 1, dev->buf.bytesused, fp);
    fclose(fp);

    dev->frame_count++;

    if (ioctl(dev->fd, VIDIOC_QBUF, &dev->buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to stop capturing frames
int stop_capturing(v4l2_device *dev) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(dev->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to uninitialize a V4L2 device
int uninit_device(v4l2_device *dev) {
    if (dev->buffer != MAP_FAILED && dev->buffer != NULL) {
        if (munmap(dev->buffer, dev->buffer_size) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    if (close(dev->fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    for (int i = 0; i < num_devices; i++) {
        if (devices[i].fd != -1) {
            uninit_device(&devices[i]);
        }
    }
    if (devices != NULL) {
        free(devices);
    }
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    const char *device_name = DEFAULT_DEVICE;
    const char *filename_template = DEFAULT_FILENAME;
    int device_index = 0;

    // Parse command-line arguments
    if (argc > 1) {
        device_name = argv[1];
    }
    if (argc > 2) {
        filename_template = argv[2];
    }
    if (argc > 3) {
        device_index = atoi(argv[3]);
        if (device_index < 0 || device_index >= num_devices) {
            fprintf(stderr, "Invalid device index. Using default device.\n");
            device_index = 0;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize devices
    num_devices = 1; // Assuming only one device for simplicity
    devices = (v4l2_device *)malloc(num_devices * sizeof(v4l2_device));
    if (devices == NULL) {
        fprintf(stderr, "Error allocating memory for devices\n");
        return 1;
    }

    if (init_device(&devices[0], device_name) < 0) {
        fprintf(stderr, "Failed to initialize device %s\n", device_name);
        cleanup();
        return 1;
    }

    devices[0].filename = strdup(filename_template);
    if (devices[0].filename == NULL) {
        fprintf(stderr, "Error allocating memory for filename\n");
        cleanup();
        return 1;
    }
    devices[0].frame_count = 1;

    // Start capturing
    if (start_capturing(&devices[0]) < 0) {
        fprintf(stderr, "Failed to start capturing\n");
        cleanup();
        return 1;
    }

    printf("Capturing frames from %s...\n", device_name);

    // Capture loop
    while (running) {
        if (capture_frame(&devices[0]) < 0) {
            fprintf(stderr, "Failed to capture frame\n");
            break;
        }
    }

    // Stop capturing and cleanup
    if (stop_capturing(&devices[0]) < 0) {
        fprintf(stderr, "Failed to stop capturing\n");
    }

    if (uninit_device(&devices[0]) < 0) {
        fprintf(stderr, "Failed to uninitialize device\n");
    }

    free(devices[0].filename);
    free(devices);

    printf("Captured %d frames.\n", devices[0].frame_count);

    return 0;
}

