static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int init_mmap(int fd, struct buffer **buffers, unsigned int *n_buffers)
{
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));

    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS failed\n");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    *n_buffers = req.count;
    *buffers = calloc(req.count, sizeof(**buffers));

    if (!*buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (*n_buffers = 0; *n_buffers < req.count; ++*n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = *n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed\n");
            return -1;
        }

        (*buffers)[*n_buffers].length = buf.length;
        (*buffers)[*n_buffers].start =
            mmap(NULL /* start anywhere */,
                 buf.length,
                 PROT_READ | PROT_WRITE /* required */,
                 MAP_SHARED /* recommended */,
                 fd, buf.m.offset);

        if (MAP_FAILED == (*buffers)[*n_buffers].start) {
            fprintf(stderr, "mmap failed\n");
            return -1;
        }
    }

    return 0;
}

static int start_capturing(int fd, struct buffer *buffers, unsigned int n_buffers)
{
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed\n");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON failed\n");
        return -1;
    }

    return 0;
}

static int stop_capturing(int fd)
{
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed\n");
        return -1;
    }

    return 0;
}

static int uninit_mmap(int fd, struct buffer *buffers, unsigned int n_buffers)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            fprintf(stderr, "munmap failed\n");
            return -1;
        }
    }

    free(buffers);

    return 0;
}

static int log_timestamp(FILE *fp, struct timeval tv)
{
    fprintf(fp, "%ld.%06ld\n", tv.tv_sec, tv.tv_usec);
    fflush(fp);
    return 0;
}

static void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, stopping...\n");
    stop = 1;
}

int main()
{
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return 1;
    }

    if (init_mmap(fd, &buffers, &n_buffers) < 0) {
        close(fd);
        return 1;
    }

    if (start_capturing(fd, buffers, n_buffers) < 0) {
        uninit_mmap(fd, buffers, n_buffers);
        close(fd);
        return 1;
    }

    log_file = fopen("frame_log.txt", "w");
    if (!log_file) {
        perror("Cannot open log file");
        stop_capturing(fd);
        uninit_mmap(fd, buffers, n_buffers);
        close(fd);
        return 1;
    }

    signal(SIGINT, signal_handler);

    fd_set fds;
    struct timeval tv;
    int r;
    unsigned int i;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    while (!stop) {
        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            perror("select()");
            break;
        }

        if (r == 0) {
            fprintf(stderr, "select() timeout\n");
            break;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            fprintf(stderr, "VIDIOC_DQBUF failed\n");
            break;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);

        log_timestamp(log_file, tv);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed\n");
            break;
        }
    }

    stop_capturing(fd);
    uninit_mmap(fd, buffers, n_buffers);
    fclose(log_file);
    close(fd);

    return 0;
}

