#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // YUYV
#define MAX_PAYLOAD_SIZE 65000
#define MAX_FRAGMENTS (MAX_PAYLOAD_SIZE / (FRAME_SIZE / 2)) // Assuming 2 bytes per YUYV pair
#define HEADER_SIZE 8

// Structure to hold frame data and header
typedef struct {
    unsigned char *data;
    size_t size;
