#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM period (20 ms)
#define PWM_PERIOD 20000

// Define PWM duty cycle range
#define PWM_MIN 50
#define PWM_MAX 1000

// Define servo range
#define SERVO_MIN 25
#define SERVO_MAX 125

// Global variables
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_servo_position(int servo_pin, int position);
void handle_button_press(int button_pin, int servo_pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pins as output
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);

    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Set servo position using PWM
void set_servo_position(int servo_pin, int position) {
    // Map position (25-125) to duty cycle (50-1000)
    int duty_cycle = PWM_MIN + (int)(((float)(position - SERVO_MIN) / (SERVO_MAX - SERVO_MIN)) * (PWM_MAX - PWM_MIN));

    gpioPWM(servo_pin, duty_cycle);
}

// Handle button press
void handle_button_press(int button_pin, int servo_pin) {
    static int servo_position = 75; // Initial position

    if (button_pin == PAN_LEFT_PIN) {
        servo_position -= 5;
        if (servo_position < SERVO_MIN) {
            servo_position = SERVO_MIN;
        }
    } else if (button_pin == PAN_RIGHT_PIN) {
        servo_position += 5;
        if (servo_position > SERVO_MAX) {
            servo_position = SERVO_MAX;
        }
    } else if (button_pin == TILT_UP_PIN) {
        servo_position += 5;
        if (servo_position > SERVO_MAX) {
            servo_position = SERVO_MAX;
        }
    } else if (button_pin == TILT_DOWN_PIN) {
        servo_position -= 5;
        if (servo_position < SERVO_MIN) {
            servo_position = SERVO_MIN;
        }
    }

    set_servo_position(servo_pin, servo_position);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, 75);
    set_servo_position(TILT_SERVO_PIN, 75);

    // Main loop
    while (running) {
        // Check button states and handle button presses
        if (gpioRead(PAN_LEFT_PIN) == 0) {
            handle_button_press(PAN_LEFT_PIN, PAN_SERVO_PIN);
        }
        if (gpioRead(PAN_RIGHT_PIN) == 0) {
            handle_button_press(PAN_RIGHT_PIN, PAN_SERVO_PIN);
        }
        if (gpioRead(TILT_UP_PIN) == 0) {
            handle_button_press(TILT_UP_PIN, TILT_SERVO_PIN);
        }
        if (gpioRead(TILT_DOWN_PIN) == 0) {
            handle_button_press(TILT_DOWN_PIN, TILT_SERVO_PIN);
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms
    }

    return 0;
}

