// Configuration
#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define JPEG_QUALITY 75
#define BLUR_KERNEL_SIZE 5
#define BLUR_KERNEL_RADIUS 2

// Global variables
static int fd = -1;
static struct v4l2_buffer buf;
static unsigned char *buffers[4];
static unsigned int n_buffers;
static volatile sig_atomic_t stop = 0;

// Structure to hold image data
typedef struct {
    unsigned char *data;
    size_t size;
} image_data_t;

// Structure to hold JPEG data
typedef struct {
    unsigned char *data;
    size_t size;
} jpeg_data_t;

// Error handling function
void error_exit(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
    exit(EXIT_FAILURE);
}

// Signal handler
void signal_handler(int sig) {
    stop = 1;
    printf("Caught signal %d, exiting...\n", sig);
}

// Function to initialize the camera
int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        error_exit("Cannot open device");
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        error_exit("VIDIOC_QUERYCAP failed");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s: %s\n", DEVICE_NAME, "is no video capture device");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s: %s\n", DEVICE_NAME, "does not support streaming i/o");
        exit(EXIT_FAILURE);
    }

    // Set format
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        error_exit("VIDIOC_S_FMT failed");
    }

    // Request buffers
    CLEAR(req);
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        error_exit("VIDIOC_REQBUFS failed");
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        exit(EXIT_FAILURE);
    }

    // Map the buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            error_exit("VIDIOC_QUERYBUF failed");
        }

        buffers[n_buffers] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers] == MAP_FAILED) {
            error_exit("mmap failed");
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    unsigned int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    // Queue the buffers
    for (i = 0; i < n_buffers; ++i) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            error_exit("VIDIOC_QBUF failed");
        }
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        error_exit("VIDIOC_STREAMON failed");
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(image_data_t *image) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Select interrupted by signal\n");
            return -1; // Interrupted by signal
        }
        error_exit("select failed");
    }

    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1; // Timeout
    }

    // Dequeue the buffer
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        error_exit("VIDIOC_DQBUF failed");
    }

    // Allocate memory for the captured frame
    image->data = (unsigned char *)malloc(buf.bytesused);
    if (image->data == NULL) {
        error_exit("Failed to allocate memory for captured frame");
    }
    image->size = buf.bytesused;

    // Copy the frame data from the buffer
    memcpy(image->data, buffers[buf.index], buf.bytesused);

    // Queue the buffer again
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        error_exit("VIDIOC_QBUF failed");
    }

    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    unsigned char *y, *u, *v;
    unsigned char *r, *g, *b;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            y = yuyv + (i * width * 2) + (j * 2);
            u = y + 1;
            v = y + 3;

            r = rgb + (i * width * 3) + (j * 3);
            g = r + 1;
            b = r + 2;

            *r = *y + 1.0 * (*u - 128) * 0.29900;
            *g = *y - 0.16874 * (*u - 128) - 0.33126 * (*v - 128);
            *b = *y + 1.13983 * (*v - 128);

            if (j + 1 < width) {
                *r = *y + 1.0 * (*u - 128) * 0.29900;
                *g = *y - 0.16874 * (*u - 128) - 0.33126 * (*v - 128);
                *b = *y + 1.13983 * (*v - 128);

                y += 2;
                u += 2;
                v += 2;
                r += 3;
                g += 3;
                b += 3;
            }
        }
    }
}

// Function to apply a 5x5 box blur filter
void box_blur(unsigned char *input, unsigned char *output, int width, int height, int radius) {
    int i, j, k, l;
    int sum;
    unsigned char *pixel;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            sum = 0;
            for (k = -radius; k <= radius; k++) {
                for (l = -radius; l <= radius; l++) {
                    int x = j + l;
                    int y = i + k;

                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        sum += input[(y * width + x) * 3];
                    }
                }
            }
            output[(i * width + j) * 3] = (unsigned char)(sum / (BLUR_KERNEL_SIZE * BLUR_KERNEL_SIZE));
        }
    }
}

