#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control ctrl;
    int focus_supported = 0;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);

    // Check if the device supports frame size enumeration
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) < 0) {
        perror("Error enumerating formats");
        close(fd);
        return 1;
    }

    // Enumerate frame sizes
    frmsize.index = 0;
    frmsize.pixel_format = fmtdesc.pixelformat;
    frmsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;
    printf("\nSupported Resolutions:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  Continuous resolution range\n");
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  Stepwise resolution range\n");
        }
        frmsize.index++;
    }

    // Enumerate frame intervals
    frmival.index = 0;
    frmival.pixel_format = fmtdesc.pixelformat;
    frmival.type = V4L2_FRMIVAL_TYPE_DISCRETE;
    printf("\nSupported Frame Rates:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("  %d/%d (%f fps)\n", frmival.discrete.numerator, frmival.discrete.denominator, (float)frmival.discrete.numerator / frmival.discrete.denominator);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
            printf("  Continuous frame rate range\n");
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("  Stepwise frame rate range\n");
        }
        frmival.index++;
    }

    // Check for autofocus support
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) == 0) {
        focus_supported = 1;
    } else {
        perror("Error querying focus control");
    }

    if (focus_supported) {
        printf("\nAutofocus supported: Yes\n");
    } else {
        printf("\nAutofocus supported: No\n");
    }

    close(fd);
    return 0;
}

