#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define SERVER_URL_BASE "http://"
#define SERVER_URL_PORT ":8080"
#define SERVER_URL_PATH "/upload"

// Global variables
static volatile int running = 1;
static char *server_ip = NULL;
static int server_port = 0;
static char *server_url = NULL;

// Structure to hold the response from libcurl
typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

// Callback function for libcurl to write the response to memory
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;

    return realsize;
}

// Function to capture an image using libcamera-still
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -w %d -h %d --quality %d --timeout 1000", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    }
    return (WIFEXITED(status) && WEXITSTATUS(status) == 0) ? 0 : -1; // Check if the command executed successfully
}

// Function to generate a timestamp string
void generate_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    char micros[7];
    snprintf(micros, 7, ".%06ldZ", ts.tv_nsec / 1000);
    strcat(timestamp, micros);
}

// Function to create the JSON payload
int create_json_payload(char *filename, char *timestamp, char *motion_status, char *gpio_pin, char *json_payload) {
    snprintf(json_payload, 256, "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": \"%s\", \"gpio_pin\": \"%d\"}",
             filename, timestamp, motion_status, GPIO_PIN);
    return 0;
}

// Function to send the JSON payload to the server using libcurl
int send_payload(const char *json_payload) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.data = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, server_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("Response: %s\n", chunk.data);
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    free(chunk.data);
    return (res == CURLE_OK) ? 0 : -1;
}

// Function to handle motion detection
void handle_motion() {
    char filename[64];
    char timestamp[30];
    char json_payload[256];
    char motion_status[10] = "Motion Detected";

    // Generate filename
    generate_timestamp(timestamp);
    snprintf(filename, sizeof(filename), "motion_captures/%s.jpg", timestamp);

    // Capture image
    if (capture_image(filename) != 0) {
        fprintf(stderr, "Failed to capture image\n");
        return;
    }

    // Create JSON payload
    create_json_payload(filename, timestamp, motion_status, GPIO_PIN, json_payload);

    // Send payload
    if (send_payload(json_payload) != 0) {
        fprintf(stderr, "Failed to send payload\n");
    }
}

// Function to handle motion detection with debounce
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 1) { // Rising edge (motion detected)
        if (current_tick - last_tick > DEBOUNCE_TIME * 1000000) { // Debounce
            handle_motion();
            last_tick = current_tick;
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Function to create the motion_captures directory
int create_directory() {
    struct stat st = {0};

    if (stat("motion_captures", &st) == -1) {
        if (mkdir("motion_captures", 0777) == -1) {
            perror("mkdir");
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);
    if (server_port <= 0) {
        fprintf(stderr, "Invalid server port\n");
        return 1;
    }

    // Construct server URL
    char server_url_buffer[256];
    snprintf(server_url_buffer, sizeof(server_url_buffer), "%s%s%s", SERVER_URL_BASE, server_ip, SERVER_URL_PORT);
    server_url = strdup(server_url_buffer);
    if (server_url == NULL) {
        perror("strdup");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Create the motion_captures directory
    if (create_directory() != 0) {
        fprintf(stderr, "Failed to create motion_captures directory\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for motion detection
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    free(server_url);

    return 0;
}

