#define IMAGE_QUALITY 85
#define IMAGE_TIMEOUT 2000 // milliseconds
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_gpio(void);
int capture_image(void);
void log_event(const char *format, ...);
void signal_handler(int sig);
void cleanup(void);

// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y%m%d_%H%M%S", timeinfo);
}

// Initialize GPIO
int init_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read GPIO value
int read_gpio(void)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Capture image using libcamera-still
int capture_image(void)
{
    char filename[100];
    get_timestamp(filename);
    snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename), "_mmm.jpg", filename);

    char command[200];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d -q %d --timeout %d --nopreview",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY, IMAGE_TIMEOUT);

    int status = system(command);
    if (status == -1) {
        perror("Error executing libcamera-still");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        log_event("Error: libcamera-still exited with status %d", WEXITSTATUS(status));
        return -1;
    }

    char log_message[200];
    snprintf(log_message, sizeof(log_message), "Captured image: %s", filename);
    log_event(log_message);
    return 0;
}

// Log event to file
void log_event(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, buffer);
}

// Signal handler
void signal_handler(int sig)
{
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal %d, terminating...", sig);
        terminate = 1;
    }
}

// Cleanup resources
void cleanup(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main(void)
{
    openlog("motion_capture", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_event("GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    log_event("Motion capture started");

    // Main loop
    while (!terminate) {
        int value = read_gpio();
        if (value < 0) {
            log_event("Error reading GPIO, retrying...");
            usleep(100000); // 100 ms
            continue;
        }

        if (value == 1) {
            log_event("Motion detected!");
            if (capture_image() < 0) {
                log_event("Image capture failed");
            }
            usleep(DEBOUNCE_DELAY_NS); // Debounce
        }

        usleep(10000); // Check every 10 ms
    }

    // Cleanup and exit
    cleanup();
    log_event("Motion capture stopped");
    return 0;
}

