#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static volatile int keep_running = 1;
static int fd = -1;
static void *buffer = NULL;
static struct v4l2_buffer buf;
static struct v4l2_capability cap;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static unsigned int n_buffers;

static void int_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main()
{
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        close(fd);
        return EXIT_FAILURE;
    }

    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        close(fd);
        return EXIT_FAILURE;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF failed");
        close(fd);
        return EXIT_FAILURE;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == buffer) {
        perror("mmap failed");
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF failed");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        perror("select error");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (0 == r) {
        fprintf(stderr, "select timeout\n");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF failed");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (buf.bytesused != buf.length) {
        fprintf(stderr, "Captured frame size (%d) does not match requested size (%d)\n", buf.bytesused, buf.length);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (buf.width != WIDTH || buf.height != HEIGHT) {
        fprintf(stderr, "Captured frame dimensions (%dx%d) do not match requested dimensions (%dx%d)\n", buf.width, buf.height, WIDTH, HEIGHT);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (buf.bytesused < WIDTH * HEIGHT * 2) {
        fprintf(stderr, "Captured frame size (%d) is smaller than expected (%d)\n", buf.bytesused, WIDTH * HEIGHT * 2);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen failed");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *src = buffer;
    unsigned char *dst = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!dst) {
        perror("malloc failed");
        fclose(fp);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    for (int y = CROP_Y; y < CROP_Y + CROP_HEIGHT; y++) {
        for (int x = CROP_X; x < CROP_X + CROP_WIDTH; x++) {
            int src_y = (y * WIDTH + x) * 2;
            int dst_y = (y - CROP_Y) * CROP_WIDTH * 2 + (x - CROP_X) * 2;
            dst[dst_y] = src[src_y];
            dst[dst_y + 1] = src[src_y + 1];
        }
    }

    fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp);
    fclose(fp);
    free(dst);
    munmap(buffer, buf.length);
    close(fd);

    return EXIT_SUCCESS;
}

