#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define neutral angle
#define NEUTRAL_ANGLE 90

// Define PWM pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int set_pan_angle(int angle);
int set_tilt_angle(int angle);
void handle_input();
void signal_handler(int signal);

// Signal handler for Ctrl+C and 'q' key
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal, exiting gracefully...\n");
        set_pan_angle(NEUTRAL_ANGLE);
        set_tilt_angle(NEUTRAL_ANGLE);
