int set_tilt_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Tilt angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
