            if (new_pan_angle < MIN_ANGLE) new_pan_angle = MIN_ANGLE;
            set_pan_angle(new_pan_angle);
            pan_angle = new_pan_angle;
            break;
        case 'a':
            new_tilt_angle = tilt_angle - 5;
            if (new_tilt_angle < MIN_ANGLE) new_tilt_angle = MIN_ANGLE;
