// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp_milli_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temp_milli_celsius = atoi(buffer);
    return temp_milli_celsius;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[1024];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Failed to open /proc/stat");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read /proc/stat");
        fclose(fp);
        return -1.0;
    }

    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    unsigned long long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0, prev_iowait = 0, prev_irq = 0, prev_softirq = 0, prev_steal = 0, prev_guest = 0, prev_guest_nice = 0;
    static unsigned long long prev_user_sys = 0, prev_idle_sys = 0;

    FILE *fp_stat = fopen("/proc/stat", "r");
    if (fp_stat == NULL) {
        perror("Failed to open /proc/stat for second read");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp_stat) == NULL) {
        perror("Failed to read /proc/stat for second read");
        fclose(fp_stat);
        return -1.0;
    }

    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat for second read\n");
        fclose(fp_stat);
        return -1.0;
    }

    fclose(fp_stat);

    unsigned long long user_diff = user - prev_user;
    unsigned long long nice_diff = nice - prev_nice;
    unsigned long long system_diff = system - prev_system;
    unsigned long long idle_diff = idle - prev_idle;
    unsigned long long iowait_diff = iowait - prev_iowait;
    unsigned long long irq_diff = irq - prev_irq;
    unsigned long long softirq_diff = softirq - prev_softirq;
    unsigned long long steal_diff = steal - prev_steal;
    unsigned long long guest_diff = guest - prev_guest;
    unsigned long long guest_nice_diff = guest_nice - prev_guest_nice;

    unsigned long long prev_user_sys_diff = user_diff + system_diff;
    unsigned long long prev_idle_sys_diff = idle_diff + iowait_diff;

    unsigned long long total_diff = prev_user_sys_diff + prev_idle_sys_diff;
    unsigned long long idle_diff_sys = prev_idle_sys_diff;

    usage = (float)(total_diff - idle_diff_sys) / total_diff * 100.0;

    return usage;
}

// Function to display text on the OLED screen
void display_text(int x, int y, const char *text) {
    int i, j;
    unsigned char c;
    int char_x = x;
    int char_y = y;

    for (i = 0; text[i] != '\0'; i++) {
        c = text[i];

        // Check if character is in the font array
        if (c >= 32 && c <= 126) {
            // Calculate the starting position for the character
            int char_index = c - 32;
            unsigned char *char_data = font[char_index];

            // Write the character data to the OLED
            for (j = 0; j < 5; j++) {
                oled_write_data(char_data[j]);
            }
            oled_write_data(0x00); // Add a space between characters

            // Update the x position for the next character
            char_x += 6; // Each character is 6 pixels wide (5 pixels of data + 1 pixel spacing)
        } else {
            // If the character is not found in the font, skip it
            fprintf(stderr, "Character '%c' not found in font\n", c);
        }
    }
}

// Function to display temperature on the OLED screen
void display_temperature(float temp) {
    char temp_str[20];
    snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temp / 1000.0);
    display_text(0, 0, temp_str);
}

