#include <pigpio.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int running = 1;
int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulses);
void log_data(double flow_rate, double total_volume);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(const char *text);

// Function to initialize the LCD
int lcd_init() {
    // Initialization sequence (adjust based on your LCD's datasheet)
    char init_commands[] = {0x33, 0x32, 0x28, 0x0C, 0x06, 0x01};
    int i;

    for (i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) < 0) {
            fprintf(stderr, "Error initializing LCD: %d\n", i2c_handle);
            return -1;
        }
        gpioDelay(5000); // Wait 5ms
    }

    return 0;
}

// Function to clear the LCD
void lcd_clear() {
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error clearing LCD: %d\n", i2c_handle);
    }
    gpioDelay(2000); // Wait 2ms
}

// Function to print text to the LCD
void lcd_print(const char *text) {
    int i;
    int len = strlen(text);
    char data[LCD_WIDTH + 1];

    for (i = 0; i < len; i++) {
        data[i] = text[i];
    }
    data[len] = '\0';

    for (i = 0; i < len; i++) {
        if (i2cWriteByteData(i2c_handle, 0x40, data[i]) < 0) {
            fprintf(stderr, "Error writing to LCD: %d\n", i2c_handle);
        }
    }
}

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER / (60.0 / 1000.0); // Liters per minute
}

