#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define PULSE_PER_LITER 7.5
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);

// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses) {
    return (float)pulses / PULSE_PER_LITER * 60.0;
}

// Function to display flow rate on LCD1602
void display_flow_rate(float flow_rate) {
    char buffer[17]; // Ensure buffer is large enough
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// LCD initialization function
int lcd_init() {
    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return -1;
    }

    // Initialize LCD (4-bit mode, 2 lines, 5x8 font)
    // Send initialization commands (refer to LCD datasheet)
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x33); // Initialize
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x32); // Initialize
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x0C); // Display on, cursor off, blink off
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x06); // Increment cursor, no shift
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display

    return 0;
}

// LCD clear function
void lcd_clear() {
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display command
    gpioDelay(2); // Delay for clear display to complete
}

// LCD set cursor function
void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else {
        addr = 0x40 + col;
    }
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x80 | addr); // Set DDRAM address
}

// LCD print function
void lcd_print(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        wiringPiI2CWriteReg8(i2c_fd, 0x00, str[i]); // Send character
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on rising edge
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate
        display_flow_rate(flow_rate);

        // Print flow rate to console
        printf("Flow Rate: %.2f L/min\n", flow_rate);
    }

    // Clean up
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable interrupt
    gpioTerminate();
    lcd_clear(); // Clear LCD before exiting
    close(i2c_fd);

    return 0;
}

