#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows (anodes)
const int rows[] = {17, 18, 27, 22, 23, 24, 25, 4};
// Define GPIO pins for columns (cathodes)
const int cols[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Number of rows and columns
const int numRows = sizeof(rows) / sizeof(rows[0]);
const int numCols = sizeof(cols) / sizeof(cols[0]);

// Wave delay in microseconds
const int waveDelay = 800;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set row pins as outputs
    for (int i = 0; i < numRows; i++)
    {
        gpioSetMode(rows[i], PI_OUTPUT);
        gpioWrite(rows[i], 0); // Initialize rows to LOW (off)
    }

    // Set column pins as outputs
    for (int i = 0; i < numCols; i++)
    {
        gpioSetMode(cols[i], PI_OUTPUT);
        gpioWrite(cols[i], 1); // Initialize columns to HIGH (off)
    }

    return 0; // Indicate success
}

// Function to clear the LED matrix
void clear_matrix()
{
    for (int i = 0; i < numCols; i++)
    {
        gpioWrite(cols[i], 1); // Turn off all columns
    }
}

// Function to display a single frame of the wave pattern
void display_wave_frame(int direction)
{
    clear_matrix();

    int start_col = (direction == 1) ? 0 : numCols - 1;
    int end_col = (direction == 1) ? numCols : -1; // Start from the end
    int step = (direction == 1) ? 1 : -1;

    for (int col = start_col; col != end_col; col += step)
    {
        gpioWrite(cols[col], 0); // Turn on the current column
        gpioDelay(waveDelay);
    }
}

// Function to perform the wave animation
void wave_animation()
{
    while (!terminate)
    {
        display_wave_frame(1); // Left-to-right
        display_wave_frame(-1); // Right-to-left
    }
}

// Function to clean up GPIO pins
void cleanup_gpio()
{
    // Turn off all LEDs
    for (int i = 0; i < numRows; i++)
    {
        gpioWrite(rows[i], 0); // Turn off all rows
    }
    for (int i = 0; i < numCols; i++)
    {
        gpioWrite(cols[i], 1); // Turn off all columns
    }

    gpioTerminate();
    fprintf(stderr, "GPIO cleanup complete.\n");
}

int main()
{
    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Wave animation started. Press Ctrl+C to exit.\n");

    // Run the wave animation
    wave_animation();

    // Clean up GPIO before exiting
    cleanup_gpio();

    return 0;
}

