#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define row and column GPIO numbers
int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *row_lines[8];
struct gpiod_line *col_lines[8];

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int sig);
void clear_matrix();
void set_column(int col);
void scan_columns();

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request row lines
    for (int i = 0; i < 8; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            perror("Error getting row line");
            cleanup_gpio();
            return -1;
        }
        if (gpiod_line_request(row_lines[i], "wave_animation", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            perror("Error requesting row line as output");
            cleanup_gpio();
            return -1;
        }
        gpiod_line_set_value(row_lines[i], 1); // Initialize all rows HIGH
    }

    // Request column lines
    for (int i = 0; i < 8; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            perror("Error getting column line");
            cleanup_gpio();
            return -1;
        }
        if (gpiod_line_request(col_lines[i], "wave_animation", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            perror("Error requesting column line as output");
            cleanup_gpio();
            return -1;
        }
        gpiod_line_set_value(col_lines[i], 1); // Initialize all columns HIGH
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(col_lines[i], 1);
        gpiod_line_set_value(row_lines[i], 0);
    }
}

// Function to set a specific column LOW
void set_column(int col) {
    if (col < 0 || col > 7) {
        fprintf(stderr, "Error: Invalid column number %d\n", col);
        return;
    }
    gpiod_line_set_value(col_lines[col], 0);
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(row_lines[i], 1);
    }
}

// Function to scan columns and create a wave-like animation
void scan_columns() {
    for (int i = 0; i < 8; i++) {
        set_column(i);
        usleep(150000); // 150 ms delay
        clear_matrix();
    }
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio() {
    // Release row lines
    for (int i = 0; i < 8; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }

    // Release column lines
    for (int i = 0; i < 8; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Wave animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        scan_columns();
    }

    return 0;
}

