#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C

// Define the distance register address
#define DISTANCE_REG 0x0D

// Define the log file name
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int address);
int read_distance(int handle);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read distance from the sensor
int read_distance(int handle) {
    char buf[1];
    char data[2];
    int result;

    // Write the register address to be read
    buf[0] = DISTANCE_REG;
    result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read two bytes from the distance register
    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert the two bytes to a 16-bit integer (big-endian)
    int distance = (data[0] << 8) | data[1];
    return distance;
}

// Log data to the CSV file
int log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write the data to the file
    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    config_t config = {I2C_BUS, MLX75031_ADDR, LOG_FILE};

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, but continuing...\n");
        }

        gpioDelay(100); // Sample every 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

