#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_COMMAND 0x18

// Si1145 commands
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init(int i2c_handle);
int si1145_read_data(int i2c_handle, int *proximity, int *ambient_light);
void log_data(FILE *log_file, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Si1145 initialization function
int si1145_init(int i2c_handle) {
    int part_id;

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify PART ID
    part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read PART ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rates (example values)
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to set ALS force command\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to set PS force command\n");
        return -1;
    }

    return 0;
}

// Si1145 data reading function
int si1145_read_data(int i2c_handle, int *proximity, int *ambient_light) {
    int als_vis_data0, als_vis_data1, ps1_data0, ps1_data1;

    als_vis_data0 = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    als_vis_data1 = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);
    ps1_data0 = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    ps1_data1 = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0 + 1);

    if (als_vis_data0 < 0 || als_vis_data1 < 0 || ps1_data0 < 0 || ps1_data1 < 0) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    *ambient_light = (als_vis_data1 << 8) | als_vis_data0;
    *proximity = ps1_data1;

    return 0;
}

// Data logging function
void log_data(FILE *log_file, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int proximity, ambient_light;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    init_result = si1145_init(i2c_handle);
    if (init_result != 0) {
        fprintf(stderr, "Error: Si1145 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (si1145_read_data(i2c_handle, &proximity, &ambient_light) == 0) {
            // Log the data
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data, continuing...\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

