#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_data.log"

// Si1145 Registers
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_CH_LIST 0x4F
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_ALS_VIS_DATA0 0x22

// Commands
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init(int i2c_handle);
int read_si1145_data(int i2c_handle, int *proximity, int *ambient_light);
int log_data(FILE *log_file, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Si1145 initialization function
int si1145_init(int i2c_handle) {
    int part_id;

    // Verify PART_ID
    part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Set CH_LIST
    if (i2cWriteByteData(i2c_handle, SI1145_REG_CH_LIST, 0x03) < 0) {
        fprintf(stderr, "Error writing CH_LIST\n");
        return -1;
    }

    // Configure measurement rates
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE0, 0xFF) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE1, 0x01) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE1\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data
int read_si1145_data(int i2c_handle, int *proximity, int *ambient_light) {
    unsigned char data[4];

    // Trigger measurements
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE | SI1145_CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Error triggering measurements\n");
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10ms delay

    // Read ALS_VIS data
    if (i2cReadI2CBlockData(i2c_handle, SI1145_REG_ALS_VIS_DATA0, (char *)data, 2) < 0) {
        fprintf(stderr, "Error reading ALS_VIS data\n");
        return -1;
    }
    *ambient_light = (data[1] << 8) | data[0];

    // Read PS1 data
    if (i2cReadI2CBlockData(i2c_handle, SI1145_REG_PS1_DATA0, (char *)data, 2) < 0) {
        fprintf(stderr, "Error reading PS1 data\n");
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *log_file, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,proximity,ambient_light\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(i2c_handle, &proximity, &ambient_light) == 0) {
            // Log data
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

