int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output and input
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        log_data(-1.0, "Error setting trigger high");
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        log_data(-1.0, "Error setting trigger low");
    }
}

// Function to measure the echo pulse width
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int timeout_count = 0;

    // Wait for echo line to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        if (timeout_count++ > TIMEOUT_US) {
            log_data(-1.0, "Timeout waiting for echo high");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo line to go low
    timeout_count = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timeout_count++ > TIMEOUT_US) {
            log_data(-1.0, "Timeout waiting for echo low");
            return -1;
        }
        usleep(1);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error

    // Calculate distance in centimeters
    float distance = (pulse_width * 34300.0) / 2.0;

    // Validate distance
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        log_data(distance, "Distance out of range");
        return -1.0; // Indicate error
    }

    return distance;
}

