    if (distance > 0 && distance < WATERING_THRESHOLD_CM) {
        printf("Time to water the plant!\n");
        log_data(distance, "Time to water the plant!");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

