    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
