        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Log the data
        log_data(distance, "Measurement");

        // Check the watering threshold
        check_watering_threshold(distance);

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

