#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define APDS9960_ADDR 0x39
#define CSV_FILE "color_proximity_log.csv"

// APDS9960 Registers
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_apds9960();
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the APDS9960 sensor
int initialize_apds9960() {
    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%X\n", sensor_id);
        return -1;
    }

    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the APDS9960 sensor
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int r_datal, r_datal_h, r_datal_l, g_datal, g_datal_h, g_datal_l, b_datal, b_datal_h, b_datal_l, p_datal;

    r_datal = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
    r_datal_h = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
    g_datal = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
    g_datal_h = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
    b_datal = i2cReadByteData(i2c_handle, APDS9960_BDATAL);
    b_datal_h = i2cReadByteData(i2c_handle, APDS9960_BDATAH);
    p_datal = i2cReadByteData(i2c_handle, APDS9960_PDATAL);

    if (r_datal < 0 || r_datal_h < 0 || g_datal < 0 || g_datal_h < 0 || b_datal < 0 || b_datal_h < 0 || p_datal < 0) {
        fprintf(stderr, "Error reading RGB/Proximity data\n");
        return -1;
    }

    *red = (uint16_t)((r_datal_h << 8) | r_datal);
    *green = (uint16_t)((g_datal_h << 8) | g_datal);
    *blue = (uint16_t)((b_datal_h << 8) | b_datal);
    *proximity = (uint8_t)p_datal;

    return 0;
}

// Function to log data to a CSV file
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_apds9960() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    uint8_t proximity;

    // Main loop
    while (!terminate) {
        if (read_apds9960_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > 200) {
                if (log_data(red, green, blue, proximity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            gpioInitialise();
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                continue; // Skip the rest of the loop
            }
            if (initialize_apds9960() < 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue; // Skip the rest of the loop
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Closing I2C bus...\n");
    i2cClose(i2c_handle);
    printf("Closing log file...\n");
    fclose(log_file);
    printf("Terminating pigpio...\n");
    gpioTerminate();

    return 0;
}

