#define CH101_ADDR 0x45
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define MEASURE_CMD 0x01
#define MAX_DISTANCE 4000 // Maximum measurable distance in mm
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ch101_address;
    char *log_file_name;
} config_t;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int trigger_measurement(int handle);
int read_distance(int handle);
float convert_to_mm(int raw_distance);
int log_distance(float distance);
void print_distance(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Trigger a measurement
int trigger_measurement(int handle) {
    char buf[1];
    buf[0] = MEASURE_CMD;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int handle) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance: %d\n", result);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Convert raw distance to millimeters
float convert_to_mm(int raw_distance) {
    if (raw_distance == 0) return 0.0; // Avoid division by zero
    return (float)raw_distance * MAX_DISTANCE / 65535.0;
}

