    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(sensor_data_t *data) {
    int result;
    char buf[2];
    int retries = 0;

    // Read proximity data
    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, buf, 2);
        if (result == 2) {
            data->proximity = (buf[1] << 8) | buf[0];
            break;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
        data->proximity = 0; // Indicate error
    }

    retries = 0;
    // Read ambient light data
    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, AMBIENT_LIGHT_REG, buf, 2);
        if (result == 2) {
            data->ambient_light = (buf[1] << 8) | buf[0];
