#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define MEASURE_COMMAND 0x500A0001
#define RESPONSE_LENGTH 15
#define INTRUSION_THRESHOLD 1000 // mm
#define LOG_FILE "intrusion_log.txt"
#define SAMPLE_DELAY_MS 100

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, const uint8_t *data, size_t length);
int i2c_read(int fd, uint8_t *data, size_t length);
int request_measurement(int fd);
int parse_response(uint8_t *response, int *distance);
int calculate_average_distance(int *distances, int num_samples);
int log_intrusion(int average_distance);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, const uint8_t *data, size_t length) {
    ssize_t bytes_written = write(fd, data, length);
    if (bytes_written < 0) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (bytes_written != length) {
        fprintf(stderr, "Warning: Wrote %zd bytes, expected %zu\n", bytes_written, length);
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, size_t length) {
    ssize_t bytes_read = read(fd, data, length);
    if (bytes_read < 0) {
        perror("Error reading from I2C device");
        return -1;
    }
    if (bytes_read != length) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %zu\n", bytes_read, length);
    }
    return 0;
}

// Request measurement function
int request_measurement(int fd) {
    uint8_t command[4];
    command[0] = (MEASURE_COMMAND >> 16) & 0xFF;
    command[1] = (MEASURE_COMMAND >> 8) & 0xFF;
    command[2] = MEASURE_COMMAND & 0xFF;
    command[3] = 0x01; // Command length

    if (i2c_write(fd, command, 4) < 0) {
        fprintf(stderr, "Error requesting measurement\n");
        return -1;
    }
    return 0;
}

// Parse response function
int parse_response(uint8_t *response, int *distance) {
    if (response[0] != 0x50) {
        fprintf(stderr, "Error: Invalid response header\n");
        return -1;
    }

    *distance = (response[11] << 8) | response[12];
    return 0;
}

// Calculate average distance function
int calculate_average_distance(int *distances, int num_samples) {
    int sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Log intrusion function
int log_intrusion(int average_distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Intrusion detected: Average distance = %d mm\n", timestamp, average_distance);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        int distances[10];
        for (int i = 0; i < 10; i++) {
            uint8_t response[RESPONSE_LENGTH];
            if (request_measurement(i2c_fd) < 0) {
                fprintf(stderr, "Error requesting measurement, retrying...\n");
                usleep(10000); // 10 ms
                continue;
            }
            usleep(10000); // Wait 10 ms

            if (i2c_read(i2c_fd, response, RESPONSE_LENGTH) < 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                usleep(10000); // 10 ms
                continue;
            }

            if (parse_response(response, &distances[i]) < 0) {
                fprintf(stderr, "Error parsing response, retrying...\n");
                usleep(10000); // 10 ms
                continue;
            }
        }

        int average_distance = calculate_average_distance(distances, 10);
        if (average_distance < INTRUSION_THRESHOLD) {
            log_intrusion(average_distance);
        }

        usleep(SAMPLE_DELAY_MS * 1000); // 100 ms delay
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

