#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check if the sensor is present
    int model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Initialize the sensor (simplified initialization sequence)
    // This is a placeholder.  A full initialization sequence is much longer.
    // Refer to the VL53L0X datasheet for the complete initialization.
    if (i2cWriteByteData(i2c_handle, 0x88, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x88: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x80, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x80: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0xFF, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0xFF: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x00: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance() {
    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x00: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the measurement to complete (polling RESULT_INTERRUPT_STATUS)
    int status = 0;
    int timeout = 100; // Timeout in milliseconds
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
            return -1;
        }
        if (status & 0x01) {
            break; // Measurement complete
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    int distance = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Clear the interrupt
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x0B: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

// Function to format the timestamp
void format_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L0X sensor
    if (init_vl53l0x() < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the distance
        int distance = read_distance();
        if (distance >= 0) {
            // Format the timestamp
            char timestamp[20];
            format_timestamp(timestamp);

            // Print the distance
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

