int init_si1182() {
    // Enable proximity mode
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to read the proximity data from the sensor
int read_proximity_data(unsigned short *proximity) {
    char lsb, msb;

    // Check if data is ready
    if (i2cReadByteData(i2c_handle, IRQ_STATUS_REG) < 0) {
        fprintf(stderr, "Error reading IRQ status register\n");
        return -1;
    }

    // Read LSB and MSB
    lsb = i2cReadByteData(i2c_handle, PROX_DATA_LSB);
    msb = i2cReadByteData(i2c_handle, PROX_DATA_MSB);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    // Combine LSB and MSB to form the 16-bit proximity value
    *proximity = (unsigned short)((msb << 8) | lsb);
    return 0;
}

