#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Define the I2C bus and device address
#define I2C_BUS 1
#define I2C_DEVICE_ADDRESS 0x4C

// Define the distance register address
#define DISTANCE_REGISTER 0x00

// Define the scaling factor (0.125 mm per count)
#define SCALING_FACTOR 0.125

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read the distance from the MLX75030 sensor
int read_distance(int i2c_fd) {
    uint8_t buffer[2];
    int result;

    // Read 2 bytes from the distance register
    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Convert the 2 bytes to a 16-bit integer (little-endian)
    int16_t distance_raw = (buffer[1] << 8) | buffer[0];

    return distance_raw;
}

// Function to convert the raw distance value to millimeters
float convert_to_mm(int16_t distance_raw) {
    return (float)distance_raw * SCALING_FACTOR;
}

// Function to log the distance to stdout
void log_distance(float distance_mm) {
    printf("Distance: %.2f mm\n", distance_mm);
}

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device file
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify the device responds by reading a register (optional)
    uint8_t test_read_buffer[1];
    if (read(i2c_fd, test_read_buffer, 1) != 1) {
        fprintf(stderr, "Error verifying device response: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log the distance
    while (1) {
        int16_t distance_raw = read_distance(i2c_fd);
        if (distance_raw != -1) {
            float distance_mm = convert_to_mm(distance_raw);
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Sleep for 500 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here, but close the file descriptor if it does
    close(i2c_fd);
    return 0;
}

