int read_register(int handle, int reg) {
    int value = i2cReadWordData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log sensor data
void log_data(int ch0_dist, int ambient, int error_flags) {
    printf("CH0 Dist: %d, Ambient: %d, Error Flags: %d\n", ch0_dist, ambient, error_flags);
}

