    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int ch0_dist = read_register(i2c_handle, OPT3101_REG_CH0_DIST);
        int ambient = read_register(i2c_handle, OPT3101_REG_AMBIENT);
        int error_flags = read_register(i2c_handle, OPT3101_REG_ERROR);

        // Log the data
        if (ch0_dist >= 0 && ambient >= 0 && error_flags >= 0) {
            log_data(ch0_dist, ambient, error_flags);
        } else {
