#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 38000       // 38 ms timeout
#define TIMEOUT_MS 200         // 200 ms timeout
#define LOG_INTERVAL_SEC 1

// Global variables
static volatile int running = 1;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
float calculateDistance(long pulseWidth);
void logDistance(float distance);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for echo to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_MS * 1000) {
        startTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Timeout
    }

    // Wait for echo to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_MS * 1000) {
        endTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_MS * 1000) {
