#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 1.0 // meters
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define LED_ON_TIME 2 // seconds

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int size);
int validate_magic_word(const unsigned char *buffer, int size);
int parse_range_profile(const unsigned char *buffer, int size, int *range_profile);
int detect_intrusion(const int *range_profile, int range_profile_size, float distance_threshold);
void activate_led(int gpio_pin, int duration);
void log_intrusion(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = serOpen(device, baud_rate, 0); // 0 for default flags (8N1)
    if (fd < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, int size) {
    int bytes_read = serRead(fd, buffer, size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    }
    return bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, int size) {
    if (size != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error: Magic word size mismatch\n");
        return -1;
    }

    unsigned char expected_magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (buffer[i] != expected_magic_word[i]) {
            fprintf(stderr, "Error: Magic word mismatch\n");
            return -1;
        }
    }
    return 0;
}

// Parse range profile
int parse_range_profile(const unsigned char *buffer, int size, int *range_profile) {
    if (size != RANGE_PROFILE_SIZE) {
        fprintf(stderr, "Error: Range profile size mismatch\n");
        return -1;
    }

    for (int i = 0; i < RANGE_PROFILE_SIZE / 2; i++) {
        // Convert 2 bytes (16-bit integer) to integer
        range_profile[i] = (buffer[i * 2 + 1] << 8) | buffer[i * 2];
    }
    return 0;
}

// Detect intrusion
int detect_intrusion(const int *range_profile, int range_profile_size, float distance_threshold) {
    for (int i = 0; i < range_profile_size; i++) {
        float distance = range_profile[i] * RANGE_RESOLUTION;
        if (distance <= distance_threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

