void activate_led(int gpio_pin, int duration) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration * 1000000); // Delay for specified duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Turn LED off
}

