    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        serClose(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char magic_word[MAGIC_WORD_SIZE];
    int range_profile[RANGE_PROFILE_SIZE / 2];
    int bytes_read;

    fprintf(stdout, "Starting intrusion detection...\n");

    while (!terminate) {
        // Read magic word
        bytes_read = read_uart_data(uart_fd, magic_word, MAGIC_WORD_SIZE);
        if (bytes_read == MAGIC_WORD_SIZE) {
            if (validate_magic_word(magic_word, MAGIC_WORD_SIZE) == 0) {
                // Read range profile
                bytes_read = read_uart_data(uart_fd, (unsigned char *)range_profile, RANGE_PROFILE_SIZE);
                if (bytes_read == RANGE_PROFILE_SIZE) {
                    // Parse range profile
                    if (parse_range_profile((unsigned char *)range_profile, RANGE_PROFILE_SIZE, range_profile) == 0) {
                        // Detect intrusion
                        if (detect_intrusion(range_profile, RANGE_PROFILE_SIZE, DISTANCE_THRESHOLD)) {
                            // Calculate distance
                            float distance = range_profile[0] * RANGE_RESOLUTION;
                            // Log intrusion
                            log_intrusion(distance);
                            // Activate LED
                            activate_led(GPIO_PIN, LED_ON_TIME);
                        }
                    }
                }
            }
        }
        gpioDelay(10000); // Delay to avoid busy-waiting (10ms)
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    serClose(uart_fd);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Exiting.\n");
    return 0;
}

