#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void activate_buzzer(struct gpiod_line *line, int state);
void log_event(const char *event);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer state: %d\n", ret);
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to setup GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return -1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d\n", SENSOR_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line %d\n", BUZZER_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        return -1;
    }

    int ret = gpiod_line_request(sensor_line, "obstacle_detector", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor line: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    ret = gpiod_line_request(buzzer_line, "obstacle_detector", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("obstacle_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed!\n");
        fclose(log_file);
        return 1;
    }

    int last_sensor_value = -1; // Initialize to an invalid value
    int buzzer_state = 0; // Initial buzzer state

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value != last_sensor_value) {
            if (sensor_value == 0) {
                activate_buzzer(buzzer_line, 1);
                log_event("Obstacle detected");
            } else {
                activate_buzzer(buzzer_line, 0);
                log_event("Obstacle removed");
            }
            last_sensor_value = sensor_value;
            buzzer_state = sensor_value; // Update buzzer state
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

