void trigger_alert(uint16_t distance) {
    if (distance < (uint16_t)(DISTANCE_THRESHOLD * 10.0)) {
        gpioWrite(GPIO_ALERT, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_ALERT, 0); // Set GPIO low
    }
}

