void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_ALERT, 0); // Ensure GPIO is low on exit
    gpioSetMode(GPIO_ALERT, PI_INPUT); // Set GPIO back to input
    gpioTerminate();
}

