#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078

// Thresholds for distance-based guidance
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void log_distance_data(FILE *log_file, int distance);
void print_parking_guidance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    int status;
    uint8_t model_id;

    // Check sensor presence
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_MODEL_ID, (char *)&model_id, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    status = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE_START, (char *)"\x00", 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSRANGE_START: %d\n", status);
        return -1;
    }
    gpioDelay(2); // Wait 2ms

    status = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE_START, (char *)"\x01", 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSRANGE_START: %d\n", status);
        return -1;
    }

    // Start continuous ranging
    status = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, (char *)"\x01", 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSTEM_MODE_START: %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    int status;
    uint8_t interrupt_status;
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int distance;

    // Poll for data ready
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, (char *)&interrupt_status, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading interrupt status: %d\n", status);
        return -1;
    }

    while (!(interrupt_status & 0x01)) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, (char *)&interrupt_status, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            return -1;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Read range status
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, (char *)&range_status, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", status);
        return -1;
    }

    // Read distance (big-endian)
    status = i2cReadI2CBlockData(i2c_handle, 0x078, (char *)&distance_msb, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", status);
        return -1;
    }
    status = i2cReadI2CBlockData(i2c_handle, 0x079, (char *)&distance_lsb, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", status);
        return -1;
    }

    distance = (distance_msb << 8) | distance_lsb;

    // Clear interrupt
    status = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, (char *)"\x01", 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSTEM_INTERRUPT_CLEAR: %d\n", status);
        return -1;
    }

    return distance;
}

// Data logging function
void log_distance_data(FILE *log_file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Parking guidance function
void print_parking_guidance(int distance) {
    if (distance < STOP_THRESHOLD) {
        printf("STOP\n");
    } else if (distance >= STOP_THRESHOLD && distance < APPROACH_THRESHOLD) {
        printf("APPROACH\n");
    } else if (distance >= APPROACH_THRESHOLD && distance < SLOW_THRESHOLD) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance_data(log_file, distance);
            print_parking_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

