    status = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, (char *)"\x01", 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSTEM_INTERRUPT_CLEAR: %d\n", status);
        return -1;
    }

    return distance;
}

// Data logging function
void log_distance_data(FILE *log_file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Parking guidance function
void print_parking_guidance(int distance) {
    if (distance < STOP_THRESHOLD) {
        printf("STOP\n");
    } else if (distance >= STOP_THRESHOLD && distance < APPROACH_THRESHOLD) {
        printf("APPROACH\n");
    } else if (distance >= APPROACH_THRESHOLD && distance < SLOW_THRESHOLD) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance_data(log_file, distance);
            print_parking_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

