#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define BLINK_FREQUENCY_MIN 1.0  // Hz
#define BLINK_FREQUENCY_MAX 10.0 // Hz
#define DISTANCE_MIN 50.0       // mm
#define DISTANCE_MAX 500.0      // mm
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_distance(int *distance);
float map_distance_to_frequency(int distance);
void set_led_frequency(float frequency);
void log_data(int distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg1;
    uint8_t config_reg2;
} sensor_config_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from CH201 sensor
int read_distance(int *distance) {
    char buf[2];
    int result;
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", I2C_RETRY_COUNT - retries + 1, result);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

// Function to map distance to blink frequency
float map_distance_to_frequency(int distance) {
    float frequency;

    if (distance <= DISTANCE_MIN) {
        frequency = BLINK_FREQUENCY_MAX;
    } else if (distance >= DISTANCE_MAX) {
        frequency = BLINK_FREQUENCY_MIN;
    } else {
        frequency = BLINK_FREQUENCY_MAX - (distance - DISTANCE_MIN) * (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN) / (DISTANCE_MAX - DISTANCE_MIN);
    }

    return frequency;
}

// Function to set LED blink frequency
void set_led_frequency(float frequency) {
    gpioSetPWMfrequency(LED_GPIO, (int)(1000.0 / frequency)); // pigpio uses Hz
    gpioPWM(LED_GPIO, 128); // 50% duty cycle
}

