void log_data(int distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int distance;
    float frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = map_distance_to_frequency(distance);
            set_led_frequency(frequency);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000); // 100 ms delay (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

