// Function prototypes
int init_sensor(sensor_config_t *config);
int read_distance(int i2c_handle, int *distance);
int log_data(FILE *log_file, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the MLX75030 sensor
int init_sensor(sensor_config_t *config) {
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
        if (i2c_handle >= 0) {
            printf("I2C connection established.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening I2C device: %d. Retrying...\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to open I2C device after multiple retries.\n");
    return -1; // Failure
}

// Read distance data from the sensor
int read_distance(int i2c_handle, int *distance) {
    int result;
    char buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Trigger measurement
        result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d. Retrying...\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(1000); // Wait for measurement (adjust as needed)

        // Read distance data
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
