#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates current_states = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Debounce and log events for sensor 1
        if (sensor1_value != current_states.sensor1_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
            if (read_sensor(SENSOR_1_GPIO) == sensor1_value) {
                if (sensor1_value == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
                current_states.sensor1_state = sensor1_value;
            }
        }

