#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int trigger_measurement(int fd);
int read_distance(int fd, uint16_t *distance);
int log_data(FILE *fp, uint16_t distance);
void signal_handler(int sig);

// Helper function to read a single register
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading register value: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Helper function to write a single register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to trigger a range measurement
int trigger_measurement(int fd) {
    if (i2c_write_reg(fd, MEAS_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd, uint16_t *distance) {
    int high, low;

    high = i2c_read_reg(fd, DIST_HIGH);
    if (high < 0) {
        fprintf(stderr, "Error reading DIST_HIGH\n");
        return -1;
    }

    low = i2c_read_reg(fd, DIST_LOW);
    if (low < 0) {
        fprintf(stderr, "Error reading DIST_LOW\n");
        return -1;
    }

    *distance = (high << 8) | low;
    return 0;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, uint16_t distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_fp = fopen(CSV_FILE, "a");
    if (csv_fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t distance;
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for data to be ready
        int ready = 0;
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (!ready && !terminate) {
            int status = i2c_read_reg(i2c_fd, MEAS_STATUS);
            if (status < 0) {
                fprintf(stderr, "Error reading MEAS_STATUS, retrying...\n");
                sleep(1); // Wait before retrying
                break;
            }
            if (status & 0x01) {
                ready = 1;
            } else {
                clock_gettime(CLOCK_MONOTONIC, &now);
                double elapsed = (now.tv_sec - start.tv_sec) + (now.tv_nsec - start.tv_nsec) / 1000000000.0;
                if (elapsed > 0.5) {
                    fprintf(stderr, "Timeout waiting for data, retrying...\n");
                    sleep(1); // Wait before retrying
                    ready = 1; // Exit the loop to retry
                }
            }
        }

        if (!ready) continue; // Retry if timeout or error

        // Read distance
        if (read_distance(i2c_fd, &distance) != 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(csv_fp, distance) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait 500ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    fclose(csv_fp);

    return 0;
}

