#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance measurement
#define DISTANCE_REG 0x00 // Example register, check datasheet

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int retry_count;
    int delay_ms;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C connection
int open_i2c_connection(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read a register from the MLX75030 sensor
int read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    int result, retries = 0;
    while (retries < 3) {
        result = i2cReadI2CBlockData(handle, reg_addr, (char *)data, len);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(10); // Wait 10 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after 3 retries\n");
    return -1;
}

// Function to write a register to the MLX75030 sensor
int write_register(int handle, uint8_t reg_addr, uint8_t data) {
    int result, retries = 0;
    while (retries < 3) {
        result = i2cWriteByteData(handle, reg_addr, data);
        if (result == 0) {
            return 0;
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(10); // Wait 10 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after 3 retries\n");
    return -1;
}

// Function to read the distance measurement from the sensor
int read_distance(int handle, uint16_t *distance) {
    uint8_t data[2];
    int result = read_register(handle, DISTANCE_REG, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Function to log the distance measurement with a timestamp
void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("Timestamp: %ld.%09ld, Distance: %d mm\n", ts.tv_sec, ts.tv_nsec, distance);
}

// Function to close the I2C connection and terminate pigpio
void cleanup(int handle) {
    i2cClose(handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, MLX75030_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint16_t distance;
    while (!terminate) {
        if (read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup and exit
    cleanup(i2c_handle);
    return 0;
}

