int write_register(int handle, uint16_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

