int read_distance(int handle, uint16_t *distance) {
    uint8_t range_status;
    int result;

    // Check interrupt status
    result = read_register(handle, VL53L4CX_REG_RESULT_RANGE_STATUS, &range_status);
    if (result < 0) {
        return -1;
    }

    if ((range_status & 0x01) == 0) {
        // Interrupt not set, skip reading distance
        return 0;
    }

    // Read distance
    uint8_t high_byte, low_byte;
    result = read_register(handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &low_byte);
    if (result < 0) return -1;
    result = read_register(handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &high_byte);
    if (result < 0) return -1;

    *distance = (uint16_t)((high_byte << 8) | low_byte);

    // Clear interrupt by writing 0 to register 0x0046
    result = write_register(handle, VL53L4CX_REG_SYSRANGE_START, 0x00);
    if (result < 0) {
        return -1;
    }

    return 0;
}

