#include <fcntl.h>
#include <mqueue.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/vl53l1x_queue"
#define MAX_MSG_SIZE 256
#define MSG_COUNT 10

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global Variables
int i2c_handle;
mqd_t mq;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_vl53l1x();
int read_distance(int *distance);
void activate_buzzer(int activate);
void log_distance(int distance);
void signal_handler(int signal);
int send_message(int distance);

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// VL53L1X Initialization Function
int init_vl53l1x() {
    int model_id;
    int status;

    // Check Model ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software Reset
    status = i2cWriteByteData(i2c_handle, 0x00, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing reset register 0x00: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait 10ms
    status = i2cWriteByteData(i2c_handle, 0x00, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing reset register 0x01: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait 10ms

    // Configure Timing Budget (50ms)
    status = i2cWriteByteData(i2c_handle, 0x00, 0x04); // Set timing budget to 50ms
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget register: %d\n", status);
        return -1;
    }

    return 0;
}

// Distance Reading Function
int read_distance(int *distance) {
    int status;
    int range_status;

    // Start Ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    // Poll Data Ready
    int ready = 0;
    for (int i = 0; i < 100; ++i) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading range status: %d\n", status);
            return -1;
        }
        range_status = status;
        if (range_status & 0x01) {
            ready = 1;
            break;
        }
        gpioDelay(1); // Wait 1ms
    }

    if (!ready) {
        fprintf(stderr, "Data not ready after polling.\n");
        return -1;
    }

    // Read Distance
    status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }
    *distance = status;

    return 0;
}

// Buzzer Control Function
void activate_buzzer(int activate) {
    gpioWrite(BUZZER_GPIO, activate);
}

// Message Queue Sending Function
int send_message(int distance) {
    char buffer[MAX_MSG_SIZE];
    snprintf(buffer, MAX_MSG_SIZE, "Distance: %d mm", distance);

    if (mq_send(mq, buffer, strlen(buffer), 0) == -1) {
        fprintf(stderr, "Error sending message: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Logging Function
void log_distance(int distance) {
    printf("Distance: %d mm\n", distance);
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set Buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure Message Queue Attributes
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = MSG_COUNT;
    attr.mq_msgsize = MAX_MSG_SIZE;
    attr.mq_curmsgs = 0;

    // Create Message Queue
    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set Signal Handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main Loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer(1);
            } else {
                activate_buzzer(0);
            }

            if (send_message(distance) != 0) {
                fprintf(stderr, "Error sending message, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, but continuing...\n");
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();
    mq_close(mq);
    mq_unlink(MESSAGE_QUEUE_NAME);

    return 0;
}

