#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_THRESHOLD 30.0 // cm
#define TIMEOUT_US 50000        // 50 ms timeout
#define BUZZER_ON_DURATION 1000 // 1 second

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
volatile float distance = 0.0;
volatile int sensor_absent = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick, void *user);
float calculateDistance(uint32_t pulse_width);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate echo start
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset echo received flag
    }
}

// Function to calculate distance from pulse width
float calculateDistance(uint32_t pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate timeout
    }
    float time_taken = (float)pulse_width / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Calculate distance in cm
    return distance;
}

// Function to control the buzzer
void controlBuzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        gpioDelay(BUZZER_ON_DURATION); // Keep buzzer on for 1 second
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    } else {
        gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to register interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        triggerSensor(); // Trigger the sensor
        gpioDelay(100);   // Wait 100 ms

        // Calculate pulse width and distance
        uint32_t pulse_width = end_tick - start_tick;
        if (pulse_width > 0) {
            distance = calculateDistance(pulse_width);
        } else {
            distance = -1.0; // Indicate timeout
        }

        // Handle timeout and invalid reading
        if (distance < 0) {
            sensor_absent = 1;
            printf("Sensor absent (timeout)\n");
        } else if (distance < 2 || distance > 400) {
            printf("Invalid reading: %.2f cm\n", distance);
        } else {
            sensor_absent = 0;
            printf("Distance: %.2f cm\n", distance);
        }

        // Control the buzzer
        controlBuzzer(distance);

        // Reset variables for next iteration
        start_tick = 0;
        end_tick = 0;
        echo_received = 0;
        distance = 0.0;
    }

    return 0; // This line will never be reached due to the infinite loop
}

