#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_ANGLE 180
#define SERVO_CLOSED_ANGLE 0
#define SERVO_SPEED_MS 500 // Time to move from 0 to 180 degrees (in milliseconds)
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x24

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
bool gate_open = false;
bool running = true;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_set_angle(int angle);
void gate_open();
void gate_close();
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// VL53L1X Initialization
int vl53l1x_init() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X software reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Check sensor presence (optional, but good practice)
    int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X sensor not present\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading
int vl53l1x_read_distance() {
    int distance = -1;
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (status >= 0) {
            distance = status;
            break;
        } else {
            fprintf(stderr, "Error: VL53L1X read failed, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (distance < 0) {
        fprintf(stderr, "Error: VL53L1X read failed after multiple retries\n");
    }

    return distance;
}

// Servo Motor Control
void servo_set_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = (int)(500 + (float)angle * (2000.0 / 180.0));

    gpioPWM(SERVO_PIN, pulse_width);
}

// Gate Control Functions
void gate_open() {
    if (!gate_open) {
        printf("Opening gate...\n");
        servo_set_angle(SERVO_OPEN_ANGLE);
        gate_open = true;
        log_event("force_open");
    }
}

void gate_close() {
    if (gate_open) {
        printf("Closing gate...\n");
        servo_set_angle(SERVO_CLOSED_ANGLE);
        gate_open = false;
        log_event("force_close");
    }
}

// MQTT Callbacks
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        printf("MQTT connected to %s:%d\n", MQTT_HOST, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        printf("Received message on topic %s: %s\n", message->topic, payload);

        if (strcmp(payload, "status_request") == 0) {
            int distance = vl53l1x_read_distance();
            if (distance >= 0) {
                char status_message[50];
                snprintf(status_message, sizeof(status_message), "distance:%d", distance);
                mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(status_message), status_message, 0, false);
            } else {
                mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen("error"), "error", 0, false);
            }
        }
    }
}

// Logging Function
void log_event(const char *event) {
    FILE *fp = fopen("gate_log.txt", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file\n");
    }
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize servo motor
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz PWM frequency
    gpioSetPWMrange(SERVO_PIN, 2000); // Range of 0-2000

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT connection failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD && !gate_open) {
                gate_open();
            } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
                gate_close();
            }
        } else {
            fprintf(stderr, "Error: Could not read distance\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

