#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 30000       // Timeout in microseconds
#define VALID_PULSE_MIN_US 100 // Minimum valid pulse width in microseconds
#define VALID_PULSE_MAX_US 30000 // Maximum valid pulse width in microseconds
#define MEASUREMENT_INTERVAL_MS 200 // Measurement interval in milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold GPIO configuration
typedef struct {
    int trig_pin;
    int echo_pin;
} gpio_config_t;

// Function prototypes
int initialize_gpio(gpio_config_t *config);
void trigger_sensor(int trig_pin);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trig_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);
    gpioSetPullUpDown(config->echo_pin, PI_PUD_DOWN); // Pull-down resistor

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor(int trig_pin) {
    gpioWrite(trig_pin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(trig_pin, 0);
}

// Callback function for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t rising_edge_tick = 0;
    static uint32_t falling_edge_tick = 0;
    static int echo_received = 0; // Flag to indicate if echo is received
    static uint32_t last_tick = 0;
    uint32_t pulse_width;

    if (level == 1) {
        rising_edge_tick = tick;
        echo_received = 1; // Reset the flag
    } else if (level == 0) {
        falling_edge_tick = tick;
        echo_received = 1; // Reset the flag
    }

    if (echo_received) {
        pulse_width = falling_edge_tick - rising_edge_tick;

        // Handle pigpio tick wraparound
        if (rising_edge_tick > falling_edge_tick) {
            pulse_width += (1LL << 32); // Add 2^32 to handle wraparound
        }

        if (pulse_width > 0 && pulse_width <= TIMEOUT_US) {
            double distance = calculate_distance(pulse_width);
            log_distance(distance);
            echo_received = 0; // Reset the flag after processing
        } else {
            fprintf(stderr, "Warning: Invalid pulse width: %u us\n", pulse_width);
        }
    }
}

// Calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Log distance to stdout and file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Flush the buffer to ensure immediate write
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    gpio_config_t gpio_config = {TRIG_PIN, ECHO_PIN};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_config) != 0) {
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set alert function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor(TRIG_PIN);
        gpioDelay(MEASUREMENT_INTERVAL_MS); // Wait for the next measurement
    }

    cleanup();
    return 0;
}

