#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_CLOSE 50 // cm
#define DISTANCE_THRESHOLD_OPEN 60  // cm
#define SERVO_OPEN_PULSE_WIDTH 2000 // us
#define SERVO_CLOSED_PULSE_WIDTH 1000 // us
#define I2C_BUS 1
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_pulse_width(int pulse_width);
void log_data(int distance, int gate_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int model_id;
    int status;

    // Check sensor presence
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    model_id = status;

    if (model_id != 0xEACC) {
        fprintf(stderr, "VL53L1X not found. Model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Basic initialization sequence (simplified)
    // Refer to VL53L1X datasheet for complete initialization
    // This is a placeholder, replace with actual initialization sequence
    status = i2cWriteByteData(i2c_handle, 0x02d, 0x01); // Example register write
    if (status < 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x02e, 0x00); // Example register write
    if (status < 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", status);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int status;
    int distance = -1; // Default to error value

    // Check if data is ready
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY);
    if (status < 0) {
        fprintf(stderr, "Error reading data ready status: %d\n", status);
        return -1;
    }

    if ((status & 0x01) == 0) {
        //printf("Data not ready yet.\n");
        return -1; // Data not ready
    }

    // Read distance
    status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    distance = status; // Distance in mm

    return distance;
}

// Set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(SERVO_PIN, pulse_width);
}

// Log data to file
void log_data(int distance, int gate_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Distance: %d cm, Gate State: %s\n", timestamp, distance / 10, gate_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    set_servo_pulse_width(0); // Stop servo
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int distance;
    int gate_state = 0; // 0 = closed, 1 = open
    int last_distance = -1; // Initialize to an invalid distance

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed!\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(SERVO_PIN, 20000); // 20ms period

    // Set initial servo position (closed)
    set_servo_pulse_width(SERVO_CLOSED_PULSE_WIDTH);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Parking Gate System started.\n");

    // Main loop
    while (program_running) {
        distance = read_distance();

        if (distance > 0) {
            printf("Distance: %d mm\n", distance);
            int distance_cm = distance / 10; // Convert to cm

            if (distance_cm < DISTANCE_THRESHOLD_CLOSE && gate_state == 0) {
                // Open gate
                set_servo_pulse_width(SERVO_OPEN_PULSE_WIDTH);
                gate_state = 1;
                log_data(distance_cm, gate_state);
                printf("Opening gate...\n");
            } else if (distance_cm > DISTANCE_THRESHOLD_OPEN && gate_state == 1) {
                // Close gate
                set_servo_pulse_width(SERVO_CLOSED_PULSE_WIDTH);
                gate_state = 0;
                log_data(distance_cm, gate_state);
                printf("Closing gate...\n");
            }

            last_distance = distance_cm;
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

