// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// GPIO pins
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24

// Motor control constants
#define FORWARD 1
#define BACKWARD 0
#define STOP 2

// I2C handle
int i2c_handle;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void motor_control(int distance);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    int status;
    int retries = 3;
    int delay_ms = 1;

    // Soft reset
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x00);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error: I2C write failed (soft reset): %d. Retrying in %d ms.\n", status, delay_ms);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: I2C write failed (soft reset) after multiple retries.\n");
        return -1;
    }

    gpioDelay(1000); // Wait 1 ms

    // Start measurement
    retries = 3;
    delay_ms = 1;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error: I2C write failed (start measurement): %d. Retrying in %d ms.\n", status, delay_ms);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: I2C write failed (start measurement) after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    int status;
    int retries = 3;
    int delay_ms = 1;
    unsigned char data[2];
    int distance;

    // Poll data ready bit
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status >= 0) {
            if (status & 0x01) {
                break; // Data ready
            }
        } else {
            fprintf(stderr, "Error: I2C read failed (range status): %d. Retrying in %d ms.\n", status, delay_ms);
        }
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: I2C read failed (range status) after multiple retries.\n");
        return -1;
    }

    // Read distance
    retries = 3;
    delay_ms = 1;
    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
        if (status >= 0) {
            distance = (data[0] << 8) | data[1];
            return distance;
        } else {
            fprintf(stderr, "Error: I2C read failed (distance): %d. Retrying in %d ms.\n", status, delay_ms);
        }
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "Error: I2C read failed (distance) after multiple retries.\n");
    return -1;
}

// Function to control the DC motor
void motor_control(int distance) {
    static int motor_state = STOP; // Initialize to STOP

    if (distance < 100) {
        if (motor_state != FORWARD) {
            gpioWrite(MOTOR_FORWARD_PIN, 1);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = FORWARD;
            printf("Distance: %d mm, Motor: Forward\n", distance);
        }
    } else if (distance > 300) {
        if (motor_state != BACKWARD) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 1);
            motor_state = BACKWARD;
            printf("Distance: %d mm, Motor: Backward\n", distance);
        }
    } else {
        if (motor_state != STOP) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = STOP;
            printf("Distance: %d mm, Motor: Stop\n", distance);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

