#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO_1 17
#define LED_GPIO_2 18
#define LED_GPIO_3 27
#define LED_GPIO_4 22
#define NUM_ELECTRODES 12
#define POLLING_INTERVAL_MS 50

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int mpr121_reset(int fd);
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd, uint16_t *status);
void set_led_pattern(int gpio1, int gpio2, int gpio3, int gpio4, int pattern);
void log_event(const char *message);
void signal_handler(int signal);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device.\n");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    return 0;
}

// MPR121 reset function
int mpr121_reset(int fd) {
    if (i2c_write_register(fd, 0x80, 0x63) != 0) {
        fprintf(stderr, "Error resetting MPR121.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete
    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (mpr121_reset(fd) != 0) {
        return -1;
    }

    // Stop mode
    if (i2c_write_register(fd, 0x5E, 0x00) != 0) {
        fprintf(stderr, "Error setting MPR121 to stop mode.\n");
        return -1;
    }

    // Baseline filtering
    if (i2c_write_register(fd, 0x5B, 0x01) != 0) return -1;
    if (i2c_write_register(fd, 0x5C, 0x01) != 0) return -1;
    if (i2c_write_register(fd, 0x5D, 0x0E) != 0) return -1;
    if (i2c_write_register(fd, 0x5E, 0x00) != 0) return -1;

    // Auto-configuration thresholds
    if (i2c_write_register(fd, 0x5A, 0x0B) != 0) return -1;
    if (i2c_write_register(fd, 0x5D, 0xC8) != 0) return -1;
    if (i2c_write_register(fd, 0x5E, 0x82) != 0) return -1;
    if (i2c_write_register(fd, 0x5F, 0xB4) != 0) return -1;

    // Enable all electrodes in run mode
    if (i2c_write_register(fd, 0x5E, 0x0C) != 0) {
        fprintf(stderr, "Error setting MPR121 to run mode.\n");
        return -1;
    }

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd, uint16_t *status) {
    uint8_t buf[2];
    if (write(fd, buf, 0) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status from I2C device.\n");
        return -1;
    }
    *status = (buf[1] << 8) | buf[0];
    return 0;
}

// Set LED pattern function
void set_led_pattern(int gpio1, int gpio2, int gpio3, int gpio4, int pattern) {
    gpioWrite(gpio1, (pattern >> 0) & 1);
    gpioWrite(gpio2, (pattern >> 1) & 1);
    gpioWrite(gpio3, (pattern >> 2) & 1);
    gpioWrite(gpio4, (pattern >> 3) & 1);
}

// Log event function
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device.\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MPR121
    if (mpr121_init(i2c_fd) != 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_GPIO_1, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);
    gpioSetMode(LED_GPIO_3, PI_OUTPUT);
    gpioSetMode(LED_GPIO_4, PI_OUTPUT);

    uint16_t touch_status;
    int any_electrode_touched = 0;

    // Main loop
    while (!terminate) {
        if (mpr121_read_touch_status(i2c_fd, &touch_status) == 0) {
            any_electrode_touched = 0;
            for (int i = 0; i < NUM_ELECTRODES; i++) {
                if (touch_status & (1 << i)) {
                    any_electrode_touched = 1;
                    switch (i) {
                        case 0:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0011);
                            break;
                        case 1:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b1100);
                            break;
                        case 2:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0101);
                            break;
                        case 3:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b1010);
                            break;
                        case 4:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 5:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 6:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 7:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 8:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 9:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 10:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                        case 11:
                            set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000);
                            break;
                    }
                    char log_message[100];
                    snprintf(log_message, sizeof(log_message), "Electrode %d touched", i);
                    log_event(log_message);
                    break; // Only set one pattern per loop iteration
                }
            }
            if (!any_electrode_touched) {
                log_event("No electrode touched");
            }
        } else {
            fprintf(stderr, "Error reading touch status.\n");
            log_event("Error reading touch status");
        }

        gpioDelay(POLLING_INTERVAL_MS);
    }

    // Cleanup
    set_led_pattern(LED_GPIO_1, LED_GPIO_2, LED_GPIO_3, LED_GPIO_4, 0b0000); // Turn off all LEDs
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

