#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x2B
#define MPR121_TOUCH_THRESHOLD_0 0x41
#define MPR121_RELEASE_THRESHOLD_0 0x42
#define MPR121_FILTERTHRESHOLD_0 0x2C
#define MPR121_FILTERTHRESHOLD_1 0x2D
#define MPR121_FILTERTHRESHOLD_2 0x2E
#define MPR121_FILTERTHRESHOLD_3 0x2F
#define MPR121_FILTERTHRESHOLD_4 0x30
#define MPR121_FILTERTHRESHOLD_5 0x31
#define MPR121_FILTERTHRESHOLD_6 0x32
#define MPR121_FILTERTHRESHOLD_7 0x33
#define MPR121_FILTERTHRESHOLD_8 0x34
#define MPR121_FILTERTHRESHOLD_9 0x35
#define MPR121_FILTERTHRESHOLD_10 0x36
#define MPR121_FILTERTHRESHOLD_11 0x37

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void log_event(const char *message);
void signal_handler(int signal);
