    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// MPR121 initialization function
int mpr121_init() {
    // Check if the MPR121 is present
    char buf[2];
    buf[0] = MPR121_TOUCHSTATUS_L;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Check device ID (optional, but good practice)
    char device_id;
    if (i2cReadDevice(i2c_handle, &device_id, 1) != 0) {
        fprintf(stderr, "Error reading device ID.\n");
        return -1;
    }
    if (device_id != 0x5A) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure MPR121 registers
    char config[2];

    // Set touch and release thresholds for electrode 0
    config[0] = MPR121_TOUCH_THRESHOLD_0;
    config[1] = PROXIMITY_THRESHOLD;
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error writing touch threshold.\n");
        return -1;
    }

    config[0] = MPR121_RELEASE_THRESHOLD_0;
    config[1] = RELEASE_THRESHOLD;
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error writing release threshold.\n");
        return -1;
    }

    // Configure debounce
    config[0] = MPR121_FILTERTHRESHOLD_0;
    config[1] = 0x0A; // Example debounce value
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error writing debounce threshold.\n");
        return -1;
    }

    // Configure baseline filtering
    config[0] = MPR121_BASELINE_FILTER_CONFIG;
    config[1] = 0x03; // Example baseline filter value
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error writing baseline filter config.\n");
        return -1;
    }

    // Enable electrode 0
    config[0] = MPR121_ELECTRODE_CONFIG;
    config[1] = 0x01; // Enable electrode 0
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error writing electrode config.\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    buf[0] = MPR121_TOUCHSTATUS_L;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error reading touch status.\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to log events with timestamps
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

