        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    // Main loop
    while (!terminate) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x01) { // Check if electrode 0 is touched
                printf("Proximity detected on electrode 0\n");
                log_event("Proximity detected on electrode 0");
                gpioWrite(LED_GPIO, 1); // Turn on LED
                gpioDelay(1000); // Wait for 1 second
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading touch status. Retrying...\n");
        }
        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

