#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms timeout
#define PULSE_LENGTH_US 10     // 10 us pulse length
#define TRIGGER_DELAY_US 5     // 5 us trigger delay

// Global variables
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio(void);
void trigger_sensor(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
int log_distance(double distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        program_running = 0;
        printf("Caught SIGINT, exiting...\n");
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    struct gpiod_line_request_config trigger_config;
    memset(&trigger_config, 0, sizeof(trigger_config));
    trigger_config.consumer = "distance_sensor";
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(trigger_line, &trigger_config, 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    struct gpiod_line_request_config echo_config;
    memset(&echo_config, 0, sizeof(echo_config));
    echo_config.consumer = "distance_sensor";
    echo_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(echo_line, &echo_config, 0);
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor(void) {
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = TRIGGER_DELAY_US * 1000; // Convert us to ns

    // Set trigger low
    struct gpiod_line_request_config trigger_config;
    memset(&trigger_config, 0, sizeof(trigger_config));
    trigger_config.consumer = "distance_sensor";
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(trigger_line, &trigger_config, 0) < 0) {
        perror("Error requesting trigger line as output");
        return;
    }
    gpiod_line_set_value(trigger_line, 0);
    nanosleep(&delay, NULL);

    // Set trigger high
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger high");
        return;
    }
    delay.tv_nsec = PULSE_LENGTH_US * 1000; // Convert us to ns
    nanosleep(&delay, NULL);

    // Set trigger low
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger low");
        return;
    }
    gpiod_line_release(trigger_line);
}

// Measure the pulse width of the echo signal
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for echo to go high
    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret < 0) {
        perror("Error getting start time");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 0) {
        ret = clock_gettime(CLOCK_MONOTONIC, &end);
        if (ret < 0) {
            perror("Error getting end time");
            return -1;
        }
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (pulse_width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    // Wait for echo to go low
