#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343000.0 // Speed of sound in cm/s
#define LOG_FILE "distance_log.txt"

// Global variables
FILE *log_file = NULL;
volatile int echo_received = 0;
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that an echo has been received
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        uint32_t pulse_width = end_tick - start_tick;

        // Handle tick wrap-around
        if (start_tick > end_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick + 1;
        }

        if (pulse_width > 0 && pulse_width < 25000) { // Validate pulse width
            double distance = calculate_distance(pulse_width);
            log_distance(distance);
        } else {
            fprintf(stderr, "Invalid pulse width: %u\n", pulse_width);
        }
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * 343.0 / 2000000.0; // cm/s to m/s conversion
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(1000); // 1 second delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

