    if (i2cWriteByteData(i2c_handle, 0x0019, TIMEOUT_DISABLE) < 0) {
        syslog(LOG_ERR, "Failed to write timeout disable register");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0020, START_RANGING) < 0) {
        syslog(LOG_ERR, "Failed to write start ranging register");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    *distance = (buf[1] << 8) | buf[0];
    return 0;
}

// Read status from VL53L1X sensor
int read_status(int *status) {
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, STATUS_REG, buf, 1) != 1) {
        syslog(LOG_ERR, "Failed to read status data");
        return -1;
    }

    *status = buf[0];
    return 0;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Configure XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1); // Enable sensor

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance, status;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

