#define LOG_FILE "gate_log.txt"

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0010
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Cleanup Function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    gpioTerminate();
}

// VL53L1X Initialization Function
int init_vl53l1x() {
    int model_id;

    // Check Model ID
    model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        log_data(-1, -1); // Log error
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        log_data(-1, -1); // Log error
        return -1;
    }
    printf("VL53L1X Model ID: 0x%02X\n", model_id);

    // Set Ranging Mode to Short
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x00) < 0) {
