        log_data(-1, -1); // Log error
        return -1;
    }

    // Read Distance
    distance_mm = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance_mm < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance_mm);
        log_data(-1, -1); // Log error
        return -1;
    }

    distance_cm = distance_mm / 10; // Convert mm to cm

    return distance_cm;
}

// Gate Control Function
void control_gate(int distance) {
    int gate_state = 0; // 0 = closed, 1 = open

    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_GPIO, 1); // Open gate
        gate_state = 1;
    } else {
        gpioWrite(GATE_GPIO, 0); // Close gate
        gate_state = 0;
    }

    log_data(distance, gate_state);
}

