void log_data(int distance, int gate_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %d cm, Gate State: %s\n", timestamp, distance, gate_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

