#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000        // 30 ms timeout
#define MOVING_AVG_SIZE 5
#define LOG_FILE "distance_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold moving average data
typedef struct {
    double values[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverage;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
double measure_distance();
double moving_average(MovingAverage *avg, double new_value);
double map_distance_to_angle(double distance);
void set_servo_angle(double angle);
void log_data(double distance, double angle);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range and frequency for servo
    gpioSetPWMrange(SERVO_PIN, 20000); // 20ms period
    gpioSetPWMfrequency(SERVO_PIN, 50);  // 50Hz

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pulse width measurement
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static int echo_received = 0;

    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate start of echo
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Reset flag after echo ends
    }

    if (end_tick > start_tick) {
        uint32_t pulse_width = end_tick - start_tick;
        double distance = measure_distance(pulse_width);
        MovingAverage *avg = (MovingAverage *)user;

        if (distance >= 2.0 && distance <= 400.0) {
            double avg_distance = moving_average(avg, distance);
            double angle = map_distance_to_angle(avg_distance);
            set_servo_angle(angle);
            log_data(avg_distance, angle);
        } else {
            log_data(-1.0, 90.0); // Log invalid reading
        }
    } else {
        log_data(-1.0, 90.0); // Log invalid reading
    }
}

// Measure distance in centimeters
double measure_distance(uint32_t pulse_width) {
    double time_taken = (double)pulse_width / 1000000.0; // Convert us to s
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance = (time * speed) / 2
    return distance;
}

// Calculate moving average
double moving_average(MovingAverage *avg, double new_value) {
    avg->values[avg->index] = new_value;
    avg->index = (avg->index + 1) % MOVING_AVG_SIZE;
    if (avg->count < MOVING_AVG_SIZE) {
        avg->count++;
    }

    double sum = 0.0;
    for (int i = 0; i < avg->count; i++) {
        sum += avg->values[i];
    }
    return sum / avg->count;
}

// Map distance to servo angle (non-linear logarithmic mapping)
double map_distance_to_angle(double distance) {
    // Non-linear mapping (logarithmic)
    double angle = 90.0 + (distance - 2.0) * (180.0 - 90.0) / (400.0 - 2.0);
    return angle;
}

// Set servo angle
void set_servo_angle(double angle) {
    int pulse_width = 500 + (int)(angle * 2000.0 / 180.0); // Map angle (0-180) to pulse width (500-2500)
    gpioServo(SERVO_PIN, pulse_width);
}

// Log data to CSV file
void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file); // Flush to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    }
    fflush(log_file);

    // Initialize moving average filter
    MovingAverage distance_avg = {{0.0}, 0, 0};

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, &distance_avg) != 0) {
        fprintf(stderr, "Error setting alert function for ECHO_PIN\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(100); // Trigger every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

