    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance = (time * speed) / 2
    return distance;
}

// Calculate moving average
double moving_average(MovingAverage *avg, double new_value) {
    avg->values[avg->index] = new_value;
    avg->index = (avg->index + 1) % MOVING_AVG_SIZE;
    if (avg->count < MOVING_AVG_SIZE) {
        avg->count++;
    }

    double sum = 0.0;
    for (int i = 0; i < avg->count; i++) {
        sum += avg->values[i];
    }
    return sum / avg->count;
}

// Map distance to servo angle (non-linear logarithmic mapping)
double map_distance_to_angle(double distance) {
    // Non-linear mapping (logarithmic)
    double angle = 90.0 + (distance - 2.0) * (180.0 - 90.0) / (400.0 - 2.0);
    return angle;
}

// Set servo angle
void set_servo_angle(double angle) {
    int pulse_width = 500 + (int)(angle * 2000.0 / 180.0); // Map angle (0-180) to pulse width (500-2500)
    gpioServo(SERVO_PIN, pulse_width);
}

// Log data to CSV file
void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file); // Flush to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    }
    fflush(log_file);

    // Initialize moving average filter
    MovingAverage distance_avg = {{0.0}, 0, 0};

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, &distance_avg) != 0) {
        fprintf(stderr, "Error setting alert function for ECHO_PIN\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(100); // Trigger every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

