#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200 // mm

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void update_led(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);   // Close I2C connection
    gpioTerminate();        // Terminate pigpio
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (refer to VL53L1X datasheet)
    // This is a simplified example and may need adjustments based on your specific sensor configuration
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x01) < 0) {
        fprintf(stderr, "Error writing to VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x01) < 0) {
        fprintf(stderr, "Error writing to VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) < 0) { // Enable all ranging modes
        fprintf(stderr, "Error writing to VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, 0x0008, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int distance = -1; // Default to error value
    int retries = 3;

    while (retries > 0) {
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance >= 0) {
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    if (distance < 0) {
        fprintf(stderr, "Failed to read distance after multiple retries\n");
        return -1; // Indicate failure
    }

    return distance;
}

// Update LED based on distance
void update_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn on LED
    } else {
        gpioWrite(GPIO_LED, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            // Store distance in circular buffer
            distance_buffer[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Update LED
            update_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

