#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define GPIO_INTERRUPT 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int threshold = 1000;
int running = 1;

// Function prototypes
int init_pigpio();
int init_i2c(int i2c_bus, int i2c_address);
int read_proximity(int i2c_handle);
int check_threshold(int proximity, int threshold);
int log_data(const char *timestamp, int proximity, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int i2c_handle;
    int threshold;
} ProgramState;

ProgramState state;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read proximity value from Si1102 sensor
int read_proximity(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG_HIGH, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read proximity data: %d\n", result);
        return -1;
    }

    uint16_t proximity = (buf[0] << 8) | buf[1];
    return proximity;
}

// Check if proximity exceeds the threshold
int check_threshold(int proximity, int threshold) {
    return (proximity > threshold) ? 1 : 0;
}

// Log data to file
int log_data(const char *timestamp, int proximity, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(fp, "%s, %d, %s\n", timestamp, proximity, status);
    fclose(fp);
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    int proximity = read_proximity(state.i2c_handle);
    if (proximity < 0) {
        fprintf(stderr, "Failed to read proximity in interrupt handler\n");
        return;
    }

    int threshold_exceeded = check_threshold(proximity, state.threshold);

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    const char *status = (threshold_exceeded) ? "ALERT" : "SAFE";

    if (log_data(timestamp, proximity, status) != 0) {
        fprintf(stderr, "Failed to log data in interrupt handler\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("Caught signal, exiting...\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                // Attempt to parse the address as hex or decimal
                if (strchr(optarg, '.') != NULL) {
                    // Assume it's a hex address
                    state.i2c_handle = init_i2c(I2C_BUS, strtol(optarg, NULL, 16));
                } else {
                    // Assume it's a decimal address
                    state.i2c_handle = init_i2c(I2C_BUS, strtol(optarg, NULL, 10));
                }
                if (state.i2c_handle < 0) {
                    fprintf(stderr, "Invalid I2C address\n");
                    return 1;
                }
                break;
            case 't':
                state.threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (state.i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        i2cClose(state.i2c_handle);
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(GPIO_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_UP);

    // Set interrupt handler for rising edge
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        i2cClose(state.i2c_handle);
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioTerminate();
    i2cClose(state.i2c_handle);

    return 0;
}

