#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz
#define LOG_BASE 10.0

// Global variables
volatile sig_atomic_t program_running = 1;
double previous_frequency = 0.0;

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double calculate_frequency(double distance);
void set_pwm_frequency(double frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, stopping program...\n", signal);
        program_running = 0;
    }
}

// Function to measure distance using HC-SR04
double measure_distance() {
    int wave_id;
    int echo_start = 0, echo_end = 0;
    int timeout = 0;

    // Trigger the sensor
    if (gpioWaveClear() != 0) {
        fprintf(stderr, "Error: Failed to clear wave buffer.\n");
        return -1.0;
    }

    gpioWaveAddGeneric(1, (gpioPulse_t[]){{0, TRIGGER_PIN, 1}, {1, TRIGGER_PIN, 0}});
    wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Error: Failed to create wave: %d\n", wave_id);
        return -1.0;
    }

    gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
    gpioWaveTxStart();

    // Wait for echo or timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        gpioWaveDelete(wave_id);
        return -1.0; // Timeout
    }

    echo_start = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        gpioWaveDelete(wave_id);
        return -1.0; // Timeout
    }

    echo_end = gpioTick();

    gpioWaveDelete(wave_id);

    // Calculate pulse width in microseconds
    int pulse_width = echo_end - echo_start;

    // Calculate distance in centimeters
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 to get distance

    return distance;
}

// Function to calculate frequency based on distance
double calculate_frequency(double distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Calculate frequency using logarithmic formula
    double frequency = MIN_FREQUENCY * pow(LOG_BASE, (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));

    return frequency;
}

// Function to set PWM frequency
void set_pwm_frequency(double frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate PWM period in microseconds
    double period_us = 1000000.0 / frequency;

    // Calculate PWM duty cycle (50%)
    double duty_cycle_us = period_us / 2.0;

    // Set PWM frequency and duty cycle
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    gpioPWM(PWM_PIN, (int)(duty_cycle_us / period_us * 255.0)); // pigpio duty cycle is 0-255
}

// Cleanup function to stop PWM and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Set PWM frequency (initial value)
    set_pwm_frequency(1000.0); // Set initial frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Measure distance
        double distance = measure_distance();

        // Calculate frequency
        double frequency = calculate_frequency(distance);

        // Set PWM frequency
        set_pwm_frequency(frequency);

        // Update previous frequency
        previous_frequency = frequency;

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

