#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define frequency range
#define MIN_FREQ 200
#define MAX_FREQ 2000

// Define distance range
#define MIN_DIST 50
#define MAX_DIST 500

// Define timeout value
#define TIMEOUT 100000 // 100 ms in microseconds

// Global variables
volatile int echo_start_time = 0;
volatile int echo_end_time = 0;
volatile int valid_distance = 0;
volatile int timeout_flag = 0;

// Function prototypes
void triggerSensor();
int getDistance();
int mapDistanceToFrequency(int distance);
void setBuzzerFrequency(int frequency);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
int getDistance() {
    echo_start_time = 0;
    echo_end_time = 0;
    timeout_flag = 0;

    triggerSensor();

    // Wait for echo to start (rising edge)
    int start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT) {
            timeout_flag = 1;
            return -1; // Timeout
        }
    }
    echo_start_time = gpioTick();

    // Wait for echo to end (falling edge)
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT) {
            timeout_flag = 1;
            return -1; // Timeout
        }
    }
    echo_end_time = gpioTick();

    // Calculate pulse width in microseconds
    int pulse_width = echo_end_time - echo_start_time;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    int distance = pulse_width / 58; // cm

    // Validate distance
    if (distance < 5 || distance > 500) {
        return -1; // Invalid distance
    }

    return distance;
}

// Function to map distance to frequency
int mapDistanceToFrequency(int distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DIST) {
        distance = MIN_DIST;
    } else if (distance > MAX_DIST) {
        distance = MAX_DIST;
    }

    // Linear mapping
    int frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    return frequency;
}

// Function to set the buzzer frequency
void setBuzzerFrequency(int frequency) {
    gpioHardwarePWM(BUZZER_PIN, frequency, 128); // 50% duty cycle
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler
    signal(SIGINT, signalHandler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read distance
        int distance = getDistance();

        // Handle timeout or invalid distance
        if (distance == -1) {
            if (timeout_flag) {
                fprintf(stderr, "Error: Timeout reading distance\n");
            } else {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
            distance = valid_distance; // Reuse the last valid distance
        } else {
            valid_distance = distance; // Update last valid distance
        }

        // Map distance to frequency
        int frequency = mapDistanceToFrequency(distance);

        // Set buzzer frequency
        setBuzzerFrequency(frequency);

        // Print distance and frequency
        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    return 0;
}

