#define TIMEOUT_US 50000      // 50 ms timeout
#define MIN_DISTANCE 2.0      // Minimum valid distance (cm)
#define MAX_DISTANCE 400.0    // Maximum valid distance (cm)

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo pin to go high (with timeout)
    long timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    start_tick = gpioTick();

    // Wait for echo pin to go low (with timeout)
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width / 2.0 / SPEED_OF_SOUND;
}

// Function to print the distance
void printDistance(float distance) {
    if (distance < 0) {
        printf("Invalid reading\n");
    } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Distance: %.2f cm (Invalid)\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_width = measurePulseWidth();

        if (pulse_width < 0) {
            printf("Timeout occurred\n");
        } else {
            float distance = calculateDistance(pulse_width);
            printDistance(distance);
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

