#define REG_MEASURE_MODE 0x01
#define REG_RANGE_CONFIG 0x02
#define REG_MEASURE_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Global variables
int spi_handle;
