int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Sensor initialization function
int sensor_init() {
    char tx_buf[2];
    char rx_buf[2];

    // Set continuous measurement mode
    tx_buf[0] = REG_MEASURE_MODE;
    tx_buf[1] = 0x01;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x01\n");
        return -1;
    }

    // Set range configuration (5 m)
    tx_buf[0] = REG_RANGE_CONFIG;
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
