    tx_buf[0] = REG_MEASURE_TRIGGER;
    tx_buf[1] = 0x01;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x00\n");
        return -1;
    }

    return 0;
