#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_REG_LOW 0x22
#define ALS_VISIBLE_REG_HIGH 0x23
#define CSV_FILE "proximity_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

// Read ALS visible function
uint16_t read_als_visible(int fd) {
    uint8_t low, high;

    low = i2c_read_reg(fd, ALS_VISIBLE_REG_LOW);
    if (low < 0) {
        fprintf(stderr, "Error reading ALS visible low byte\n");
        return 0; // Or some error value
    }

    high = i2c_read_reg(fd, ALS_VISIBLE_REG_HIGH);
    if (high < 0) {
        fprintf(stderr, "Error reading ALS visible high byte\n");
        return 0; // Or some error value
    }

    return (uint16_t)((high << 8) | low);
}

// Get ISO-8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data function
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u\n", timestamp, als_visible) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Read ALS visible value
        uint16_t als_visible = read_als_visible(i2c_fd);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp. Skipping logging.\n");
            sleep(5);
            continue;
        }

        // Log data
        if (log_data(timestamp, als_visible) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated successfully.\n");
    return 0;
}

