#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_RESET_REG 0x30
#define SI1120_PART_ID_REG 0x00
#define SI1120_ALS_DATA_LOW 0x22
#define SI1120_ALS_DATA_HIGH 0x23
#define SI1120_PS1_DATA_LOW 0x18
#define SI1120_PS1_DATA_HIGH 0x19
#define SI1120_ALS_DATA_REG 0x22
#define SI1120_PS1_DATA_REG 0x18

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(uint16_t *als_data, uint16_t *prox_data);
void log_data(uint16_t als_data, uint16_t prox_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize the Si1120 sensor
int init_si1120() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_RESET_REG, 0x01);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error resetting Si1120: %d\n", result);
            retries--;
            gpioDelay(10000); // 10 ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    gpioDelay(10000); // Wait for reset to complete

    // Verify Part ID
    uint8_t part_id;
    retries = 3;
    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, SI1120_PART_ID_REG);
        if (part_id >= 0) {
            if (part_id == 0x41) {
                break;
            } else {
                fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
            }
        } else {
            fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read ALS and proximity data from the Si1120 sensor
int read_si1120_data(uint16_t *als_data, uint16_t *prox_data) {
    int retries = 3;
    int result;
    uint8_t low, high;

    // Read ALS data
    while (retries > 0) {
        low = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_LOW);
        if (low < 0) {
            fprintf(stderr, "Error reading ALS low byte: %d\n", low);
            retries--;
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        high = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_HIGH);
        if (high < 0) {
            fprintf(stderr, "Error reading ALS high byte: %d\n", high);
            retries--;
            gpioDelay(10000); // 10 ms delay
            continue;
        }

