#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the Si1182-A-GM I2C address
#define SI1182_ADDR 0x39

// Define register addresses
#define SI1182_PART_ID 0x00
#define SI1182_MEAS_RATE 0x08
#define SI1182_ALS_DATA_LSB 0x22
#define SI1182_ALS_DATA_MSB 0x23
#define SI1182_PROX_DATA_LSB 0x24
#define SI1182_PROX_DATA_MSB 0x25

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(int *fd);
int si1182_init(int fd);
int read_register(int fd, uint8_t reg, uint8_t *value);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_ambient_light(int fd, uint16_t *lux);
int read_proximity(int fd, uint16_t *proximity);
void log_data(uint16_t lux, uint16_t proximity);
void signal_handler(int signal);
char* get_timestamp();

// I2C initialization function
int i2c_init(int *fd) {
    *fd = open(I2C_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(*fd);
        return -1;
    }

    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    uint8_t part_id;
    if (read_register(fd, SI1182_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }

    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate (example value)
    if (write_register(fd, SI1182_MEAS_RATE, 0x07) != 0) {
        fprintf(stderr, "Error writing to MEAS_RATE register\n");
        return -1;
    }

    return 0;
}

// Function to read a register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return 0;
}

// Function to write a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Function to read ambient light data
int read_ambient_light(int fd, uint16_t *lux) {
    uint8_t lsb, msb;

    if (read_register(fd, SI1182_ALS_DATA_LSB, &lsb) != 0) {
        fprintf(stderr, "Error reading ALS LSB\n");
        return -1;
    }

    if (read_register(fd, SI1182_ALS_DATA_MSB, &msb) != 0) {
        fprintf(stderr, "Error reading ALS MSB\n");
        return -1;
    }

    *lux = (uint16_t)((msb << 8) | lsb);
    *lux = *lux * 0.1; // Convert to lux

    return 0;
}

// Function to read proximity data
int read_proximity(int fd, uint16_t *proximity) {
    uint8_t lsb, msb;

    if (read_register(fd, SI1182_PROX_DATA_LSB, &lsb) != 0) {
        fprintf(stderr, "Error reading PROX LSB\n");
        return -1;
    }

    if (read_register(fd, SI1182_PROX_DATA_MSB, &msb) != 0) {
        fprintf(stderr, "Error reading PROX MSB\n");
        return -1;
    }

    *proximity = (uint16_t)((msb << 8) | lsb);

    return 0;
}

// Function to log data to file
void log_data(uint16_t lux, uint16_t proximity) {
    char* timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(log_file, "%s,%u,%u\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written to disk
    free(timestamp);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (i2c_init(&i2c_fd) != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    uint16_t lux, proximity;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_ambient_light(i2c_fd, &lux) != 0) {
            fprintf(stderr, "Error reading ambient light\n");
        }
        if (read_proximity(i2c_fd, &proximity) != 0) {
            fprintf(stderr, "Error reading proximity\n");
        }

        // Log data
        log_data(lux, proximity);

        // Print data to stdout
        printf("Lux: %u, Proximity: %u\n", lux, proximity);

        // Wait 100 ms
        usleep(100000); // 100 ms
    }

    // Close I2C device and log file (should not reach here if signal handler works)
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

