            break;
        } else {
            fprintf(stderr, "Error writing PS_ADC_MISC (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write PS_ADC_MISC after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, SI1145_REG_PS_ADC_GAIN, 0x07);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing PS_ADC_GAIN (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write PS_ADC_GAIN after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing COMMAND (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write COMMAND after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Read proximity data from Si1145
int read_proximity() {
    int low, high;
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
        if (result >= 0) {
            low = result;
            break;
        } else {
            fprintf(stderr, "Error reading PS1_DATA0 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS1_DATA0 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA1);
        if (result >= 0) {
            high = result;
            break;
        } else {
            fprintf(stderr, "Error reading PS1_DATA1 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS1_DATA1 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return (high << 8) | low;
}

// Log data to file
int log_data(int proximity) {
    char* timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, proximity);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            if (log_data(proximity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading proximity data\n");
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

