#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Speed of sound in cm/us
#define SPEED_OF_SOUND 0.0343

// Global variables for timestamps
static volatile uint32_t rising_edge_time = 0;
static volatile uint32_t falling_edge_time = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick, void *user);
float calculateDistance(uint32_t pulseWidth);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Structure to hold sensor data
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
    float distance;
} sensor_data_t;

// Global variable to store sensor data
sensor_data_t sensor_data;

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        rising_edge_time = tick;
    } else if (level == 0) {
        falling_edge_time = tick;
    }
}

// Function to calculate distance in centimeters
float calculateDistance(uint32_t pulseWidth) {
    return (pulseWidth * SPEED_OF_SOUND) / 2.0;
}

// Function to control the buzzer based on distance
void controlBuzzer(float distance) {
    if (distance < 20.0) {
        gpioWrite(BUZZER_PIN, 1); // Set buzzer pin high
    } else {
        gpioWrite(BUZZER_PIN, 0); // Set buzzer pin low
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate pigpio
    exit(0);         // Exit the program
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Wait for a short period
        gpioDelay(500000); // 0.5 seconds

        // Calculate pulse width and distance
        uint32_t pulseWidth = falling_edge_time - rising_edge_time;
        sensor_data.distance = calculateDistance(pulseWidth);

        // Control the buzzer
        controlBuzzer(sensor_data.distance);

        // Print the distance
        printf("Distance: %.2f cm\n", sensor_data.distance);
    }

    return 0; // This line will never be reached due to the infinite loop
}

