#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 200.0     // Maximum measurable distance in cm
#define MIN_DISTANCE 20.0      // Minimum measurable distance in cm
#define MAX_PULSE_WIDTH 2500.0  // Maximum pulse width for servo (us)
#define MIN_PULSE_WIDTH 500.0   // Minimum pulse width for servo (us)
#define TIMEOUT_US 50000        // Timeout for echo pulse (us)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_timeout = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_width);
void setServoAngle(float distance);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    int start_tick, end_tick;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (width++ > timeout) {
            echo_timeout = 1;
            return -1; // Timeout
        }
    }

    echo_start_tick = gpioTick();

    // Wait for the pulse to end
    width = 0;
    while (gpioRead(pin) == level) {
        if (width++ > timeout) {
            echo_timeout = 1;
            return -1; // Timeout
        }
    }

    echo_end_tick = gpioTick();

    return echo_end_tick - echo_start_tick;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Error code from pulseIn

    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to set the servo angle based on the distance
void setServoAngle(float distance) {
    float pulse_width;

    if (distance < MIN_DISTANCE) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (distance > MAX_DISTANCE) {
        pulse_width = MAX_PULSE_WIDTH;
    } else {
        pulse_width = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking Assist System running...\n");

    while (1) {
        triggerSensor();
        long pulse_width = pulseIn(ECHO_PIN, 1, TIMEOUT_US);
        echo_timeout = 0; // Reset timeout flag

        if (pulse_width > 0) {
            float distance = calculateDistance(pulse_width);
            if (distance > 0) {
                printf("Distance: %.2f cm\n", distance);
                setServoAngle(distance);
            } else {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
        } else if (pulse_width < 0) {
            fprintf(stderr, "Error: Echo timeout\n");
        } else {
            fprintf(stderr, "Error: No echo received\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

