#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 50000       // 50 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
    program_running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width
double measurePulseWidth() {
    uint32_t start_tick, end_tick;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) return -1.0; // Timeout

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }
    if (count >= TIMEOUT_US) return -1.0; // Timeout

    end_tick = gpioTick();

    return (double)(end_tick - start_tick);
}

// Function to calculate distance from pulse width
double calculateDistance(double pulse_width_us) {
    if (pulse_width_us < 0) return -1.0; // Indicate error
    return (pulse_width_us * SPEED_OF_SOUND) / 2.0;
}

// Function to map distance to angle
double mapDistanceToAngle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    }
}

// Function to set the servo angle
void setServoAngle(double angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%.2f degrees).\n", angle);
        return;
    }

    // Calculate pulse width based on angle
    double pulse_width = (angle / MAX_ANGLE) * (2000.0 - 500.0) + 500.0; // 500-2500 us
    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        double pulse_width_us = measurePulseWidth();

        // Calculate the distance
        double distance = calculateDistance(pulse_width_us);

        // Map the distance to an angle
        double angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // This point is reached only if program_running is set to 0 by the signal handler
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    return 0;
}

