// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define MEASUREMENT_DELAY_MS 10
#define READ_DELAY_MS 10

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int configure_sensor();
int read_sensor_data(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the Si7005 sensor
int configure_sensor() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = 0x00; // Disable heater, select internal temperature sensor

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for configuration to take effect
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    char buf[1];
    char read_buf[2];
    int result;

    // Read temperature
    buf[0] = TEMP_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to temperature register: %d\n", result);
        return -1;
    }
    gpioDelay(READ_DELAY_MS);
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    int raw_temp = (read_buf[0] << 8) | read_buf[1];
    *temperature = (175.72 * raw_temp) / 65536.0 - 46.85;

    // Read humidity
    buf[0] = HUMID_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to humidity register: %d\n", result);
        return -1;
    }
    gpioDelay(READ_DELAY_MS);
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    int raw_humidity = (read_buf[0] << 8) | read_buf[1];
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

// Log temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }
        gpioDelay(2000); // Wait 2 seconds
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

