#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *temp, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t temp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void signal_handler(int signal);

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the MPU-6050
int init_mpu6050() {
    int who_am_i;

    // Verify sensor presence
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }

    // Reset the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear sleep bit
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100); // Wait for stabilization

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, 0x19, 7) < 0) {
        fprintf(stderr, "Error writing to sample rate divider register\n");
        return -1;
    }

    // Configure accelerometer range
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to accelerometer config register\n");
        return -1;
    }

    // Configure gyroscope range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to gyroscope config register\n");
        return -1;
    }

    return 0;
}

