void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t temp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    printf("Accel X: %6d, Accel Y: %6d, Accel Z: %6d, Temp: %6d, Gyro X: %6d, Gyro Y: %6d, Gyro Z: %6d\n",
