    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MPU-6050 initialised successfully. Reading data every 100ms...\n");

    // Main loop
    int16_t accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z;
    while (program_running) {
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &temp, &gyro_x, &gyro_y, &gyro_z) == 0) {
            print_data(accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

