#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Measurement command for high repeatability
#define MEASURE_HIGH_REPEATABILITY 0xFD

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REPEATABILITY;
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0, cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * raw_temperature / 65535.0;
    *humidity = -6 + 125 * raw_humidity / 65535.0;
    if (*humidity < 0) *humidity = 0;
    if (*humidity > 100) *humidity = 100;

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht40(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

