#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int reg, float *temperature);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read temperature data from the sensor
int read_sensor_data(int reg, float *temperature) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_fd, reg, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Convert the raw data to temperature in Celsius
    int16_t raw_temp = (buf[1] << 8) | buf[0];
    *temperature = (float)raw_temp * 0.02 - 273.15;

    return 0;
}

// Function to log temperature data to a file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read ambient temperature
        if (read_sensor_data(AMBIENT_TEMP_REG, &sensor_data.ambient_temp) != 0) {
            fprintf(stderr, "Error reading ambient temperature, retrying I2C init...\n");
            i2cClose(i2c_fd);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break;
            }
            continue; // Retry reading
        }

        // Read object temperature
        if (read_sensor_data(OBJECT_TEMP_REG, &sensor_data.object_temp) != 0) {
            fprintf(stderr, "Error reading object temperature, retrying I2C init...\n");
            i2cClose(i2c_fd);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break;
            }
            continue; // Retry reading
        }

        // Log the temperature data
        if (log_temperature(sensor_data.ambient_temp, sensor_data.object_temp) != 0) {
