#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x08
#define DATA_FRAME_SIZE 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "pressure_log.csv"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, int cmd1, int cmd2);
int read_data(int handle, char *buffer, int size);
sensor_data_t convert_data(const char *data);
int log_data(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
unsigned char crc8(const char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, int cmd1, int cmd2) {
    char buf[2] = {cmd1, cmd2};
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int size) {
    int result = i2cReadDevice(handle, buffer, size);
    if (result != size) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const char *data) {
    sensor_data_t sensor_data;
    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factors
    float scale_pressure = (float)((data[6] << 8) | data[7]) / 100.0f;
    float scale_temperature = (float)((data[8] << 8) | data[9]) / 100.0f;

    // Apply scale factors to get calibrated values
    sensor_data.pressure = raw_pressure / scale_pressure;
    sensor_data.temperature = raw_temperature / scale_temperature;

    return sensor_data;
}

// Log data to CSV file
int log_data(const char *timestamp, float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD_1, MEASURE_CMD_2) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data_frame[DATA_FRAME_SIZE];
        int retry = 0;
        int read_result = -1;

        // Retry reading data if it fails
        while (retry < RETRY_COUNT && read_result != 0) {
            read_result = read_data(i2c_handle, data_frame, DATA_FRAME_SIZE);
            if (read_result != 0) {
                fprintf(stderr, "Retrying read... (%d/%d)\n", retry + 1, RETRY_COUNT);
                gpioDelay(1000); // Wait 1ms before retrying
                retry++;
            }
        }

        if (read_result == 0) {
            // CRC check
            unsigned char crc_pressure = crc8(data_frame, 2);
            unsigned char crc_temperature = crc8(data_frame + 3, 2);
            unsigned char crc_scale = crc8(data_frame + 6, 2);

            if (crc_pressure != data_frame[2] || crc_temperature != data_frame[5] || crc_scale != data_frame[8]) {
                fprintf(stderr, "CRC check failed\n");
            } else {
                // Convert data
                sensor_data_t sensor_data = convert_data(data_frame);

                // Get timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];
                time(&rawtime);
                timeinfo = gmtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                // Log data
                if (log_data(timestamp, sensor_data.pressure, sensor_data.temperature) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read data after multiple retries\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

