// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 10
#define LOG_FILE "sht40_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t cmd);
int i2c_read(int fd, uint8_t *buf, int len);
int sht40_read_measurement(int fd, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int sig);

// CRC-8 algorithm
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// SHT40 read measurement function
int sht40_read_measurement(int fd, float *temperature, float *humidity) {
    uint8_t buf[6];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write(fd, MEASURE_HIGH_REPEATABILITY) != 0) {
            fprintf(stderr, "Error writing measurement command. Retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

        if (i2c_read(fd, buf, 6) != 0) {
            fprintf(stderr, "Error reading measurement data. Retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // CRC validation
        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC validation failed. Retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        uint16_t raw_temperature = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[3] << 8) | buf[4];

        *temperature = -45 + 175 * raw_temperature / 65535.0;
        *humidity = 100 * raw_humidity / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after multiple retries.\n");
    return -1; // Failure
}

