#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIGGER_MEASUREMENT 0x2196
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    uint8_t cmd[2] = {(TRIGGER_MEASUREMENT >> 8) & 0xFF, TRIGGER_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure_pa = (float)raw_pressure / 60.0;
    sensor_data.temperature_c = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        sensor_data_t sensor_data;

        // Trigger measurement with retry logic
        int trigger_result = -1;
        for (int i = 0; i < 3; ++i) {
            if (trigger_measurement() == 0) {
                trigger_result = 0;
                break;
            } else {
                gpioDelay(1000); // Wait 1 ms before retrying
            }
        }
        if (trigger_result != 0) {
            fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        gpioDelay(1000); // Wait at least 1 ms after triggering

        // Read sensor data with retry logic
        int read_result = -1;
        for (int i = 0; i < 3; ++i) {
            if (read_sensor_data(data) == 0) {
                read_result = 0;
                break;
            } else {
                gpioDelay(1000); // Wait 1 ms before retrying
            }
        }
        if (read_result != 0) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

