#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_LENGTH 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define SCALE_FACTOR_REG 0x00
#define MEASUREMENT_DELAY_MS 45
#define LOG_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *bus, int addr);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t *data, int len);
int crc8(const uint8_t *data, int len);
int read_sensor_data(int fd, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);

// CRC-8 checksum calculation
int crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t raw_data[DATA_LENGTH];
    int16_t raw_pressure, raw_temperature;
    uint8_t crc_pressure, crc_temperature, crc_scale;

    // Trigger measurement
    if (i2c_write(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement to complete
    usleep(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

    // Read data
    if (i2c_read(fd, raw_data, DATA_LENGTH) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Validate CRC for pressure
    crc_pressure = raw_data[2];
    if (crc8(raw_data, 2) != crc_pressure) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature
    crc_temperature = raw_data[5];
    if (crc8(raw_data + 3, 2) != crc_temperature) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Validate CRC for scale factor
    crc_scale = raw_data[8];
    if (crc8(raw_data + 6, 2) != crc_scale) {
        fprintf(stderr, "CRC error for scale factor data\n");
        return -1;
    }

    // Extract raw values
    raw_pressure = (raw_data[0] << 8) | raw_data[1];
    raw_temperature = (raw_data[3] << 8) | raw_data[4];

    // Convert to physical units
    data->pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data->temperature = (float)raw_temperature / 200.0 - 45.0;

    return 0;
}

// Log data function
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    sensor_data_t sensor_data;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    fflush(log_file);

    // Main loop
    while (program_running) {
        // Read sensor data
        ret = read_sensor_data(i2c_fd, &sensor_data);
        if (ret == 0) {
            // Log data
            if (log_data(log_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize I2C...\n");
            close(i2c_fd);
            i2c_fd = i2c_init(I2C_BUS, SDP800_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                program_running = 0; // Exit if re-initialization fails
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sample every 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

