#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define PRESSURE_SCALE 240.0
#define TEMPERATURE_SCALE 200.0
#define TEMPERATURE_OFFSET -45.0
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define DATA_FILE "airflow_data.txt"
#define RETRY_COUNT 3

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len);
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len);
int crc8(const uint8_t *data, int len);
int read_sdp800(int fd, float *pressure, float *temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);

// CRC-8 calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read SDP800 sensor function
int read_sdp800(int fd, float *pressure, float *temperature) {
    uint8_t write_data[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t read_data[6];
    int retries = RETRY_COUNT;

    // Send measurement command
    while (retries > 0) {
        if (i2c_write(fd, SDP800_ADDR, write_data, 2) == 0) {
            break;
        } else {
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to send measurement command after multiple retries.\n");
        return -1;
    }

    // Wait for measurement (at least 1 ms)
    usleep(1000);

    // Read data
    retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2c_read(fd, SDP800_ADDR, read_data, 6) == 0) {
            break;
        } else {
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read data after multiple retries.\n");
        return -1;
    }

    // CRC validation
    if (crc8(read_data, 2) != read_data[2] || crc8(read_data + 3, 2) != read_data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert data
    int16_t raw_pressure = (read_data[0] << 8) | read_data[1];
    int16_t raw_temperature = (read_data[3] << 8) | read_data[4];

    *pressure = (float)raw_pressure / PRESSURE_SCALE;
    *temperature = (float)raw_temperature / TEMPERATURE_SCALE + TEMPERATURE_OFFSET;

    return 0;
}

// Log data function
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    float pressure, temperature;

    // Main loop
    while (keep_running) {
        if (read_sdp800(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1); // Read data every 1 second
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

