#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define HUMIDITY_THRESHOLD 70.0
#define TEMPERATURE_THRESHOLD_HIGH 28.0
#define TEMPERATURE_THRESHOLD_LOW 27.0

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer structure
typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
int i2c_handle;
CircularBuffer buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(CircularBuffer *buffer, float temperature, float humidity);
void print_buffer(CircularBuffer *buffer);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    char buf[2];
    int result;
    int retries = 0;

    // Trigger temperature measurement
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, 0xE3);
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing temperature trigger (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write temperature trigger after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break; // Success
        fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read temperature data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;

    // Trigger humidity measurement
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, 0xE5);
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing humidity trigger (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write humidity trigger after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break; // Success
        fprintf(stderr, "Error reading humidity data (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read humidity data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0;
}

// Control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMPERATURE_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMPERATURE_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float temperature, float humidity) {
    time(&buffer->data[buffer->head].timestamp);
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].humidity = humidity;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Print the contents of the circular buffer
void print_buffer(CircularBuffer *buffer) {
    printf("Timestamp, Temperature, Humidity\n");
    int start = (buffer->count == BUFFER_SIZE) ? buffer->head : 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer->data[index].timestamp));
        printf("%s, %.2f, %.2f\n", timestamp_str, buffer->data[index].temperature, buffer->data[index].humidity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially OFF

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_buffer(&buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int retry;

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(&temperature, &humidity) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "Failed to read sensor data (attempt %d).\n", retry + 1);
                retry++;
                gpioDelay(1000000); // Wait 1 second before retrying
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Assuming sensor absent.\n", RETRY_COUNT);
            temperature = -999.0; // Indicate sensor absent
            humidity = -999.0;
        }

        // Log data to buffer
        add_to_buffer(&buffer, temperature, humidity);

        // Control fan
        control_fan(temperature);

        // Print buffer contents
        print_buffer(&buffer);

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

