#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Command to start periodic measurement
#define START_PERIODIC_MEASUREMENT 0x21B1

// Command to stop periodic measurement
#define STOP_PERIODIC_MEASUREMENT 0x3F86

// Data ready flag command
#define DATA_READY_FLAG 0xE4B8

// Data read command
#define READ_MEASUREMENT 0xEC05

// Log file name
#define LOG_FILE "air_quality.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int crc8(const uint8_t *data, int len);
int read_scd40_data(int i2c_handle, uint16_t *co2, float *temperature, float *humidity);
int log_data(FILE *log_file, uint16_t co2, float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 checksum calculation
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read data from SCD40 sensor
int read_scd40_data(int i2c_handle, uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buffer[9];
    uint16_t raw_co2, raw_temperature, raw_humidity;

    // Send read measurement command
    if (i2cWriteWordData(i2c_handle, 0, READ_MEASUREMENT) != 0) {
        fprintf(stderr, "Error writing read measurement command to SCD40\n");
        return -1;
    }

    // Wait for data to be ready (at least 1 second)
    gpioDelay(1000000); // 1 second

    // Read 9 bytes from the sensor
    if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
        fprintf(stderr, "Error reading data from SCD40\n");
        return -1;
    }

    // Verify CRC checksum for CO2
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }

    // Verify CRC checksum for temperature
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Verify CRC checksum for humidity
    if (crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Extract raw values
    raw_co2 = (buffer[0] << 8) | buffer[1];
    raw_temperature = (buffer[3] << 8) | buffer[4];
    raw_humidity = (buffer[6] << 8) | buffer[7];

    // Convert raw values to physical units
    *co2 = raw_co2;
    *temperature = -45 + 175 * raw_temperature / 65535.0;
    *humidity = 100 * raw_humidity / 65535.0;

    return 0;
}

// Log data to file
int log_data(FILE *log_file, uint16_t co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint16_t co2;
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handle
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Start periodic measurement
    if (i2cWriteWordData(i2c_handle, 0, START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error writing start periodic measurement command to SCD40\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000000); // Wait 1 second

    // Main loop
    while (!terminate) {
        // Read data from SCD40
        if (read_scd40_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            // Log data to file
            if (log_data(log_file, co2, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading SCD40 data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Stop periodic measurement
    if (i2cWriteWordData(i2c_handle, 0, STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error writing stop periodic measurement command to SCD40\n");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
