#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    time_t timestamp;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint8_t *data);
int stop_periodic_measurement();
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(uint16_t co2, uint16_t temperature, uint16_t humidity);
void print_buffer();
void control_led(uint16_t co2);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    uint8_t command[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to get data ready status
int get_data_ready_status() {
    uint8_t command[2] = {0xE4, 0xB8};
    uint8_t data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write get data ready status command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read get data ready status: %d\n", result);
        return -1;
    }

    return data[0];
}

// Function to read measurement data
int read_measurement(uint8_t *data) {
    uint8_t command[2] = {0xEC, 0x05};
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    uint8_t command[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write stop periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to add data to the circular buffer
void add_to_buffer(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    circular_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("[%d] CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%RH, Timestamp: %s\n",
               index, circular_buffer[index].co2, (float)circular_buffer[index].temperature / 100.0, (float)circular_buffer[index].humidity / 100.0, timestamp_str);
    }
    printf("--- End of Buffer ---\n\n");
}

// Function to control the LED based on CO2 level
void control_led(uint16_t co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Check if data is ready
        int data_ready = get_data_ready_status();
        if (data_ready == 1) {
            uint8_t data[9];
            if (read_measurement(data) == 0) {
                // Validate CRC checksums
                if (crc8(data, 2) == data[2] && crc8(data + 3, 2) == data[5] && crc8(data + 6, 2) == data[8]) {
                    // Extract sensor data
                    uint16_t co2 = (data[0] << 8) | data[1];
                    uint16_t temperature = (data[3] << 8) | data[4];
                    uint16_t humidity = (data[6] << 8) | data[7];

                    // Add data to circular buffer
                    add_to_buffer(co2, temperature, humidity);

                    // Print sensor data
                    printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%RH\n", co2, (float)temperature / 100.0, (float)humidity / 100.0);

                    // Control LED
                    control_led(co2);
                } else {
                    fprintf(stderr, "CRC checksum error\n");
                }
            } else {
                fprintf(stderr, "Failed to read measurement data\n");
            }
        } else {
            fprintf(stderr, "Data not ready\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();

    // Print the buffer before exiting
    print_buffer();

    return 0;
}

