#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50000 // 50 ms timeout
#define NUM_SAMPLES 100 // Number of samples for averaging

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int consecutive_failures = 0;

// Structure to hold temperature data
typedef struct {
    int th;
    int tl;
} TemperatureData;

// Function prototypes
int initialize_pigpio();
TemperatureData read_temperature();
float convert_to_celsius(TemperatureData data);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read temperature from TMP05 sensor
TemperatureData read_temperature() {
    TemperatureData data;
    int high_time = 0;
    int total_time = 0;
    int start_tick, end_tick;

    // Wait for the start of the signal (falling edge)
    start_tick = gpioTick();
