#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define CRC8_POLYNOMIAL 0x31
#define OFFSET_AMPLITUDE 2.0
#define OFFSET_FREQUENCY 0.01
#define OFFSET_DUTY_CYCLE 0.5
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int read_sht35(int handle, uint16_t *temperature, uint16_t *humidity);
uint8_t crc8(const uint8_t *data, int len);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void add_offset(float *temperature, float *humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_temperature(uint16_t raw_temperature) {
    float temperature = (175.0 * raw_temperature) / 65535.0 - 45.0;
    return temperature;
}

// Humidity conversion function
float convert_humidity(uint16_t raw_humidity) {
    float humidity = (100.0 * raw_humidity) / 65535.0;
    return humidity;
}

// Add offset to temperature and humidity
void add_offset(float *temperature, float *humidity) {
    time_t now = time(NULL);
    double seconds = difftime(now, 0); // Get seconds since epoch
    double offset = OFFSET_AMPLITUDE * sin(OFFSET_FREQUENCY * seconds + OFFSET_DUTY_CYCLE * M_PI);
    *temperature += offset;
    *humidity += offset;
}

// Log data to file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from SHT35 sensor
int read_sht35(int handle, uint16_t *temperature, uint16_t *humidity) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[6];

    if (i2cWriteDevice(handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15 ms)

    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    uint8_t temp_data[2] = {buf[0], buf[1]};
    uint8_t hum_data[2] = {buf[3], buf[4]};

    if (crc8(temp_data, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (crc8(hum_data, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[3] << 8) | buf[4];

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c(I2C_BUS, SHT35_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data with retries
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sht35(i2c_handle, &raw_temperature, &raw_humidity) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retry %d failed, retrying in %d seconds...\n", retry + 1, RETRY_DELAY);
                gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries, logging NaN values\n", RETRY_COUNT);
            temperature = NAN;
            humidity = NAN;
        } else {
            // Convert raw data to temperature and humidity
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);
        }

        // Add offset to temperature and humidity
        add_offset(&temperature, &humidity);

        // Log data to file
        if (log_data(log_file, temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

