// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define HUMIDITY_CMD 0xF5
#define TEMPERATURE_CMD 0xF3
#define PAIRING_CMD 0xE0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00
#define READ_ATTEMPTS 5
#define READ_TIMEOUT_MS 100
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int handle, uint16_t command, uint16_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len, uint8_t crc);
int convert_temperature(uint16_t raw_temp);
int convert_humidity(uint16_t raw_humidity);
int log_data(const char *timestamp, int temperature, int humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int temperature;
    int humidity;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries and timeout
int read_sensor_data(int handle, uint16_t command, uint16_t *data) {
    char buf[3];
    int attempts = 0;
    int result;

    while (attempts < READ_ATTEMPTS) {
        // Send measurement command
        result = i2cWriteByteData(handle, command, 0); // No data to write
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            gpioDelay(1000); // 1 ms delay
            attempts++;
            continue;
        }

        gpioDelay(100); // Wait for measurement (datasheet specifies 20ms for high precision)

        // Read 3 bytes of data
        result = i2cReadI2CBlockData(handle, 0, buf, 3);
        if (result != 3) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            gpioDelay(1000); // 1 ms delay
            attempts++;
            continue;
        }

        // Verify CRC
        if (verify_crc((uint8_t *)buf, 2, buf[2])) {
            *data = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "CRC check failed\n");
            gpioDelay(1000); // 1 ms delay
            attempts++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d attempts\n", READ_ATTEMPTS);
    return -1; // Failure
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC-8 checksum
int verify_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Convert raw temperature data to Celsius
int convert_temperature(uint16_t raw_temp) {
    return (int)(175.72 * raw_temp / 65536.0 - 46.85);
}

// Convert raw humidity data to percentage
int convert_humidity(uint16_t raw_humidity) {
    return (int)(125.0 * raw_humidity / 65536.0 - 6.0);
}

// Log data to CSV file
int log_data(const char *timestamp, int temperature, int humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];
        uint16_t raw_humidity, raw_temperature;
        sensor_data_t sensor_data;

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Read humidity
        if (read_sensor_data(i2c_handle, HUMIDITY_CMD, &raw_humidity) != 0) {
            fprintf(stderr, "Error reading humidity, resetting sensor\n");
            i2cWriteByteData(i2c_handle, 0xFE, 0); // Reset command
            gpioDelay(1000); // Wait for reset
            continue;
        }

        // Read temperature
        if (read_sensor_data(i2c_handle, TEMPERATURE_CMD, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading temperature, resetting sensor\n");
            i2cWriteByteData(i2c_handle, 0xFE, 0); // Reset command
            gpioDelay(1000); // Wait for reset
            continue;
        }

        // Convert data
        sensor_data.temperature = convert_temperature(raw_temperature);
        sensor_data.humidity = convert_humidity(raw_humidity);

        // Log data
        if (log_data(timestamp, sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

