#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_CMD_MSB 0x36
#define MEASUREMENT_CMD_LSB 0x2F
#define CONVERSION_TIME_MS 50
#define SAMPLE_INTERVAL_S 1
#define DATA_FILE "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function prototypes
int init_pigpio();
int init_i2c();
int send_measurement_command(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data);
float convert_pressure(uint16_t raw_pressure, uint8_t scale_factor);
float convert_temperature(uint16_t raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc = crc8_table[crc ^ data[i]];
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send the continuous measurement command to the sensor
int send_measurement_command(int i2c_handle) {
    char cmd[2] = {MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C bus
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Convert raw pressure data to Pascals
float convert_pressure(uint16_t raw_pressure, uint8_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor - 1000.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    size_t bytes_written = fwrite(&pressure, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write pressure data\n");
        return -1;
    }
    bytes_written = fwrite(&temperature, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write temperature data\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "wb");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        uint16_t raw_pressure, raw_temperature;
        uint8_t scale_factor;

        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS);

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for pressure
        uint8_t crc_pressure = crc8(data, 2);
        if (crc_pressure != data[2]) {
            fprintf(stderr, "Pressure CRC check failed\n");
            continue;
        }

        // Validate CRC for temperature
        uint8_t crc_temperature = crc8(data + 3, 2);
        if (crc_temperature != data[5]) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue;
        }

        // Extract raw pressure and temperature values
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];
        scale_factor = data[6];

        // Convert data
        float pressure = convert_pressure(raw_pressure, scale_factor);
        float temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(data_file, pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

