#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle);
float calculate_flow_rate(int raw_data);
void set_fan_speed(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle) {
    int raw_data = i2cReadWordData(i2c_handle, 0x00); // Read from register 0x00
    if (raw_data < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", raw_data);
        return -1; // Indicate error
    }
    return raw_data;
}

// Function to calculate flow rate from raw data
float calculate_flow_rate(int raw_data) {
    // Mask off status bits (assuming only 2 status bits)
    raw_data &= 0x3FFF; // Keep only the 14 bits

    // Linear transfer function: 0 counts = 0 SLPM, 14745 counts = 10 SLPM
    float flow_rate = ((float)raw_data / 14745.0) * 10.0;
    return flow_rate;
}

// Function to set fan speed based on flow rate
void set_fan_speed(float flow_rate) {
    // Map flow rate (0-10 SLPM) to PWM duty cycle (0-255)
    int duty_cycle = (int)((flow_rate / 10.0) * 255.0);

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to PWM mode
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_data = read_sensor_data(i2c_handle);
        if (raw_data >= 0) {
            float flow_rate = calculate_flow_rate(raw_data);
            set_fan_speed(flow_rate);
            log_data(flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor, skipping this iteration.\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

