#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define LED_GPIO 17
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature();
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);

// Function to read temperature from STLM75
int read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1; // Indicate error
    }

    // Convert from little-endian to big-endian
    raw_temp = ((raw_temp & 0xFF) << 8) | ((raw_temp & 0xFF00) >> 8);

    // Extract the 9-bit temperature value (ignoring the 7-bit status)
    int temp_value = raw_temp >> 7;

    // Convert to Celsius (9-bit resolution)
    temperature = (float)temp_value * 0.125;

    return (int)(temperature * 100); // Return as integer for simplicity
}

// Function to calculate the running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer with zeros
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_temp = read_temperature();
        if (raw_temp != -1) {
            // Store temperature in circular buffer
            temperature_buffer[buffer_index] = (float)raw_temp / 100.0; // Convert back to float
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average temperature
            float average_temperature = calculate_average();

            // Control LED
            control_led(average_temperature);

            printf("Temperature: %.2f C, Average: %.2f C\n", (float)raw_temp / 100.0, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping average calculation.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

