#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_CONT_MEAS 0x21B1
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_SET_MEAS_INTERVAL 0x4600

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 2

// Ventilation system thresholds
#define CO2_LOW 800
#define CO2_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int start_continuous_measurement();
int read_measurement(float *co2, float *temperature, float *humidity);
int get_data_ready();
int crc8(const unsigned char *data, int len);
void log_data(float co2, float temperature, float humidity);
void control_ventilation(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement with ambient pressure compensation disabled
int start_continuous_measurement() {
    unsigned char cmd[2] = {(SCD30_CMD_START_CONT_MEAS >> 8) & 0xFF, SCD30_CMD_START_CONT_MEAS & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start continuous measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read measurement data from SCD30
int read_measurement(float *co2, float *temperature, float *humidity) {
    unsigned char cmd[2] = {(SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF, SCD30_CMD_READ_MEASUREMENT & 0xFF};
    unsigned char data[18];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, (char *)data, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC Check
    if (crc8(data, 4) != data[4] || crc8(data + 5, 4) != data[9] || crc8(data + 10, 4) != data[14]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data to float
    unsigned int co2_raw = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    unsigned int temperature_raw = (data[6] << 24) | (data[7] << 16) | (data[8] << 8) | data[9];
    unsigned int humidity_raw = (data[12] << 24) | (data[13] << 16) | (data[14] << 8) | data[15];

    *co2 = *((float *)&co2_raw);
    *temperature = *((float *)&temperature_raw);
    *humidity = *((float *)&humidity_raw);

    return 0;
}

// Get data ready flag
int get_data_ready() {
    unsigned char cmd[2] = {(SCD30_CMD_GET_DATA_READY >> 8) & 0xFF, SCD30_CMD_GET_DATA_READY & 0xFF};
    unsigned char data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write get data ready command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data ready data: %d\n", result);
        return -1;
    }

    // CRC Check
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC check failed for data ready\n");
        return -1;
    }

    return data[0];
}

// Log data to file
void log_data(float co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

// Control ventilation system
void control_ventilation(float co2) {
    if (co2 < CO2_LOW) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_HIGH) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start continuous measurement
    if (start_continuous_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    float co2, temperature, humidity;
    while (!terminate) {
        // Check data ready flag
        int data_ready = get_data_ready();
        if (data_ready != 1) {
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Read measurement data
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            // Log data
            log_data(co2, temperature, humidity);

            // Control ventilation
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Failed to read measurement\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay for measurement interval
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

