#define CRC_INIT 0xFF
#define MEASUREMENT_DELAY_MS 45

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

