void log_data(const sensor_data_t *data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f C\n", data->pressure, data->temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

    // Read data from sensor
    uint8_t raw_data[9];
    if (read_data(i2c_handle, raw_data, 9) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate CRC checksums
    if (!validate_crc(raw_data, 3) || !validate_crc(raw_data + 3, 3) || !validate_crc(raw_data + 6, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Convert data
    sensor_data_t sensor_data = convert_data(raw_data);

    // Log data
    log_data(&sensor_data);

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

