// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define HDC1000_TEMP_REG 0x00
#define HDC1000_HUMID_REG 0x01
#define HDC1000_CONFIG_REG 0x02

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the HDC1000 sensor
int hdc1000_init(int fd) {
    uint8_t config_data[2];
    config_data[0] = HDC1000_CONFIG_REG;
    config_data[1] = 0x00; // Default configuration

    if (write(fd, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int hdc1000_read(int fd, float *temperature, float *humidity) {
    uint8_t data[4];
    uint16_t raw_temperature, raw_humidity;

    // Write the temperature register address to initiate a measurement
    uint8_t temp_reg = HDC1000_TEMP_REG;
    if (write(fd, &temp_reg, 1) != 1) {
        fprintf(stderr, "Error writing to temperature register: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the measurement to complete (at least 20 ms)
    usleep(20000); // 20 ms

    // Read 4 bytes from the sensor
    if (read(fd, data, 4) != 4) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the raw temperature and humidity values
    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[2] << 8) | data[3];

    // Convert the raw values to temperature and humidity
    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device file
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (hdc1000_init(i2c_fd) != 0) {
        fprintf(stderr, "Error initializing HDC1000 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log temperature and humidity data
    float temperature, humidity;
    while (1) {
        if (hdc1000_read(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading temperature and humidity.\n");
        }

        sleep(5);
    }

    // The program should never reach here due to the infinite loop, but it's good practice to include cleanup code
    close(i2c_fd);
    return 0;
}

