// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_CMD 0xE3
#define MEASUREMENT_DELAY_MS 20
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7051_address;
    int measurement_delay_ms;
} config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from Si7051 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement (20ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        unsigned int raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Log temperature to console
void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

