    program_running = 0;
}

// Function to read pressure from the MLX90833 sensor
int read_pressure(int i2c_handle) {
    char buf[2];
    int result;

    // Write the pressure register address to the sensor
    result = i2cWriteByteData(i2c_handle, PRESSURE_REG, PRESSURE_REG);
    if (result != 0) {
        fprintf(stderr, "Error writing to pressure register: %d\n", result);
        return -1; // Indicate an error
    }

    // Read two bytes from the pressure register
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit value
    int16_t pressure_raw = (buf[0] << 8) | buf[1];

    return pressure_raw;
}

