        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

