// I2C address of the ICP-10101 sensor
#define ICP10101_ADDR 0x63

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// OTP read command
#define OTP_READ_CMD 0x50

// High-precision measurement command
#define MEASURE_CMD 0x40

// OTP data length
#define OTP_DATA_LEN 8

// Measurement data length
#define MEASUREMENT_DATA_LEN 6

// Structure to hold calibration coefficients
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
} calibration_coeffs_t;

// Global variables
int i2c_handle;
calibration_coeffs_t coeffs;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(calibration_coeffs_t *coeffs);
int trigger_measurement();
int read_measurement_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double temperature);
void log_data(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data(calibration_coeffs_t *coeffs) {
    char buf[OTP_DATA_LEN];
    int result = i2cReadI2CBlockData(i2c_handle, OTP_READ_CMD, buf, OTP_DATA_LEN);

    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    if (result == 0) {
        fprintf(stderr, "Error: No data received from sensor.\n");
        return -1;
    }

    // Convert the received bytes to integers
    coeffs->c0 = (int32_t)((uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3]);
