    // Shift the values to get the correct sign
    coeffs->c0 = coeffs->c0 >> 8;
    coeffs->c1 = coeffs->c1 >> 8;

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

