int read_measurement_data(int32_t *temperature, int32_t *pressure) {
    char buf[MEASUREMENT_DATA_LEN];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, MEASUREMENT_DATA_LEN);

    if (result < 0) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    if (result == 0) {
        fprintf(stderr, "Error: No data received from sensor.\n");
        return -1;
