int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90819_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure data from the sensor
int read_pressure(int i2c_handle, int *raw_pressure) {
    char buf[2];
    int result;

    // Trigger measurement (write to control register, if needed)
    // For MLX90819, triggering is typically done by reading the pressure registers.
    // If triggering is required, implement the appropriate I2C write here.

    // Read MSB
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_MSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading MSB: %d\n", result);
        return -1;
    }
    int msb = buf[0];

    // Read LSB
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_LSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading LSB: %d\n", result);
        return -1;
    }
    int lsb = buf[0];

    *raw_pressure = (msb << 8) | lsb;
    return 0;
}

// Convert raw pressure value to kPa
float convert_to_kPa(int raw_pressure) {
    return (float)raw_pressure * SCALING_FACTOR;
}

