    ProgramState state = { .i2c_handle = -1, .terminate = 0 };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    state.i2c_handle = i2c_handle; // Update state

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_pressure;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(state.i2c_handle, &raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            log_data(pressure_kPa);
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup(&state);
    return 0;
}

