#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 45
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw pressure data to Pascals
float convert_pressure(uint16_t raw_pressure) {
    return (float)raw_pressure / 60.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_command(MEASURE_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        uint16_t raw_pressure, raw_temperature;
        uint8_t crc_pressure, crc_temperature;

        // Wait for measurement
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

        // Read data
        if (read_data(data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Extract raw values and CRCs
        raw_pressure = (data[0] << 8) | data[1];
        crc_pressure = data[2];
        raw_temperature = (data[3] << 8) | data[4];
        crc_temperature = data[5];

        // CRC validation
        uint8_t pressure_data[2] = {data[0], data[1]};
        uint8_t temperature_data[2] = {data[3], data[4]};

        if (crc8(pressure_data, 2) != crc_pressure) {
            fprintf(stderr, "Pressure CRC check failed!\n");
            continue;
