#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 45
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

