#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define SCALE_FACTOR 0.01
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_pressure(uint16_t *pressure);
float convert_to_kPa(uint16_t raw_pressure);
int log_pressure(float pressure_kPa);
void check_pressure_range(float pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read pressure from the sensor
int read_pressure(uint16_t *pressure) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
            return -1;
        }
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading pressure data after re-open: %d\n", result);
            return -1;
        }
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw pressure to kPa
float convert_to_kPa(uint16_t raw_pressure) {
    return raw_pressure * SCALE_FACTOR;
}

// Function to log pressure to a CSV file
int log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        // Check if the file is newly created and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        rewind(log_file);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to check pressure range and log warnings
void check_pressure_range(float pressure_kPa) {
    if (pressure_kPa < MIN_PRESSURE || pressure_kPa > MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure out of safe range: %.2f kPa\n", pressure_kPa);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_pressure;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            log_pressure(pressure_kPa);
            check_pressure_range(pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

