        if (result != 2) {
            fprintf(stderr, "Error reading pressure data after re-open: %d\n", result);
            return -1;
        }
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw pressure to kPa
float convert_to_kPa(uint16_t raw_pressure) {
    return raw_pressure * SCALE_FACTOR;
}

// Function to log pressure to a CSV file
int log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        // Check if the file is newly created and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        rewind(log_file);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to check pressure range and log warnings
void check_pressure_range(float pressure_kPa) {
    if (pressure_kPa < MIN_PRESSURE || pressure_kPa > MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure out of safe range: %.2f kPa\n", pressure_kPa);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_pressure;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            log_pressure(pressure_kPa);
            check_pressure_range(pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

