        fprintf(stderr, "Failed to open log file for size check\n");
        return 1;
    }

    fseek(finfo, 0, SEEK_END);
    long file_size = ftell(finfo);
    fclose(finfo);

    if (file_size > LOG_FILE_SIZE_LIMIT) {
        remove(LOG_FILE);
        fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open log file for truncation\n");
            return 1;
        }
        fclose(fp);
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

