#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define GPIO_PIN 4
#define SENT_SYNC_PULSE 56
#define SENT_DATA_BITS 12
#define SENT_CHECKSUM_PULSE 56
#define MIN_PULSE_WIDTH 36
#define MAX_PULSE_WIDTH 813
#define LOG_FILE "pressure_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int sync_pulse;
    unsigned int status_nibble;
    unsigned int data_nibbles[3];
    unsigned int checksum_nibble;
} SENT_Data;

// Function prototypes
int initialize_gpio();
SENT_Data read_sent_data();
float convert_to_pressure(SENT_Data data);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read SENT data
SENT_Data read_sent_data() {
    SENT_Data data;
    int i;
    unsigned int pulse_width;
    unsigned int start_time, end_time;

    // Wait for the start of the SENT frame (falling edge)
    while (gpioRead(GPIO_PIN) == 1 && running) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    start_time = gpioTick();

    // Read the sync pulse
    while (gpioRead(GPIO_PIN) == 0 && running) {
        gpioDelay(1);
    }
    end_time = gpioTick();
    data.sync_pulse = end_time - start_time;

    // Read the status nibble
    for (i = 0; i < 4; i++) {
        while (gpioRead(GPIO_PIN) == 1 && running) {
            gpioDelay(1);
        }
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0 && running) {
            gpioDelay(1);
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Invalid pulse width for status nibble: %d\n", pulse_width);
            data.status_nibble = 0; // Indicate error
            return data;
        }
        if (i < 2) {
            data.status_nibble = (data.status_nibble << 4) | (pulse_width / 6); // Divide by 6 to get nibble value
        } else {
            data.status_nibble = (data.status_nibble << 4) | (pulse_width / 6); // Divide by 6 to get nibble value
        }
    }

    // Read the data nibbles
    for (i = 0; i < 3; i++) {
        while (gpioRead(GPIO_PIN) == 1 && running) {
            gpioDelay(1);
        }
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0 && running) {
            gpioDelay(1);
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Invalid pulse width for data nibble %d: %d\n", i, pulse_width);
            data.data_nibbles[i] = 0; // Indicate error
            return data;
        }
        data.data_nibbles[i] = pulse_width / 6; // Divide by 6 to get nibble value
    }

    // Read the checksum nibble
    while (gpioRead(GPIO_PIN) == 1 && running) {
        gpioDelay(1);
    }
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && running) {
        gpioDelay(1);
    }
    end_time = gpioTick();
    pulse_width = end_time - start_time;
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width for checksum nibble: %d\n", pulse_width);
        data.checksum_nibble = 0; // Indicate error
        return data;
    }
    data.checksum_nibble = pulse_width / 6; // Divide by 6 to get nibble value

    return data;
}

// Function to convert raw data to pressure
float convert_to_pressure(SENT_Data data) {
    unsigned int raw_value = (data.data_nibbles[0] << 8) | data.data_nibbles[1];
    raw_value = raw_value << 4; // Align to 12 bits
    raw_value = raw_value | (data.data_nibbles[2] >> 4);

    // Linear transfer function: pressure = raw_value * scale + offset
    float pressure = (float)raw_value * 0.1 + 0.0; // Example: scale = 0.1, offset = 0.0

    return pressure;
}

// Function to log pressure data
void log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for clean exit
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Brake Pressure Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        SENT_Data data = read_sent_data();

        if (data.status_nibble != 0) { // Check for error during read
            if (data.status_nibble == 0) {
                fprintf(stderr, "Error: Invalid SENT data received\n");
            }
            continue; // Skip to the next iteration
        }

        // Validate checksum
        unsigned int checksum = (data.data_nibbles[0] + data.data_nibbles[1] + data.data_nibbles[2]) % 16;
        if (checksum != data.checksum_nibble) {
            fprintf(stderr, "Error: Checksum mismatch: received %d, calculated %d\n", data.checksum_nibble, checksum);
            continue; // Skip to the next iteration
        }

        // Convert to pressure
        float pressure = convert_to_pressure(data);

        // Log pressure
        log_pressure(pressure);

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

