    raw_value = raw_value << 4; // Align to 12 bits
    raw_value = raw_value | (data.data_nibbles[2] >> 4);

    // Linear transfer function: pressure = raw_value * scale + offset
    float pressure = (float)raw_value * 0.1 + 0.0; // Example: scale = 0.1, offset = 0.0

    return pressure;
}

// Function to log pressure data
void log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for clean exit
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Brake Pressure Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        SENT_Data data = read_sent_data();

        if (data.status_nibble != 0) { // Check for error during read
            if (data.status_nibble == 0) {
                fprintf(stderr, "Error: Invalid SENT data received\n");
            }
            continue; // Skip to the next iteration
        }

        // Validate checksum
        unsigned int checksum = (data.data_nibbles[0] + data.data_nibbles[1] + data.data_nibbles[2]) % 16;
        if (checksum != data.checksum_nibble) {
            fprintf(stderr, "Error: Checksum mismatch: received %d, calculated %d\n", data.checksum_nibble, checksum);
            continue; // Skip to the next iteration
        }

        // Convert to pressure
        float pressure = convert_to_pressure(data);

        // Log pressure
        log_pressure(pressure);

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

