#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int write_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int tmp117_address;
    const char *filename;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", bytes_read);
        return -1;
    }

    // Convert to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    *temperature = (float)raw_temp * TEMP_SCALE;

    return 0;
}

// Write temperature to file
int write_temperature(float temperature) {
    if (fp == NULL) {
        fprintf(stderr, "File not opened.\n");
        return -1;
    }

    // Convert float to little-endian bytes
    uint32_t temp_int = *(uint32_t*)&temperature;
    uint8_t temp_bytes[4];
    temp_bytes[0] = temp_int & 0xFF;
    temp_bytes[1] = (temp_int >> 8) & 0xFF;
    temp_bytes[2] = (temp_int >> 16) & 0xFF;
    temp_bytes[3] = (temp_int >> 24) & 0xFF;

    size_t bytes_written = fwrite(temp_bytes, 1, 4, fp);
    if (bytes_written != 4) {
        fprintf(stderr, "Error writing to file: %zu\n", bytes_written);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

