    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open file for appending
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (write_temperature(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

