#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int send_command(int handle, unsigned char command);
int read_data(int handle, unsigned char *data, int count);
unsigned char calculate_crc8(const unsigned char *data, int len);
int validate_crc8(const unsigned char *data, int len, unsigned char crc);
sensor_data_t convert_data(unsigned char *raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SHT40 sensor
int send_command(int handle, unsigned char command) {
    int result = i2cWriteByteData(handle, command, 0); // Write command to the sensor
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SHT40 sensor
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
unsigned char calculate_crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc8(const unsigned char *data, int len, unsigned char crc) {
    unsigned char calculated_crc = calculate_crc8(data, len);
    return (calculated_crc == crc);
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(unsigned char *raw_data) {
    sensor_data_t data;
    unsigned short raw_temp = (raw_data[0] << 8) | raw_data[1];
    unsigned short raw_hum = (raw_data[3] << 8) | raw_data[4];

    data.temperature = -45 + 175 * (raw_temp / 65535.0);
    data.humidity = -6 + 125 * (raw_hum / 65535.0);

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char raw_data[6];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for measurement (at least 8.5 ms)
        gpioDelay(10); // 10 ms

        // Read data
        if (read_data(i2c_handle, raw_data, 6) != 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        // Validate CRC checksums
        if (!validate_crc8(raw_data, 2, raw_data[2]) || !validate_crc8(raw_data + 3, 2, raw_data[5])) {
            fprintf(stderr, "CRC checksum validation failed\n");
            break;
        }

        // Convert data
        sensor_data = convert_data(raw_data);

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        // Wait 5 seconds
        gpioDelay(5000); // 5000 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

