#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for the circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
void flush_buffer_to_file(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

