#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 command for normal power measurement
#define SHTC3_MEASURE_CMD 0x7866

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} SHTC3Data;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int crc8(const uint8_t *data, int len);
SHTC3Data read_shtc3();
void log_data(SHTC3Data data);
void signal_handler(int signal);
int initialize();
void cleanup();

// CRC-8 calculation function
int crc8(const uint8_t *data, int len) {
    int crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHTC3
SHTC3Data read_shtc3() {
    SHTC3Data data;
    uint8_t cmd[2] = {(SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF};
    uint8_t buffer[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Wait for measurement to complete (at least 12.4 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert raw data to temperature and humidity
    int raw_temperature = (buffer[0] << 8) | buffer[1];
    int raw_humidity = (buffer[3] << 8) | buffer[4];

    data.temperature = 175.0 * raw_temperature / 65535.0 - 45.0;
    data.humidity = 100.0 * raw_humidity / 65535.0;

    // Validate temperature and humidity
    if (data.temperature < -40.0 || data.temperature > 125.0 || data.humidity < 0.0 || data.humidity > 100.0) {
        fprintf(stderr, "Temperature or humidity out of range\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    return data;
}

// Function to log data to file
void log_data(SHTC3Data data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (data.temperature != -999.0 && data.humidity != -999.0) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        SHTC3Data data = read_shtc3();

        if (data.temperature != -999.0 && data.humidity != -999.0) {
            printf("%s,%.2f,%.2f\n", __TIME__, data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        log_data(data);

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

