#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAGNETIC_FIELD_REG 0x00 // Example register address
#define TEMPERATURE_REG 0x01    // Example register address
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float magnetic_field_gauss;
    float temperature_celsius;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *raw_magnetic_field, int *raw_temperature);
SensorData convert_data(int raw_magnetic_field, int raw_temperature);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the Si7202
int read_sensor_data(int *raw_magnetic_field, int *raw_temperature) {
    char buf[2];
    int result;

    // Read magnetic field data
    result = i2cReadI2CBlockData(i2c_handle, MAGNETIC_FIELD_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", result);
        return -1;
    }
    *raw_magnetic_field = (buf[0] << 8) | buf[1];

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *raw_temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw sensor data to magnetic field (Gauss) and temperature (Celsius)
SensorData convert_data(int raw_magnetic_field, int raw_temperature) {
    SensorData data;
    data.magnetic_field_gauss = (float)raw_magnetic_field * 0.1;
    data.temperature_celsius = (float)raw_temperature * 0.01 - 25.0;
    return data;
}

// Log sensor data to a CSV file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.magnetic_field_gauss, data.temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    int raw_magnetic_field, raw_temperature;
    SensorData data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_magnetic_field, &raw_temperature) == 0) {
            // Convert data
            data = convert_data(raw_magnetic_field, raw_temperature);

            // Log data
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            // Log NaN values if sensor read fails
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

