            gpioDelay(RETRY_DELAY_MS);
            retries++;
        }
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        gpioTerminate();
        return 1;
