#define FLOW_LOG_FILE "flow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
SensorData convert_data(uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from I2C
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading I2C data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to SLPM and Celsius
SensorData convert_data(uint8_t *data) {
    SensorData sensor_data;
    int16_t raw_flow = (data[0] << 8) | data[1];
    int16_t raw_temp = (data[2] << 8) | data[3];

    sensor_data.flow_rate = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
    sensor_data.temperature = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

    return sensor_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(FLOW_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, data.flow_rate, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

