    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[4];
        int retry = 0;
        int read_result = -1;

        // Read sensor data with retries
        while (retry < RETRY_COUNT && read_result != 0) {
            read_result = read_sensor_data(data);
            if (read_result != 0) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }

        if (read_result == 0) {
            // Convert data
            SensorData sensor_data = convert_data(data);

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries. Logging error.\n", RETRY_COUNT);
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, ERROR: Failed to read sensor data after %d retries.\n", timestamp, RETRY_COUNT);
            fflush(log_file);
        }

        gpioDelay(1000000); // Sample every 1 second (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

