#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100000 // 100 ms timeout
#define MAX_RETRIES 3

// Structure to hold sensor data
typedef struct {
    int humidity;
    int temperature;
} SensorData;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int dht11_read(SensorData *data);
void log_error(const char *message, int status_code);
void log_reading(int humidity, int temperature);
void signal_handler(int signal);
int validate_checksum(unsigned char data[5]);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from DHT11 sensor
int dht11_read(SensorData *data) {
    int i, j;
    unsigned char data_bytes[5] = {0, 0, 0, 0, 0};
    unsigned int start_tick, end_tick, pulse_length;

    // 1. Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18); // 18 ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20 us
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // 2. Wait for response (80us low followed by 80us high)
    start_tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            log_error("Timeout waiting for DHT11 response (low)", 1);
            return 1;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            log_error("Timeout waiting for DHT11 response (high)", 2);
            return 2;
        }
    }

    // 3. Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for low pulse
        start_tick = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                log_error("Timeout waiting for DHT11 data bit (low)", 3);
                return 3;
            }
        }

        // Measure high pulse duration
        start_tick = gpioTick();
        while (gpioRead(DHT11_GPIO) == 0) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                log_error("Timeout waiting for DHT11 data bit (high)", 4);
                return 4;
            }
        }
        end_tick = gpioTick();
        pulse_length = end_tick - start_tick;

        // Determine bit value
        data_bytes[i / 8] <<= 1;
        if (pulse_length > 40) {
            data_bytes[i / 8] |= 1;
        }
    }

    // 4. Validate checksum
    if (!validate_checksum(data_bytes)) {
        log_error("Checksum validation failed", 5);
        return 5;
    }

    // 5. Store data
    data->humidity = (data_bytes[0] * 10 + data_bytes[1]) / 10; // Integer part
    data->temperature = (data_bytes[2] * 10 + data_bytes[3]) / 10; // Integer part

    return 0; // Success
}

// Function to log errors to file
void log_error(const char *message, int status_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - ERROR: %s (Status Code: %d)\n", timestamp, message, status_code);
    fflush(log_file);
}

// Function to log sensor readings to file
void log_reading(int humidity, int temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", timestamp, temperature / 10.0, humidity / 10.0);
    fflush(log_file);
}

// Function to validate checksum
int validate_checksum(unsigned char data[5]) {
    return ((data[0] + data[1] + data[2] + data[3]) & 0xFF) == data[4];
}

int main() {
    SensorData sensor_data;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_errors.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
