    log_file = fopen("dht11_errors.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (dht11_read(&sensor_data) == 0) {
                log_reading(sensor_data.humidity, sensor_data.temperature);
                break; // Exit retry loop on success
            } else {
                retries++;
                fprintf(stderr, "DHT11 read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(1000); // Wait 1 second before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "DHT11 read failed after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(2000000); // Sample every 2 seconds
    }

