#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc8(const uint8_t *data, int len, uint8_t crc);
int convert_data(uint8_t *data, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SHT31-D
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SHT31-D
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc8(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    return (calculated_crc == crc);
}

// Convert raw data to temperature and humidity
int convert_data(uint8_t *data, float *temperature, float *humidity) {
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    if (!validate_crc8(data, 2) || !validate_crc8(data + 3, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *temperature = -45 + 175 * raw_temperature / 65535.0;
    *humidity = 100 * raw_humidity / 65535.0;
    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        float temperature, humidity;
        int retry = 0;

        // Send measurement command with retry
        while (retry < RETRY_COUNT) {
            if (send_command(i2c_handle, MEASURE_CMD) == 0) {
                break; // Command sent successfully
            } else {
                fprintf(stderr, "Command send failed, retrying (%d/%d)\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to send measurement command after multiple retries\n");
            continue; // Skip to the next iteration
        }

        // Wait for measurement (at least 15 ms)
        gpioDelay(20000); // 20 ms

        // Read data with retry
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_data(i2c_handle, data, 6) == 0) {
                break; // Data read successfully
            } else {
                fprintf(stderr, "Data read failed, retrying (%d/%d)\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read data after multiple retries\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        if (convert_data(data, &temperature, &humidity) == 0) {
            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to convert data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

