// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN 0.0
#define PMAX 800.0
#define TEMP_OFFSET -40.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *pressure, uint16_t *temperature);
sensor_data_t convert_data(uint16_t raw_pressure, uint16_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MLX90824
int read_sensor_data(uint16_t *pressure, uint16_t *temperature) {
    char buf[4];
    int result;

    // Read pressure register (0x0A2C)
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }
    *pressure = (buf[0] << 8) | buf[1];

    // Read temperature register (0x0A2E)
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw data to kPa and Celsius
sensor_data_t convert_data(uint16_t raw_pressure, uint16_t raw_temperature) {
    sensor_data_t data;
    data.pressure_kPa = (float)(raw_pressure - OUTPUT_MIN) * (PMAX - PMIN) / (OUTPUT_MAX - OUTPUT_MIN);
    data.temperature_C = (float)raw_temperature * 0.01 - TEMP_OFFSET;
    return data;
}

