#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_HYSTERESIS_HIGH 28.0
#define TEMP_HYSTERESIS_LOW 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int init_pigpio();
int init_i2c();
float read_temperature();
float calculate_average();
void control_fan(float average_temperature);
void add_to_buffer(float temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75B
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Extract the 9-bit temperature value (bits D9-D1)
    int16_t temp_value = raw_temp >> 7;

    // Apply the 0.5 °C resolution
    float temperature = temp_value * 0.5;

    // Handle negative temperatures (two's complement)
    if (raw_temp & 0x0100) {
        temperature -= 16.0;
    }

    return temperature;
}

// Function to calculate the running average
float calculate_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    return sum / buffer_count;
}

// Function to control the cooling fan
void control_fan(float average_temperature) {
    if (average_temperature > TEMP_HYSTERESIS_HIGH && gpioRead(FAN_GPIO) == 0) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (Average Temperature: %.2f)\n", average_temperature);
    } else if (average_temperature < TEMP_HYSTERESIS_LOW && gpioRead(FAN_GPIO) == 1) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (Average Temperature: %.2f)\n", average_temperature);
    }
}

// Function to add a temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();
        if (temperature < -999.0) { // Check for read error
            fprintf(stderr, "Error reading temperature, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Add to buffer
        add_to_buffer(temperature);

        // Calculate average
        float average_temperature = calculate_average();

        // Control fan
        control_fan(average_temperature);

        printf("Temperature: %.2f °C, Average Temperature: %.2f °C\n", temperature, average_temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

