#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define LOG_FILE "airflow.log"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_sensor_data(uint8_t *data, int count);
SensorData process_sensor_data(uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_sensor_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Process sensor data
SensorData process_sensor_data(uint8_t *data) {
    SensorData sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC validation
    uint8_t crc_pressure = data[2];
    uint8_t crc_temperature = data[5];

    uint8_t crc_calculated_pressure = crc8(data, 2);
    uint8_t crc_calculated_temperature = crc8(data + 3, 2);

    if (crc_pressure != crc_calculated_pressure || crc_temperature != crc_calculated_temperature) {
        fprintf(stderr, "CRC mismatch!\n");
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    // Convert to physical units
    sensor_data.pressure = (float)raw_pressure / PRESSURE_SCALE;
    sensor_data.temperature = (float)raw_temperature / TEMPERATURE_SCALE;

    return sensor_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.pressure == -999.0 || data.temperature == -999.0) {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
        fprintf(stderr, "%s,ERROR,ERROR\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
        fflush(log_file); // Ensure data is written immediately
    }

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        SensorData sensor_data;

        // Send measurement command
        if (send_command(MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement (45 ms)
        gpioDelay(45000); // 45 ms

        // Read sensor data
        if (read_sensor_data(data, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Log data
        if (sensor_data.pressure != -999.0) {
            log_data(sensor_data);

            // Check for pressure threshold
            if (sensor_data.pressure > 5.0) {
                fprintf(stderr, "WARNING: Differential pressure exceeds 5.0 Pa: %.2f Pa\n", sensor_data.pressure);
            }
        } else {
            fprintf(stderr, "Error processing sensor data, skipping logging.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

