#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_temperature(int16_t raw_temp);
void set_led_state(struct gpiod_line *line, int state);
void log_temperature(float temperature);
void signal_handler(int sig);
int initialize();
void cleanup();

// I2C read function with retry mechanism
int i2c_read_word(int fd, uint8_t reg) {
    int retries = 0;
    int result = -1;
    while (retries < RETRY_COUNT) {
        if (i2c_smbus_write_byte(fd, reg) < 0) {
            perror("Failed to write register address");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = i2c_smbus_read_word_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            perror("Failed to read word data");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    fprintf(stderr, "I2C read failed after %d retries. Error: %s\n", RETRY_COUNT, strerror(errno));
    return -1; // Indicate failure
}

// Temperature conversion function
float convert_temperature(int16_t raw_temp) {
    return (float)((int16_t)(raw_temp >> 4)) * 0.0625;
}

// LED control function
void set_led_state(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set LED state: %s\n", strerror(-ret));
    }
}

// Temperature logging function
void log_temperature(float temperature) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);
    printf("%s Temperature: %.2f °C\n", buf, temperature);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Initialization function
int initialize() {
    // I2C initialization
    i2c_fd = i2c_open(I2C_BUS, STTS2004_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    // GPIO initialization
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    int ret = gpiod_line_request_output(led_line, "temperature_monitor", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialization
    if (initialize() < 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_temp = i2c_read_word(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float temperature = convert_temperature(raw_temp);
        log_temperature(temperature);

        // LED control based on temperature
        if (temperature > TEMP_THRESHOLD_HIGH) {
            set_led_state(led_line, 1); // Turn LED on
        } else if (temperature < TEMP_THRESHOLD_LOW) {
            set_led_state(led_line, 0); // Turn LED off
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

