    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);
    printf("%s Temperature: %.2f °C\n", buf, temperature);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Initialization function
int initialize() {
    // I2C initialization
    i2c_fd = i2c_open(I2C_BUS, STTS2004_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    // GPIO initialization
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    int ret = gpiod_line_request_output(led_line, "temperature_monitor", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialization
    if (initialize() < 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_temp = i2c_read_word(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float temperature = convert_temperature(raw_temp);
        log_temperature(temperature);

        // LED control based on temperature
        if (temperature > TEMP_THRESHOLD_HIGH) {
            set_led_state(led_line, 1); // Turn LED on
        } else if (temperature < TEMP_THRESHOLD_LOW) {
            set_led_state(led_line, 0); // Turn LED off
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

