#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define PRESSURE_SCALE_FACTOR_REG 0x00
#define MEASUREMENT_DELAY_MS 45

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
sensor_data_t process_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Process raw data to get differential pressure and temperature
sensor_data_t process_data(uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Read scale factor from register 0x00
    uint8_t scale_factor_reg = 0x00;
    uint8_t scale_factor_data[3];
    i2cWriteDevice(i2c_handle, (char *)&scale_factor_reg, 1);
    i2cReadDevice(i2c_handle, (char *)scale_factor_data, 3);

    int32_t scale_factor = (scale_factor_data[0] << 24) | (scale_factor_data[1] << 16) | (scale_factor_data[2] << 8);

    // CRC check for pressure
    uint8_t crc_pressure = data[2];
    uint8_t pressure_data[2] = {data[0], data[1]};
    if (crc8(pressure_data, 2) != crc_pressure) {
        fprintf(stderr, "CRC check failed for pressure\n");
        sensor_data.differential_pressure = -999.0; // Indicate error
    } else {
        // Convert pressure to Pascals
        sensor_data.differential_pressure = (float)raw_pressure / scale_factor;
    }

    // CRC check for temperature
    uint8_t crc_temperature = data[5];
    uint8_t temperature_data[2] = {data[3], data[4]};
    if (crc8(temperature_data, 2) != crc_temperature) {
        fprintf(stderr, "CRC check failed for temperature\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        // Convert temperature to Celsius
        sensor_data.temperature = (float)raw_temperature / 200.0;
    }

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying I2C init...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Wait for measurement
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

        // Read data
        if (read_data(data, 9) != 0) {
            fprintf(stderr, "Failed to read data, retrying I2C init...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Process data
        sensor_data = process_data(data);

        // Log data
        if (sensor_data.differential_pressure != -999.0 && sensor_data.temperature != -999.0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error: Invalid sensor data, skipping logging.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

