#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY_CMD 0xF5
#define MEASURE_TEMPERATURE_CMD 0xF3
#define READ_TEMP_CMD 0xE0
#define RETRY_COUNT 3
#define LOG_FILE "environment.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_humidity, uint16_t *raw_temperature);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *raw_humidity, uint16_t *raw_temperature) {
    char buf[2];
    int result;
    int retries = 0;

    // Measure Humidity
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, &MEASURE_HUMIDITY_CMD, 1);
        if (result == 0) break;
        fprintf(stderr, "Error writing humidity command, retry %d: %d\n", retries + 1, result);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;

    gpioDelay(20000); // Wait 20 ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Error reading humidity data, retry %d: %d\n", retries + 1, result);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;
    *raw_humidity = (buf[0] << 8) | buf[1];

    // Measure Temperature
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, &MEASURE_TEMPERATURE_CMD, 1);
        if (result == 0) break;
        fprintf(stderr, "Error writing temperature command, retry %d: %d\n", retries + 1, result);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;

    gpioDelay(20000); // Wait 20 ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Error reading temperature data, retry %d: %d\n", retries + 1, result);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;
    *raw_temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return 175.72 * raw_temperature / 65536 - 46.85;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125 * raw_humidity / 65536 - 6;
    if (humidity < 0) humidity = 0;
    if (humidity > 100) humidity = 100;
    return humidity;
}

// Function to log data to file and stdout
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(stdout, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(stdout);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_humidity, raw_temperature;

        if (read_sensor_data(&raw_humidity, &raw_temperature) == 0) {
            float temperature = convert_temperature(raw_temperature);
            float humidity = convert_humidity(raw_humidity);

            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            fprintf(log_file, "Failed to read sensor data\n");
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

