#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDRESS 0x44
#define MEASURE_HIGH_REPEATABILITY 0x2C00
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"
#define MEASUREMENT_DELAY_MS 10
#define LOGGING_INTERVAL_S 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *device);
int i2c_set_slave_address(int fd, int address);
int i2c_write(int fd, const uint8_t *data, size_t length);
int i2c_read(int fd, uint8_t *data, size_t length);
uint8_t crc8(const uint8_t *data, size_t length);
float convert_ticks_to_celsius(uint16_t ticks);
int log_temperature(float temperature);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %m\n", device);
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %m\n", address);
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, const uint8_t *data, size_t length) {
    ssize_t bytes_written = write(fd, data, length);
    if (bytes_written != (ssize_t)length) {
        fprintf(stderr, "Error writing to I2C device: %m\n");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, size_t length) {
    ssize_t bytes_read = read(fd, data, length);
    if (bytes_read != (ssize_t)length) {
        fprintf(stderr, "Error reading from I2C device: %m\n");
        return -1;
    }
    return 0;
}

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_ticks_to_celsius(uint16_t ticks) {
    return -45 + 175 * ticks / 65535.0;
}

// Logging function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %m\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (i2c_set_slave_address(i2c_fd, STS40_ADDRESS) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %m\n", LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    uint8_t command[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    uint8_t data[3];
    uint16_t ticks;
    float temperature;

    // Main loop
    while (program_running) {
        // Send measurement command
        if (i2c_write(i2c_fd, command, sizeof(command)) < 0) {
            break;
        }

        // Wait for measurement (10 ms)
        usleep(MEASUREMENT_DELAY_MS * 1000);

        // Read measurement data
        if (i2c_read(i2c_fd, data, sizeof(data)) < 0) {
            break;
        }

        // CRC validation
        uint8_t crc = crc8(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC mismatch! Expected 0x%02X, got 0x%02X\n", data[2], crc);
            continue; // Skip logging this reading
        }

        // Convert ticks to temperature
        ticks = (data[0] << 8) | data[1];
        temperature = convert_ticks_to_celsius(ticks);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            break;
        }

        printf("Temperature: %.2f C\n", temperature);

        // Wait for the next logging interval
        sleep(LOGGING_INTERVAL_S);
    }

    // Clean up
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

