// Global Variables
int i2c_handle;
volatile sig_atomic_t running = 1;
circular_buffer_t buffer;

// Function Prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int stop_periodic_measurement();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
int validate_crc(uint8_t data[], uint8_t crc);
int add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int read_from_buffer(circular_buffer_t *buffer, sensor_data_t *data, int index);
int write_buffer_to_csv(const char *filename);
void *logging_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// CRC-8 Calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to send start periodic measurement command: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to send stop periodic measurement command: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Read measurement
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        syslog(LOG_ERR, "Failed to send read measurement command: %s", strerror(errno));
        return -1;
    }

    char data[9];
    if (i2cReadDevice(i2c_handle, data, 9) != 9) {
        syslog(LOG_ERR, "Failed to read measurement data: %s", strerror(errno));
        return -1;
    }

    // Validate CRC
    if (!validate_crc((uint8_t *)data, data[2]) || !validate_crc((uint8_t *)(data + 3), data[5]) || !validate_crc((uint8_t *)(data + 6), data[8])) {
        syslog(LOG_ERR, "CRC validation failed");
        return -1;
    }

    *co2 = (uint16_t)((data[0] << 8) | data[1]);
    *temperature = -45 + 175 * ((uint16_t)((data[3] << 8) | data[4])) / 65535.0;
    *humidity = 100 * ((uint16_t)((data[6] << 8) | data[7])) / 65535.0;

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t calculated_crc = crc8(data, 2);
    return (calculated_crc == crc);
}

// Add to circular buffer
int add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count < BUFFER_CAPACITY) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Read from circular buffer
int read_from_buffer(circular_buffer_t *buffer, sensor_data_t *data, int index) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Invalid index
    }
    int actual_index = (buffer->tail + index) % BUFFER_CAPACITY;
    *data = buffer->data[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Write buffer to CSV
int write_buffer_to_csv(const char *filename) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s.csv", CSV_DIR, filename);

    // Create directory if it doesn't exist
    struct stat st = {0};
    if (stat(CSV_DIR, &st) == -1) {
        if (mkdir(CSV_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create directory %s: %s", CSV_DIR, strerror(errno));
            return -1;
        }
    }

    FILE *fp = fopen(filepath, "w");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open CSV file for writing: %s", strerror(errno));
        return -1;
    }

    fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");

    pthread_mutex_lock(&buffer.mutex);
    int start = buffer.tail;
    int end = buffer.head;
    if (end < start) {
        end += BUFFER_CAPACITY;
    }

    for (int i = 0; i < buffer.count; i++) {
        int index = (start + i) % BUFFER_CAPACITY;
        sensor_data_t data = buffer.data[index];
        fprintf(fp, "%ld,%u,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
    }
    pthread_mutex_unlock(&buffer.mutex);

    fclose(fp);
    return 0;
}

// Logging thread
void *logging_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        sleep(LOGGING_INTERVAL);
        time_t now = time(NULL);
        char filename[64];
        snprintf(filename, sizeof(filename), "scd40_data_%ld", now);
        if (write_buffer_to_csv(filename) != 0) {
            syslog(LOG_ERR, "Failed to write CSV file");
        }
    }
    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping...");
    running = 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();
    pthread_mutex_destroy(&buffer.mutex);
    closelog();
}

int main() {
    // Initialize syslog
    openlog("scd40_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        syslog(LOG_ERR, "Failed to initialize I2C, exiting");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    pthread_mutex_init(&buffer.mutex, NULL);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        syslog(LOG_ERR, "Failed to start periodic measurement, exiting");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create logging thread: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        uint16_t co2;
        float temperature, humidity;

        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            add_to_buffer(&buffer, data);
        } else {
            syslog(LOG_ERR, "Failed to read measurement, skipping");
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    pthread_join(logging_thread_id, NULL);
    cleanup();
    return 0;
}

