uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc8(const uint8_t *data, int len, uint8_t expected_crc);
sensor_data_t process_data(const uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc8(const uint8_t *data, int len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    return (calculated_crc == expected_crc);
}

// Data processing function
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure_Pa = (float)raw_pressure / 1000.0;
    sensor_data.temperature_C = -45.0 + 175.0 * (float)raw_temperature / 65535.0;

    return sensor_data;
}

