    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            continue; // Try again
        }

        // Wait for measurement (at least 45 ms)
        gpioDelay(50); // Wait 50 ms

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data from sensor\n");
            continue; // Try again
        }

        // Validate CRCs
        if (!validate_crc8(data, 2, data[2]) || !validate_crc8(data + 3, 2, data[5]) || !validate_crc8(data + 6, 2, data[8])) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Try again
        }

        // Process data
        sensor_data = process_data(data);

        // Log data
        if (log_data(log_file, sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // Wait 1000 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

