#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICP_10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VALUE 0x08
#define CALIB_DATA_REG 0x05
#define MEASURE_CMD_REG 0x00
#define DATA_REG 0x00
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int32_t c0, c1, c00, c10;

// Function prototypes
int init_pigpio();
int init_i2c();
int verify_sensor_id();
int read_calibration_data();
int trigger_measurement();
int read_sensor_data(int32_t *pressure, int32_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int32_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify sensor ID
int verify_sensor_id() {
    char buf[1];
    int result = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", result);
        return -1;
    }
    if (buf[0] != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", buf[0], WHO_AM_I_VALUE);
        return -1;
    }
    return 0;
}

// Function to read calibration data
int read_calibration_data() {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_DATA_REG, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Failed to read calibration data: %d\n", result);
        return -1;
    }

    c0 = (int32_t)buf[0] | ((int32_t)buf[1] << 8) | ((int32_t)buf[2] << 16) | ((int32_t)buf[3] << 24);
    c1 = (int32_t)buf[4] | ((int32_t)buf[5] << 8) | ((int32_t)buf[6] << 16) | ((int32_t)buf[7] << 24);

    c00 = (int32_t)buf[0] | ((int32_t)buf[1] << 8);
    c10 = (int32_t)buf[4] | ((int32_t)buf[5] << 8);

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    char buf[1];
    buf[0] = 0x00; // Trigger measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, MEASURE_CMD_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int32_t *pressure, int32_t *temperature) {
    char buf[DATA_LENGTH];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, DATA_LENGTH);
    if (result != DATA_LENGTH) {
