#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ICP_10125_ADDR 0x63
#define LED_GPIO_PIN 17
#define HIGH_ALTITUDE_THRESHOLD 95000.0
#define HIGH_ALTITUDE_BLINK_RATE 5 // Hz
#define NORMAL_BLINK_RATE 1       // Hz
#define MEASUREMENT_DELAY_MS 20
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Calibration coefficients structure
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
} icp10125_calibration_coeffs_t;

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;
static icp10125_calibration_coeffs_t coeffs;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t val);
int read_calibration_coefficients(int fd, icp10125_calibration_coeffs_t *coeffs);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
int verify_crc(uint8_t *data, int len);
int16_t convert_to_int16(uint8_t *data);
double convert_pressure(int32_t raw_pressure, icp10125_calibration_coeffs_t coeffs);
double convert_temperature(int32_t raw_temperature, icp10125_calibration_coeffs_t coeffs);
void blink_led(struct gpiod_line *led_line, int rate_hz);
void signal_handler(int sig);
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **led_line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *led_line);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = val;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd, icp10125_calibration_coeffs_t *coeffs) {
    uint8_t data[12];
    if (i2c_read_bytes(fd, 0x66, data, 12) != 0) {
        fprintf(stderr, "Error reading calibration coefficients\n");
        return -1;
    }

    coeffs->c0 = (int32_t)((data[0] << 8) | data[1]);
    coeffs->c1 = (int32_t)((data[2] << 8) | data[3]);
    coeffs->c00 = (int32_t)((data[4] << 8) | data[5]);
    coeffs->c10 = (int32_t)((data[6] << 8) | data[7]);
    coeffs->c01 = (int32_t)((data[8] << 8) | data[9]);
    coeffs->c11 = (int32_t)((data[10] << 8) | data[11]);
    coeffs->c20 = 0; // Not used in the formulas

    return 0;
}

// Trigger a measurement
int trigger_measurement(int fd) {
    if (i2c_write_byte(fd, 0x06, 0x40) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }
    if (i2c_write_byte(fd, 0x07, 0x11) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }
    return 0;
}

// Verify CRC
int verify_crc(uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Convert to 16-bit signed integer
int16_t convert_to_int16(uint8_t *data) {
    return (int16_t)((data[0] << 8) | data[1]);
}

// Convert pressure
double convert_pressure(int32_t raw_pressure, icp10125_calibration_coeffs_t coeffs) {
    double p = coeffs.c00 + raw_pressure * (coeffs.c10 + raw_pressure * coeffs.c20) + coeffs.c01 * raw_pressure + raw_pressure * coeffs.c11 * raw_pressure;
    return p;
}

// Convert temperature
double convert_temperature(int32_t raw_temperature, icp10125_calibration_coeffs_t coeffs) {
    double t = coeffs.c0 + raw_temperature * (coeffs.c1 + raw_temperature * coeffs.c20);
    return t;
}

// Blink LED
void blink_led(struct gpiod_line *led_line, int rate_hz) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = 1000000000 / rate_hz / 2; // Half period
    off_time.tv_sec = 0;
    off_time.tv_nsec = 1000000000 / rate_hz / 2; // Half period

    int ret;
    ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED high: %d\n", ret);
    }
    nanosleep(&on_time, NULL);

    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED low: %d\n", ret);
    }
    nanosleep(&off_time, NULL);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **led_line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *led_line = gpiod_chip_get_line(*chip, LED_GPIO_PIN);
    if (!*led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "icp10125_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(*led_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *led_line) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &led_line) != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup_gpio(chip, led_line);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        cleanup_gpio(chip, led_line);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd, &coeffs) != 0) {
        close(i2c_fd);
        cleanup_gpio(chip, led_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int32_t raw_pressure, raw_temperature;
        double pressure, temperature;
        int ret;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            sleep(1);
            continue;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

        // Read sensor data
        if (read_sensor_data(i2c_fd, data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            sleep(1);
            continue;
        }

        // Verify CRC
        if (!verify_crc(data, 3) || !verify_crc(data + 3, 3)) {
            fprintf(stderr, "CRC check failed, retrying...\n");
            sleep(1);
            continue;
        }

        // Convert data
        raw_pressure = convert_to_int16(data);
        raw_temperature = convert_to_int16(data + 3);

        // Convert to Pascals and Celsius
        pressure = convert_pressure(raw_pressure, coeffs);
        temperature = convert_temperature(raw_temperature, coeffs);

        // Print data
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Check altitude and blink LED
        if (pressure < HIGH_ALTITUDE_THRESHOLD) {
            blink_led(led_line, HIGH_ALTITUDE_BLINK_RATE);
        } else {
            blink_led(led_line, NORMAL_BLINK_RATE);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    cleanup_gpio(chip, led_line);

    return 0;
}

