#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mlx90614(int i2c_handle, int reg, int *value);
float convert_to_celsius(int raw_value);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from MLX90614 sensor
int read_mlx90614(int i2c_handle, int reg, int *value) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            *value = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retrying...\n", reg);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", RETRY_COUNT, reg);
    return -1; // Failure
}

// Function to convert raw temperature value to Celsius
float convert_to_celsius(int raw_value) {
    return (float)raw_value * 0.02 - 273.15;
}

// Function to log temperature data to file
void log_temperature(float ambient_temp, float object_temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f C)\n", object_temp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int ambient_raw, object_raw;
    float ambient_temp, object_temp;

    // Main loop
    while (!terminate) {
        // Read ambient temperature
        if (read_mlx90614(i2c_handle, AMBIENT_TEMP_REG, &ambient_raw) == 0) {
            ambient_temp = convert_to_celsius(ambient_raw);
        } else {
            ambient_temp = -999.0; // Indicate invalid reading
        }

        // Read object temperature
        if (read_mlx90614(i2c_handle, OBJECT_TEMP_REG, &object_raw) == 0) {
            object_temp = convert_to_celsius(object_raw);
        } else {
            object_temp = -999.0; // Indicate invalid reading
        }

        // Log temperature data
        if (ambient_temp != -999.0 && object_temp != -999.0) {
            log_temperature(ambient_temp, object_temp);
        }

        // Control the fan
        control_fan(object_temp);

        // Wait 2 seconds
        gpioDelay(2000000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
    fclose(log_file);

    return 0;
}

