#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define BUFFER_SIZE 1024

// Global variables
int i2c_handle = -1;
int server_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sht40(SensorData *data);
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();
char* format_html(SensorData data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40 sensor
int read_sht40(SensorData *data) {
    char cmd[1] = {MEASURE_HIGH_REPEATABILITY};
    char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait 10ms

        if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
            fprintf(stderr, "Error reading from I2C: %d\n", i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned short raw_temperature = (buffer[0] << 8) | buffer[1];
        unsigned short raw_humidity = (buffer[3] << 8) | buffer[4];

        data->temperature = -45 + 175 * (raw_temperature / 65535.0);
        data->humidity = -6 + 125 * (raw_humidity / 65535.0);

        // Clamp humidity to 0-100%
        if (data->humidity < 0) data->humidity = 0;
        if (data->humidity > 100) data->humidity = 100;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Format HTML page
char* format_html(SensorData data) {
    char *html = malloc(BUFFER_SIZE);
    if (html == NULL) {
        perror("malloc failed");
        return NULL;
    }
    snprintf(html, BUFFER_SIZE, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>Temperature: %.2f &deg;C</h1><h1>Humidity: %.2f %%</h1></body></html>", data.temperature, data.humidity);
    return html;
}

// Handle client connection
void handle_client(int client_socket) {
    SensorData data;
    char *html;

    if (read_sht40(&data) == 0) {
        html = format_html(data);
        if (html != NULL) {
            send(client_socket, html, strlen(html), 0);
            free(html);
        } else {
            fprintf(stderr, "Failed to format HTML.\n");
            const char *error_html = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>Error</title></head><body><h1>Internal Server Error</h1></body></html>";
            send(client_socket, error_html, strlen(error_html), 0);
        }
    } else {
        fprintf(stderr, "Failed to read sensor data.\n");
        const char *error_html = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>Error</title></head><body><h1>Internal Server Error</h1></body></html>";
        send(client_socket, error_html, strlen(error_html), 0);
    }

    close(client_socket);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    int client_socket;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    // Forcefully attaching socket to the port 8080
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        cleanup();
        return 1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 8080
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (!terminate) {
        // Accept connection
        if ((client_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening even if accept fails
        }

        handle_client(client_socket);
    }

    cleanup();
    return 0;
}

