// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed, exiting...\n");
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC2010
int read_hdc2010(int handle, float *temperature, float *humidity) {
    int retries = 0;
    int temp_raw, humid_raw;

    // Trigger measurement
    if (write_register(handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement to complete (polling MEASUREMENT_CONFIG register)
    while (retries < 10) {
        int config_value = read_register(handle, MEASUREMENT_CONFIG);
        if (config_value < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register\n");
            return -1;
        }
        if ((config_value & 0x01) == 0) break; // Check bit 0
        gpioDelay(50); // Wait 50ms
        retries++;
    }

    if (retries == 10) {
        fprintf(stderr, "Timeout waiting for measurement to complete\n");
        return -1;
    }

    // Read temperature
    temp_raw = read_register(handle, TEMP_REG);
    if (temp_raw < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return -1;
    }
    temp_raw |= (read_register(handle, TEMP_REG + 1) << 8);

    // Read humidity
    humid_raw = read_register(handle, HUMID_REG);
    if (humid_raw < 0) {
        fprintf(stderr, "Error reading humidity\n");
        return -1;
    }
    humid_raw |= (read_register(handle, HUMID_REG + 1) << 8);

    // Convert to Celsius and percentage
    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humid_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set heater to disabled and 14-bit resolution
    if (write_register(i2c_handle, CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error setting configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_hdc2010(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

