#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define MEASUREMENT_DELAY_MS 45
#define LOG_INTERVAL_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int send_measurement_command(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data);
int calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len, uint8_t crc);
void log_data(int16_t pressure, int16_t temperature);
void signal_handler(int signal);

// CRC-8 checksum calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 checksum verification function
int verify_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command to the sensor
int send_measurement_command(int i2c_handle) {
    char cmd[2];
    cmd[0] = (MEASUREMENT_CMD >> 8) & 0xFF;
    cmd[1] = MEASUREMENT_CMD & 0xFF;

    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C bus
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Log the raw pressure and temperature values
void log_data(int16_t pressure, int16_t temperature) {
    printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t data[6];
    int16_t pressure, temperature;
    int retries = 3; // Number of retries for I2C operations

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
