#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define NUM_RELAYS 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Relay GPIO pins
const int relay_pins[NUM_RELAYS] = {22, 23, 24, 25};

// PID parameters
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Function prototypes
int read_profile(const char *filename, float **times, float **temperatures, int *num_profiles);
int read_max6675(int spi_handle, float *temperature);
int control_relay(int gpio_pin, float duty_cycle);
int log_data(FILE *log_file, float temperature, float target_temperature, int relay_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the program
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Relay1,Relay2,Relay3,Relay4,TargetTemp1,TargetTemp2,TargetTemp3,TargetTemp4,ActualTemp1,ActualTemp2,ActualTemp3,ActualTemp4\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read the temperature profile from a file
int read_profile(const char *filename, float **times, float **temperatures, int *num_profiles) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open profile file\n");
        return 1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        count++;
    }
    rewind(fp);

    *times = (float *)malloc(count * sizeof(float));
    *temperatures = (float *)malloc(count * sizeof(float));
    if (*times == NULL || *temperatures == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        return 1;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%f,%f", &(*times)[i], &(*temperatures)[i]) != 2) {
            fprintf(stderr, "Invalid line in profile file\n");
            free(*times);
            free(*temperatures);
            fclose(fp);
            return 1;
        }
        i++;
    }

    fclose(fp);
    *num_profiles = count;
    return 0;
}

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    unsigned char data[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiRead(spi_handle, data, 2);
        if (result == 2) {
            // Check for errors
            if (data[0] & 0x01) {
                fprintf(stderr, "MAX6675 Error: Open circuit\n");
                return 1; // Error: Open circuit
            }
            if (data[0] & 0x02) {
                fprintf(stderr, "MAX6675 Error: Short to GND\n");
                return 1; // Error: Short to GND
            }
            if (data[0] & 0x04) {
                fprintf(stderr, "MAX6675 Error: Short to VCC\n");
                return 1; // Error: Short to VCC
            }

            // Extract temperature (bits 3-14)
            int raw_temp = ((data[0] & 0xFC) << 8) | data[1];
            *temperature = (float)raw_temp * 0.25;
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "MAX6675 read failed after %d retries\n", MAX_RETRIES);
    return 1; // Failure after retries
}

// Function to control the relay
int control_relay(int gpio_pin, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int on_time = (int)(duty_cycle * 1000); // Convert duty cycle to milliseconds
    int off_time = 1000 - on_time;

    gpioWrite(gpio_pin, 1); // Turn relay on
    gpioDelay(on_time * 1000); // Delay for on_time milliseconds
    gpioWrite(gpio_pin, 0); // Turn relay off
    gpioDelay(off_time * 1000); // Delay for off_time milliseconds

    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float temperature, float target_temperature, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp,
            (relay_state & 0x01) ? temperature : -999.0, // Relay 1
            (relay_state & 0x02) ? temperature : -999.0, // Relay 2
            (relay_state & 0x04) ? temperature : -999.0, // Relay 3
            (relay_state & 0x08) ? temperature : -999.0, // Relay 4
            (relay_state & 0x01) ? target_temperature : -999.0, // Relay 1 Target
            (relay_state & 0x02) ? target_temperature : -999.0, // Relay 2 Target
            (relay_state & 0x04) ? target_temperature : -999.0, // Relay 3 Target
            (relay_state & 0x08) ? target_temperature : -999.0, // Relay 4 Target
            (relay_state & 0x01) ? temperature : -999.0, // Relay 1 Actual
            (relay_state & 0x02) ? temperature : -999.0, // Relay 2 Actual
            (relay_state & 0x04) ? temperature : -999.0, // Relay 3 Actual
            (relay_state & 0x08) ? temperature : -999.0); // Relay 4 Actual

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    if (initialize()) {
        return 1;
    }

    float *times = NULL;
    float *temperatures = NULL;
    int num_profiles = 0;

    if (read_profile(PROFILE_FILE, &times, &temperatures, &num_profiles)) {
        cleanup();
        return 1;
    }

    int current_profile = 0;
    float current_time = 0.0;
    float current_target_temperature = temperatures[current_profile];
    float integral = 0.0;
    float previous_error = 0.0;

    printf("Starting reflow oven control...\n");

    while (program_running) {
        // Read temperature from MAX6675
        float temperature = -999.0; // Initialize to an invalid value
        if (read_max6675(spi_handle, &temperature) != 0) {
            fprintf(stderr, "Failed to read temperature, using previous value\n");
        }

        // Calculate PID output
        float error = current_target_temperature - temperature;
        integral += error;
        float derivative = error - previous_error;
        float output = Kp * error + Ki * integral + Kd * derivative;

        // Limit PID output to 0.0 to 1.0
        if (output < 0.0) output = 0.0;
        if (output > 1.0) output = 1.0;

        // Control relays
        int relay_state = 0;
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (temperature > temperatures[current_profile + i]) {
                relay_state |= (1 << i);
                control_relay(relay_pins[i], output);
            } else {
                control_relay(relay_pins[i], 0.0);
            }
        }

        // Log data
        log_data(log_file, temperature, current_target_temperature, relay_state);

        // Update current time and target temperature
        current_time += 1.0; // Increment time by 1 second
        while (current_time >= times[current_profile]) {
            current_profile++;
            if (current_profile >= num_profiles) {
                current_profile = num_profiles - 1; // Loop back to the last profile
                break;
            }
            current_target_temperature = temperatures[current_profile];
            current_time -= times[current_profile];
        }

        previous_error = current_target_temperature - temperature;

        // Sleep for 1 second
        gpioDelay(1000000); // 1 second
    }

    cleanup();
    return 0;
}

