    ret = gpiod_line_request(pwm_line, "greenhouse_pwm", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request PWM GPIO line for PWM control: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(heater_line);
        gpiod_line_release(pwm_line);
        return -1;
    }

    return 0;
}

