            // Set PWM duty cycle
            duty_cycle = (int)pid_output;
            set_pwm_duty_cycle(duty_cycle);

            // Set heater state based on PID output (example: turn on if PID output > 50)
            if (pid_output > 50) {
                set_heater_state(1); // Turn on heater
