        sleep(5);
    }

    // Cleanup
    set_heater_state(0); // Turn off heater
    set_pwm_duty_cycle(0); // Disable PWM
    cleanup_gpio();
    cleanup_pwm();
    fclose(log_file);

    return 0;
}

