volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_handle);
int aht20_read_data(int i2c_handle, float *humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// AHT20 initialization function
int aht20_init(int i2c_handle) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int result;

    result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed (I2C write error: %d)\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for initialization to complete
    return 0;
}

// AHT20 data reading function
int aht20_read_data(int i2c_handle, float *humidity) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    char data[6];
    int result;
    int retries = 0;

    // Trigger measurement
    result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 trigger command failed (I2C write error: %d)\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS);

    // Read data with retries
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result == 6) {
            // Verify status byte
            if ((data[0] & 0x80) == 0) {
                // Convert data to humidity
                uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
                *humidity = ((float)humidity_raw / 0x100000) * 100;
                return 0; // Success
            } else {
                fprintf(stderr, "Error: AHT20 status byte indicates busy or calibration error (status: 0x%02X)\n", data[0]);
                retries++;
                gpioDelay(RETRY_DELAY_MS);
            }
        } else {
            fprintf(stderr, "Error: AHT20 read failed (I2C read error: %d)\n", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    fprintf(stderr, "Error: AHT20 read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure after retries
}

// Dehumidifier control function
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Data logging function
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    float humidity;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (error code: %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    init_result = aht20_init(i2c_handle);
    if (init_result != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (aht20_read_data(i2c_handle, &humidity) == 0) {
            log_data(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Error: Failed to read humidity data\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier on exit
    gpioTerminate();

    return 0;
}

