#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SLEEP_SECONDS 60

// Global variables
int i2c_fd = -1;
int http_socket = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int i2c_read_data(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_data(int fd, unsigned char reg, unsigned char data);
float read_humidity(int fd);
int post_humidity(float humidity);
void signal_handler(int sig);
int setup_i2c();
int setup_http_socket();
void cleanup();

// I2C read function with retry and exponential backoff
int i2c_read_data(int fd, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int delay_ms = 10;
    int bytes_read = 0;

    while (retries < RETRY_COUNT) {
        if (write(fd, &reg, 1) != 1) {
            syslog(LOG_ERR, "I2C write register failed: %s", strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        bytes_read = read(fd, data, len);
        if (bytes_read == len) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C read failed (bytes read: %d, expected: %d): %s", bytes_read, len, strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    syslog(LOG_ERR, "I2C read failed after %d retries.", RETRY_COUNT);
    return -1; // Failure
}

// I2C write function with retry and exponential backoff
int i2c_write_data(int fd, unsigned char reg, unsigned char data) {
    int retries = 0;
    int delay_ms = 10;
    int bytes_written = 0;

    while (retries < RETRY_COUNT) {
        if (write(fd, &data, 1) == 1) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    syslog(LOG_ERR, "I2C write failed after %d retries.", RETRY_COUNT);
    return -1; // Failure
}

// Function to read humidity from HTU21D sensor
float read_humidity(int fd) {
    unsigned char data[3];
    int retries = 0;
    int delay_ms = 10;

    while (retries < RETRY_COUNT) {
        if (i2c_write_data(fd, HUMIDITY_MEASURE_HOLD, 0) != 0) {
            syslog(LOG_ERR, "Failed to trigger humidity measurement.");
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        usleep(50000); // Wait for measurement (datasheet specifies 50ms)

        if (i2c_read_data(fd, 0, data, 3) != 0) {
            syslog(LOG_ERR, "Failed to read humidity data.");
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // CRC check (simplified, assumes no CRC implementation)
        // In a real application, implement the CRC check as per the datasheet.
        // This example assumes the data is valid.

        // Convert raw data to humidity (see HTU21D datasheet)
        unsigned int raw_humidity = (data[0] << 8) | data[1];
        float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

        return humidity;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries.", RETRY_COUNT);
    return -1.0; // Indicate failure
}

// Function to POST humidity data to the server
int post_humidity(float humidity) {
    char json_data[50];
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    struct sockaddr_in server_addr;
    struct timeval tv;
    int bytes_sent;

    // Create socket
    http_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (http_socket < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    // Set timeout for socket operations
    tv.tv_sec = 10; // 10 seconds timeout
    tv.tv_usec = 0;
    if (setsockopt(http_socket, SOL_SOCKET, SO_SNDTIMEO, (const char*)&tv, sizeof tv)) {
        syslog(LOG_ERR, "setsockopt failed");
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Assuming HTTP on port 80
    if (inet_pton(AF_INET, SERVER_URL, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", SERVER_URL);
        close(http_socket);
        return -1;
    }

    // Connect to server
    if (connect(http_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(http_socket);
        return -1;
    }

    // Send HTTP request
    char request[200];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %ld\r\n\r\n%s", SERVER_URL, strlen(json_data), json_data);
    if (send(http_socket, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(http_socket);
        return -1;
    }

    // Receive server response (optional, for debugging)
    char buffer[1024];
    memset(buffer, 0, sizeof(buffer));
    ssize_t bytes_received = recv(http_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        syslog(LOG_INFO, "Server response: %s", buffer);
    } else {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
    }

    close(http_socket);
    http_socket = -1; // Reset socket
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Setup I2C communication
int setup_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Setup HTTP socket
int setup_http_socket() {
    // This function is currently a placeholder.  The actual socket setup
    // is done in the post_humidity function.  This function is called
    // during initialization, but the socket is not actually used until
    // post_humidity is called.  This is a design choice to keep the
    // code modular and to allow for potential future enhancements.
    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (http_socket != -1) {
        close(http_socket);
        http_socket = -1;
    }

    closelog();
}

int main() {
    // Initialize syslog
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    if (setup_i2c() != 0) {
        syslog(LOG_ERR, "I2C setup failed, exiting.");
        cleanup();
        return 1;
    }

    // Setup HTTP socket (done in post_humidity, but included for completeness)
    setup_http_socket();

    syslog(LOG_INFO, "Humidity monitor started.");

    // Main loop
    while (!terminate) {
        float humidity = read_humidity(i2c_fd);
        if (humidity >= 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

