#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 1 // 1x oversampling
#define BMP280_OVERSAMPLING_PRESS 1 // 1x oversampling
#define BMP280_MODE_FORCED 3       // Forced mode

// Pressure thresholds
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
