#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define RETRY_COUNT 3
#define BACKOFF_DELAY_MS 10
#define LOG_DIR "/home/pi/logs/"

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int addr);
int read_tmp117(int i2c_handle, float *temperature);
int read_aht20(int i2c_handle, float *humidity, float *temperature);
int read_pir(int gpio_pin);
int log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
int check_sensor_presence(int i2c_handle, int addr);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int addr) {
    int handle = i2cOpen(I2C_BUS, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from TMP117
int read_tmp117(int i2c_handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading TMP117: %d\n", result);
        return -1;
    }

    // Convert big-endian to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * 0.0078125;

    return 0;
}

// Function to read humidity and temperature from AHT20
int read_aht20(int i2c_handle, float *humidity, float *temperature) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    char measure_cmd[3] = {0xAC, 0x33, 0x00};
    char response[7];
    int result;
    int retries = 0;

    // Init command
    while (retries < RETRY_COUNT) {
        result = i2cWriteI2CBlockData(i2c_handle, 0x00, init_cmd, 3);
        if (result == 3) break; // Success
        fprintf(stderr, "Error sending AHT20 init command, retry %d\n", retries + 1);
        gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to send AHT20 init command after %d retries\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(20); // Wait for initialization

    // Measure command
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteI2CBlockData(i2c_handle, 0x00, measure_cmd, 3);
        if (result == 3) break; // Success
        fprintf(stderr, "Error sending AHT20 measure command, retry %d\n", retries + 1);
        gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
        retries++;
    }
