void control_motor(int rain_detected);
void signal_handler(int signal);
void log_event(const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");
        gpioWrite(MOTOR_ENABLE_PIN, 0); // Stop the motor
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        log_event("Error reading rain sensor.");
        return -1; // Indicate an error
    }
    return rain_detected;
}

// Function to control the motor
void control_motor(int rain_detected) {
    if (rain_detected == 0) { // Rain detected (YL-83 is active-low)
        log_event("Rain detected, closing window...");
        gpioWrite(MOTOR_ENABLE_PIN, 1); // Enable the motor
        gpioWrite(MOTOR_IN1_PIN, 1);    // Set IN1 high
        gpioWrite(MOTOR_IN2_PIN, 0);    // Set IN2 low
        gpioDelay(5000000);             // Run for 5 seconds (5000000 microseconds)
        gpioWrite(MOTOR_ENABLE_PIN, 0); // Disable the motor
        log_event("Window closed.");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

