    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up/down resistor for rain sensor (optional, adjust as needed)
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) {
            control_motor(1); // Treat 0 as rain detected, even if the sensor is active-low
        } else if (rain_detected > 0) {
            log_event("No rain detected.");
        } else {
            log_event("Error reading rain sensor, retrying...");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(MOTOR_ENABLE_PIN, 0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    log_event("Program terminated.");

    return 0;
}

