#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88

// UDP server address and port
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000

// Global variables
int i2c_handle;
int udp_socket;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int init_udp_socket();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int send_udp_data(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Check the chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Incorrect chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to initialize UDP socket
int init_udp_socket() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data() {
    unsigned char data[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    unsigned char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - (dig_T1 / 1024.0)) * dig_T2;
    var2 = ((((double)raw_temperature / 131072.0) - (dig_T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (dig_T1 / 8192.0))) * dig_T3;
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Function to send data over UDP
int send_udp_data(double temperature, double pressure) {
    char json_string[100];
    snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending data");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize UDP socket
    if (init_udp_socket() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;

        // Set forced mode
        if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, Normal mode
            fprintf(stderr, "Error writing to CTRL_MEAS register\n");
            break;
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(10); // 10 ms delay

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Compensate temperature and pressure
        double temperature = compensate_temperature(raw_temperature);
        double pressure = compensate_pressure(raw_pressure, temperature);

        // Send data over UDP
        if (send_udp_data(temperature, pressure) != 0) {
            fprintf(stderr, "Error sending UDP data\n");
        }

        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

