#define SPI_BAUD 500000
#define PWM_FREQUENCY 1000
#define BUFFER_SIZE 20

// Temperature thresholds and duty cycle values
#define TEMP_LOW 25.0
#define TEMP_HIGH 60.0
#define DUTY_LOW 0
