} LogEntry;

// Global variables
static volatile int running = 1;
static int spi_handle;
static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int init_gpio();
int init_spi();
int read_max31855(uint32_t *data);
float convert_to_celsius(uint32_t raw_data);
int check_fault(uint32_t raw_data);
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read data from MAX31855
int read_max31855(uint32_t *data) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];

    return 0;
}

// Function to convert raw data to Celsius
float convert_to_celsius(uint32_t raw_data) {
    // Extract the 14-bit thermocouple temperature data
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask out the relevant bits

    // Check for fault
    if (thermocouple_data & 0x2000) {
        return -273.15; // Return absolute zero for fault
    }

    // Check if the temperature is negative
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend
    }

    return thermocouple_data * 0.25;
}

// Function to check for MAX31855 faults
int check_fault(uint32_t raw_data) {
    if (raw_data & 0x00000001) {
        fprintf(stderr, "Open circuit fault detected\n");
        return -1;
    }
    if (raw_data & 0x00000002) {
        fprintf(stderr, "Short to GND fault detected\n");
        return -1;
    }
    if (raw_data & 0x00000004) {
        fprintf(stderr, "Short to VCC fault detected\n");
        return -1;
    }
    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_LOW) {
        duty_cycle = DUTY_LOW;
    } else if (temperature < TEMP_HIGH) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW) * (DUTY_HIGH - DUTY_LOW));
    } else {
        duty_cycle = DUTY_HIGH;
    }

    return duty_cycle;
}

