void log_data(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Print the log buffer
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t raw_data;
        float temperature;
        int duty_cycle;

        // Read temperature from MAX31855
        if (read_max31855(&raw_data) == 0) {
            // Convert to Celsius
            temperature = convert_to_celsius(raw_data);

            // Check for faults
            if (check_fault(raw_data) == 0) {
                // Calculate duty cycle
                duty_cycle = calculate_duty_cycle(temperature);

                // Update fan speed
                update_fan(duty_cycle);

                // Log data
                log_data(temperature, duty_cycle);
            } else {
                fprintf(stderr, "Fault detected, skipping fan update\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature, skipping fan update\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

