#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// Calibration values (example, adjust based on your RTD)
#define RREF 430.0  // Reference resistor value
#define A 0.0039083  // RTD constant A
#define B -0.0000005775  // RTD constant B

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_spi();
int init_cs_line();
int init_log_file();
void close_resources();
void signal_handler(int sig);
float read_temperature();
void log_temperature(float temperature);
void cleanup_spi();

// Structure to hold GPIO configuration
typedef struct {
    int chip_num;
    int line_num;
} gpio_config_t;

// Function to initialize GPIO
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(cs_line, "rtd_monitor", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1); // Initially high (inactive)

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return 0;
}

// Function to initialize Chip Select line
int init_cs_line() {
    return 0; // No explicit CS line initialization needed with pigpio
}

// Function to initialize the log file
int init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }
    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C)\n");
    }
    return 0;
}

// Function to close resources
void close_resources() {
    printf("Closing resources...\n");
    if (spi_fd != -1) {
        cleanup_spi();
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Resources closed.\n");
}

// Function to cleanup SPI
void cleanup_spi() {
    spiClose(spi_fd);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Function to read temperature from MAX31865
float read_temperature() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int ret;
    int rtd_raw;
    float temperature;

    // Configure MAX31865 for 3-wire RTD mode with bias enabled
    tx_buf[0] = MAX31865_CONFIG_REG | 0x80; // Write command
    tx_buf[1] = 0xC2; // 3-wire, bias enabled, auto conversion
    tx_buf[2] = 0x00; // Dummy data

    gpiod_line_set_value(cs_line, 0); // Select the chip
    ret = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret != 0) {
        fprintf(stderr, "SPI write failed: %d\n", ret);
        return -1000.0; // Indicate error
    }

    // Read RTD value
    tx_buf[0] = MAX31865_RTD_MSB_REG | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    gpiod_line_set_value(cs_line, 0); // Select the chip
    ret = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret != 0) {
        fprintf(stderr, "SPI read failed: %d\n", ret);
        return -1000.0; // Indicate error
    }

    rtd_raw = ((rx_buf[1] << 8) | rx_buf[2]) >> 1; // Combine MSB and LSB, remove fault bit

    // Check for fault
    tx_buf[0] = MAX31865_FAULT_REG | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    gpiod_line_set_value(cs_line, 0); // Select the chip
    ret = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret != 0) {
        fprintf(stderr, "SPI read failed: %d\n", ret);
        return -1000.0; // Indicate error
    }

    if (rx_buf[2] & 0x01) {
        fprintf(stderr, "RTD Fault detected!\n");
        return -1000.0; // Indicate error
    }

    // Convert RTD value to temperature (Callendar-Van Dusen equation)
    temperature = (rtd_raw / 32768.0) * RREF; // Convert to resistance
    temperature = temperature / (1.0 + 0.0039083 * temperature); // Simplified equation
    temperature = temperature / (1.0 + 0.0000005775 * temperature * temperature); // Simplified equation
    temperature = temperature - 100.0; // Offset

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        close_resources();
        return 1;
    }

    // Initialize log file
    if (init_log_file() != 0) {
        fprintf(stderr, "Log file initialization failed. Exiting.\n");
        close_resources();
        return 1;
    }

    printf("RTD Monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Check log file.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    close_resources();
    return 0;
}

