// Function to read temperature from MAX31865
float read_temperature() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int ret;
    int rtd_raw;
    float temperature;

    // Configure MAX31865 for 3-wire RTD mode with bias enabled
    tx_buf[0] = MAX31865_CONFIG_REG | 0x80; // Write command
    tx_buf[1] = 0xC2; // 3-wire, bias enabled, auto conversion
    tx_buf[2] = 0x00; // Dummy data

    gpiod_line_set_value(cs_line, 0); // Select the chip
    ret = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret != 0) {
        fprintf(stderr, "SPI write failed: %d\n", ret);
        return -1000.0; // Indicate error
    }

    // Read RTD value
    tx_buf[0] = MAX31865_RTD_MSB_REG | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    gpiod_line_set_value(cs_line, 0); // Select the chip
    ret = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret != 0) {
        fprintf(stderr, "SPI read failed: %d\n", ret);
        return -1000.0; // Indicate error
    }

    rtd_raw = ((rx_buf[1] << 8) | rx_buf[2]) >> 1; // Combine MSB and LSB, remove fault bit

    // Check for fault
    tx_buf[0] = MAX31865_FAULT_REG | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    gpiod_line_set_value(cs_line, 0); // Select the chip
    ret = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret != 0) {
        fprintf(stderr, "SPI read failed: %d\n", ret);
        return -1000.0; // Indicate error
    }

    if (rx_buf[2] & 0x01) {
        fprintf(stderr, "RTD Fault detected!\n");
        return -1000.0; // Indicate error
    }

    // Convert RTD value to temperature (Callendar-Van Dusen equation)
    temperature = (rtd_raw / 32768.0) * RREF; // Convert to resistance
    temperature = temperature / (1.0 + 0.0039083 * temperature); // Simplified equation
    temperature = temperature / (1.0 + 0.0000005775 * temperature * temperature); // Simplified equation
    temperature = temperature - 100.0; // Offset

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

