        close_resources();
        return 1;
    }

    // Initialize log file
    if (init_log_file() != 0) {
        fprintf(stderr, "Log file initialization failed. Exiting.\n");
        close_resources();
        return 1;
    }

    printf("RTD Monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Check log file.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    close_resources();
    return 0;
}

