// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration) {
    calibration->ac1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    calibration->ac2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    calibration->ac3 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    calibration->ac4 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    calibration->ac5 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    calibration->ac6 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    calibration->b1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    calibration->b2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    calibration->mb = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    calibration->mc = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    calibration->md = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (calibration->ac1 == PI_BAD_I2C_ADDR || calibration->ac2 == PI_BAD_I2C_ADDR || calibration->ac3 == PI_BAD_I2C_ADDR ||
        calibration->ac4 == PI_BAD_I2C_ADDR || calibration->ac5 == PI_BAD_I2C_ADDR || calibration->ac6 == PI_BAD_I2C_ADDR ||
        calibration->b1 == PI_BAD_I2C_ADDR || calibration->b2 == PI_BAD_I2C_ADDR || calibration->mb == PI_BAD_I2C_ADDR ||
        calibration->mc == PI_BAD_I2C_ADDR || calibration->md == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error writing to control register for temperature\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)
    *raw_temperature = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (*raw_temperature < 0) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) {
        fprintf(stderr, "Error writing to control register for pressure\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (minimum)
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temperature, bmp180_calibration_data_t *calibration) {
    long x1 = (((long)raw_temperature - (long)calibration->ac6) * (long)calibration->ac5) >> 15;
    long x2 = ((long)calibration->mc << 11) / (x1 + calibration->md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t *calibration) {
    long x1 = (((long)raw_temperature - (long)calibration->ac6) * (long)calibration->ac5) >> 15;
    long x2 = ((long)calibration->mc << 11) / (x1 + calibration->md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration->b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)calibration->ac2 * b6) >> 11;
