    }

    x1 = (pressure >> 8) * (pressure >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * pressure) >> 16;
    pressure = pressure + ((x1 + x2 + 3791) >> 4);

    return (double)pressure / 100.0; // Convert to hPa
}

// Function to add a reading to the circular buffer
void add_reading(circular_buffer_t *buffer, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    buffer->buffer[buffer->head].pressure = pressure;
    buffer->buffer[buffer->head].temperature = calculate_temperature(0, &calibration_data); // Dummy temperature for logging

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the rolling average of the pressure readings
double calculate_rolling_average(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    double sum = 0.0;
    int index = buffer->head;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[(index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE].pressure;
    }
    return sum / buffer->count;
}

// Function to trigger an alert on GPIO24
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(1000000);       // Wait 1 second
