        return 1;
    }

    // Initialize circular buffer
    pressure_buffer.head = 0;
    pressure_buffer.count = 0;

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback function
    gpioSetTimerFuncEx(0, 50, timer_callback, NULL); // Timer 0, every 50ms

    // Main loop
    while (!terminate) {
        gpioDelay(100000); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

