    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    // Main loop
    while (!terminate) {
        gpioDelay(1000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
