volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *device);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int bmp280_init(int fd, bmp280_calib_data *calib);
int bmp280_read_calibration_data(int fd, bmp280_calib_data *calib);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temp, bmp280_calib_data *calib);
double bmp280_compensate_pressure(int32_t raw_pressure, bmp280_calib_data *calib);
int log_data(double temperature, double pressure);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// BMP280 initialization function
int bmp280_init(int fd, bmp280_calib_data *calib) {
    uint8_t chip_id;

    // Check chip ID
    if (i2c_read_bytes(fd, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Incorrect chip ID 0x%02X (expected 0x58)\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data(fd, calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Configure sensor: Forced mode, oversampling x1
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP_X1 | BMP280_OVERSAMPLING_PRESS_X1 | BMP280_MODE_FORCED);
    if (i2c_write_byte(fd, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    return 0;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data(int fd, bmp280_calib_data *calib) {
    uint8_t data[24];
    if (i2c_read_bytes(fd, BMP280_REG_CALIB_00, data, 24) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// BMP280 read raw data function
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, BMP280_REG_PRESSURE_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temp, bmp280_calib_data *calib) {
    double var1, var2, T;
    var1 = (((double)raw_temp / 16384.0) - ((double)calib->dig_T1) / 1024.0) * ((double)calib->dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib->dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib->dig_T1) / 8192.0)) * ((double)calib->dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_pressure, bmp280_calib_data *calib) {
    double var1, var2, p;
    double t_fine; // Assuming t_fine is already calculated in compensate_temperature

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib->dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib->dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib->dig_P4) * 65536.0);
    var1 = (((double)calib->dig_P3) * var1 * var1 / 524288.0 + ((double)calib->dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib->dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib->dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib->dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib->dig_P7)) / 16.0;

    return p/100.0; // Return in hPa
}

// Log data function
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_string[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_string, sizeof(log_string), "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);

    FILE *fp = fopen("weather_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (fputs(log_string, fp) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    int retries = 3;
    int i2c_address = BMP280_ADDR_1;
    int fd;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    while (retries > 0) {
        fd = i2c_open(i2c_device);
        if (fd >= 0) {
            i2c_fd = fd;
            break;
        }
        fprintf(stderr, "Retrying I2C open in 1 second...\n");
        sleep(1);
        retries--;
    }

    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device after multiple retries. Exiting.\n");
        return 1;
    }

    // Initialize BMP280 sensor
    while (retries > 0) {
        if (bmp280_init(i2c_fd, &calib) == 0) {
            break;
        }
        fprintf(stderr, "Retrying BMP280 initialization in 1 second...\n");
        sleep(1);
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to initialize BMP280 sensor after multiple retries. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data, attempting to re-initialize...\n");
            close(i2c_fd);
            i2c_fd = i2c_open(i2c_device);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-open I2C device. Exiting.\n");
                program_running = 0;
                continue;
            }
            if (bmp280_init(i2c_fd, &calib) != 0) {
                fprintf(stderr, "Failed to re-initialize BMP280 sensor. Exiting.\n");
                close(i2c_fd);
                program_running = 0;
                continue;
            }
            continue; // Skip to the next iteration
        }

        // Compensate temperature and pressure
        temperature = bmp280_compensate_temperature(raw_temperature, &calib);
        pressure = bmp280_compensate_pressure(raw_pressure, &calib);

        // Log data
        if (log_data(temperature, pressure) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

