#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int i2c_fd = -1;
static volatile int running = 1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void update_led(float temperature);
void *data_acquisition_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75 sensor
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_fd, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", bytes_read);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert two's complement to signed integer
    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temp = raw_temp >> 5; // Shift right by 5 bits

    // Convert to Celsius
    float temperature = (float)raw_temp / 256.0;
    return temperature;
}

// Function to update LED based on temperature
void update_led(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Thread function for data acquisition
void *data_acquisition_thread(void *arg) {
    while (running) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            pthread_mutex_lock(&buffer_mutex);
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            pthread_mutex_unlock(&buffer_mutex);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO back to input
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Create data acquisition thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating thread\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        float sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += temperature_buffer[i];
        }
        float average_temperature = sum / BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        update_led(average_temperature);
        printf("Average Temperature: %.2f°C\n", average_temperature);
        sleep(5); // Log every 5 seconds
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

