#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <jansson.h>
#include <time.h>

// Configuration file path
#define CONFIG_FILE "config.json"

// Default values if config file is missing
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// GPIO pin for heater control (PWM)
#define HEATER_GPIO 18

// SPI channel for MAX31865
#define SPI_CHANNEL 0

// SPI clock frequency (500 kHz)
#define SPI_FREQUENCY 500000

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// PWM range (0-1000 for 0-100% duty cycle)
#define PWM_RANGE 1000

// MAX31865 register addresses
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// MAX31865 fault codes
#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_SHORT_GND 0x02
#define MAX31865_FAULT_SHORT_VCC 0x04

// Global variables
static int spi_handle;
static double target_temperature = DEFAULT_TARGET_TEMP;
static double Kp = DEFAULT_KP;
static double Ki = DEFAULT_KI;
static double Kd = DEFAULT_KD;
static volatile int running = 1;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
int read_config(const char *filename, double *target_temp, double *Kp, double *Ki, double *Kd);
int init_max31865();
double read_temperature();
double rtd_to_resistance(uint16_t rtd_code);
double resistance_to_temperature(double resistance);
double pid_control(double setpoint, double actual_temperature);
void set_heater_power(double duty_cycle);
void signal_handler(int signal);

// Function to read configuration from JSON file
int read_config(const char *filename, double *target_temp, double *Kp, double *Ki, double *Kd) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file %s: %s\n", filename, error.text);
        return -1;
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    json_t *Kp_json = json_object_get(root, "Kp");
    json_t *Ki_json = json_object_get(root, "Ki");
    json_t *Kd_json = json_object_get(root, "Kd");

    if (!json_is_real(target_temp_json) || !json_is_real(Kp_json) || !json_is_real(Ki_json) || !json_is_real(Kd_json)) {
        fprintf(stderr, "Error: Invalid config file format\n");
        json_decref(root);
        return -1;
    }

    *target_temp = json_real_value(target_temp_json);
    *Kp = json_real_value(Kp_json);
    *Ki = json_real_value(Ki_json);
    *Kd = json_real_value(Kd_json);

    json_decref(root);
    return 0;
}

// Function to initialize the MAX31865
int init_max31865() {
    char buf[2];

    // Enable VBIAS, auto-conversion, and clear faults
    buf[0] = MAX31865_CONFIG_REG | 0x80; // Write to config register
    buf[1] = 0xC1; // Enable VBIAS, auto-conversion, clear faults

    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write to MAX31865 config register\n");
        return -1;
    }

    return 0;
}

// Function to read temperature from MAX31865
double read_temperature() {
    char buf[1];
    char read_buf[3];
    uint16_t rtd_code;
    double resistance;
    double temperature;
    int fault;

    // Read RTD MSB and LSB registers
    buf[0] = MAX31865_RTD_MSB_REG | 0x00; // Read RTD MSB and LSB registers
    if (spiXfer(spi_handle, buf, read_buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to read RTD data from MAX31865\n");
        return -1000.0; // Indicate error with a very low temperature
    }

    // Extract RTD code (15 bits)
    rtd_code = ((uint16_t)read_buf[1] << 8) | (uint16_t)read_buf[2];
    rtd_code = rtd_code >> 1; // Remove fault bit

    // Read fault register
    buf[0] = MAX31865_FAULT_REG | 0x00; // Read fault register
    if (spiXfer(spi_handle, buf, read_buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to read fault register from MAX31865\n");
        return -1000.0; // Indicate error with a very low temperature
    }

    fault = (uint8_t)read_buf[0];

    // Check for faults
    if (fault & MAX31865_FAULT_OPEN) {
        fprintf(stderr, "Error: MAX31865 fault: Open circuit\n");
        return -1000.0;
    }
    if (fault & MAX31865_FAULT_SHORT_GND) {
        fprintf(stderr, "Error: MAX31865 fault: Short to GND\n");
        return -1000.0;
    }
    if (fault & MAX31865_FAULT_SHORT_VCC) {
        fprintf(stderr, "Error: MAX31865 fault: Short to VCC\n");
        return -1000.0;
    }

