double rtd_to_resistance(uint16_t rtd_code) {
    double rtd_resistance = (rtd_code / 32768.0) * 430.0;
    return rtd_resistance;
}

// Function to convert resistance to temperature using the Callendar-Van Dusen equation
double resistance_to_temperature(double resistance) {
    double r0 = 100.0; // Nominal resistance of PT100
    double a = 3.9083e-3;
    double b = -5.775e-7;
    double t;

    // Callendar-Van Dusen equation
    t = (r0 / resistance) - 1.0;
    t = t / (a + b * t);

    return t;
}

