// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 3;
    int bytes_read = 0;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        bytes_read = read(fd, buf, len);
        if (bytes_read == len) {
            return 0; // Success
        } else {
            perror("Failed to read data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &value, 1) == 1) {
            return 0; // Success
        } else {
            perror("Failed to write data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// Read calibration data from the BMP180
int read_calibration_data(int fd) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, buf, 22) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Read raw temperature value from the BMP180
int read_raw_temperature(int fd) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms (minimum)
    uint8_t buf[2];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Read raw pressure value from the BMP180
int read_raw_pressure(int fd) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }

    usleep(26000); // Wait for conversion (OSS = 3)

    uint8_t buf[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 3) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
}

// Calculate temperature in degrees Celsius
float calculate_temperature(int ut) {
    long x1 = ((long)ut - (long)ac6) * (long)ac5 / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
float calculate_pressure(int up, int ut) {
    long x1 = ((long)ut - (long)ac6) * (long)ac5 / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    long b6 = b5 - 4000;
    long x3 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    long x4 = ac2 * b6 / pow(2, 11);
    long b3 = (((long)ac1 * 4 + x3 + x4) + 2) / 4;
    unsigned long b4 = ac4 * (unsigned long)(x3 + x4 + 32768) / pow(2, 15);
    unsigned long b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Check if temperature or pressure exceeds thresholds
int check_thresholds(float temperature, float pressure) {
    if (temperature > TEMPERATURE_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
        return 1; // Breach detected
    }
    return 0; // No breach
}

// Log breach to file
int log_breach(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Breach: Temperature=%.2f°C, Pressure=%.2f hPa\n", timestamp, temperature, pressure);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// I2C setup function
int i2c_setup(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_setup("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 sensor... Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read raw temperature and pressure
        int ut = read_raw_temperature(i2c_fd);
        int up = read_raw_pressure(i2c_fd);

        if (ut != -1 && up != -1) {
            // Calculate temperature and pressure
            float temperature = calculate_temperature(ut);
            float pressure = calculate_pressure(up, ut);

            // Check for breaches
            if (check_thresholds(temperature, pressure)) {
                log_breach(temperature, pressure);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

