void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    char write_buf[1] = {0x2E}; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[3];
    char write_buf[1] = {0x34 + (OSS << 6)}; // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms for OSS=0

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate true temperature in degrees Celsius
float calculate_true_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + (int32_t)md);
    int32_t B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_true_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + (int32_t)md);
    int32_t B5 = X1 + X2;
    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) >> 2;
    uint32_t X5 = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X6 = ((uint32_t)b1 * (B6 * B6) >> 12) >> 16;
    uint32_t B4 = ((uint32_t)X5 + X6 + 32768) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, float temperature, float pressure) {
    buffer->data[buffer->head].timestamp = time(NULL);
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].pressure = pressure;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer(circular_buffer_t *buffer) {
    printf("Timestamp,Temperature(C),Pressure(Pa)\n");
    int start = (buffer->count == BUFFER_SIZE) ? buffer->head : 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer->data[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f\n", timestamp_str, buffer->data[index].temperature, buffer->data[index].pressure);
    }
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0f) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temp, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_true_temperature(raw_temp);
        pressure = calculate_true_pressure(raw_pressure, raw_temp);

        add_to_buffer(&buffer, temperature, pressure);
        print_buffer(&buffer);
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);   // Close I2C
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Keep the program running until a signal is received
    while (!terminate) {
        gpioDelay(1000); // Sleep for 1 second
    }

    return 0;
}

