void add_to_buffer(circular_buffer_t *buffer, float temperature, float pressure) {
    buffer->data[buffer->head].timestamp = time(NULL);
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].pressure = pressure;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer(circular_buffer_t *buffer) {
    printf("Timestamp,Temperature(C),Pressure(Pa)\n");
    int start = (buffer->count == BUFFER_SIZE) ? buffer->head : 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer->data[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f\n", timestamp_str, buffer->data[index].temperature, buffer->data[index].pressure);
    }
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0f) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temp, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_true_temperature(raw_temp);
        pressure = calculate_true_pressure(raw_pressure, raw_temp);

        add_to_buffer(&buffer, temperature, pressure);
        print_buffer(&buffer);
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);   // Close I2C
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Keep the program running until a signal is received
    while (!terminate) {
        gpioDelay(1000); // Sleep for 1 second
    }

    return 0;
}

