// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data\n");
        return 1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Read raw temperature value from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char write_buf[1];

    write_buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Failed to write temperature measurement command\n");
        return 1;
    }
    gpioDelay(5); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Failed to read raw temperature data\n");
        return 1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Read raw pressure value from BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char write_buf[1];

    write_buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Failed to write pressure measurement command\n");
        return 1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait time depends on OSS

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return 1;
    }

    *raw_pressure = ((unsigned long)buf[0] << 16 | (unsigned long)buf[1] << 8 | (unsigned long)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate pressure using BMP180 compensation formulas
double calculate_pressure(int raw_temp, int raw_pressure) {
    double x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Temperature calculations
    x1 = ((double)raw_temp - (double)ac6) * ((double)ac5) / pow(2, 15);
    x2 = ((double)mc * pow(2, 11)) / (x1 + (double)md);
    b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4);

    // Pressure calculations
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((((double)ac1) * 4 + x3) + 2) / 4);
    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / 4;
    b4 = ac4 * (unsigned long)(x3 + 32768) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (x1 + x2 + 3791) / pow(2, 4);

    return pressure;
}

// Log pressure reading to file
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open pressure_log.txt\n");
        return;
    }

    fprintf(fp, "%s, %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler for GPIO27
void interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();

    // Debounce the interrupt
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

