#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 25.0 // Default target temperature in Celsius
#define MAX_DUTY_CYCLE 80.0   // Maximum duty cycle percentage
#define PI 3.14159265359

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double Kp = 1.0; // Proportional gain
static double Ki = 0.1; // Integral gain
static double integral = 0.0;
static double target_temperature = TARGET_TEMPERATURE;

// Function prototypes
double read_temperature();
double calculate_pwm(double current_temperature, double target_temperature);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855 via SPI
double read_temperature() {
    int handle;
    char rx_buffer[4];
    int i;
    double temperature = NAN; // Initialize to NaN in case of error

    handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Open SPI channel
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return NAN;
    }

    // Read 4 bytes from SPI
    i = spiRead(handle, rx_buffer, 4);
    if (i != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", i);
        spiClose(handle);
        return NAN;
    }

    spiClose(handle);

    // Check for fault bits
    if (rx_buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault detected!\n");
        return NAN;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_pwm(double current_temperature, double target_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;

