#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds (millidegrees Celsius)
#define TEMP_LOW   40000
#define TEMP_MED  59999
#define TEMP_HIGH 60000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU temperature from sysfs file
int read_cpu_temp()
{
    FILE *fp;
    int temp = -1; // Initialize to an invalid value

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to map temperature to RGB values
void map_temp_to_rgb(int temp, int *red, int *green, int *blue)
{
    if (temp < TEMP_LOW) {
        *red   = 0;
        *green = 0;
        *blue  = 255;
    } else if (temp > TEMP_HIGH) {
        *red   = 255;
        *green = 0;
        *blue  = 0;
    } else {
        *red   = 0;
        *green = 255;
        *blue  = 0;
    }
}

// Function to set RGB LED color using PWM
void set_rgb_led(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int temp = read_cpu_temp();
        if (temp == -1) {
            // Error reading temperature, skip this cycle
            sleep(0.5);
            continue;
        }

        int red, green, blue;
        map_temp_to_rgb(temp, &red, &green, &blue);

        set_rgb_led(red, green, blue);

        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);

        sleep(0.5);
    }

    // Cleanup: Turn off LEDs and terminate pigpio
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();

    return 0;
}

