    if ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) != data_bytes[4]) {
        data.error = -3; // Checksum error
        return data;
    }

    // Parse data
    data.humidity = (float)((data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data.temperature = (float)(((data_bytes[2] & 0x7F) << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
        data.temperature *= -1;
    }

    return data;
}

// Function to post data to server
int post_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[100];
    long response_code;

    // Create JSON payload
    snprintf(json_data, sizeof(json_data), "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        // Set headers for JSON content
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Perform the request
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code != 200) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        // Clean up
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return 1;
    }

    curl_global_cleanup();
    return 0;
}

int main() {
    int retries;
    DHT22Data dht22_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        retries = 0;
        dht22_data.error = -4; // Initialize error code

        while (retries < MAX_RETRIES && dht22_data.error != 0) {
            dht22_data = read_dht22_data();
            if (dht22_data.error != 0) {
                fprintf(stderr, "DHT22 read failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                sleep(1); // Wait before retrying
            }
        }

        if (dht22_data.error == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", dht22_data.temperature, dht22_data.humidity);
            if (post_data(dht22_data.temperature, dht22_data.humidity) != 0) {
                fprintf(stderr, "Failed to post data to server\n");
            }
        } else {
            fprintf(stderr, "DHT22 sensor absent or communication error\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

