#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
int i2c_handle;
volatile int logging_enabled = 0;
volatile unsigned int last_interrupt_time = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_bmp180();
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temperature, int raw_pressure);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to initialize the BMP180 sensor
int init_bmp180()
{
    // Check if the sensor is present by reading a register
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 0) != 0) {
        fprintf(stderr, "Error reading from BMP180, possibly not present.\n");
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_int16(BMP180_REG_CAL_AC1);
    ac2 = read_int16(BMP180_REG_CAL_AC2);
    ac3 = read_int16(BMP180_REG_CAL_AC3);
    ac4 = read_uint16(BMP180_REG_CAL_AC4);
    ac5 = read_uint16(BMP180_REG_CAL_AC5);
    ac6 = read_uint16(BMP180_REG_CAL_AC6);
    b1 = read_int16(BMP180_REG_CAL_B1);
    b2 = read_int16(BMP180_REG_CAL_B2);
    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data from registers.\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data.\n");
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command.\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (OSS=3)

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data.\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate the pressure in hPa using the BMP180 compensation algorithm
double calculate_pressure(int raw_temperature, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Temperature calculations
    x1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0; // Temperature in degrees Celsius

    // Pressure calculations
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((ac1 * 4 + x3) << OSS) + 2) / 4;
    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = ac4 * (unsigned long)(x3 + 32768) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (x1 + x2 + 3791) / pow(2, 4); // Pressure in Pa

    return pressure / 100.0; // Convert to hPa
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user)
{
    unsigned int current_time = gpioTick();

    // Debounce the interrupt
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;

        if (logging_enabled) {
            printf("Data logging enabled.\n");
        } else {
            printf("Data logging disabled.\n");
        }
    }
}

// Signal handler function for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP180 sensor
    if (init_bmp180() != 0) {
        fprintf(stderr, "BMP180 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_temperature, raw_pressure;
    double pressure;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate pressure in hPa
                pressure = calculate_pressure(raw_temperature, raw_pressure);

                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log data to file
                FILE *fp = fopen("pressure_log.txt", "a");
                if (fp != NULL) {
                    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
                    fclose(fp);
                } else {
                    fprintf(stderr, "Error opening pressure_log.txt for writing.\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        } else {
            printf("Data logging disabled.\n");
        }

        gpioDelay(2000000); // Sample every 2 seconds
    }

    return 0;
}

