static char *server_url = DEFAULT_SERVER_URL;

// Callback function for libcurl to write received data
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (ptr == NULL) {
        syslog(LOG_ERR, "realloc() failed");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Function to read DHT22 sensor data
DHT22Data read_dht22(int gpio) {
    DHT22Data data = {0.0, 1};
    int i, j;
    int data_bits[40];
    int data_bytes[5] = {0, 0, 0, 0, 0};

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 20-40us

    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(gpio) == 0) {
            count++;
            gpioDelay(1); // Check for timeout
            if (count > 200) {
                syslog(LOG_ERR, "DHT22 timeout waiting for HIGH");
                data.error = 1;
                return data;
            }
        }

        count = 0;
        while (gpioRead(gpio) == 1) {
            count++;
            gpioDelay(1); // Check for timeout
            if (count > 200) {
                syslog(LOG_ERR, "DHT22 timeout waiting for LOW");
                data.error = 1;
                return data;
            }
        }

        data_bits[i] = count;
    }

    // Convert bits to bytes
    for (i = 0; i < 40; i++) {
        data_bytes[i / 8] <<= 1;
        if (data_bits[i] > 20) {
            data_bytes[i / 8] |= 1;
        }
    }

    // Calculate checksum
    int checksum = (data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) & 0xFF;

    if (checksum != data_bytes[4]) {
        syslog(LOG_ERR, "DHT22 checksum failure");
        data.error = 1;
        return data;
    }

    // Calculate humidity
    data.humidity = ((data_bytes[0] * 256) + data_bytes[1]) / 10.0;

