#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Configuration
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_TEMP 80000 // 80°C in millidegrees
#define MIN_TEMP 40000 // 40°C in millidegrees
#define NUM_SPEEDS 4
#define SLEEP_SECONDS 5

// Global variables
volatile sig_atomic_t program_running = 1;
int fan_fd = -1;
FILE *log_fp = NULL;

// Structure to hold speed mapping
typedef struct {
    int temp_min;
    int temp_max;
    int speed;
} speed_map_t;

speed_map_t speed_map[NUM_SPEEDS] = {
    {MIN_TEMP, 45000, 0},   // 0-45°C: Off
    {45001, 55000, 1},   // 46-55°C: Low
    {55001, 65000, 2},   // 56-65°C: Medium
    {65001, MAX_TEMP, 3}    // 66-80°C: High
};

// Function prototypes
int read_temperature();
int map_temperature_to_speed(int temperature);
int set_fan_speed(int speed);
int log_fan_state(int speed);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read the CPU temperature from the sysfs file
int read_temperature() {
    int temp = -1;
    int fd;
    char buffer[10];

    fd = open(TEMP_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        perror("Failed to read temperature");
        close(fd);
        return -1;
    }

    close(fd);
    buffer[sizeof(buffer) - 1] = '\0'; // Ensure null termination
    temp = atoi(buffer);

    return temp;
}

// Function to map the temperature to a fan speed based on the speed_map
int map_temperature_to_speed(int temperature) {
    for (int i = 0; i < NUM_SPEEDS; i++) {
        if (temperature >= speed_map[i].temp_min && temperature <= speed_map[i].temp_max) {
            return speed_map[i].speed;
        }
    }
    return 0; // Default to off if temperature is below the lowest range
}

// Function to set the fan speed by writing to the sysfs file
int set_fan_speed(int speed) {
    char buffer[2];
    int fd;

    fd = open(FAN_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open fan file");
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", speed);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write fan speed");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log the fan state to a file
int log_fan_state(int speed) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s - Fan speed: %d\n", timestamp, speed);
    fflush(log_fp); // Ensure the log is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialization function
int initialize() {
    // Check if the cooling device exists
    if (access(FAN_FILE, F_OK) == -1) {
        fprintf(stderr, "Error: Cooling device not found at %s\n", FAN_FILE);
        return -1;
    }

    // Check if the max_state file exists
    char max_state_path[256];
    snprintf(max_state_path, sizeof(max_state_path), "%s/max_state", FAN_FILE);
    if (access(max_state_path, F_OK) == -1) {
        fprintf(stderr, "Error: max_state file not found at %s\n", max_state_path);
        return -1;
    }

    // Open the log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop the fan
    set_fan_speed(0);

    // Close the log file
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    // Close the fan file descriptor
    if (fan_fd != -1) {
        close(fan_fd);
    }
}

int main() {
    int temperature, speed, prev_speed = -1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature
        temperature = read_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Map temperature to speed
        speed = map_temperature_to_speed(temperature);

        // Set fan speed
        if (set_fan_speed(speed) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds...\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Log fan state
        if (speed != prev_speed) {
            if (log_fan_state(speed) != 0) {
                fprintf(stderr, "Error logging fan state, retrying in %d seconds...\n", SLEEP_SECONDS);
            }
            prev_speed = speed;
        }

        // Sleep
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    printf("Fan control program stopped.\n");
    return 0;
}

