#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Configuration
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 50.0 // Target temperature in Celsius
#define LOG_FILE "heater_log.txt"

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// MAX31855 Fault Codes
#define FAULT_OPEN_CIRCUIT 0x01
#define FAULT_SHORT_TO_GND 0x02
#define FAULT_SHORT_TO_VCC 0x04

// Global variables
static int spi_handle;
static FILE *log_file;
static volatile int running = 1;

// PID State
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void handle_fault(int fault_code);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(log_file, "%s SPI read failed: %d\n", __func__, result);
        fflush(log_file);
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bits
    if (data[3] & 0x07) {
        handle_fault(data[3] & 0x07);
        return -273.15; // Return absolute zero on fault
    }

    // Extract temperature data (bits 31:18 of the 32-bit value)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;

    integral += error;
    double derivative = error - previous_error;

    double output = KP * error + KI * integral + KD * derivative;

    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 1000000.0 / 1000000.0); // Scale to 0-1000000
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Function to handle thermocouple faults
void handle_fault(int fault_code) {
    fprintf(log_file, "%s Fault detected: 0x%02X\n", __func__, fault_code);
    fflush(log_file);

    if (fault_code & FAULT_OPEN_CIRCUIT) {
        fprintf(log_file, "%s Open circuit fault\n", __func__);
        fflush(log_file);
    }
    if (fault_code & FAULT_SHORT_TO_GND) {
        fprintf(log_file, "%s Short to GND fault\n", __func__);
        fflush(log_file);
    }
    if (fault_code & FAULT_SHORT_TO_VCC) {
        fprintf(log_file, "%s Short to VCC fault\n", __func__);
        fflush(log_file);
    }

    // Disable heater
    set_heater_pwm(0.0);

    // Reset PID state
    integral = 0.0;
    previous_error = 0.0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "%s Received signal %d, shutting down...\n", __func__, signal);
    fflush(log_file);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(log_file, "%s Cleaning up resources...\n", __func__);
    fflush(log_file);

    // Disable heater
    set_heater_pwm(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(log_file, "%s Cleanup complete.\n", __func__);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(log_file, "%s SPI open failed: %d\n", __func__, spi_handle);
        fflush(log_file);
        cleanup();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, 1000000); // Set PWM range to 0-1000000 for better resolution

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(log_file, "%s Program started\n", __func__);
    fflush(log_file);

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        // Check for valid temperature reading
        if (temperature < -200) {
            fprintf(log_file, "%s Invalid temperature reading, skipping PID calculation\n", __func__);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Calculate PID output
        double pid_output = calculate_pid(TARGET_TEMPERATURE, temperature);

        // Set heater PWM duty cycle
        set_heater_pwm(pid_output);

        // Log data
        log_data(temperature, pid_output, pid_output); // Log duty cycle as PID output

        // Failsafe: Check for unreasonable temperature readings
        if (temperature > 100.0 || temperature < 0.0) {
            fprintf(log_file, "%s Temperature out of range (%.2f), disabling heater\n", __func__, temperature);
            fflush(log_file);
            set_heater_pwm(0.0);
            integral = 0.0;
            previous_error = 0.0;
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

