// Constants
#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000
#define TEMP_MIN 40000  // 40°C in millidegrees
#define TEMP_MAX 70000  // 70°C in millidegrees
#define DUTY_MIN 0
#define DUTY_MAX 100

// Global variables
static volatile int running = 1;
static FILE *log_fp = NULL;

// Function prototypes
int read_cpu_temp();
float map_temp_to_duty(int temp);
int set_fan_speed(float duty_cycle);
int log_data(int temp, float duty_cycle);
void signal_handler(int signal);

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to map temperature to duty cycle
float map_temp_to_duty(int temp) {
    float duty_cycle;

    if (temp <= TEMP_MIN) {
        duty_cycle = 0.0;
    } else if (temp >= TEMP_MAX) {
        duty_cycle = 100.0;
    } else {
        duty_cycle = ((float)(temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN) + DUTY_MIN;
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
int set_fan_speed(float duty_cycle) {
    int duty = (int)(duty_cycle * 1000000.0 / 100.0); // Convert percentage to microseconds
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int temp, float duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_fp, "Timestamp,CPU Temperature (°C),PWM Duty Cycle (%%)\n"); // Write header if file is new
    }

    fprintf(log_fp, "%s,%d,%.2f\n", timestamp, temp, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    int temp;
    float duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and PWM frequency
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 1000000); // Set PWM range to 1000000 for microseconds

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or default\n");
            // Consider using a default temperature or handling the error appropriately
        } else {
            // Map temperature to duty cycle
            duty_cycle = map_temp_to_duty(temp);

            // Set fan speed
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }

            // Log data
            if (log_data(temp, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Temperature: %d m°C, Duty Cycle: %.2f %%\n", temp, duty_cycle);
        }

        sleep(5);
    }

    return 0;
}

