// Define GPIO pins for the rotary encoder
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder_state();
float calculate_angle(int state);
void log_data(int state, float angle);
void signal_handler(int signal);
void cleanup();

// Structure to hold the last known state of the encoder
struct EncoderState {
    int last_a_state;
    int last_b_state;
};

struct EncoderState encoder_state = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop to monitor the encoder
    while (running) {
        int current_state = read_encoder_state();

        // Calculate the angle based on the current state
        float angle = calculate_angle(current_state);

        // Log the data
        log_data(current_state, angle);

        // Delay to avoid excessive CPU usage
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the rotary encoder
int read_encoder_state() {
    int a_state = gpioRead(SENSOR_A_PIN);
    int b_state = gpioRead(SENSOR_B_PIN);

    // Update the last known state
    encoder_state.last_a_state = a_state;
    encoder_state.last_b_state = b_state;

    // Return the combined state (A0B0 A1B1)
    return (a_state << 1) | b_state;
}

// Function to calculate the normalized angular position based on the encoder state
float calculate_angle(int state) {
    // Quadrature encoding states
    static const int states[4][2] = {
        {0, 0},   // 00
        {1, 0},   // 01
        {1, 1},   // 11
        {0, 1}    // 10
    };

    // Calculate the change in state
    int a_diff = (state & 1) - (encoder_state.last_a_state & 1);
    int b_diff = (state >> 1) - (encoder_state.last_b_state >> 1);

    // Determine the direction of rotation based on the state change
    int direction = 0;
    if (a_diff == 1) {
        direction = b_diff;
    } else if (a_diff == -1) {
        direction = -b_diff;
    } else if (b_diff == 1) {
        direction = a_diff;
    } else if (b_diff == -1) {
        direction = -a_diff;
    }

    // Calculate the angle increment based on the direction
    float angle_increment = 0.0;
    if (direction == 1) {
        angle_increment = 45.0; // Clockwise
    } else if (direction == -1) {
        angle_increment = -45.0; // Counter-clockwise
    }

    // Calculate the new angle
    static float angle = 0.0;
    angle += angle_increment;

    // Normalize the angle to be between 0.00 and 360.00
    while (angle < 0.00) {
        angle += 360.00;
    }
    while (angle >= 360.00) {
        angle -= 360.00;
    }

    return angle;
}

// Function to log the data to a file
void log_data(int state, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, State: %d, Angle: %.2f\n", timestamp, state, angle);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler function to gracefully shutdown the program
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources.\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();
}

