#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define RED_REG 0x68
#define IR_REG 0x6A
#define LED_GPIO_PIN 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg, uint8_t data);
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir);
void control_led(int gpio_line, int state);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);

// I2C read function
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read ADPD144RI data
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t data[4];

    if (i2c_read_register(fd, FIFO_DATA_REG, data, 4) != 0) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    *red = (uint16_t)data[0] << 8 | data[1];
    *ir = (uint16_t)data[2] << 8 | data[3];

    return 0;
}

// Control LED
void control_led(int gpio_line, int state) {
    if (gpiod_line_set_value(gpio_line, state) != 0) {
        perror("Failed to set LED state");
    }
}

// Log data to file
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "adpd144ri", 0) != 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t red, ir;
    int led_state = 0;

    // Main loop
    while (!terminate) {
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            log_data(log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                led_state = 1;
            } else {
                led_state = 0;
            }

            control_led(led_line, led_state);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    control_led(led_line, 0); // Turn off LED
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

