#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define RED_FIFO_REG 0x08
#define IR_FIFO_REG 0x0A
#define PART_ID_REG 0x00
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int adpd144ri_init(int fd);
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir);
void control_led(int gpio, int on);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int signal);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, &reg, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return reg;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// ADPD144RI initialization function
int adpd144ri_init(int fd) {
    // Reset the device (example initialization sequence)
    if (i2c_write_register(fd, 0x04, 0x01) < 0) return -1; // Reset bit
    usleep(10000); // Wait for reset to complete

    // Configure FIFO (example configuration)
    if (i2c_write_register(fd, 0x06, 0x03) < 0) return -1; // FIFO configuration
    if (i2c_write_register(fd, 0x07, 0x00) < 0) return -1; // FIFO watermark

    // Enable FIFO (example)
    if (i2c_write_register(fd, 0x05, 0x01) < 0) return -1; // Enable FIFO

    return 0;
}

// Read ADPD144RI data function
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t red_data[2];
    uint8_t ir_data[2];

    if (read(fd, red_data, 2) != 2) {
        perror("Failed to read red data");
        return -1;
    }
    if (read(fd, ir_data, 2) != 2) {
        perror("Failed to read IR data");
        return -1;
    }

    *red = (red_data[1] << 8) | red_data[0];
    *ir = (ir_data[1] << 8) | ir_data[0];

    return 0;
}

// Control LED function
void control_led(int gpio, int on) {
    gpioWrite(gpio, on);
}

// Log data function
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADPD144RI
    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Verify PART_ID register
    uint8_t part_id = i2c_read_register(i2c_fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("ADPD144RI PART_ID: 0x%02X\n", part_id);

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, ir;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            // Log data
            log_data(log_file, red, ir);

            // Control LED based on IR reading
            if (ir > IR_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sample every 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

