    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADPD144RI
    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Verify PART_ID register
    uint8_t part_id = i2c_read_register(i2c_fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("ADPD144RI PART_ID: 0x%02X\n", part_id);

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, ir;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            // Log data
            log_data(log_file, red, ir);

            // Control LED based on IR reading
            if (ir > IR_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sample every 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

