#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *audio_input_line = NULL;
static struct gpiod_line *gain_select_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int set_gain(int gain);
int read_audio_input(void);
void log_event(void);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("\nCaught signal %d, exiting gracefully...\n", sig);
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get audio input line
    audio_input_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (!audio_input_line) {
        perror("Error getting audio input line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get gain select line
    gain_select_line = gpiod_chip_get_line(chip, GAIN_SELECT_PIN);
    if (!gain_select_line) {
        perror("Error getting gain select line");
        gpiod_chip_close(chip);
        gpiod_line_release(audio_input_line);
        return -1;
    }

    // Request audio input line as input
    ret = gpiod_line_request(audio_input_line, "audio_input", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        perror("Error requesting audio input line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(audio_input_line);
        gpiod_line_release(gain_select_line);
        return -1;
    }

    // Request gain select line as output
    ret = gpiod_line_request(gain_select_line, "gain_select", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting gain select line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(audio_input_line);
        gpiod_line_release(gain_select_line);
        return -1;
    }

    return 0;
}

// Set gain (60dB or 30dB)
int set_gain(int gain) {
    int ret;

    if (gain == 60) {
        ret = gpiod_line_set_value(gain_select_line, 0); // 60dB
    } else if (gain == 30) {
        ret = gpiod_line_set_value(gain_select_line, 1); // 30dB
    } else {
        fprintf(stderr, "Invalid gain setting: %d\n", gain);
        return -1;
    }

    if (ret < 0) {
        perror("Error setting gain");
        return -1;
    }

    return 0;
}

// Read audio input
int read_audio_input(void) {
    int value = gpiod_line_get_value(audio_input_line);
    if (value < 0) {
        perror("Error reading audio input");
        return -1;
    }
    return value;
}

// Log event to file
void log_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s LEVEL\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup GPIO resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (audio_input_line) {
        gpiod_line_release(audio_input_line);
    }
    if (gain_select_line) {
        gpiod_line_release(gain_select_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set gain to 60dB
    if (set_gain(60) < 0) {
        fprintf(stderr, "Failed to set gain to 60dB. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int audio_level = read_audio_input();
        if (audio_level < 0) {
            fprintf(stderr, "Error reading audio input. Continuing...\n");
            usleep(10000); // Sleep for 10ms
            continue;
        }

        if (audio_level == 1) {
            log_event();
        }

        usleep(10000); // Sleep for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

