#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASUREMENT_CMD_MSB 0x36
#define MEASUREMENT_CMD_LSB 0x08
#define CRC_POLYNOMIAL 0x31
#define FLOW_RATE_SCALE 1000.0
#define LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint8_t command_msb, uint8_t command_lsb);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
float convert_to_flow_rate(int16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// CRC-8 algorithm
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to sensor
int send_command(int handle, uint8_t command_msb, uint8_t command_lsb) {
    char buf[2] = {command_msb, command_lsb};
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw flow data to flow rate
float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE;
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s,%.6f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        int16_t raw_flow;
        float flow_rate;

        // Read sensor data
        if (read_sensor_data(i2c_handle, data, 3) == 0) {
            // CRC validation
            uint8_t crc_calculated = calculate_crc(data, 2);
            if (crc_calculated == data[2]) {
                // Convert to flow rate
                raw_flow = (int16_t)((data[0] << 8) | data[1]);
                flow_rate = convert_to_flow_rate(raw_flow);

                // Log flow rate
                if (log_flow_rate(flow_rate) != 0) {
                    fprintf(stderr, "Error logging flow rate\n");
                }
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

