#define I2C_BUS 1
#define SENSOR_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define IAQ_MIN 0
#define IAQ_MAX 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(uint16_t tvoc, uint16_t eco2);
int log_data(float iaq, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
int read_sensor_data(sensor_data_t *data) {
    char buf[7];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 7);

    if (bytes_read != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    data->tvoc = (uint16_t)((buf[1] << 8) | buf[0]);
    data->eco2 = (uint16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate IAQ index
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0 - (float)tvoc / 10.0 - ((float)eco2 - 400.0) / 50.0;
    if (iaq < IAQ_MIN) {
        iaq = IAQ_MIN;
    } else if (iaq > IAQ_MAX) {
        iaq = IAQ_MAX;
    }
    return iaq;
}

// Log data to CSV file
int log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float iaq;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

