#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pin and chip
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"

// Define tamper detection threshold (in seconds)
#define TAMPER_THRESHOLD 5

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
void handle_intrusion(void);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO line
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Handle intrusion alert
void handle_intrusion(void) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("INTRUSION DETECTED: %s\n", timestamp);
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    time_t touch_start = 0;
    int sensor_value = 0;
    int last_sensor_value = 0;

    while (!terminate) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1 && last_sensor_value == 0) {
            // Sensor touched
            touch_start = time(NULL);
        } else if (sensor_value == 0 && last_sensor_value == 1) {
            // Sensor released
            touch_start = 0; // Reset timer
        }

        if (touch_start > 0 && time(NULL) - touch_start >= TAMPER_THRESHOLD) {
            handle_intrusion();
            touch_start = 0; // Reset timer after alert
        }

        last_sensor_value = sensor_value;
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Tamper detection system stopped.\n");
    return EXIT_SUCCESS;
}

