#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1 // Mono
#define BITS_PER_SAMPLE 24
#define PCM_SAMPLE_SIZE (NUM_CHANNELS * (BITS_PER_SAMPLE / 8)) // 1 byte per sample
#define BUFFER_SIZE (SAMPLE_RATE * 10) // 10 seconds of audio

// GPIO pin for L/R select (INMP441)
#define L_R_SELECT_PIN 17

// ALSA device name
#define ALSA_DEVICE "default"

// Global variables
snd_pcm_t *pcm_handle;
FILE *audio_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data and timestamp
typedef struct {
    int16_t sample;
    struct timeval timestamp;
} audio_frame_t;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int init_gpio(int pin);
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S24_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(pin, 0); // Select left channel initially
    return 0;
}

// Capture audio data
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file) {
    char buffer[PCM_SAMPLE_SIZE * BUFFER_SIZE];
    int err;
    int frames = BUFFER_SIZE;
    int bytes_read;

    while (!terminate) {
        bytes_read = snd_pcm_readi(pcm_handle, buffer, frames);
        if (bytes_read == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(bytes_read));
            return -1;
        } else if (bytes_read > 0) {
            // Process the audio data
            for (int i = 0; i < bytes_read; i += PCM_SAMPLE_SIZE) {
                // Extract 24-bit sample from the frame
                int32_t sample_24bit = *((int32_t *) (buffer + i));
                // Right-shift to get 16-bit PCM sample
                int16_t sample_16bit = (int16_t)(sample_24bit >> 8);

                // Get timestamp
                struct timeval timestamp;
                gettimeofday(&timestamp, NULL);

                // Write to file
                audio_frame_t frame;
                frame.sample = sample_16bit;
                frame.timestamp = timestamp;

                if (fwrite(&frame, sizeof(audio_frame_t), 1, audio_file) != 1) {
                    fprintf(stderr, "Error writing to file\n");
                    return -1;
                }
            }
        }
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
    if (audio_file) {
        fclose(audio_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(L_R_SELECT_PIN) != 0) {
        cleanup();
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen("audio_capture.pcm", "wb");
    if (audio_file == NULL) {
        fprintf(stderr, "Error opening audio file\n");
        cleanup();
        return 1;
    }

    // Capture audio
    if (capture_audio(pcm_handle, audio_file) != 0) {
        fprintf(stderr, "Audio capture failed\n");
        cleanup();
        return 1;
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

