#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define flame detection timeout (in seconds)
#define FLAME_TIMEOUT 5

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type, int flame_duration);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t flame_start_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Log system start event
    log_event("System Start", 0);

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected) {
            // Flame detected
            if (!state.flame_detected) {
                // Flame started
                state.flame_detected = 1;
                state.flame_start_time = time(NULL);
                log_event("Flame Detected", 0);
            } else {
                // Flame is still present
                time_t current_time = time(NULL);
                int flame_duration = (int)(current_time - state.flame_start_time);
                control_fan(1);
                log_event("Flame Detected", flame_duration);
            }
        } else {
            // No flame detected
            if (state.flame_detected) {
                // Flame ended
                state.flame_detected = 0;
                control_fan(0);
                log_event("Flame Ended", 0);
            }
        }

        // Check for timeout
        if (state.flame_detected && (time(NULL) - state.flame_start_time) > FLAME_TIMEOUT) {
            fprintf(stderr, "Flame detection timeout. Shutting down.\n");
            log_event("Flame Timeout", 0);
            running = 0;
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms
    }

    // Log system shutdown event
    log_event("System Shutdown", 0);

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as input
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    // Set GPIO 18 as output and enable PWM
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 1000); // Set PWM range to 1000 for 0-100% duty cycle

    return 0;
}

// Read flame sensor with debouncing
int read_flame_sensor() {
    int i;
    int count = 0;

    // Read the sensor multiple times and count the number of LOW readings
    for (i = 0; i < 5; i++) {
        if (gpioRead(FLAME_SENSOR_PIN) == 0) {
            count++;
        }
        gpioDelay(1000); // 1 ms delay
    }

    // Consider it a flame if the majority of readings are LOW
    return (count > 2); // Debounced reading
}

// Control the cooling fan using PWM
void control_fan(int flame_detected) {
    if (flame_detected) {
        // Calculate duty cycle based on flame duration (exponential curve)
        int flame_duration = (int)(time(NULL) - state.flame_start_time);
        int duty_cycle = 0;

        if (flame_duration > 0) {
            duty_cycle = (int)((1.0 - exp(-flame_duration / 10.0)) * 80.0); // Exponential curve
            if (duty_cycle > 80) duty_cycle = 80;
            if (duty_cycle < 0) duty_cycle = 0;
        }

        gpioPWM(FAN_PIN, duty_cycle * 10); // Set PWM duty cycle (0-1000)
    } else {
        // Turn off the fan
        gpioPWM(FAN_PIN, 0);
    }
}

// Log events to file
void log_event(const char *event_type, int flame_duration) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %s - Flame Duration: %d seconds\n", timestamp, event_type, flame_duration);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

