#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24
#define FRAME_PERIOD_MS 100
#define NUM_CHIRPS 64
#define NUM_SAMPLES 256
#define HEATMAP_SIZE (NUM_CHIRPS * NUM_SAMPLES)
#define HEATMAP_BYTES (HEATMAP_SIZE * 2) // 16-bit data

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    uint64_t start_frequency;
    uint64_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
    uint16_t frame_period_ms;
} radar_config_t;

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int log_header(FILE *fp, radar_config_t config);
int log_frame(FILE *fp, uint64_t timestamp, uint16_t frame_number, const uint8_t *data);
int read_spi_data(uint8_t *data);
int trigger_radar();
int data_ready();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_DOWN); // Optional pull-down

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Log the file header
int log_header(FILE *fp, radar_config_t config) {
    uint8_t header[32];
    uint8_t magic[4] = {0x52, 0x44, 0x41, 0x44}; // "RDA" (Range-Doppler)

    // Copy magic number
    memcpy(header, magic, 4);

    // Copy configuration data
    memcpy(header + 4, &config.start_frequency, 8);
    memcpy(header + 12, &config.end_frequency, 8);
    memcpy(header + 20, &config.num_chirps, 2);
    memcpy(header + 22, &config.num_samples, 2);
    memcpy(header + 24, &config.frame_period_ms, 2);

    if (fwrite(header, 1, 32, fp) != 32) {
        fprintf(stderr, "Error writing header to file\n");
        return -1;
    }
    return 0;
}

// Log a frame of data
int log_frame(FILE *fp, uint64_t timestamp, uint16_t frame_number, const uint8_t *data) {
    uint8_t frame_data[32784]; // 32768 bytes + 4 bytes for timestamp + 2 bytes for frame number
    uint8_t *frame_ptr = frame_data;

    // Copy timestamp
    memcpy(frame_ptr, &timestamp, 8);
    frame_ptr += 8;

    // Copy frame number
    memcpy(frame_ptr, &frame_number, 2);
    frame_ptr += 2;

    // Copy heatmap data
    memcpy(frame_ptr, data, HEATMAP_BYTES);

    if (fwrite(frame_data, 1, 32784, fp) != 32784) {
        fprintf(stderr, "Error writing frame to file\n");
        return -1;
    }
    return 0;
}

// Read data from SPI
int read_spi_data(uint8_t *data) {
    int bytes_read = spiRead(spi_handle, (char *)data, HEATMAP_BYTES);
    if (bytes_read != HEATMAP_BYTES) {
        fprintf(stderr, "SPI read failed: %d bytes read\n", bytes_read);
        return -1;
    }
    return 0;
}

// Trigger the radar
int trigger_radar() {
    gpioWrite(GPIO_TRIGGER, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(GPIO_TRIGGER, 0);
    return 0;
}

// Check if data is ready
int data_ready() {
    return gpioRead(GPIO_DATA_READY);
}

int main() {
    // Configuration
    radar_config_t config = {
        .start_frequency = 77000000000, // 77 GHz
        .end_frequency = 79000000000,   // 79 GHz
        .num_chirps = NUM_CHIRPS,
        .num_samples = NUM_SAMPLES,
        .frame_period_ms = FRAME_PERIOD_MS
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.log", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Log header
    if (log_header(log_file, config) != 0) {
        cleanup();
        return 1;
    }

    uint8_t heatmap_data[HEATMAP_BYTES];
    uint64_t timestamp;
    uint16_t frame_number = 0;
    struct timespec ts;
    int bytes_read;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Trigger radar
        if (trigger_radar() != 0) {
            fprintf(stderr, "Error triggering radar\n");
            break;
        }

        // Wait for data ready
        while (!data_ready() && !terminate) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (terminate) break;

        // Read SPI data
        bytes_read = read_spi_data(heatmap_data);
        if (bytes_read != 0) {
            fprintf(stderr, "Error reading SPI data\n");
            break;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        timestamp = (uint64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;

        // Log frame
        if (log_frame(log_file, timestamp, frame_number, heatmap_data) != 0) {
            fprintf(stderr, "Error logging frame\n");
            break;
        }

        frame_number++;
    }

    // Cleanup
    cleanup();

    printf("Data acquisition complete.\n");
    return 0;
}

