    // Copy heatmap data
    memcpy(frame_ptr, data, HEATMAP_BYTES);

    if (fwrite(frame_data, 1, 32784, fp) != 32784) {
        fprintf(stderr, "Error writing frame to file\n");
        return -1;
    }
    return 0;
}

// Read data from SPI
int read_spi_data(uint8_t *data) {
    int bytes_read = spiRead(spi_handle, (char *)data, HEATMAP_BYTES);
    if (bytes_read != HEATMAP_BYTES) {
        fprintf(stderr, "SPI read failed: %d bytes read\n", bytes_read);
        return -1;
    }
    return 0;
}

// Trigger the radar
int trigger_radar() {
    gpioWrite(GPIO_TRIGGER, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(GPIO_TRIGGER, 0);
    return 0;
}

// Check if data is ready
int data_ready() {
    return gpioRead(GPIO_DATA_READY);
}

int main() {
    // Configuration
    radar_config_t config = {
        .start_frequency = 77000000000, // 77 GHz
        .end_frequency = 79000000000,   // 79 GHz
        .num_chirps = NUM_CHIRPS,
        .num_samples = NUM_SAMPLES,
        .frame_period_ms = FRAME_PERIOD_MS
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.log", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Log header
    if (log_header(log_file, config) != 0) {
        cleanup();
        return 1;
    }

    uint8_t heatmap_data[HEATMAP_BYTES];
    uint64_t timestamp;
    uint16_t frame_number = 0;
    struct timespec ts;
    int bytes_read;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Trigger radar
        if (trigger_radar() != 0) {
            fprintf(stderr, "Error triggering radar\n");
            break;
        }

        // Wait for data ready
        while (!data_ready() && !terminate) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (terminate) break;

        // Read SPI data
        bytes_read = read_spi_data(heatmap_data);
        if (bytes_read != 0) {
            fprintf(stderr, "Error reading SPI data\n");
            break;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        timestamp = (uint64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;

        // Log frame
        if (log_frame(log_file, timestamp, frame_number, heatmap_data) != 0) {
            fprintf(stderr, "Error logging frame\n");
            break;
        }

        frame_number++;
    }

    // Cleanup
    cleanup();

    printf("Data acquisition complete.\n");
    return 0;
}

