#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a flame event to the log file
int log_flame_event(const char *timestamp, const char *state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - Flame %s\n", timestamp, state);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check for flame detection
int is_flame_detected(int sensor_value) {
    return (sensor_value == 0) ? 1 : 0; // Flame detected if sensor value is LOW
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    int previous_state = -1; // Initialize to an invalid state

    // Main loop
    while (keep_running) {
        int sensor_value = read_flame_sensor(line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        int current_state = is_flame_detected(sensor_value);

        if (current_state != previous_state) {
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (current_state == 1) {
                    log_flame_event(timestamp, "detected");
                    printf("Flame detected at %s\n", timestamp);
                } else {
                    log_flame_event(timestamp, "cleared");
                    printf("Flame cleared at %s\n", timestamp);
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
            }
            previous_state = current_state;
        }

        usleep(100000); // 100 milliseconds
    }

    // Clean up resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

