#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define the GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define NUM_CHANNELS 8

// Structure to hold GPIO chip and line information
struct gpio_data {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
};

// Global variable to store the GPIO data
struct gpio_data gpio_data_global;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release all GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpio_data_global.lines[i] != NULL) {
            gpiod_line_release(gpio_data_global.lines[i]);
        }
    }

    // Close the GPIO chip
    if (gpio_data_global.chip != NULL) {
        gpiod_chip_close(gpio_data_global.chip);
    }

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_data_global.chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_data_global.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpio_data_global.lines[i] = gpiod_chip_get_line(gpio_data_global.chip, i);
        if (!gpio_data_global.lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", i, strerror(errno));
            // Release any previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_data_global.lines[j]);
            }
            gpiod_chip_close(gpio_data_global.chip);
            return 1;
        }

        // Request the line for input
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        int ret = gpiod_line_request(gpio_data_global.lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", i, strerror(errno));
            // Release any previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_data_global.lines[j]);
            }
            gpiod_chip_close(gpio_data_global.chip);
            return 1;
        }
    }

    // Main loop to read and log the sensor data
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(gpio_data_global.lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO line %d: %s\n", i, strerror(errno));
                // Release all lines and chip before exiting
                for (int j = 0; j < NUM_CHANNELS; j++) {
                    gpiod_line_release(gpio_data_global.lines[j]);
                }
                gpiod_chip_close(gpio_data_global.chip);
                return 1;
            }
            printf("Channel %d: %d\n", i, value);
        }
        usleep(100000); // 100 ms delay
    }

    return 0;
}

