#include <time.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 sensor channels
const int sensor_pins[8] = {2, 3, 4, 5, 6, 7, 8, 9};

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Configure each GPIO pin as an input with a pull-down resistor
    for (int i = 0; i < 8; i++)
    {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0)
        {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0)
        {
            fprintf(stderr, "Failed to set pull-down resistor for GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (!terminate)
    {
        // Get the current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Read the state of each sensor channel
        int sensor_states[8];
        for (int i = 0; i < 8; i++)
        {
            sensor_states[i] = gpioRead(sensor_pins[i]);
        }

        // Format the log message
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "[%ld ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
                 timestamp_ms, sensor_states[0], sensor_states[1], sensor_states[2], sensor_states[3],
                 sensor_states[4], sensor_states[5], sensor_states[6], sensor_states[7]);

        // Print the log message to the console
        printf("%s", log_message);

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

