struct gpio_line {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
};

// Global variable to store the GPIO lines
struct gpio_line gpio_lines;

// Function prototypes
int initialize_gpio(struct gpio_line *lines);
int read_sensor_data(struct gpio_line *lines, unsigned int *data);
int log_sensor_data(unsigned int data);
void cleanup_gpio(struct gpio_line *lines);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio(&gpio_lines);
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpio_line *lines) {
    int i;

    // Open the GPIO chip
    lines->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!lines->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request each GPIO line as input
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines->lines[i] = gpiod_chip_get_line(lines->chip, i);
        if (!lines->lines[i]) {
            perror("Error getting GPIO line");
            // Release previously requested lines before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines->lines[j]);
            }
            gpiod_chip_close(lines->chip);
            return -1;
        }

        // Configure the line as input with bias disabled
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
