#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state, previous_state;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Get initial state
    current_state = gpioRead(TILT_SENSOR_GPIO);
    if (current_state < 0) {
        fprintf(stderr, "Error reading initial GPIO state\n");
        gpioTerminate();
        return 1;
    }
    previous_state = current_state;

    // Print startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        current_state = gpioRead(TILT_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO state\n");
            break; // Exit loop on error
        }

        if (current_state != previous_state) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (current_state == 0) {
                printf("%s Tilted\n", timestamp);
            } else {
                printf("%s Not Tilted\n", timestamp);
            }
            fflush(stdout); // Flush stdout to ensure immediate output
            previous_state = current_state;
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

