#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_UVINDEX_LSB 0x2C
#define SI1145_REG_ALS_VIS_DATA0 0x22

// Command values
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *uv_index, float *als_visible);
void log_data(float uv_index, float als_visible);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float uv_index;
    float als_visible;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read PART ID.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Si1145 PART ID: 0x%02X\n", part_id);

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    // Configure CHLIST register
    if (i2cWriteByteData(i2c_handle, SI1145_REG_CHLIST, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to write CHLIST register.\n");
        return -1;
    }

    // Set measurement rate
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE0, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0 register.\n");
        return -1;
    }

    return 0;
}

// Function to read UV index and ALS data from the sensor
int read_sensor_data(float *uv_index, float *als_visible) {
    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete

    // Read UV index
    int uv_index_raw = i2cReadByteData(i2c_handle, SI1145_REG_UVINDEX_LSB);
    if (uv_index_raw < 0) {
        fprintf(stderr, "Error: Failed to read UV index.\n");
        return -1;
    }
    *uv_index = (float)uv_index_raw / 10.0;

    // Read ALS Visible data
    int als_visible_raw = i2cReadWordData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (als_visible_raw < 0) {
        fprintf(stderr, "Error: Failed to read ALS Visible data.\n");
        return -1;
    }
    *als_visible = (float)als_visible_raw;

    return 0;
}

// Function to log data to a CSV file
void log_data(float uv_index, float als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.uv_index, &sensor_data.als_visible) == 0) {
            // Log data
            log_data(sensor_data.uv_index, sensor_data.als_visible);

            // Print data to console
            printf("UV Index: %.2f, ALS Visible: %.2f\n", sensor_data.uv_index, sensor_data.als_visible);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

