#define I2C_BUS 1
#define I2C_ADDR_1 0x36
#define I2C_ADDR_2 0x37
#define CMD_REG 0x08
#define DATA_REG 0x00
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"
#define MEASUREMENT_DELAY_MS 100
#define ALARM_THRESHOLD 0.5

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd1 = -1, i2c_fd2 = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int read_flow_rate(int fd, float *flow_rate);
int validate_crc(uint8_t *data, int len);
float calculate_average_flow(float flow1, float flow2);
void log_flow_rate(float flow1, float flow2, float average_flow);
void control_alarm(float average_flow);
void signal_handler(int signal);
int initialize_i2c(int bus, int addr);
void cleanup();

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    uint8_t data[len + 1];
    data[0] = reg;
    memcpy(data + 1, buf, len);
    if (write(fd, data, len + 1) != len + 1) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read flow rate function
int read_flow_rate(int fd, float *flow_rate) {
    uint8_t buf[9];
    int16_t raw_flow;
    uint8_t crc;

    if (i2c_read_bytes(fd, DATA_REG, buf, 9) != 0) {
        fprintf(stderr, "Error reading flow rate from I2C device.\n");
        return -1;
    }

    raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    crc = buf[2];

    if (validate_crc(buf, 3) != 0) {
        fprintf(stderr, "CRC validation failed for flow rate.\n");
        return -1;
    }

    *flow_rate = (float)raw_flow * SCALE_FACTOR;
    return 0;
}

// CRC validation function
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Calculate average flow rate function
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Log flow rate function
void log_flow_rate(float flow1, float flow2, float average_flow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file);
}

// Control alarm function
void control_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize I2C function
int initialize_i2c(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    float flow1, flow2, average_flow;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_fd1 = initialize_i2c(I2C_BUS, I2C_ADDR_1);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize I2C device 1\n");
        cleanup();
        return 1;
    }

    i2c_fd2 = initialize_i2c(I2C_BUS, I2C_ADDR_2);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize I2C device 2\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Start measurement on both sensors
    uint8_t start_cmd[2] = {0x36, 0x08};
    if (i2c_write_bytes(i2c_fd1, CMD_REG, start_cmd, 2) != 0) {
        fprintf(stderr, "Failed to start measurement on sensor 1\n");
        cleanup();
        return 1;
    }
    if (i2c_write_bytes(i2c_fd2, CMD_REG, start_cmd, 2) != 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2\n");
        cleanup();
        return 1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    // Main loop
    while (program_running) {
        // Read flow rates
        ret = read_flow_rate(i2c_fd1, &flow1);
        if (ret != 0) {
            flow1 = -1.0; // Indicate error
        }
        ret = read_flow_rate(i2c_fd2, &flow2);
        if (ret != 0) {
            flow2 = -1.0; // Indicate error
        }

        // Calculate average flow rate
        average_flow = calculate_average_flow(flow1, flow2);

        // Log flow rate
        log_flow_rate(flow1, flow2, average_flow);

        // Control alarm
        control_alarm(average_flow);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

