#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define X_REG 0x2A
#define Y_REG 0x2C
#define Z_REG 0x2E
#define SCALE_FACTOR 0.0009765625f
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "fan_health.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_sensor(int fd);
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = RETRY_COUNT;
    int result;
    while (retries > 0) {
        if (i2c_smbus_read_i2c_block_data(fd, reg, len, data) == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X, len %d)\n", RETRY_COUNT, reg, len);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = RETRY_COUNT;
    int result;
    while (retries > 0) {
        if (i2c_smbus_write_byte_data(fd, reg, data) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%02X): %s\n", reg, data, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, data 0x%02X)\n", RETRY_COUNT, reg, data);
    return -1; // Failure
}

// Initialize the sensor
int init_sensor(int fd) {
    if (i2c_write_reg(fd, MODE_CONTROL_REG, 0x10) != 0) {
        fprintf(stderr, "Failed to set sensor mode.\n");
        return -1;
    }

    // Wait for the sensor to become active
    int timeout_ms = 1000;
    while (timeout_ms > 0) {
        uint8_t status;
        if (i2c_read_reg(fd, OPERATING_STATUS_REG, &status, 1) == 0) {
            if ((status & 0x01) != 0) {
                return 0; // Success
            }
        }
        gpioDelay(10000); // Delay 10ms
        timeout_ms -= 10;
    }

    fprintf(stderr, "Sensor failed to become active within 1 second.\n");
    return -1;
