#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as input
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN as input\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN as input\n");
        gpioTerminate();
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    *sensor1_value = gpioRead(SENSOR_1_PIN);
    *sensor2_value = gpioRead(SENSOR_2_PIN);
    return 0;
}

// Function to control the LED
void control_led(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 0 || sensor2_value == 0) {
        gpioWrite(LED_PIN, 1); // Turn LED ON
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED OFF
    }
}

int main() {
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor1_value, sensor2_value;

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) != 0) {
            fprintf(stderr, "Error reading sensors\n");
            break; // Exit loop on error
        }

        // Control the LED
        control_led(sensor1_value, sensor2_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up GPIO resources
    gpioWrite(LED_PIN, 0); // Turn LED OFF before exiting
    gpioTerminate();

    return 0;
}

