#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value with error handling
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to check for stall condition
int check_stall(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 0 && sensor2_value == 0) {
        return 1; // Stall confirmed
    }
    return 0; // No stall
}

// Function to log stall event
int log_stall_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    // Check if the log file is empty or if the last entry is not the current timestamp
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "%s: Stall detected\n", timestamp);
    } else {
        fseek(log_file, 0, SEEK_END);
        char last_line[100];
        fseek(log_file, -strlen(timestamp) - 1, SEEK_END);
        fread(last_line, 1, sizeof(last_line), log_file);
        fseek(log_file, 0, SEEK_END);
        if (strstr(last_line, timestamp) == NULL) {
            fprintf(log_file, "%s: Stall detected\n", timestamp);
        }
    }

    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int stall_start_time = 0;
    int stall_confirmed = 0;

    printf("Monitoring conveyor belt... Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, but continue running
            gpioDelay(100); // Small delay to prevent busy-waiting
            continue;
        }

        if (check_stall(sensor1_value, sensor2_value)) {
            if (!stall_confirmed) {
                stall_start_time = time(NULL);
                stall_confirmed = 1;
                printf("Stall detected!\n");
            } else {
                // Stall is still confirmed, check duration
                if (time(NULL) - stall_start_time >= STALL_DURATION_SEC) {
                    if (log_stall_event() == 0) {
                        printf("Stall event logged.\n");
                    } else {
                        fprintf(stderr, "Error logging stall event.\n");
                    }
                    stall_confirmed = 0; // Reset stall flag after logging
                }
            }
        } else {
            // No stall detected, reset stall flag
            stall_confirmed = 0;
        }

        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

