// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define X_AXIS_REG 0x01
#define Y_AXIS_REG 0x03
#define Z_AXIS_REG 0x05
#define CONFIG_REG 0x00
#define DEVICE_ID_REG 0x00
#define CSV_FILE "magnetic_log.csv"
#define LOG_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mT(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);
int check_device_id();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the sensor
int initialize_sensor() {
    // Configuration: Continuous mode, all axes enabled, 50 mT range
    // Refer to TMAG5170-Q1 datasheet for register settings
    // Example configuration (adjust as needed based on datasheet)
    uint8_t config_data[2] = {0x00, 0x00}; // Example: Enable all axes, 50 mT range

    // Write configuration to the sensor
    int result = i2cWriteDevice(i2c_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to mT
float convert_to_mT(int16_t raw_value) {
    // Scale factor for 50 mT range (adjust based on datasheet)
    float scale_factor = 0.01; // Example: 1 LSB = 0.01 mT

    return (float)raw_value * scale_factor;
}

// Function to log data to CSV file
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Function to check the device ID
int check_device_id() {
    uint8_t device_id;
    int result = i2cReadByteData(i2c_handle, DEVICE_ID_REG);

    if (result < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", result);
        return -1;
    }

    device_id = (uint8_t)result;

    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x8D)\n", device_id);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check device ID
    if (check_device_id() != 0) {
        fprintf(stderr, "Device ID check failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_mT, y_mT, z_mT;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to mT
            x_mT = convert_to_mT(raw_x);
            y_mT = convert_to_mT(raw_y);
            z_mT = convert_to_mT(raw_z);

            // Log data
            log_data(x_mT, y_mT, z_mT);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(LOG_INTERVAL_MS); // Delay for 100ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

