#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define ALERT_MESSAGE "ALERT: Water detected"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define POLL_INTERVAL 2 // seconds

// Global variables
static int running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int send_alert();
int log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("Error: pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to send an alert message to the server
int send_alert() {
    char message[256];
    snprintf(message, sizeof(message), "%s", ALERT_MESSAGE);

    if (send(socket_fd, message, strlen(message), 0) < 0) {
        log_message("Error: Failed to send alert message");
        return -1;
    }

    return 0;
}

// Function to log a message to the log file
int log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (socket_fd != -1) {
        close(socket_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting water level monitoring daemon");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("Error: GPIO initialization failed. Exiting.");
        fclose(log_file);
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message("Error: Could not create socket");
        cleanup();
        return 1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_address.sin_addr) <= 0) {
        log_message("Error: Invalid server IP address");
        cleanup();
        return 1;
    }

    // Connect to server
    if (connect(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        log_message("Error: Could not connect to server");
        cleanup();
        return 1;
    }

    log_message("Connected to server");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            log_message("Water detected!");
            send_alert();
        }

        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

