#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 1 // seconds
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable the timer and alert callback
    gpioSetTimerFuncEx(GPIO_PIN, 0, NULL, NULL); // Disable timer

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Callback function for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate RPM
float calculate_rpm(int pulse_count) {
    return (float)pulse_count * 60.0;
}

// Function to log RPM to file
int log_rpm(float rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s %.2f\n", timestamp, rpm);
    fflush(log_file); // Flush the buffer to ensure immediate write

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer function to count pulses
    if (gpioSetTimerFuncEx(GPIO_PIN, SAMPLE_INTERVAL * 1000, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        // Calculate RPM
        float rpm = calculate_rpm(pulse_count);

        // Log RPM
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Failed to log RPM\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        pulse_count = 0;

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

