// Define quadrature states
typedef enum {
    Q0,
    Q1,
    Q2,
    Q3
} quadrature_state_t;

// Global variables
quadrature_state_t current_state = Q0;
quadrature_state_t previous_state = Q0;
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
quadrature_state_t process_quadrature_state(quadrature_state_t current_state, int sensor_a_value, int sensor_b_value);
void log_rotation_event(const char *direction);
void *logging_thread(void *arg);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
