        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);

    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0;
}

// Process quadrature state based on sensor values
quadrature_state_t process_quadrature_state(quadrature_state_t current_state, int sensor_a_value, int sensor_b_value) {
    switch (current_state) {
        case Q0:
            return (sensor_a_value == 0 && sensor_b_value == 1) ? Q1 : Q0;
        case Q1:
            return (sensor_a_value == 1 && sensor_b_value == 1) ? Q2 : Q1;
        case Q2:
            return (sensor_a_value == 1 && sensor_b_value == 0) ? Q3 : Q2;
        case Q3:
            return (sensor_a_value == 0 && sensor_b_value == 0) ? Q0 : Q3;
        default:
            return Q0; // Should not happen
    }
}

// Log rotation event with timestamp
void log_rotation_event(const char *direction) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%03ld",
             ts.tv_sec / 100000000 % 1000000000, // Year (not used)
             (ts.tv_sec / 1000000) % 100,          // Month
