    (void)arg; // Suppress unused parameter warning
    while (program_running) {
        pthread_mutex_lock(&state_mutex);
        if (current_state == Q1 && previous_state != Q1) {
            log_rotation_event("CW");
        } else if (current_state == Q3 && previous_state != Q3) {
            log_rotation_event("CCW");
        }
        previous_state = current_state;
        pthread_mutex_unlock(&state_mutex);
        gpioDelay(100000); // Sleep for 100ms
    }
    return NULL;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&state_mutex);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("rotation_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        perror("Error creating logging thread");
        cleanup();
        return 1;
    }

    // Main loop
    int sensor_a_value, sensor_b_value;
    while (program_running) {
        sensor_a_value = gpioRead(SENSOR_A_PIN);
        sensor_b_value = gpioRead(SENSOR_B_PIN);

        if (sensor_a_value == PI_BAD_GPIO || sensor_b_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor values\n");
            cleanup();
            return 1;
        }

        current_state = process_quadrature_state(current_state, sensor_a_value, sensor_b_value);

        gpioDelay(10000); // Sleep for 10ms
    }

    // Wait for logging thread to finish
    pthread_join(logging_thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

