#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO lines
int initialize_gpio() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", GPIOCHIP);
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line %d", TOUCH_SENSOR_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line %d", LED_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    // Request touch sensor line for input
    ret = gpiod_line_request(touch_line, "touch_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line: %d", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request LED line for output
    ret = gpiod_line_request(led_line, "led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line: %d", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read touch sensor value: %d", value);
        return -1;
    }
    return value;
}

// Control LED state
int control_led(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set LED value: %d", ret);
        return -1;
    }
    return 0;
}

// Cleanup GPIO resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");

    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    closelog();
}

int main() {
    int ret;
    int touch_state;

    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Touch sensor and LED control started");

    // Main loop
    while (!terminate) {
        touch_state = read_touch_sensor();
        if (touch_state < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        if (control_led(touch_state) < 0) {
            syslog(LOG_ERR, "Failed to control LED, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        usleep(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    syslog(LOG_INFO, "Touch sensor and LED control stopped");
    return 0;
}

