#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_touch_sensor(void);
void toggle_led(void);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error: Could not get touch sensor line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error: Could not get LED line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    // Request touch sensor line for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(touch_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request touch sensor line for input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request LED line for output
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request LED line for output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    // Initialize LED to LOW
    gpiod_line_set_value(led_line, 0);

    return 0;
}

// Read touch sensor value with debounce
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read touch sensor value\n");
        return -1;
    }

    // Debounce
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = DEBOUNCE_TIME_MS * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&delay, NULL);

    return value;
}

// Toggle LED state
void toggle_led(void) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        fprintf(stderr, "Error: Could not read LED value\n");
        return;
    }

    int new_value = !current_value;
    if (gpiod_line_set_value(led_line, new_value) < 0) {
        fprintf(stderr, "Error: Could not set LED value\n");
    }
}

// Cleanup GPIO resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up GPIO resources...\n");

    // Release lines
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    fprintf(stderr, "GPIO resources released.\n");
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
