void toggle_led(void) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        fprintf(stderr, "Error: Could not read LED value\n");
        return;
    }

    int new_value = !current_value;
    if (gpiod_line_set_value(led_line, new_value) < 0) {
        fprintf(stderr, "Error: Could not set LED value\n");
    }
}

