void cleanup(void) {
    fprintf(stderr, "Cleaning up GPIO resources...\n");

    // Release lines
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    fprintf(stderr, "GPIO resources released.\n");
}

