#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to store log events
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int new_state;
} LogEvent;

// Circular buffer structure
typedef struct {
    LogEvent buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} CircularBuffer;

// Global variables
CircularBuffer log_buffer;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int new_state);
void print_log_buffer();
void signal_handler(int signal);
void cleanup();

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor state with debouncing
int read_sensor(int pin) {
    int state = gpioRead(pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay in microseconds
    return state;
}

// Control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Log event to circular buffer
void log_event(int sensor_pin, int new_state) {
    time_t now = time(NULL);
    LogEvent event = {sensor_pin, now, new_state};

    log_buffer.buffer[log_buffer.head] = event;
    log_buffer.head = (log_buffer.head + 1) % BUFFER_SIZE;

    if (log_buffer.count == BUFFER_SIZE) {
        log_buffer.tail = (log_buffer.tail + 1) % BUFFER_SIZE;
    } else {
        log_buffer.count++;
    }
}

// Print log buffer contents
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    int i = log_buffer.tail;
    for (int j = 0; j < log_buffer.count; j++) {
        LogEvent event = log_buffer.buffer[i];
        struct tm *timeinfo = localtime(&event.timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Sensor: %d, Timestamp: %s, State: %d\n", event.sensor_pin, timestamp_str, event.new_state);
        i = (i + 1) % BUFFER_SIZE;
    }
    printf("--- End of Log Buffer ---\n");
    printf("Overflow Count: %d\n", log_buffer.overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();
}

int main() {
    // Initialize circular buffer
    log_buffer.head = 0;
    log_buffer.tail = 0;
    log_buffer.count = 0;
    log_buffer.overflow_count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR_1_PIN);
        int sensor2_state = read_sensor(SENSOR_2_PIN);

        if (sensor1_state != gpioRead(SENSOR_1_PIN)) {
            control_led(LED_1_PIN, sensor1_state);
            log_event(SENSOR_1_PIN, sensor1_state);
        }

        if (sensor2_state != gpioRead(SENSOR_2_PIN)) {
            control_led(LED_2_PIN, sensor2_state);
            log_event(SENSOR_2_PIN, sensor2_state);
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Print log buffer and cleanup
    print_log_buffer();
    cleanup();

    return 0;
}

