#include <string.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE_PATH "/var/log/rain_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an input with a pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_PATH);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to monitor the rain sensor
    while (running) {
        current_state = gpioRead(RAIN_SENSOR_GPIO);

        if (current_state != previous_state) {
            if (current_state == 0) {
                log_event("Rain Detected");
                printf("Rain Detected\n");
            } else {
                log_event("No Rain");
                printf("No Rain\n");
            }
            previous_state = current_state;
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup: Close the log file and terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");
    return 0;
}

