#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int signal);
void log_sensor_state(SensorStates states);
double calculate_rpm();
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to clean up GPIO resources and terminate the pigpio library
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to log sensor states to a CSV file
void log_sensor_state(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Function to calculate RPM based on pulse frequency
double calculate_rpm() {
    // This is a placeholder.  In a real application, you would
    // need to measure the time between pulses and calculate RPM
    // from that.  This example assumes a constant frequency.
    // For example, if you know the sensor is triggered every 0.5 seconds,
    // then RPM = 60 / 0.5 = 120 RPM.
    // This example returns a fixed value for demonstration purposes.
    return 120.0; // Example RPM
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME) {
        SensorStates states;
        states.sensor1_state = level;
        states.sensor2_state = gpioRead(SENSOR2_GPIO);
        log_sensor_state(states);
        printf("RPM: %.2f\n", calculate_rpm());
        last_tick = current_tick;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME) {
        SensorStates states;
        states.sensor1_state = gpioRead(SENSOR1_GPIO);
        states.sensor2_state = level;
        log_sensor_state(states);
        printf("RPM: %.2f\n", calculate_rpm());
        last_tick = current_tick;
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
