#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *heart_rate, int *spo2);
void log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t led_drive_strength;
    uint8_t adc_gain;
    uint8_t measurement_mode;
} sensor_config_t;

// Function to initialize the sensor
int initialize_sensor() {
    // Example configuration (adjust as needed)
    sensor_config_t config = {
        .led_drive_strength = 0x03, // Example value
        .adc_gain = 0x02,          // Example value
        .measurement_mode = 0x01    // Example value
    };

    // Write configuration to the sensor
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, config.led_drive_strength << 4 | config.adc_gain) < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", i2c_handle);
        return -1;
    }

    // Verify PART_ID register
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", i2c_handle);
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read heart rate and SpO2 data from the sensor
int read_sensor_data(int *heart_rate, int *spo2) {
    // Read heart rate data
    int hr = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (hr < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", i2c_handle);
        return -1;
    }

    // Read SpO2 data
    int spo = i2cReadByteData(i2c_handle, SPO2_REG);
    if (spo < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", i2c_handle);
        return -1;
    }

    *heart_rate = hr;
    *spo2 = spo;

    return 0;
}

// Function to log data to a file
void log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int heart_rate, spo2;
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        sleep(1); // Read data every 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

