#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Define tilt threshold duration (in seconds)
#define TILT_THRESHOLD_DURATION 2

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t last_tilt_start;
} SensorStates;

SensorStates sensor_states = {0, 0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for tilt start conditions
        if (sensor1_value == 1 && sensor_states.sensor1_state == 0) {
            sensor_states.last_tilt_start = time(NULL);
            log_event("Tilt start - Sensor 1");
        } else if (sensor2_value == 1 && sensor_states.sensor2_state == 0) {
            sensor_states.last_tilt_start = time(NULL);
            log_event("Tilt start - Sensor 2");
        }

        // Check for tilt threshold exceeded
        if (sensor1_value == 1 && sensor_states.sensor1_state == 0 && (time(NULL) - sensor_states.last_tilt_start) >= TILT_THRESHOLD_DURATION) {
            activate_alarm();
            log_event("Threshold exceeded - Sensor 1");
        } else if (sensor2_value == 1 && sensor_states.sensor2_state == 0 && (time(NULL) - sensor_states.last_tilt_start) >= TILT_THRESHOLD_DURATION) {
            activate_alarm();
            log_event("Threshold exceeded - Sensor 2");
        }

        // Check for tilt end conditions
        if (sensor1_value == 0 && sensor_states.sensor1_state == 1) {
            log_event("Tilt end - Sensor 1");
        } else if (sensor2_value == 0 && sensor_states.sensor2_state == 1) {
            log_event("Tilt end - Sensor 2");
        }

        // Update sensor states
        sensor_states.sensor1_state = sensor1_value;
        sensor_states.sensor2_state = sensor2_value;

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Function to read the value from a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return 0; // Return 0 on error to avoid unexpected behavior
    }
    return value;
}

// Function to activate the alarm (buzzer/LED)
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
    log_event("Alarm activated");
}

// Function to deactivate the alarm (buzzer/LED)
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
    log_event("Alarm deactivated");
}

// Function to log events to the log file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Log file is not open. Event: %s\n", event_type);
    }
}

// Signal handler function
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    log_event("Cleaning up...");
    deactivate_alarm(); // Ensure alarm is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    log_event("Program terminated");
}

