#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D
#define ACCEL_SCALE 0.001 // 1 mg/LSB
#define THRESHOLD 500.0
#define LED_GPIO 17
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Omron D7S-A0011 sensor
int init_sensor() {
    int retries = 0;
    int status;

    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00); // Clear power-down bit
        if (status >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL1 register (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 0;
    int status;

    while (retries < RETRY_COUNT) {
        status = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB, buffer, 6);
        if (status == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate the Euclidean vibration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = x * ACCEL_SCALE;
    double y_g = y * ACCEL_SCALE;
    double z_g = z * ACCEL_SCALE;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log an event to the log file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int16_t x, y, z;
    double magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                printf("Threshold exceeded: %.2f\n", magnitude);
                gpioWrite(LED_GPIO, 1); // Turn on LED
                gpioDelay(1000000);      // Wait 1 second
                gpioWrite(LED_GPIO, 0); // Turn off LED
                log_event(magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

