#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line, *sensor4_line, *led_line;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int control_led(struct gpiod_line *line, int state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (sensor3_line) gpiod_line_release(sensor3_line);
    if (sensor4_line) gpiod_line_release(sensor4_line);
    if (led_line) gpiod_line_release(led_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Function to read sensor data
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active-low: 0 = object detected
}

// Function to control the LED
int control_led(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED state: %d\n", ret);
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Get GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR_3_PIN);
    sensor4_line = gpiod_chip_get_line(chip, SENSOR_4_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line || !sensor4_line || !led_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        goto cleanup;
    }

    // Request GPIO lines for input and output
    if (gpiod_line_request(sensor1_line, "sensor1", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting sensor1 line for input\n");
        goto cleanup;
    }
    if (gpiod_line_request(sensor2_line, "sensor2", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting sensor2 line for input\n");
        goto cleanup;
    }
    if (gpiod_line_request(sensor3_line, "sensor3", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting sensor3 line for input\n");
        goto cleanup;
    }
    if (gpiod_line_request(sensor4_line, "sensor4", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting sensor4 line for input\n");
        goto cleanup;
    }
    if (gpiod_line_request(led_line, "led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error requesting led line for output\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);
        int sensor3_value = read_sensor(sensor3_line);
        int sensor4_value = read_sensor(sensor4_line);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0 || sensor4_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            goto cleanup;
        }

        int any_object_detected = (sensor1_value || sensor2_value || sensor3_value || sensor4_value);

        if (control_led(led_line, any_object_detected) < 0) {
            fprintf(stderr, "Error controlling LED, exiting...\n");
            goto cleanup;
        }

        usleep(50000); // 50 ms
    }

cleanup:
    // Release GPIO lines
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (sensor3_line) gpiod_line_release(sensor3_line);
    if (sensor4_line) gpiod_line_release(sensor4_line);
    if (led_line) gpiod_line_release(led_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return 1;
}

