#define SENSOR2_ID 2
#define SENSOR3_ID 3
#define SENSOR4_ID 4
#define SENSOR5_ID 5

#define SENSOR1_PIN 2
#define SENSOR2_PIN 3
#define SENSOR3_PIN 4
#define SENSOR4_PIN 17
#define SENSOR5_PIN 27

#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[5] = {NULL, NULL, NULL, NULL, NULL};

// Function prototypes
int initialize_gpio();
int read_sensor(int sensor_id, int pin);
int log_event(int sensor_id, int pin);
void cleanup_gpio();
void signal_handler(int sig);

// Structure to hold sensor data
typedef struct {
    int id;
    int pin;
    struct gpiod_line *line;
} sensor_t;

