sensor_t sensors[] = {
    {SENSOR1_ID, SENSOR1_PIN, NULL},
    {SENSOR2_ID, SENSOR2_PIN, NULL},
    {SENSOR3_ID, SENSOR3_PIN, NULL},
    {SENSOR4_ID, SENSOR4_PIN, NULL},
    {SENSOR5_ID, SENSOR5_PIN, NULL}
};

int main() {
    openlog("flame_monitor", LOG_PID, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Flame monitor started.");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int sensor_value = read_sensor(sensors[i].id, sensors[i].pin);
            if (sensor_value == 0) { // Flame detected (LOW signal)
                log_event(sensors[i].id, sensors[i].pin);
            }
        }
        sleep(1);
    }

    // Cleanup GPIO
    cleanup_gpio();

    syslog(LOG_INFO, "Flame monitor stopped.");
    closelog();

    return 0;
}

