#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 8

// Structure to hold GPIO line objects
struct gpio_line {
    struct gpiod_line *line;
    int index;
};

// Global variables
struct gpio_line lines[GPIO_LINES];
struct gpiod_chip *chip = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor_state(void);
void log_state_change(int index, int value);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Initializes the GPIO chip and lines
int initialize_gpio(void) {
    int i;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get the line numbers for each channel
    int line_numbers[GPIO_LINES] = {5, 6, 13, 19, 26, 12, 16, 20};

    // Request each line
    for (i = 0; i < GPIO_LINES; i++) {
        lines[i].index = i;
        lines[i].line = gpiod_chip_get_line(chip, line_numbers[i]);
        if (!lines[i].line) {
            fprintf(stderr, "Error getting line %d: %s\n", line_numbers[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j].line);
            }
            gpiod_chip_close(chip);
            return -1;
        }

        // Request the line as input
        ret = gpiod_line_request(lines[i].line, "touch_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", line_numbers[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j].line);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Reads the current state of the sensor
int read_sensor_state(void) {
    int i;
    int value;
    int current_state = 0;

    for (i = 0; i < GPIO_LINES; i++) {
        value = gpiod_line_get_value(lines[i].line);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", lines[i].index, strerror(errno));
            return -1; // Indicate an error
        }
        current_state |= (value << i);
    }

    return current_state;
}

// Logs a state change to the console
void log_state_change(int index, int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor %d (BCM %d): %s\n", timestamp, index, lines[index].index, value ? "Touched" : "Released");
}

// Releases the GPIO lines and closes the chip
void cleanup_gpio(void) {
    int i;

    // Release each line
    for (i = 0; i < GPIO_LINES; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int current_state, previous_state;
    int i;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Read initial state
    previous_state = read_sensor_state();
    if (previous_state < 0) {
        fprintf(stderr, "Failed to read initial sensor state. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        current_state = read_sensor_state();
        if (current_state < 0) {
            fprintf(stderr, "Failed to read sensor state. Continuing.\n");
            // Attempt to recover, but continue the loop
            continue;
        }

        // Check for state changes
        for (i = 0; i < GPIO_LINES; i++) {
            if ((current_state >> i) & 1) {
                if (!((previous_state >> i) & 1)) {
                    log_state_change(i, 1);
                }
            } else {
                if (((previous_state >> i) & 1)) {
                    log_state_change(i, 0);
                }
            }
        }

        previous_state = current_state;
        usleep(50000); // 50ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

