#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_veml7700();
int read_als_data(uint16_t *raw_data);
float convert_to_lux(uint16_t raw_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int veml7700_address;
    int led_gpio;
    int pwm_frequency;
    float lux_threshold_1;
    float lux_threshold_2;
    float lux_threshold_3;
} config_t;

config_t config = {
    I2C_BUS,
    VEML7700_ADDR,
    LED_GPIO,
    PWM_FREQUENCY,
    LUX_THRESHOLD_1,
    LUX_THRESHOLD_2,
    LUX_THRESHOLD_3
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (config_veml7700() != 0) {
        fprintf(stderr, "Failed to configure VEML7700. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(config.led_gpio, config.pwm_frequency);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    uint16_t raw_data;
    float lux;
    int brightness;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&raw_data) != 0) {
            error_code = 1; // Sensor error
            fprintf(stderr, "Error reading ALS data.\n");
        } else {
            // Convert to lux
            lux = convert_to_lux(raw_data);

            // Set LED brightness
            brightness = set_led_brightness(lux);

            // Log data
            if (log_data(lux, brightness, error_code) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            error_code = 0; // Reset error code after successful logging
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.veml7700_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure VEML7700
int config_veml7700() {
    // ALS Gain: 1/8 (0x00)
    // ALS Integration Time: 100ms (0x00)
    uint16_t config_value = 0x0000; // Default values

    // Write the configuration to the sensor
    int result = i2cWriteWordData(i2c_handle, ALS_CONFIG_REG, config_value);
    if (result != 0) {
        fprintf(stderr, "Failed to write config data: %d\n", result);
        return 1;
    }
    return 0;
}

// Read ALS data
int read_als_data(uint16_t *raw_data) {
    int result = i2cReadWordData(i2c_handle, ALS_DATA_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return 1;
    }
    *raw_data = (uint16_t)result;
    return 0;
}

// Convert raw data to lux
float convert_to_lux(uint16_t raw_data) {
    return (float)raw_data * 0.0576;
}

// Set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness;

    if (lux < config.lux_threshold_1) {
        brightness = 100;
    } else if (lux < config.lux_threshold_2) {
        brightness = 75;
    } else if (lux < config.lux_threshold_3) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(config.led_gpio, brightness);
    return brightness;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Turn off LED
    gpioPWM(config.led_gpio, 0);

    // Close I2C
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

