#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors
#define TOUCH_PIN_1 2
#define TOUCH_PIN_2 3
#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9

// Define GPIO pin for LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int gpio_pin);
int log_touch_event(int gpio_pin);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold the last touch state for each channel
struct {
    int last_state;
    unsigned long last_change_time;
} touch_states[8];

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pins as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(TOUCH_PIN_1 + i, PI_INPUT);
        gpioSetPullUpDown(TOUCH_PIN_1 + i, PI_PUD_DOWN);
        touch_states[i].last_state = 0; // Initialize last state to 0 (untouched)
        touch_states[i].last_change_time = 0; // Initialize last change time
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    control_led(0); // Turn LED off initially

    return 0;
}

// Function to read the state of a touch sensor
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log a touch event to a file
int log_touch_event(int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, gpio_pin - TOUCH_PIN_1 + 1);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    control_led(0); // Turn off LED
    gpioTerminate(); // Release pigpio resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Security Keypad Simulation running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        for (int i = 0; i < 8; i++) {
            int current_state = read_touch_sensor(TOUCH_PIN_1 + i);

            // Debouncing logic
            unsigned long now = gpioTick();
            if (current_state != touch_states[i].last_state) {
                if (now - touch_states[i].last_change_time > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
                    touch_states[i].last_state = current_state;
                    touch_states[i].last_change_time = now;

                    if (current_state == 1) {
                        log_touch_event(TOUCH_PIN_1 + i);
                        control_led(1); // Turn on LED
                    }
                }
            }
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

