#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810 // Continuous conversion, auto range, 100ms
#define LUX_SCALE 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_opt3001();
int read_opt3001(float *lux);
int log_data(float lux);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int opt3001_address;
    char *log_file_name;
} config_t;

// Function to initialize the OPT3001 sensor
int init_opt3001() {
    int result;
    uint16_t config_word = CONFIG_WORD;

    // Byte swap the configuration word
    uint16_t swapped_config_word = (config_word >> 8) | (config_word << 8);

    result = i2cWriteWordData(i2c_handle, CONFIG_REG, swapped_config_word);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }

    // Wait for at least 100ms for the first conversion
    gpioDelay(100000); // 100ms

    return 0;
}

// Function to read the light data from the OPT3001 sensor
int read_opt3001(float *lux) {
    int result;
    uint16_t raw_result;
    uint16_t exponent, mantissa;

    result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading result register: %d\n", result);
        return -1;
    }

    raw_result = (uint16_t)result;

    // Byte swap the result
    exponent = (raw_result >> 8) & 0x00FF;
    mantissa = raw_result & 0x00FF;

    *lux = (float)mantissa * LUX_SCALE * (1 << exponent);

    return 0;
}

// Function to log the light data to a file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float lux;
    config_t config = {1, OPT3001_ADDR, LOG_FILE};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(config.i2c_bus, config.opt3001_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3001 sensor
    if (init_opt3001() != 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_opt3001(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

