#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define ALERT_LED_PIN 17

// Define log file name
#define LOG_FILE "fire_events.log"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void log_event(int flame_detected);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int alert_led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);
    gpioWrite(ALERT_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Function to log an event to the log file
