#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log touch events
int log_touch_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    int last_state = -1; // Initialize to an invalid state
    int current_state;

    // Main loop
    while (!terminate) {
        current_state = read_touch_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                if (log_touch_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error logging touch detected event.\n");
                    break;
                }
            } else {
                if (log_touch_event("Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch released event.\n");
                    break;
                }
            }
            last_state = current_state;
            struct timespec delay = {0, DEBOUNCE_MS * 1000000L}; // 50ms
            nanosleep(&delay, NULL);
        }
        struct timespec short_delay = {0, 1000000L}; // 1ms
        nanosleep(&short_delay, NULL);
    }

    // Cleanup
    fclose(log_file);
    cleanup_gpio();

    return EXIT_SUCCESS;
}

