#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define MEASURE_CMD 0x3608
#define FLOW_RATE_SCALE 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(uint16_t command);
int read_sensor_data(int16_t *raw_flow, uint8_t *flags);
float convert_to_ml_min(int16_t raw_flow);
char *get_status(float flow_rate, uint8_t flags);
int log_data(float flow_rate, uint8_t flags, char *status);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *raw_flow, uint8_t *flags) {
    char buf[3];
    int result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flags = buf[2];

    // CRC validation
    uint8_t crc_data[2] = {buf[0], buf[1]};
    uint8_t calculated_crc = crc8(crc_data, 2);
    if (calculated_crc != *flags) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, *flags);
        return -1;
    }

    return 0;
}

// Convert raw flow value to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE;
}

// Get status string
char *get_status(float flow_rate, uint8_t flags) {
    if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
        return "INVALID";
    } else if (flags != 0) {
        return "ERROR";
    } else {
        return "OK";
    }
}

// Log data to file
int log_data(float flow_rate, uint8_t flags, char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_flow;
    uint8_t flags;
    float flow_rate;
    char *status;

    while (!terminate) {
        // Send measurement command
        if (send_command(MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, attempting to re-initialize I2C\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Wait for at least 2 ms
        gpioDelay(2000);

        // Read sensor data
        if (read_sensor_data(&raw_flow, &flags) != 0) {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize I2C\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert to ml/min
        flow_rate = convert_to_ml_min(raw_flow);

        // Get status
        status = get_status(flow_rate, flags);

        // Log data
        log_data(flow_rate, flags, status);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

