    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_flow;
    uint8_t flags;
    float flow_rate;
    char *status;

    while (!terminate) {
        // Send measurement command
        if (send_command(MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, attempting to re-initialize I2C\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Wait for at least 2 ms
        gpioDelay(2000);

        // Read sensor data
        if (read_sensor_data(&raw_flow, &flags) != 0) {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize I2C\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert to ml/min
        flow_rate = convert_to_ml_min(raw_flow);

        // Get status
        status = get_status(flow_rate, flags);

        // Log data
        log_data(flow_rate, flags, status);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

