#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    int samples[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_sensor();
int read_heart_rate(int *raw_value);
float convert_to_bpm(int raw_value);
float apply_moving_average(float new_value, MovingAverageFilter *filter);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Moving average filter initialization
void moving_average_init(MovingAverageFilter *filter) {
    filter->index = 0;
    filter->count = 0;
    memset(filter->samples, 0, sizeof(filter->samples));
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Initialize moving average filter
    MovingAverageFilter bpm_filter;
    moving_average_init(&bpm_filter);

    // Main loop
    while (!terminate) {
        int raw_value;
        float bpm;

        // Read heart rate
        if (read_heart_rate(&raw_value) == 0) {
            // Convert to BPM
            bpm = convert_to_bpm(raw_value);

            // Apply moving average
            float filtered_bpm = apply_moving_average(bpm, &bpm_filter);

            // Validate BPM
            if (validate_bpm(filtered_bpm)) {
                // Log data
                if (log_data(filtered_bpm) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the Si1182 sensor
int initialize_sensor() {
    // Check if the sensor is present by reading the PART_ID register
    int part_id = i2cReadByteData(i2c_handle, 0x00);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Check HW_REV register
    int hw_rev = i2cReadByteData(i2c_handle, 0x01);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing to LED_CURRENT_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing to AVERAGING_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE_REG\n");
        return -1;
    }

    return 0;
}

// Read the heart rate from the sensor
int read_heart_rate(int *raw_value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (result >= 0) {
            *raw_value = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    return -1; // Failure after retries
}

// Convert raw heart rate value to BPM
float convert_to_bpm(int raw_value) {
    return (float)raw_value * 0.5;
}

// Apply a 5-sample moving average filter
float apply_moving_average(float new_value, MovingAverageFilter *filter) {
    filter->samples[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;

    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->samples[i];
    }

    return sum / filter->count;
}

// Validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log data to file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

