        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing to AVERAGING_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE_REG\n");
        return -1;
    }

    return 0;
}

// Read the heart rate from the sensor
int read_heart_rate(int *raw_value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (result >= 0) {
            *raw_value = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    return -1; // Failure after retries
}

// Convert raw heart rate value to BPM
float convert_to_bpm(int raw_value) {
    return (float)raw_value * 0.5;
}

// Apply a 5-sample moving average filter
float apply_moving_average(float new_value, MovingAverageFilter *filter) {
    filter->samples[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;

    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->samples[i];
    }

    return sum / filter->count;
}

// Validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log data to file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

