#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for sensor inputs and outputs
#define SENSOR_BASE 5
#define OUTPUT_BASE 17

// Define the number of channels
#define NUM_CHANNELS 8

// Define the stabilization delay in milliseconds
#define STABILIZATION_DELAY_MS 200

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[NUM_CHANNELS];
static struct gpiod_line *output_lines[NUM_CHANNELS];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor_lines(void);
void update_output_lines(int channel, int state);
void log_touch_event(int channel, int counter);
void print_touch_message(int channel, int counter);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int i;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_BASE + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", i, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(sensor_lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }

        // Configure sensor lines as input with pull-down resistor
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
        config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;

        ret = gpiod_line_request(sensor_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting sensor line %d: %s\n", i, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(sensor_lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Request output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, OUTPUT_BASE + i);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", i, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(sensor_lines[j]);
                gpiod_line_release(output_lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }

        // Configure output lines as output with initial value 0
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0; // No flags needed for output

        ret = gpiod_line_request(output_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting output line %d: %s\n", i, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(sensor_lines[j]);
                gpiod_line_release(output_lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Stabilization delay
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = STABILIZATION_DELAY_MS * 1000000; // 200 ms
    nanosleep(&delay, NULL);

    return 0;
}

// Read sensor lines and detect rising edges
int read_sensor_lines(void) {
    int i;
    int new_state;
    int previous_states[NUM_CHANNELS];
    int rising_edge_channels[NUM_CHANNELS];
    int num_rising_edges = 0;

    // Read initial states
    for (i = 0; i < NUM_CHANNELS; i++) {
        new_state = gpiod_line_get_value(sensor_lines[i]);
        if (new_state < 0) {
            fprintf(stderr, "Error reading sensor line %d: %s\n", i, strerror(errno));
            return -1; // Indicate an error
        }
        previous_states[i] = new_state;
    }

    // Poll sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        new_state = gpiod_line_get_value(sensor_lines[i]);
        if (new_state < 0) {
            fprintf(stderr, "Error reading sensor line %d: %s\n", i, strerror(errno));
            return -1; // Indicate an error
        }

        if (new_state > previous_states[i]) {
            rising_edge_channels[num_rising_edges++] = i;
            previous_states[i] = new_state;
        }
    }

    return num_rising_edges;
}

// Update output lines based on the counter value
void update_output_lines(int channel, int state) {
    int i;
    int bit_index = channel;

    // Set the appropriate bit in the output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (i == channel) {
            gpiod_line_set_value(output_lines[i], state);
        } else {
            gpiod_line_set_value(output_lines[i], 0); // Ensure other bits are 0
        }
    }
}

// Log touch event to file
void log_touch_event(int channel, int counter) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    // Write the log entry
    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);

    // Close the log file
    fclose(fp);
}

// Print touch message to stdout
void print_touch_message(int channel, int counter) {
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int i;

    // Release output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
        }
    }

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i;
    int counter = 0;
    int num_rising_edges;
    int channel;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch counter started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor lines
        num_rising_edges = read_sensor_lines();
        if (num_rising_edges < 0) {
            // Error occurred during sensor read, continue to the next iteration
            nanosleep(&(struct timespec){0, 10000000}, NULL); // Sleep for 10ms to avoid busy-waiting
            continue;
        }

        // Update output lines and log events
        for (i = 0; i < num_rising_edges; i++) {
            channel = rising_edge_channels[i];
            update_output_lines(channel, 1); // Set the bit to 1
            counter = (counter + 1) % 256;   // Increment counter (0-255)
            update_output_lines(channel, 0); // Set the bit to 0
            log_touch_event(channel, counter);
            print_touch_message(channel, counter);
        }

        // Sleep for 10 ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10000000; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    printf("Touch counter stopped.\n");

    return 0;
}

