        }
    }
}

// Log touch event to file
void log_touch_event(int channel, int counter) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    // Write the log entry
    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);

    // Close the log file
    fclose(fp);
}

// Print touch message to stdout
void print_touch_message(int channel, int counter) {
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int i;

    // Release output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
        }
    }

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i;
    int counter = 0;
    int num_rising_edges;
    int channel;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch counter started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor lines
        num_rising_edges = read_sensor_lines();
        if (num_rising_edges < 0) {
            // Error occurred during sensor read, continue to the next iteration
            nanosleep(&(struct timespec){0, 10000000}, NULL); // Sleep for 10ms to avoid busy-waiting
            continue;
        }

        // Update output lines and log events
        for (i = 0; i < num_rising_edges; i++) {
            channel = rising_edge_channels[i];
            update_output_lines(channel, 1); // Set the bit to 1
            counter = (counter + 1) % 256;   // Increment counter (0-255)
            update_output_lines(channel, 0); // Set the bit to 0
            log_touch_event(channel, counter);
            print_touch_message(channel, counter);
        }

        // Sleep for 10 ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10000000; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    printf("Touch counter stopped.\n");

    return 0;
}

