                fprintf(stderr, "Error writing to CSV file.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensors.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

