#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Define log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int gpio);
int log_event(int gpio);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up and exiting...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip 'gpiochip0'.\n");
        return -1;
    }

    // Get GPIO line for sensor 1
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d.\n", SENSOR1_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for sensor 2
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d.\n", SENSOR2_GPIO);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        return -1;
    }

    // Request GPIO line for sensor 1
    ret = gpiod_line_request(sensor1_line, "tilt_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for input: %d\n", SENSOR1_GPIO, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    // Request GPIO line for sensor 2
    ret = gpiod_line_request(sensor2_line, "tilt_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for input: %d\n", SENSOR2_GPIO, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    // Set bias to pull-up
    ret = gpiod_line_set_bias(sensor1_line, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set bias for GPIO line %d: %d\n", SENSOR1_GPIO, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    ret = gpiod_line_set_bias(sensor2_line, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set bias for GPIO line %d: %d\n", SENSOR2_GPIO, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int gpio) {
    int value;
    int ret;

    struct gpiod_line *line = (gpio == SENSOR1_GPIO) ? sensor1_line : sensor2_line;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not read GPIO line %d: %d\n", gpio, ret);
        return -1;
    }

    value = ret;
    return value;
}

// Log event to file
int log_event(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, (gpio == SENSOR1_GPIO) ? 1 : 2);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int sensor1_value, sensor2_value;
    struct timespec debounce_timer;
    struct timespec start_time, current_time;
    long elapsed_time;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    printf("Monitoring tilt sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1_value = read_sensor(SENSOR1_GPIO);
        sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor values.\n");
            break; // Exit loop on read error
        }

        // Debounce sensor 1
        if (sensor1_value == 0) { // Sensor tilted (active low)
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (1) {
                sensor1_value = read_sensor(SENSOR1_GPIO);
                if (sensor1_value < 0) {
                    fprintf(stderr, "Error: Failed to read sensor values during debounce.\n");
                    break; // Exit debounce loop on read error
                }
                if (sensor1_value != 0) break; // Sensor returned to inactive state
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000;
                if (elapsed_time > DEBOUNCE_TIME_MS * 1000) break; // Debounce timeout
            }
            if (sensor1_value == 0) { // Ensure still tilted after debounce
                log_event(SENSOR1_GPIO);
            }
        }

        // Debounce sensor 2
        if (sensor2_value == 0) { // Sensor tilted (active low)
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (1) {
                sensor2_value = read_sensor(SENSOR2_GPIO);
                if (sensor2_value < 0) {
                    fprintf(stderr, "Error: Failed to read sensor values during debounce.\n");
                    break; // Exit debounce loop on read error
                }
                if (sensor2_value != 0) break; // Sensor returned to inactive state
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000;
                if (elapsed_time > DEBOUNCE_TIME_MS * 1000) break; // Debounce timeout
            }
            if (sensor2_value == 0) { // Ensure still tilted after debounce
                log_event(SENSOR2_GPIO);
            }
        }

        // Wait 100ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

