    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1_value = read_sensor(SENSOR1_GPIO);
        sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor values.\n");
            break; // Exit loop on read error
        }

        // Debounce sensor 1
        if (sensor1_value == 0) { // Sensor tilted (active low)
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (1) {
                sensor1_value = read_sensor(SENSOR1_GPIO);
                if (sensor1_value < 0) {
                    fprintf(stderr, "Error: Failed to read sensor values during debounce.\n");
                    break; // Exit debounce loop on read error
                }
                if (sensor1_value != 0) break; // Sensor returned to inactive state
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000;
                if (elapsed_time > DEBOUNCE_TIME_MS * 1000) break; // Debounce timeout
            }
            if (sensor1_value == 0) { // Ensure still tilted after debounce
                log_event(SENSOR1_GPIO);
            }
        }

        // Debounce sensor 2
        if (sensor2_value == 0) { // Sensor tilted (active low)
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (1) {
                sensor2_value = read_sensor(SENSOR2_GPIO);
                if (sensor2_value < 0) {
                    fprintf(stderr, "Error: Failed to read sensor values during debounce.\n");
                    break; // Exit debounce loop on read error
                }
                if (sensor2_value != 0) break; // Sensor returned to inactive state
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000;
                if (elapsed_time > DEBOUNCE_TIME_MS * 1000) break; // Debounce timeout
            }
            if (sensor2_value == 0) { // Ensure still tilted after debounce
                log_event(SENSOR2_GPIO);
            }
        }

        // Wait 100ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

