#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate and delay
#define SAMPLING_RATE 8000 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLING_RATE) // microseconds

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to sample the microphone input
int sample_microphone()
{
    return gpioRead(MIC_PIN);
}

// Function to trigger the LED
void trigger_led()
{
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100000);     // Wait for 100 ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Sample the microphone
        int mic_value = sample_microphone();

        // Check for peak detection
        if (mic_value == 1)
        {
            // Get current timestamp
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1)
            {
                fprintf(stderr, "Error getting timestamp\n");
                continue; // Continue to the next iteration
            }

            // Print timestamp
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Trigger the LED
            trigger_led();
        }

        // Delay to achieve desired sampling rate
        gpioDelay(SAMPLE_PERIOD);
    }

    // Clean up and terminate
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio

    return 0;
}

