#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x49
#define ALS_VIS_DATA0 0x24
#define ALS_VIS_DATA1 0x25
#define I2C_DEV_PATH "/dev/i2c-1" // Adjust if needed

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *device);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_als_visible(int fd);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Read ALS visible data function
int read_als_visible(int fd) {
    int lsb = i2c_read_reg(fd, ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from ALS Visible data registers\n");
        return -1;
    }

    int msb = i2c_read_reg(fd, ALS_VIS_DATA1);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from ALS Visible data registers\n");
        return -1;
    }

    return (msb << 8) | lsb;
}

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEV_PATH);
    if (i2c_fd < 0) {
        return 1;
    }

    printf("Si1175 Heart Rate Sensor Reader\n");

    // Main loop
    while (!terminate) {
        int als_visible = read_als_visible(i2c_fd);
        if (als_visible >= 0) {
            printf("ALS Visible: %d\n", als_visible);
        } else {
            fprintf(stderr, "Failed to read ALS Visible data\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

