#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the 8 channels
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13
#define GPIO_19 19
#define GPIO_26 26
#define GPIO_12 12
#define GPIO_16 16
#define GPIO_20 20

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL};

// Function prototypes
int read_sensor_channel(int gpio_pin);
void log_sensor_data(int channel_states[8]);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up...\n", signum);

        // Release all GPIO lines
        for (int i = 0; i < 8; i++) {
            if (lines[i] != NULL) {
                gpiod_line_release(lines[i]);
            }
        }

        // Close the GPIO chip
        if (chip != NULL) {
            gpiod_chip_close(chip);
        }

        printf("Cleanup complete. Exiting.\n");
        exit(0);
    }
}

// Function to read the state of a single sensor channel
int read_sensor_channel(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }

    // Request the line as an input
    if (gpiod_line_request_input(line, "sensor") < 0) {
        fprintf(stderr, "Error: Could not request line %d as input\n", gpio_pin);
        gpiod_line_release(line);
        return -1; // Indicate an error
    }

    // Read the line value
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read value from line %d\n", gpio_pin);
        gpiod_line_release(line);
        return -1; // Indicate an error
    }

    // Release the line
    gpiod_line_release(line);

    return value;
}

// Function to log the sensor data to the console
void log_sensor_data(int channel_states[8]) {
    struct timespec ts;
    char timestamp[30];
    char log_message[256];
    int i;

    // Get the current timestamp
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    // Construct the log message
    snprintf(log_message, sizeof(log_message), "[%s] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
             timestamp, channel_states[0], channel_states[1], channel_states[2], channel_states[3],
             channel_states[4], channel_states[5], channel_states[6], channel_states[7]);

    // Print the log message to the console
    printf("%s", log_message);
}

int main() {
    int i;
    int channel_states[8];

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Request all 8 lines as inputs
    for (i = 0; i < 8; i++) {
        int gpio_pin = GPIO_5 + i;
        lines[i] = gpiod_chip_get_line(chip, gpio_pin);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
            // Release any previously acquired lines
            for (int j = 0; j < i; j++) {
