#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define fade duration (seconds)
#define FADE_DURATION 5

// Define number of steps in fade
#define FADE_STEPS 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to set up GPIO pins for PWM output
int setup_gpio_pins() {
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for RED_PIN");
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for GREEN_PIN");
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for BLUE_PIN");
        return -1;
    }
    return 0;
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        syslog(LOG_ERR, "Failed to set PWM for pin %d", pin);
        return -1;
    }
    return 0;
}

// Function to convert HSV to RGB
void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b) {
    if (s == 0.0) {
        *r = *g = *b = (int)(v * 255);
        return;
    }

    h = fmod(h, 360.0);
    if (h < 0) h += 360.0;

    float hh, p, q, t, ff;
    long i;

    hh = h / 60.0;
    i = (long)hh;
    ff = hh - i;
    p = v * (1.0 - s);
    q = v * (1.0 - (s * ff));
    t = v * (1.0 - (s * (1.0 - ff)));

    switch (i) {
        case 0:
            *r = (int)(v * 255);
            *g = (int)(t * 255);
            *b = (int)(p * 255);
            break;
        case 1:
            *r = (int)(q * 255);
            *g = (int)(v * 255);
            *b = (int)(p * 255);
            break;
        case 2:
            *r = (int)(p * 255);
            *g = (int)(v * 255);
            *b = (int)(t * 255);
            break;
        case 3:
            *r = (int)(p * 255);
            *g = (int)(q * 255);
            *b = (int)(v * 255);
            break;
        case 4:
            *r = (int)(t * 255);
            *g = (int)(p * 255);
            *b = (int)(v * 255);
            break;
        case 5:
        default:
            *r = (int)(v * 255);
            *g = (int)(p * 255);
            *b = (int)(q * 255);
            break;
    }
}

// Function to fade between two colors
void fade_color(int red_pin, int green_pin, int blue_pin, int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue, int steps) {
    float red_step = (float)(end_red - start_red) / steps;
    float green_step = (float)(end_green - start_green) / steps;
    float blue_step = (float)(end_blue - start_blue) / steps;

    for (int i = 0; i < steps; i++) {
        int current_red = start_red + (int)(red_step * i);
        int current_green = start_green + (int)(green_step * i);
        int current_blue = start_blue + (int)(blue_step * i);

        set_pwm_duty_cycle(red_pin, 255 - current_red);
        set_pwm_duty_cycle(green_pin, 255 - current_green);
        set_pwm_duty_cycle(blue_pin, 255 - current_blue);

        gpioDelay(1000000 / steps); // Delay for smooth transition
    }
}

int main() {
    // Open syslog for logging
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return 1;
    }

    // Set up GPIO pins
    if (setup_gpio_pins() != 0) {
        syslog(LOG_ERR, "Failed to set up GPIO pins, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Main loop
    while (program_running) {
        // Seed the random number generator with /dev/urandom
        FILE *urandom = fopen("/dev/urandom", "r");
        if (urandom == NULL) {
            syslog(LOG_ERR, "Failed to open /dev/urandom, using default seed");
        } else {
            unsigned int seed;
            fread(&seed, sizeof(unsigned int), 1, urandom);
            fclose(urandom);
            srand(seed);
        }

        // Generate random hue, saturation, and value
        float hue = (float)rand() / RAND_MAX * 360.0;
        float saturation = 1.0;
        float value = 1.0;

        // Convert HSV to RGB
        int red, green, blue;
        hsv_to_rgb(hue, saturation, value, &red, &green, &blue);

        // Fade to the new color
        fade_color(RED_PIN, GREEN_PIN, BLUE_PIN, 255 - red, 255 - green, 255 - blue, 0, 0, 0, FADE_STEPS);

        // Wait for 5 seconds
        sleep(FADE_DURATION);
    }

    // Turn off the LED
    set_pwm_duty_cycle(RED_PIN, 255);
    set_pwm_duty_cycle(GREEN_PIN, 255);
    set_pwm_duty_cycle(BLUE_PIN, 255);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

