#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define LED_GPIO_PIN 17
#define RED_THRESHOLD 200
#define NUM_SENSORS 2

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ID 0x12

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and calibration parameters
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    float clear_scale;
    float red_scale;
    float green_scale;
    float blue_scale;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(int pin);
int init_sensor(int fd);
int read_sensor_data(int fd, sensor_data_t *data);
void calibrate_sensor(sensor_data_t *data);
void control_led(int red, int green, int blue);
void cleanup(int fd, struct gpiod_line *line, struct gpiod_chip *chip);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO
int init_gpio(int pin) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    led_line = gpiod_chip_get_line(chip, pin);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize TCS34725 sensor
int init_sensor(int fd) {
    // Power on and enable RGBC
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Error setting I2C slave address during init");
        return -1;
    }

    uint8_t enable_value = 0x03; // PON | AEN
    if (write(fd, &enable_value, 1) != 1) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time
    uint8_t atime_value = 0x00; // 154ms
    if (write(fd, &atime_value, 1) != 1) {
        perror("Error writing to ATIME register");
        return -1;
    }

    // Set gain
    uint8_t control_value = 0x00; // 1x
    if (write(fd, &control_value, 1) != 1) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    // Verify sensor ID
    uint8_t id;
    if (read(fd, &id, 1) != 1) {
        perror("Error reading ID register");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

