#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define NUM_LEDS 10
#define I2C_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define PWM_FREQ 800000 // 800 kHz
#define PWM_RANGE 1000  // PWM range for smooth brightness control

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold LED color data
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} led_color_t;

// Function prototypes
int init_i2c();
int read_bh1750(int *lux);
void set_led_color(int led_index, led_color_t color);
void set_strip_brightness(int brightness);
void generate_waveform();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(int *lux) {
    char cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to I2C: %d, retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to I2C after multiple retries.\n");
        return -1;
    }

    gpioDelay(180000); // Wait 180 ms

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading from I2C: %d, retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
        return -1;
    }

    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

// Set the color of a specific LED
void set_led_color(int led_index, led_color_t color) {
    if (led_index < 0 || led_index >= NUM_LEDS) {
        fprintf(stderr, "Error: LED index out of bounds.\n");
        return;
    }

    // WS2812B timing: 0 bit = 0.45us, 1 bit = 0.6us
    // Each color component (R, G, B) is 8 bits
    // Total bits per LED: 3 * 8 = 24 bits

    // Create a buffer to hold the LED data
    uint8_t led_data[4]; // 4 bytes for 3 color components + 1 padding byte
    led_data[0] = color.red;
    led_data[1] = color.green;
    led_data[2] = color.blue;
    led_data[3] = 0x00; // Padding byte

    // Generate the WS2812B waveform for the LED data
    for (int i = 0; i < 24; i++) {
        // Determine if the bit is 0 or 1
        int bit = (led_data[i / 8] >> (7 - (i % 8))) & 1;

        // Calculate the pulse width in microseconds
        int pulse_width = bit ? 6 : 4;

        // Generate the PWM waveform
        gpioPWM(18, 0); // Low
        gpioDelay(pulse_width * 1000); // Delay for pulse width
        gpioPWM(18, 1); // High
        gpioDelay(pulse_width * 1000); // Delay for pulse width
    }
}

// Set the overall brightness of the LED strip
void set_strip_brightness(int brightness) {
    // Map the brightness value (0-1000) to a PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)brightness / 1000.0) * PWM_RANGE);

    // Set the PWM duty cycle
    gpioPWM(18, duty_cycle);
}

// Generate the WS2812B waveform for the entire strip
void generate_waveform() {
    // Create a buffer to hold the LED data for the entire strip
    uint8_t led_data[NUM_LEDS * 4]; // 4 bytes per LED (3 color components + 1 padding byte)

    // Set the color of each LED in the strip
    for (int i = 0; i < NUM_LEDS; i++) {
        led_color_t color;
        // Example: Set all LEDs to a gradient from red to blue
        color.red = (uint8_t)((float)i / (NUM_LEDS - 1) * 255);
        color.green = 0;
        color.blue = (uint8_t)(255 - (float)i / (NUM_LEDS - 1) * 255);
        set_led_color(i, color);
    }
}

// Cleanup resources before exiting
void cleanup() {
    // Stop PWM
    gpioPWM(18, 0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 to output mode
    gpioSetMode(18, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(18, PWM_FREQ);
    gpioSetPWMrange(18, PWM_RANGE);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read light level from BH1750 sensor
        if (read_bh1750(&lux) == 0) {
            // Map light level to brightness (non-linear mapping)
            brightness = (int)(1000.0 * pow((double)lux / 1000.0, 0.5)); // Example: logarithmic mapping
            if (brightness > 1000) brightness = 1000;
            if (brightness < 0) brightness = 0;

            // Set the strip brightness
            set_strip_brightness(brightness);

            // Generate the WS2812B waveform
            generate_waveform();
        } else {
            fprintf(stderr, "Error reading light level.\n");
        }

        // Delay for a short period
        gpioDelay(50000); // 50 ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

