#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x21
#define APA102_DATA_PIN 10
#define APA102_CLOCK_PIN 11
#define NUM_LEDS 30
#define FADE_TIME_MS 500
#define DELAY_TIME_MS 100

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int addr);
int read_bh1750(int i2c_handle);
float calculate_average_lux(int lux1, int lux2);
int map_lux_to_brightness(float average_lux);
void fade_brightness(int current_brightness, int target_brightness, int fade_time_ms);
void set_apa102_brightness(int brightness);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read lux value from BH1750
int read_bh1750(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_ONE_TIME_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }
    gpioDelay(180); // Wait for conversion (at least 180ms)

    int data = i2cReadWordData(i2c_handle, 0x00);
    if (data < 0) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }

    // BH1750 returns big-endian, need to swap bytes
    return (data >> 8) | (data << 8);
}

// Function to calculate average lux
float calculate_average_lux(int lux1, int lux2) {
    if (lux1 == -1 && lux2 == -1) return 0.0;
    if (lux1 == -1) return (float)lux2;
    if (lux2 == -1) return (float)lux1;
    return (float)(lux1 + lux2) / 2.0;
}

// Function to map lux to brightness (0-31)
int map_lux_to_brightness(float average_lux) {
    // Invert the relationship: lower lux -> higher brightness
    float brightness_float = 31.0 - (average_lux / 1000.0) * 31.0; // Scale to 0-31
    if (brightness_float < 0.0) brightness_float = 0.0;
    if (brightness_float > 31.0) brightness_float = 31.0;
    return (int)brightness_float;
}

// Function to fade brightness over time
void fade_brightness(int current_brightness, int target_brightness, int fade_time_ms) {
    int steps = 100; // Number of steps in the fade
    float brightness_increment = (float)(target_brightness - current_brightness) / steps;
    for (int i = 0; i < steps; i++) {
        int new_brightness = current_brightness + (int)(brightness_increment * (i + 1));
        set_apa102_brightness(new_brightness);
        gpioDelay(fade_time_ms / steps); // Delay for each step
    }
    set_apa102_brightness(target_brightness); // Ensure final brightness is set
}

// Function to set APA102 brightness
void set_apa102_brightness(int brightness) {
    // APA102 requires a specific format for brightness control
    // This is a simplified example; a full implementation would involve
    // setting the start frame, data frame, and end frame.
    // For simplicity, we'll just set the brightness on the last LED.

    // Start frame (4 bytes of 0x00)
    for (int i = 0; i < 4; i++) {
        gpioWrite(APA102_DATA_PIN, 0);
        gpioWrite(APA102_CLOCK_PIN, 1);
        gpioWrite(APA102_CLOCK_PIN, 0);
    }

    // Data frame (4 bytes of brightness data)
    for (int i = 0; i < 4; i++) {
        gpioWrite(APA102_DATA_PIN, (brightness >> (3 - i)) & 1);
        gpioWrite(APA102_CLOCK_PIN, 1);
        gpioWrite(APA102_CLOCK_PIN, 0);
    }

    // End frame (4 bytes of 0xFF)
    for (int i = 0; i < 4; i++) {
        gpioWrite(APA102_DATA_PIN, 1);
        gpioWrite(APA102_CLOCK_PIN, 1);
        gpioWrite(APA102_CLOCK_PIN, 0);
    }
}

// Signal handler for clean exit
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Turn off LED strip
    set_apa102_brightness(0);

    // Close I2C handles
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);

    // Close SPI handle
    if (spi_handle >= 0) spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle_low = init_i2c(BH1750_ADDR_LOW);
    i2c_handle_high = init_i2c(BH1750_ADDR_HIGH);

    // Initialize SPI
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set APA102 pins as output
    gpioSetMode(APA102_DATA_PIN, PI_OUTPUT);
    gpioSetMode(APA102_CLOCK_PIN, PI_OUTPUT);

    int current_brightness = 0;
    int target_brightness = 0;

    while (!terminate) {
        // Read lux values from BH1750 sensors
        int lux1 = (i2c_handle_low >= 0) ? read_bh1750(i2c_handle_low) : -1;
        int lux2 = (i2c_handle_high >= 0) ? read_bh1750(i2c_handle_high) : -1;

        // Calculate average lux
        float average_lux = calculate_average_lux(lux1, lux2);

        // Map lux to brightness
        target_brightness = map_lux_to_brightness(average_lux);

        // Fade to target brightness
        fade_brightness(current_brightness, target_brightness, FADE_TIME_MS);

        // Update current brightness
        current_brightness = target_brightness;

        // Delay before next cycle
        gpioDelay(DELAY_TIME_MS);
    }

    return 0;
}

