#define MAX_BRIGHTNESS 255.0
#define GPIO_CHIP "gpiochip0"

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init(int fd);
int veml7700_read_als(int fd);
float calculate_lux(int als_data);
int map_lux_to_brightness(float lux);
void ws2812b_set_brightness(int brightness);
void ws2812b_send_data(uint8_t *data, size_t len);
void ws2812b_clear_strip();
void signal_handler(int sig);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint16_t value);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read register data");
        return -1;
    }
    return data;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write register data");
        return -1;
    }
    return 0;
}

// Initialize VEML7700 sensor
int veml7700_init(int fd) {
    uint16_t config_value = 0x0000; // Integration time 100ms, Gain 1/8
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_reg(fd, VEML7700_CONFIG, config_value) == 0) {
            return 0; // Success
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
    }

    fprintf(stderr, "Error: Failed to initialize VEML7700 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read ALS data from VEML7700
int veml7700_read_als(int fd) {
    int als_data = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        als_data = i2c_read_reg(fd, VEML7700_ALS_DATA);
        if (als_data >= 0) {
            return als_data;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
    }

    fprintf(stderr, "Error: Failed to read ALS data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculate lux value from ALS data
float calculate_lux(int als_data) {
    return (float)als_data * 0.0288;
}

// Map lux value to brightness (gamma correction)
int map_lux_to_brightness(float lux) {
    float brightness_float = MAX_BRIGHTNESS * powf(lux / MAX_LUX, 1.0 / 2.2);
    int brightness = (int)brightness_float;
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return brightness;
}

// Bit-banging WS2812B LED strip control
void ws2812b_set_brightness(int brightness) {
    // Simple on/off control if bit-banging is not feasible
    if (gpio_line == NULL) {
        fprintf(stderr, "Error: GPIO line not initialized.\n");
        return;
    }

    int on_time_us, off_time_us;

    // Calculate on/off times based on brightness (800kHz = 1.25us per bit)
    if (brightness > 0) {
        on_time_us = (int)(brightness * 0.45); // 0.45us per bit for high
        off_time_us = (int)((255 - brightness) * 0.6); // 0.6us per bit for low
    } else {
        on_time_us = 0;
        off_time_us = 0;
    }

    // Set GPIO line to output mode
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ws2812b";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        return;
    }

    // Send data (dummy data for now)
    uint8_t data[] = {0x00, 0x00, 0x00}; // Example data
    size_t len = sizeof(data);

    for (size_t i = 0; i < len; ++i) {
        for (int j = 7; j >= 0; --j) {
            if ((data[i] >> j) & 1) {
                // Send '1'
                gpiod_line_set_value(gpio_line, 1);
                usleep(on_time_us);
                gpiod_line_set_value(gpio_line, 0);
                usleep(off_time_us);
            } else {
                // Send '0'
                gpiod_line_set_value(gpio_line, 1);
                usleep(off_time_us);
                gpiod_line_set_value(gpio_line, 0);
                usleep(on_time_us);
            }
        }
    }

    // Release GPIO line
    gpiod_line_release(gpio_line);
}

// Clear the LED strip (set all pixels to black)
void ws2812b_clear_strip() {
    // Send a buffer of zeros to clear the strip
    uint8_t clear_data[] = {0x00, 0x00, 0x00}; // Example data (all zeros)
    ws2812b_send_data(clear_data, sizeof(clear_data));
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;

    // Turn off LED strip
    ws2812b_clear_strip();

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Unexport GPIO chip
    // No explicit unexport in gpiod, but good practice to note
    // struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    // gpiod_chip_close(chip);

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
