        close(i2c_fd);
        return 1;
    }

    // Initialize VEML7700 sensor
    if (veml7700_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: Failed to initialize VEML7700 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, WS2812B_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ALS data
        int als_data = veml7700_read_als(i2c_fd);
        if (als_data < 0) {
            fprintf(stderr, "Error: Failed to read ALS data.\n");
            continue; // Try again
        }

        // Calculate lux value
        float lux = calculate_lux(als_data);

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Set LED strip brightness
        ws2812b_set_brightness(brightness);

        // Print lux and brightness values
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        usleep(200000); // 200ms
    }

    return 0;
}

