#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define SELF_TEST_DURATION 2 // seconds
#define FLAME_DETECTED 0
#define FLAME_NOT_DETECTED 1
#define FLAME_FAULT 2

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_flame_sensor(void);
void activate_buzzer(void);
void deactivate_buzzer(void);
void activate_led(void);
void deactivate_led(void);
void log_event(const char *message);
void self_test(void);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    // Request lines for input (flame sensor) and output (buzzer, LED)
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        perror("Error reading flame sensor value");
        return FLAME_FAULT;
    }
    return (value == FLAME_DETECTED) ? FLAME_DETECTED : FLAME_NOT_DETECTED;
