#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <sys/time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define CIRCULAR_BUFFER_SIZE 60
#define MAX_LUX 1000.0

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int gpio_fd = -1;

// Circular buffer structure
typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_read_word(int fd, uint8_t addr);
float convert_to_lux(uint16_t raw_value);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
void gpio_export(int pin);
void gpio_unexport(int pin);
void gpio_set_direction(int pin, const char *direction);
void gpio_write(int pin, int value);
float calculate_blink_rate(float average_lux);
void signal_handler(int signal);
int i2c_write(int fd, uint8_t addr, uint8_t data);

// I2C read function
int i2c_read_word(int fd, uint8_t addr) {
    uint8_t buf[2];
    int ret;

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    ret = read(fd, buf, 2);
    if (ret != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Lux conversion function
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Circular buffer functions
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (cb->count < CIRCULAR_BUFFER_SIZE) {
        cb->count++;
    }
}

float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// GPIO functions
void gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        perror("gpio/export");
    }

    close(fd);
}

void gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        perror("gpio/unexport");
    }

    close(fd);
}

void gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
    }

    close(fd);
}

void gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/value");
        return;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) < 0) {
        perror("gpio/value");
    }

    close(fd);
}

// Blink rate calculation function
float calculate_blink_rate(float average_lux) {
    float rate = 0.5 + (average_lux / MAX_LUX) * 4.5;
    if (rate < 0.5) {
        rate = 0.5;
    } else if (rate > 5.0) {
        rate = 5.0;
    }
    return rate;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = data;
    int ret;

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

int main() {
    CircularBuffer lux_buffer;
    float average_lux;
    float blink_rate;
    struct timeval start_time, current_time;
    long elapsed_time_ms;
    int i;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO
    gpio_export(GPIO_PIN);
    gpio_set_direction(GPIO_PIN, "out");

    // Initialize circular buffer
    circular_buffer_init(&lux_buffer);

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        int retries = 3;

        // Read raw value from BH1750
        while (retries > 0) {
            raw_value = i2c_read_word(i2c_fd, BH1750_ADDR);
            if (raw_value >= 0) {
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
                retries--;
                usleep(10000); // 10ms delay
            }
        }

        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from BH1750 after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Convert raw value to lux
        float lux = convert_to_lux(raw_value);

        // Add lux value to circular buffer
        circular_buffer_add(&lux_buffer, lux);

        // Calculate average lux
        average_lux = circular_buffer_average(&lux_buffer);

        // Calculate blink rate
        blink_rate = calculate_blink_rate(average_lux);

        // Blink LED
        gettimeofday(&start_time, NULL);
        while (program_running) {
            gettimeofday(&current_time, NULL);
            elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;

            if (elapsed_time_ms >= (1000.0 / blink_rate) * 2) {
                break;
            }

            gpio_write(GPIO_PIN, 1);
            usleep(500000 / (int)(blink_rate * 2)); // Half period on
            gpio_write(GPIO_PIN, 0);
            usleep(500000 / (int)(blink_rate * 2)); // Half period off
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_write(GPIO_PIN, 0); // Turn off LED
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

