        perror("gpio/direction");
    }

    close(fd);
}

void gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/value");
        return;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) < 0) {
        perror("gpio/value");
    }

    close(fd);
}

// Blink rate calculation function
float calculate_blink_rate(float average_lux) {
    float rate = 0.5 + (average_lux / MAX_LUX) * 4.5;
    if (rate < 0.5) {
        rate = 0.5;
    } else if (rate > 5.0) {
        rate = 5.0;
    }
    return rate;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = data;
    int ret;

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

int main() {
    CircularBuffer lux_buffer;
    float average_lux;
    float blink_rate;
    struct timeval start_time, current_time;
    long elapsed_time_ms;
    int i;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO
    gpio_export(GPIO_PIN);
    gpio_set_direction(GPIO_PIN, "out");

    // Initialize circular buffer
    circular_buffer_init(&lux_buffer);

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        int retries = 3;

        // Read raw value from BH1750
        while (retries > 0) {
            raw_value = i2c_read_word(i2c_fd, BH1750_ADDR);
            if (raw_value >= 0) {
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
                retries--;
                usleep(10000); // 10ms delay
            }
        }

        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from BH1750 after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Convert raw value to lux
        float lux = convert_to_lux(raw_value);

        // Add lux value to circular buffer
        circular_buffer_add(&lux_buffer, lux);

        // Calculate average lux
        average_lux = circular_buffer_average(&lux_buffer);

        // Calculate blink rate
        blink_rate = calculate_blink_rate(average_lux);

        // Blink LED
        gettimeofday(&start_time, NULL);
        while (program_running) {
            gettimeofday(&current_time, NULL);
            elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;

            if (elapsed_time_ms >= (1000.0 / blink_rate) * 2) {
                break;
            }

            gpio_write(GPIO_PIN, 1);
            usleep(500000 / (int)(blink_rate * 2)); // Half period on
            gpio_write(GPIO_PIN, 0);
            usleep(500000 / (int)(blink_rate * 2)); // Half period off
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_write(GPIO_PIN, 0); // Turn off LED
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

