// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the digit pattern for '5' (common cathode)
const uint8_t digit5 = 0b01110111;

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line;
struct gpiod_line *clock_line;
struct gpiod_line *latch_line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to shift out data to the 74HC595
void shift_out(uint8_t data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        if ((data >> i) & 1) {
            gpiod_line_set_value(data_line, 1);
        } else {
            gpiod_line_set_value(data_line, 0);
        }

        // Clock the data in
        gpiod_line_set_value(clock_line, 1);
        gpiod_usleep(clock_line, 1); // Small delay for clock stability
        gpiod_line_set_value(clock_line, 0);
    }
}

// Function to display the digit on the 7-segment display
void display_digit(uint8_t digit) {
    // Latch the data to the output
    gpiod_line_set_value(latch_line, 1);
    gpiod_usleep(latch_line, 1); // Small delay for latch stability
    gpiod_line_set_value(latch_line, 0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(data_line, "digit_display", 0) < 0 ||
        gpiod_line_request_output(clock_line, "digit_display", 0) < 0 ||
        gpiod_line_request_output(latch_line, "digit_display", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to blink the digit
    while (1) {
        // Turn the digit on
        shift_out(digit5);
        display_digit(digit5);
        gpiod_usleep(latch_line, 500); // On for 500ms

        // Turn the digit off
        shift_out(0b00000000);
        display_digit(0b00000000);
        gpiod_usleep(latch_line, 500); // Off for 500ms
    }

    return 0;
}

