#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip
#define GPIOCHIP 0

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *led_line;
struct gpiod_line *button_line;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO
int initialize_gpio()
{
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %d\n", GPIOCHIP);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d\n", LED_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line %d\n", BUTTON_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request LED line as output initially low
    struct gpiod_line_request_config led_config;
    memset(&led_config, 0, sizeof(led_config));
    led_config.consumer = "blink_button";
    led_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    led_config.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN; // Optional: Open drain

    int ret = gpiod_line_request(led_line, &led_config, 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Request button line as input with falling edge detection
    struct gpiod_line_request_config button_config;
    memset(&button_config, 0, sizeof(button_config));
    button_config.consumer = "blink_button";
    button_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    button_config.flags = GPIOD_LINE_REQUEST_FLAG_DRAIN_ON_RELEASE; // Release on exit

    ret = gpiod_line_request(button_line, &button_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led()
{
    struct timespec on_time, off_time;
    on_time.tv_sec = 1;  // 1 second on
    on_time.tv_nsec = 0;
    off_time.tv_sec = 1; // 1 second off
    off_time.tv_nsec = 0;

    while (!terminate) {
        // Turn LED on
        if (gpiod_line_set_value(led_line, 1) < 0) {
            fprintf(stderr, "Error setting LED value to 1\n");
            break;
        }
        nanosleep(&on_time, NULL);

        // Turn LED off
        if (gpiod_line_set_value(led_line, 0) < 0) {
            fprintf(stderr, "Error setting LED value to 0\n");
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

// Function to handle button press
void handle_button_press()
{
    printf("Button pressed! Exiting.\n");
    // Turn off LED
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error setting LED value to 0 during button press\n");
    }

    // Release GPIO lines
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    exit(0);
}

int main()
{
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Blink the LED
    blink_led();

    // Handle button press (should not reach here if signal handler works correctly)
    handle_button_press();

    return 0;
}

