#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// PWM period in nanoseconds (10 ms)
#define PWM_PERIOD 10000000

// Structure to hold GPIO chip and lines
struct gpio_config {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line;
    struct gpiod_line *green_line;
    struct gpiod_line *blue_line;
};

// Global variable to store the GPIO configuration
struct gpio_config gpio_config_global;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_config_global.red_line) {
        gpiod_line_release(gpio_config_global.red_line);
    }
    if (gpio_config_global.green_line) {
        gpiod_line_release(gpio_config_global.green_line);
    }
    if (gpio_config_global.blue_line) {
        gpiod_line_release(gpio_config_global.blue_line);
    }

    // Close GPIO chip
    if (gpio_config_global.chip) {
        gpiod_chip_close(gpio_config_global.chip);
    }

    exit(0);
}

// Function to set the PWM duty cycle for a given GPIO line
int set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO line.\n");
        return -1;
    }

    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and 100.\n");
        return -1;
    }

    // Calculate the number of nanoseconds to keep the line high
    int high_time_ns = (int)((PWM_PERIOD * duty_cycle) / 100.0);

    // Busy-wait to set the PWM duty cycle
    struct timespec high_time, low_time;
    high_time.tv_sec = 0;
    high_time.tv_nsec = high_time_ns;
    low_time.tv_sec = 0;
    low_time.tv_nsec = PWM_PERIOD - high_time_ns;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO value to 1: %s\n", strerror(errno));
        return -1;
    }

    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &high_time) < 0) {
        fprintf(stderr, "Error sleeping high: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO value to 0: %s\n", strerror(errno));
        return -1;
    }

    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &low_time) < 0) {
        fprintf(stderr, "Error sleeping low: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to generate a random RGB color value
void generate_random_color(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

int main() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_config_global.chip = gpiod_chip_open_by_number(0);
    if (!gpio_config_global.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    gpio_config_global.red_line = gpiod_chip_get_line(gpio_config_global.chip, RED_PIN);
    gpio_config_global.green_line = gpiod_chip_get_line(gpio_config_global.chip, GREEN_PIN);
    gpio_config_global.blue_line = gpiod_chip_get_line(gpio_config_global.chip, BLUE_PIN);

    if (!gpio_config_global.red_line || !gpio_config_global.green_line || !gpio_config_global.blue_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        goto cleanup;
    }

    // Request the GPIO lines as outputs
    if (gpiod_line_request_output(gpio_config_global.red_line, "red_led", 0) < 0) {
        fprintf(stderr, "Error requesting red GPIO line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(gpio_config_global.green_line, "green_led", 0) < 0) {
        fprintf(stderr, "Error requesting green GPIO line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(gpio_config_global.blue_line, "blue_led", 0) < 0) {
        fprintf(stderr, "Error requesting blue GPIO line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    // Main loop to generate random colors and set PWM duty cycles
    while (1) {
        int red, green, blue;
        generate_random_color(&red, &green, &blue);

        if (set_pwm_duty_cycle(gpio_config_global.red_line, red) < 0) {
            fprintf(stderr, "Error setting red PWM duty cycle.\n");
            goto cleanup;
        }
        if (set_pwm_duty_cycle(gpio_config_global.green_line, green) < 0) {
            fprintf(stderr, "Error setting green PWM duty cycle.\n");
            goto cleanup;
        }
        if (set_pwm_duty_cycle(gpio_config_global.blue_line, blue) < 0) {
            fprintf(stderr, "Error setting blue PWM duty cycle.\n");
            goto cleanup;
        }

        usleep(100000); // 100 ms delay
    }

cleanup:
    // Release GPIO lines
    if (gpio_config_global.red_line) {
        gpiod_line_release(gpio_config_global.red_line);
    }
    if (gpio_config_global.green_line) {
        gpiod_line_release(gpio_config_global.green_line);
    }
    if (gpio_config_global.blue_line) {
        gpiod_line_release(gpio_config_global.blue_line);
    }

    // Close GPIO chip
    if (gpio_config_global.chip) {
        gpiod_chip_close(gpio_config_global.chip);
    }

    return 1;
}

