#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28

// GPIO pin for impact indication
#define IMPACT_GPIO 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm303();
int read_accelerometer(float *x, float *y, float *z);
double calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LSM303DLHC sensor
int init_lsm303() {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Set full-scale range to +/- 2G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data from the LSM303DLHC
int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of data starting from OUT_X_L_A
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine low and high bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to G-force units (assuming +/- 2G full-scale)
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
