#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_LSB_REG 0x66
#define RED_MSB_REG 0x67
#define GREEN_LSB_REG 0x68
#define GREEN_MSB_REG 0x69
#define BLUE_LSB_REG 0x6A
#define BLUE_MSB_REG 0x6B
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als();
int read_color(int *red, int *green, int *blue);
void set_led_brightness(int als_value);
void log_data(int als, int red, int green, int blue);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Initialize the ADPD188BI sensor
int initialize_sensor() {
    int result;
    // Set mode to normal operation
    result = i2cWriteByteData(i2c_handle, MODE_REG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to MODE register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ambient light (ALS) data from the sensor
int read_als() {
    int lsb, msb, als_value;
    int result;

    result = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", result);
        return -1;
    }
    lsb = result;

    result = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", result);
        return -1;
    }
    msb = result;

    als_value = (msb << 8) | lsb;
    return als_value;
}

// Read color (RGB) data from the sensor
int read_color(int *red, int *green, int *blue) {
    int r_lsb, r_msb, g_lsb, g_msb, b_lsb, b_msb;
    int result;

    result = i2cReadByteData(i2c_handle, RED_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading RED LSB: %d\n", result);
        return -1;
    }
    r_lsb = result;

    result = i2cReadByteData(i2c_handle, RED_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading RED MSB: %d\n", result);
        return -1;
    }
    r_msb = result;
    *red = (r_msb << 8) | r_lsb;

    result = i2cReadByteData(i2c_handle, GREEN_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading GREEN LSB: %d\n", result);
        return -1;
    }
    g_lsb = result;

    result = i2cReadByteData(i2c_handle, GREEN_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading GREEN MSB: %d\n", result);
        return -1;
    }
    g_msb = result;
    *green = (g_msb << 8) | g_lsb;

    result = i2cReadByteData(i2c_handle, BLUE_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading BLUE LSB: %d\n", result);
        return -1;
    }
    b_lsb = result;

    result = i2cReadByteData(i2c_handle, BLUE_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading BLUE MSB: %d\n", result);
        return -1;
    }
    b_msb = result;
    *blue = (b_msb << 8) | b_lsb;

    return 0;
}

// Set LED brightness based on ALS value
void set_led_brightness(int als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * PWM_RANGE);
    gpioPWM(LED_GPIO, duty_cycle);
}

// Log data to CSV file
void log_data(int als, int red, int green, int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int als_value, red, green, blue;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open CSV file for logging
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        als_value = read_als();
        if (read_color(&red, &green, &blue) != 0) {
            fprintf(stderr, "Error reading color data\n");
        }

        // Log data
        log_data(als_value, red, green, blue);

        // Set LED brightness
        set_led_brightness(als_value);

        // Wait 500 ms
        gpioDelay(500000); // 500 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

