#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define XYZ_DATA_CFG 0x0E

// Impact threshold (2g in m/s^2)
#define IMPACT_THRESHOLD 19.62

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int verify_sensor();
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to verify the sensor's WHO_AM_I register
int verify_sensor() {
    int who_am_i;

    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X (expected 0xC7)\n", who_am_i);
        return -1;
    }

    printf("Sensor verification successful.\n");
    return 0;
}

// Function to initialize the sensor
int initialize_sensor() {
    int status;

    // Set to standby mode
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", status);
        return -1;
    }

    // Configure XYZ_DATA_CFG for ±2g mode
    status = i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", status);
        return -1;
    }

    // Set ODR to 200 Hz and active mode
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x15);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %d\n", status);
        return -1;
    }

    printf("Sensor initialized.\n");
    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Combine MSB and LSB, and shift right by 2 bits
    *x = ((int16_t)buffer[0] << 8) | (buffer[1] >> 2);
    *y = ((int16_t)buffer[2] << 8) | (buffer[3] >> 2);
    *z = ((int16_t)buffer[4] << 8) | (buffer[5] >> 2);

    return 0;
}

// Function to calculate the acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0 * 9.81;
    float y_g = (float)y / 4096.0 * 9.81;
    float z_g = (float)z / 4096.0 * 9.81;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log impact data to a file
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, (float)x / 4096.0 * 9.81, (float)y / 4096.0 * 9.81, (float)z / 4096.0 * 9.81, magnitude);
    fclose(fp);
}

int main() {
    int16_t x, y, z;
    float magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

