    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Error reading register");
        return -1;
    }
    return buf[0];
}

// Function to write a single register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    uint8_t reg = OUT_X_L;

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        perror("Error reading gyro data");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit
    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    // Convert to degrees per second (dps)
    data->x = (float)x * 0.00875;
    data->y = (float)y * 0.00875;
    data->z = (float)z * 0.00875;

    return 0;
}

// Function to calibrate the gyroscope
void calibrate_gyro(int fd, gyro_data_t *offsets) {
    gyro_data_t sample;
    float x_sum = 0, y_sum = 0, z_sum = 0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(fd, &sample) == 0) {
            x_sum += sample.x;
            y_sum += sample.y;
            z_sum += sample.z;
        } else {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            // Handle the error appropriately, e.g., exit or retry
        }
        usleep(5000); // 5 ms delay
    }

    offsets->x = x_sum / CALIBRATION_SAMPLES;
    offsets->y = y_sum / CALIBRATION_SAMPLES;
    offsets->z = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets->x, offsets->y, offsets->z);
}

// Function to log data to file
void log_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to check for alert condition
void check_alert(gyro_data_t data) {
    if (fabs(data.x) > ALERT_THRESHOLD || fabs(data.y) > ALERT_THRESHOLD || fabs(data.z) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: Gyroscope data out of range!\n");
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s,ALERT: X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, data.x, data.y, data.z);
        fflush(log_file);
        sleep(ALERT_DURATION);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, GYRO_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = read_register(i2c_fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register. Exiting.\n");
        cleanup();
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch. Expected 0x%X, got 0x%X. Exiting.\n", WHO_AM_I_VALUE, who_am_i);
        cleanup();
        return 1;
    }

    printf("WHO_AM_I check passed. Gyroscope found.\n");

    // Configure CTRL_REG1 (normal mode, all axes enabled, 100 Hz ODR)
    if (write_register(i2c_fd, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    if (write_register(i2c_fd, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4. Exiting.\n");
        cleanup();
        return 1;
    }

    // Calibrate the gyroscope
    gyro_data_t offsets;
    calibrate_gyro(i2c_fd, &offsets);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Apply offsets
            gyro_data.x -= offsets.x;
            gyro_data.y -= offsets.y;
            gyro_data.z -= offsets.z;

            // Log data
            log_data(log_file, gyro_data);

            // Check for alert condition
            check_alert(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        usleep((int)(SAMPLE_RATE * 1000000)); // Convert seconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

