#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03

// Scaling factors
#define ACCEL_SCALE 0.000244 // +/- 2g range
#define MAG_SCALE 0.00014   // +/- 4 gauss range

// Global variables
int accel_handle, mag_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x, y, z;
} SensorData;

// Function prototypes
int init_i2c();
int init_sensors();
SensorData read_accelerometer();
SensorData read_magnetometer();
float calculate_heading(SensorData accel, SensorData mag);
void log_data(float heading, SensorData accel, SensorData mag);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open accelerometer I2C device: %d\n", accel_handle);
        return -1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open magnetometer I2C device: %d\n", mag_handle);
        i2cClose(accel_handle);
        return -1;
    }

    return 0;
}

// Initialize sensors
int init_sensors() {
    // Initialize accelerometer
    if (i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    // Initialize magnetometer
    if (i2cWriteByteData(mag_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
SensorData read_accelerometer() {
    char buf[6];
    SensorData accel_data;

    if (i2cReadI2CBlockData(accel_handle, OUT_X_L_A, buf, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        accel_data.x = accel_data.y = accel_data.z = 0.0;
        return accel_data;
    }

    // Combine high and low bytes, and convert to g
    accel_data.x = (float)((int16_t)(buf[1] << 8 | buf[0])) * ACCEL_SCALE;
    accel_data.y = (float)((int16_t)(buf[3] << 8 | buf[2])) * ACCEL_SCALE;
    accel_data.z = (float)((int16_t)(buf[5] << 8 | buf[4])) * ACCEL_SCALE;

    return accel_data;
}

// Read magnetometer data
SensorData read_magnetometer() {
    char buf[6];
    SensorData mag_data;

    if (i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        mag_data.x = mag_data.y = mag_data.z = 0.0;
        return mag_data;
    }

    // Combine high and low bytes, and convert to gauss
    mag_data.x = (float)((int16_t)(buf[0] << 8 | buf[1])) * MAG_SCALE;
    mag_data.y = (float)((int16_t)(buf[2] << 8 | buf[3])) * MAG_SCALE;
    mag_data.z = (float)((int16_t)(buf[4] << 8 | buf[5])) * MAG_SCALE;

    return mag_data;
}

// Calculate tilt-compensated heading
float calculate_heading(SensorData accel, SensorData mag) {
    float roll = atan2(accel.y, accel.z);
    float pitch = atan2(-accel.x, sqrt(accel.y * accel.y + accel.z * accel.z));

    float mag_x_comp = mag.x * cos(pitch) + mag.z * sin(pitch);
    float mag_y_comp = mag.x * sin(roll) * sin(pitch) + mag.y * cos(roll) - mag.z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(float heading, SensorData accel, SensorData mag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, heading, accel.x, accel.y, accel.z, mag.x, mag.y, mag.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (accel_handle >= 0) i2cClose(accel_handle);
    if (mag_handle >= 0) i2cClose(mag_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize sensors
    if (init_sensors() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,X_Accel,Y_Accel,Z_Accel,X_Mag,Y_Mag,Z_Mag\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor data
        SensorData accel_data = read_accelerometer();
        SensorData mag_data = read_magnetometer();

        // Calculate heading
        float heading = calculate_heading(accel_data, mag_data);

        // Log data
        log_data(heading, accel_data, mag_data);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

