// VL6180X I2C address
#define VL6180X_ADDR 0x29

// VL6180X register addresses
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_STATUS 0x04D
#define VL6180X_REG_RESULT_RANGE_VAL 0x062

// I2C bus
#define I2C_BUS 1

// Distance threshold (mm)
#define DISTANCE_THRESHOLD 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_vl6180x();
int read_distance();
void log_data(int distance);
void signal_handler(int signal);
int check_sensor_presence();

// Signal handler for clean exit
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to check sensor presence
int check_sensor_presence() {
    int model_id;
    if (i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID) < 0) {
        fprintf(stderr, "Error reading sensor ID.  Re-initializing...\n");
        return 0; // Sensor not present
    }
    model_id = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xB4) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X.  Expected 0xB4.  Re-initializing...\n", model_id);
        return 0; // Incorrect sensor ID
    }
    return 1; // Sensor present
}

