#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL_US 10000

// Define retry count
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1_data;
    int16_t sensor2_data;
    double tdoa;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int16_t *data);
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, double tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", address, handle);
        return -1;
    }
    return handle;
}

// Configure the sensor (enable continuous measurement)
int configure_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = 0x00; // Control register address
    buf[1] = 0x80; // Enable continuous measurement

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int i2c_handle, int16_t *data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Calculate Time Difference of Arrival (TDOA)
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return (double)(sensor1_data - sensor2_data);
}

// Log data to file
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, double tdoa) {
    if (fprintf(fp, "%ld.%09ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure both sensors
    if (configure_sensor(i2c_handle1) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle2) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        struct timespec ts;
        int16_t sensor1_data, sensor2_data;
        double tdoa;

        // Read sensor 1 data
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
                break;
            } else {
                fprintf(stderr, "Retrying sensor 1 read (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(1000); // 1 ms delay
                retries++;
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 1 after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Read sensor 2 data
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
                break;
            } else {
                fprintf(stderr, "Retrying sensor 2 read (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(1000); // 1 ms delay
                retries++;
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 2 after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        // Log data
        if (log_data(log_file, ts, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_US);
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

