#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// Sensitivity values (from datasheet)
#define GYRO_SENSITIVITY 0.005  // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // CPOL=1, CPHA=1, aux SPI off

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function prototypes
int spi_read_register(int reg);
int spi_write_register(int reg, int data);
void cleanup();
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int reg) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    tx_buf[0] = 0x80 | (reg & 0x7F); // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy data

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    return rx_buf[1];
}

// Function to write a register in the ADIS16488A
int spi_write_register(int reg, int data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    tx_buf[0] = reg & 0x7F; // Set MSB to 0 for write
    tx_buf[1] = data;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Cleanup function to close SPI and file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Signal received (%d). Exiting...\n", signal);
    cleanup();
    exit(0);
