#include <errno.h>
#include <string.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(int channel, int speed, int cs_pin);
int spi_read_register(int handle, uint8_t address, int16_t *data);
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    // Initialize SPI
    spi_handle = spi_init(SPI_CHANNEL, SPI_SPEED, CS_PIN);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (spi_read_register(spi_handle, XGYRO_OUT, &gyro_x) < 0) {
            fprintf(stderr, "Error reading XGYRO_OUT\n");
        }
        if (spi_read_register(spi_handle, YGYRO_OUT, &gyro_y) < 0) {
            fprintf(stderr, "Error reading YGYRO_OUT\n");
        }
        if (spi_read_register(spi_handle, ZGYRO_OUT, &gyro_z) < 0) {
            fprintf(stderr, "Error reading ZGYRO_OUT\n");
        }

        // Read accelerometer data
        if (spi_read_register(spi_handle, XACCL_OUT, &accel_x) < 0) {
            fprintf(stderr, "Error reading XACCL_OUT\n");
        }
        if (spi_read_register(spi_handle, YACCL_OUT, &accel_y) < 0) {
            fprintf(stderr, "Error reading YACCL_OUT\n");
        }
        if (spi_read_register(spi_handle, ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Error reading ZACCL_OUT\n");
        }

        // Process and log the data
        process_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize SPI interface
int spi_init(int channel, int speed, int cs_pin) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read a single register from the ADIS16448
int spi_read_register(int handle, uint8_t address, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to indicate read operation
    tx_buf[0] = address | 0x80; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte for reading

    gpioWrite(CS_PIN, 0); // Activate CS
    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result != 2) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Process the raw sensor data and log it to the console
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    // Scale factors from the datasheet
    float gyro_scale = 0.02; // dps/LSB
    float accel_scale = 0.00025; // g/LSB

    // Apply scaling factors
    float gyro_x_dps = gyro_x * gyro_scale;
    float gyro_y_dps = gyro_y * gyro_scale;
    float gyro_z_dps = gyro_z * gyro_scale;
    float accel_x_g = accel_x * accel_scale;
    float accel_y_g = accel_y * accel_scale;
    float accel_z_g = accel_z * accel_scale;

    // Log the data
    printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.4f g, Accel Y: %.4f g, Accel Z: %.4f g\n",
           gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

