    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", status);
        return -1; // Indicate error
    }

    // Combine the received bytes into a 16-bit value
    int16_t value = (rx_buf[0] << 8) | rx_buf[1];
    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t gyro_x = read_register(X_GYRO_OUT);
        int16_t gyro_y = read_register(Y_GYRO_OUT);
        int16_t gyro_z = read_register(Z_GYRO_OUT);

        // Read accelerometer data
        int16_t accel_x = read_register(X_ACCL_OUT);
        int16_t accel_y = read_register(Y_ACCL_OUT);
        int16_t accel_z = read_register(Z_ACCL_OUT);

        // Check for read errors
        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1 ||
            accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100000); // 100 ms delay
            continue; // Retry the loop
        }

        // Scale and print the data
        printf("Gyro: X=%.3f deg/s, Y=%.3f deg/s, Z=%.3f deg/s\n",
               gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE);
        printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
               accel_x * ACCEL_SCALE, accel_y * ACCEL_SCALE, accel_z * ACCEL_SCALE);

        gpioDelay(100000); // 100 ms delay
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

