#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mpu6886_init(int fd);
int read_raw_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void signal_handler(int signal);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Indicate failure
}

// MPU-6886 initialization function
int mpu6886_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found (WHO_AM_I = 0x%02X)\n", who_am_i);
        return -1;
    }

    // Wake up the sensor (set PWR_MGMT_1 to 0)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to +-250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read raw accelerometer and gyroscope data
int read_raw_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    raw_accel_x = (int16_t)((i2c_read_reg(fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(fd, ACCEL_XOUT_L));
    raw_accel_y = (int16_t)((i2c_read_reg(fd, ACCEL_YOUT_H) << 8) | i2c_read_reg(fd, ACCEL_YOUT_L));
    raw_accel_z = (int16_t)((i2c_read_reg(fd, ACCEL_ZOUT_H) << 8) | i2c_read_reg(fd, ACCEL_ZOUT_L));
    raw_gyro_x = (int16_t)((i2c_read_reg(fd, GYRO_XOUT_H) << 8) | i2c_read_reg(fd, GYRO_XOUT_L));
    raw_gyro_y = (int16_t)((i2c_read_reg(fd, GYRO_YOUT_H) << 8) | i2c_read_reg(fd, GYRO_YOUT_L));
    raw_gyro_z = (int16_t)((i2c_read_reg(fd, GYRO_ZOUT_H) << 8) | i2c_read_reg(fd, GYRO_ZOUT_L));

    *accel_x = raw_accel_x;
    *accel_y = raw_accel_y;
    *accel_z = raw_accel_z;
    *gyro_x = raw_gyro_x;
    *gyro_y = raw_gyro_y;
    *gyro_z = raw_gyro_z;

    return 0;
}

// Function to print the raw data
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    printf("Accel: X=%d, Y=%d, Z=%d  Gyro: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6886 sensor
    if (mpu6886_init(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully\n");

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (program_running) {
        // Read raw data from the sensor
        if (read_raw_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the raw data
            print_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        // Wait 50 ms
        usleep(50000); // 50 ms = 50000 microseconds
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

