#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_FILTER_CTL 0x2C

// LED GPIO pin
#define LED_PIN 17

// Impact threshold (g)
#define IMPACT_THRESHOLD 2.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    float magnitude;
} AccelerometerData;

// Function to initialize the ADXL345
int adxl345_init() {
    // Set data rate to 100 Hz and full resolution
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_FILTER_CTL, 0x0B) < 0) {
        fprintf(stderr, "Error writing to ADXL345_REG_FILTER_CTL\n");
        return -1;
    }

    // Set power control register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to ADXL345_REG_POWER_CTL\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log impact data to a file
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Turn on LED
                gpioWrite(LED_PIN, 1);

                // Log impact
                log_impact(x, y, z, magnitude);

                // Wait 500 ms
                gpioDelay(500000);

                // Turn off LED
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Wait 10 ms
        gpioDelay(10000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
