#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define OUT_X_MSB_REG 0x01
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.0
#define G_PER_COUNT 1024.0
#define LED_ON_TIME_MS 500

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int gpio);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int gpio, int on);
void log_impact(void);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MMA8451Q_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(LED_GPIO) != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = read_register(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "WHO_AM_I register returned 0x%X, expected 0x1A. Exiting.\n", who_am_i);
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    accelerometer_data_t accel_data;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Failed to read acceleration data. Continuing.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            control_led(LED_GPIO, 1); // Turn LED on
            log_impact();             // Log the impact
            control_led(LED_GPIO, 0); // Turn LED off
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    printf("Cleaning up and exiting.\n");
    fclose(log_file);
    gpioTerminate();
    close(i2c_fd);

    return 0;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO
int init_gpio(int gpio) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio, PI_OUTPUT);
    return 0;
}

// Read a register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return value;
}

// Write a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (write(fd, OUT_X_MSB_REG, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / G_PER_COUNT;
    float y_g = (float)y / G_PER_COUNT;
    float z_g = (float)z / G_PER_COUNT;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Control LED
void control_led(int gpio, int on) {
    gpioWrite(gpio, on);
}

// Log impact
void log_impact(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Impact detected\n", timestamp);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating.\n", signal);
    terminate = 1;
}

