#include <errno.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x35

// Define the register addresses for X, Y, and Z data
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12

// Global variables for file descriptors and program state
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C interface
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (write(i2c_fd, &X_REG, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (read(i2c_fd, buffer, 6) == 6) {
            // Combine bytes to form 16-bit values (little-endian)
            data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data->z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to log data to a CSV file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_field_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if it is
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

