#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32

// GPIO pin for interrupt
#define INT_PIN 17

// Freefall threshold (300 mg = 0.3 g)
#define FREEFALL_THRESHOLD 0x0A

// Freefall time (100 ms = 0.1 s)
#define FREEFALL_TIME 0x06

// I2C file descriptor
int i2c_fd = -1;

// GPIO line
struct gpiod_line *gpio_line = NULL;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
int adxl345_init(int i2c_fd);
int read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void freefall_callback(struct gpiod_line_event event, void *user_data);
void signal_handler(int sig);

// Structure to hold configuration data
typedef struct {
    int i2c_address;
    int gpio_pin;
    char *log_file_name;
} config_t;

// Function to initialize the ADXL345
int adxl345_init(int i2c_fd) {
    // Put the sensor in standby mode
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        perror("Error: Could not put ADXL345 in standby mode");
        return -1;
    }

    // Set the freefall threshold
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD) < 0) {
        perror("Error: Could not set freefall threshold");
        return -1;
    }

    // Set the freefall time
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_TIME_FF, FREEFALL_TIME) < 0) {
        perror("Error: Could not set freefall time");
        return -1;
    }

    // Enable the freefall interrupt
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_INT_ENABLE, 0x08) < 0) {
        perror("Error: Could not enable freefall interrupt");
        return -1;
    }

    // Map the freefall interrupt to INT1
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_INT_MAP, 0x00) < 0) {
        perror("Error: Could not map freefall interrupt to INT1");
        return -1;
    }

    // Enter measurement mode
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        perror("Error: Could not enter measurement mode");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, ADXL345_REG_DATAX0, 6, (char *)data) < 0) {
        perror("Error: Could not read acceleration data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);

    return 0;
}

// Callback function for freefall interrupt
void freefall_callback(struct gpiod_line_event event, void *user_data) {
    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        int16_t x, y, z;

        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Log the data
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data in freefall callback\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);

    // Disable interrupts
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    config_t config = {
        .i2c_address = ADXL345_ADDR,
        .gpio_pin = INT_PIN,
        .log_file_name = "freefall_log.csv"
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, config.i2c_address) < 0) {
        perror("Error: Could not set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device ID
    uint8_t device_id;
    device_id = i2c_smbus_read_byte_data(i2c_fd, 0x00);
    if (device_id != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", device_id);
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Open GPIO line
    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Error: Could not open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(chip, config.gpio_pin);
    if (!gpio_line) {
        perror("Error: Could not get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config_gpio;
    memset(&config_gpio, 0, sizeof(config_gpio));
    config_gpio.consumer = "freefall_sensor";
    config_gpio.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config_gpio, 0) < 0) {
        perror("Error: Could not request GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request falling-edge events
    if (gpiod_line_event_request(gpio_line, freefall_callback, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE) < 0) {
        perror("Error: Could not request falling-edge events");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    printf("Freefall sensor monitoring started. Press Ctrl+C to exit.\n");

    // Poll for events
    while (1) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(gpio_line, -1);
        if (ret < 0) {
            perror("Error: Could not wait for GPIO event");
            break;
        }

        if (gpiod_line_event_read(gpio_line, &event) < 0) {
            perror("Error: Could not read GPIO event");
            break;
        }

        freefall_callback(event, NULL);
    }

