#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_lsm6dsr(sensor_data_t *data);
int log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "LSM6DSR not found. WHO_AM_I = 0x%X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read data from the LSM6DSR
int read_lsm6dsr(sensor_data_t *data) {
    char raw_data[12];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, raw_data, 12) < 0) {
        fprintf(stderr, "Error reading accelerometer/gyro data\n");
        return -1;
    }

    accel_x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    accel_y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    accel_z = (int16_t)((raw_data[5] << 8) | raw_data[4]);
    gyro_x = (int16_t)((raw_data[7] << 8) | raw_data[6]);
    gyro_y = (int16_t)((raw_data[9] << 8) | raw_data[8]);
    gyro_z = (int16_t)((raw_data[11] << 8) | raw_data[10]);

    // Convert to g and dps
    data->accel_x = (float)accel_x / 16384.0f; // +-2g range
    data->accel_y = (float)accel_y / 16384.0f;
    data->accel_z = (float)accel_z / 16384.0f;
    data->gyro_x = (float)gyro_x / 131.0f;    // +-250 dps range
    data->gyro_y = (float)gyro_y / 131.0f;
    data->gyro_z = (float)gyro_z / 131.0f;

    return 0;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Function to implement fall detection
void fall_detection(sensor_data_t data) {
    static int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT
    static time_t freefall_start_time = 0;
    static float freefall_magnitude = 0.0f;
    static time_t impact_start_time = 0;
    static float impact_magnitude = 0.0f;

    float magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    switch (state) {
        case 0: // IDLE
            if (magnitude < 0.2f) {
                state = 1;
                freefall_start_time = time(NULL);
                freefall_magnitude = magnitude;
            } else if (magnitude > 2.5f) {
                state = 2;
                impact_start_time = time(NULL);
                impact_magnitude = magnitude;
            }
            break;
        case 1: // FREEFALL
            if (time(NULL) - freefall_start_time >= 1.0f) {
                if (magnitude > freefall_magnitude * 1.1f) {
                    state = 0;
                    fprintf(log_file, "FREEFALL\n");
                    fflush(log_file);
                }
            } else {
                if (magnitude < 0.2f) {
                    // Still in freefall
                } else {
                    state = 0; // Exit freefall if acceleration changes
                }
            }
            break;
        case 2: // IMPACT
            if (time(NULL) - impact_start_time >= 1.0f) {
                if (magnitude < impact_magnitude * 0.9f) {
                    state = 0;
                    fprintf(log_file, "IMPACT\n");
                    fflush(log_file);
                }
            } else {
                if (magnitude > 2.5f) {
                    // Still in impact
                } else {
                    state = 0; // Exit impact if acceleration changes
                }
            }
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_lsm6dsr(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Fall detection
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay
        gpioDelay(10000); // 10ms delay (100Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

