    static int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT
    static time_t freefall_start_time = 0;
    static float freefall_magnitude = 0.0f;
    static time_t impact_start_time = 0;
    static float impact_magnitude = 0.0f;

    float magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    switch (state) {
        case 0: // IDLE
            if (magnitude < 0.2f) {
                state = 1;
                freefall_start_time = time(NULL);
                freefall_magnitude = magnitude;
            } else if (magnitude > 2.5f) {
                state = 2;
                impact_start_time = time(NULL);
                impact_magnitude = magnitude;
            }
            break;
        case 1: // FREEFALL
            if (time(NULL) - freefall_start_time >= 1.0f) {
                if (magnitude > freefall_magnitude * 1.1f) {
                    state = 0;
                    fprintf(log_file, "FREEFALL\n");
                    fflush(log_file);
                }
            } else {
                if (magnitude < 0.2f) {
                    // Still in freefall
                } else {
                    state = 0; // Exit freefall if acceleration changes
                }
            }
            break;
        case 2: // IMPACT
            if (time(NULL) - impact_start_time >= 1.0f) {
                if (magnitude < impact_magnitude * 0.9f) {
                    state = 0;
                    fprintf(log_file, "IMPACT\n");
                    fflush(log_file);
                }
            } else {
                if (magnitude > 2.5f) {
                    // Still in impact
                } else {
                    state = 0; // Exit impact if acceleration changes
                }
            }
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_lsm6dsr(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Fall detection
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay
        gpioDelay(10000); // 10ms delay (100Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

