#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x14
#define WHO_AM_I 0x02

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factor (degrees/sec per LSB)
#define SCALE_FACTOR 0.0305

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_register(uint8_t address, int16_t *value);
int write_register(uint8_t address, uint16_t value);
int verify_who_am_i();
int read_x_gyro_rate(float *rate);
int log_data(float rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads a 16-bit register from the ADIS16266
int read_register(uint8_t address, int16_t *value) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Set MSB for read operation
    tx_buffer[0] = address | 0x80; // Read command
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine the two received bytes into a 16-bit value
    *value = (rx_buffer[1] << 8) | rx_buffer[2];

    return 0;
}

// Writes a 16-bit value to a register
int write_register(uint8_t address, uint16_t value) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Clear MSB for write operation
    tx_buffer[0] = address & 0x7F; // Write command
    tx_buffer[1] = (value >> 8) & 0xFF; // MSB
    tx_buffer[2] = value & 0xFF; // LSB

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Verifies the WHO_AM_I register
int verify_who_am_i() {
    int16_t who_am_i_value;
    if (read_register(WHO_AM_I, &who_am_i_value) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    // Check if the WHO_AM_I value is 0x3F5A (0x5A3F in little-endian)
    if (who_am_i_value != 0x3F5A) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%X (expected 0x3F5A)\n", who_am_i_value);
        return -1;
    }

    printf("WHO_AM_I verification successful: 0x%X\n", who_am_i_value);
    return 0;
}

// Reads the X_GYRO_OUT register and scales the value
int read_x_gyro_rate(float *rate) {
    int16_t raw_value;
    if (read_register(X_GYRO_OUT, &raw_value) != 0) {
        fprintf(stderr, "Error reading X_GYRO_OUT register\n");
        return -1;
    }

    // Scale the raw value to degrees/sec
    *rate = (float)raw_value * SCALE_FACTOR;
    return 0;
}

// Logs the timestamp and angular rate to a CSV file
int log_data(float rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Angular Rate (deg/s)\n");
    }
    rewind(log_file);

    float gyro_rate;

    // Main loop
    while (!terminate) {
        if (read_x_gyro_rate(&gyro_rate) == 0) {
            if (log_data(gyro_rate) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro rate\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

