#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 8.75f // degrees per second per LSB
#define SAMPLE_RATE 10000 // 10 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    while (retries > 0) {
        // Verify WHO_AM_I register
        char who_am_i;
        if (i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, &who_am_i, 1) != 1) {
            fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
            retries--;
            gpioDelay(100000); // 100 ms delay
            continue;
        }

        if (who_am_i != 0xD3) {
            fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0xD3\n", who_am_i);
            retries--;
            gpioDelay(100000); // 100 ms delay
            continue;
        }

        // Configure CTRL_REG1 (normal mode, all axes enabled)
        char ctrl_reg1_val = 0x0F;
        if (i2cWriteI2CBlockData(i2c_handle, CTRL_REG1, &ctrl_reg1_val, 1) != 1) {
            fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
            retries--;
            gpioDelay(100000); // 100 ms delay
            continue;
        }

        // Configure CTRL_REG4 (+-250 dps full-scale range)
        char ctrl_reg4_val = 0x00;
        if (i2cWriteI2CBlockData(i2c_handle, CTRL_REG4, &ctrl_reg4_val, 1) != 1) {
            fprintf(stderr, "Error writing to CTRL_REG4: %s\n", strerror(errno));
            retries--;
            gpioDelay(100000); // 100 ms delay
            continue;
        }

        printf("Gyroscope initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Gyroscope initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to degrees per second
    data.x = (float)x / 114.285f;
    data.y = (float)y / 114.285f;
    data.z = (float)z / 114.285f;

    return data;
}

// Log data to CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;

    fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", timestamp_ns, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_RATE);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

