#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define DATA_REG_BASE 0x28
#define CSV_FILE "vibration_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to write register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to read register value: %s\n", strerror(errno));
        return -1;
    }

    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write to register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;

    x_lsb = i2c_read_reg(fd, DATA_REG_BASE);
    if (x_lsb < 0) return -1;
    x_msb = i2c_read_reg(fd, DATA_REG_BASE + 1);
    if (x_msb < 0) return -1;
    y_lsb = i2c_read_reg(fd, DATA_REG_BASE + 2);
    if (y_lsb < 0) return -1;
    y_msb = i2c_read_reg(fd, DATA_REG_BASE + 3);
    if (y_msb < 0) return -1;
    z_lsb = i2c_read_reg(fd, DATA_REG_BASE + 4);
    if (z_lsb < 0) return -1;
    z_msb = i2c_read_reg(fd, DATA_REG_BASE + 5);
    if (z_msb < 0) return -1;

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: Failed to write to CSV file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int16_t x, y, z;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    while (program_running) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // 100 ms
    }

    // Close I2C bus and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

