#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;

// Flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(struct gpiod_line *line);
int log_data(int sensor1_state, int sensor2_state);
void handle_signal(int signal);
void cleanup();

// Signal handler for graceful shutdown
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line for sensor 1
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Error getting GPIO line for sensor 1");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for sensor 2
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Error getting GPIO line for sensor 2");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        return -1;
    }

    // Request GPIO line for sensor 1 as input with pull-up
    struct gpiod_line_request_config config1;
    memset(&config1, 0, sizeof(config1));
    config1.consumer = "conveyor_monitor";
    config1.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config1.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(sensor1_line, &config1, 0) < 0) {
        perror("Error requesting GPIO line for sensor 1");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        return -1;
    }

    // Request GPIO line for sensor 2 as input with pull-up
    struct gpiod_line_request_config config2;
    memset(&config2, 0, sizeof(config2));
    config2.consumer = "conveyor_monitor";
    config2.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config2.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(sensor2_line, &config2, 0) < 0) {
        perror("Error requesting GPIO line for sensor 2");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    return 0;
}

// Function to read sensor state
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Function to log data to file
int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%ld.%03ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, sensor1_state, sensor2_state);
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Conveyor belt safety system monitoring started.\n");

    // Main loop
    while (program_running) {
        // Read sensor states
        int sensor1_state = read_sensor(sensor1_line);
        int sensor2_state = read_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
            usleep(50000); // Sleep for 50ms even if there's an error
            continue;
        }

        // Log data
        if (log_data(sensor1_state, sensor2_state) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        // Check for conveyor halt condition
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor Halted!\n");
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

