#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D

// Define register addresses
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int verify_sensor_id(int fd);
int initialize_sensor(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Verify sensor ID function
int verify_sensor_id(int fd) {
    uint8_t who_am_i;
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }
    return 0;
}

// Initialize sensor function
int initialize_sensor(int fd) {
    // Standby mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        return -1;
    }
    // Set data rate to 100 Hz
    if (i2c_write_reg(fd, CTRL_REG1, 0x10) != 0) {
        fprintf(stderr, "Failed to set data rate\n");
        return -1;
    }
    // Active mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x11) != 0) {
        fprintf(stderr, "Failed to set active mode\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_reg(fd, OUT_X_MSB, data, 6) != 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]) >> 4;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 4;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 4;
    return 0;
}

// Calculate tilt angle function
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    return angle;
}

// Log data function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float tilt_angle;

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check for fall
            if (fabs(tilt_angle) > 45.0) {
                log_data(log_file, x, y, z);
            }
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

