#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28

// Metal detector threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration offsets and scales
const float x_offset = 0.0;
const float y_offset = 0.0;
const float z_offset = 0.0;
const float x_scale = 0.146;
const float y_scale = 0.146;
const float z_scale = 0.146;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int lis3mdl_init(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_mg(int16_t raw_value, float offset, float scale);
void log_data(float x, float y, float z);
void metal_detector_alert(float x, float y, float z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// LIS3MDL initialization function
int lis3mdl_init(int fd) {
    uint8_t who_am_i;
    int retries = 3;

    while (retries > 0) {
        if (i2c_read_reg(fd, WHO_AM_I, &who_am_i, 1) == 0) {
            if (who_am_i == 0x3D) {
                // WHO_AM_I check passed
                break;
            } else {
                fprintf(stderr, "WHO_AM_I check failed: 0x%02X\n", who_am_i);
            }
        } else {
            fprintf(stderr, "Failed to read WHO_AM_I register, retrying...\n");
        }
        retries--;
        usleep(100000); // Wait 100ms before retrying
    }

    if (retries == 0) {
        fprintf(stderr, "LIS3MDL initialization failed: WHO_AM_I check failed repeatedly.\n");
        return -1;
    }

    // Configure CTRL_REG1: Continuous-conversion mode, 80 Hz ODR, high-performance mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: +-4 gauss full scale, continuous conversion mode
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }

    // Configure CTRL_REG3: Continuous conversion mode
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG3\n");
        return -1;
    }

    return 0;
}

