#include <pigpio.h>

// ADXL354B Register Addresses
#define PARTID 0x01
#define RESET 0x1F
#define POWER_CTL 0x2D
#define XDATA 0x08
#define YDATA 0x0B
#define ZDATA 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg, uint8_t *data, int len);
int spi_write_register(int reg, uint8_t data);
int reset_sensor();
int check_sensor_presence();
int read_acceleration_data(int axis, int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Function to read a register via SPI
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = 0x80 | reg; // Set read bit (bit 7) and multi-byte bit (bit 6)
    memset(tx_buf + 1, 0, len); // Fill with dummy data for reading

    for (int i = 0; i < len; i++) {
        tx_buf[i + 1] = 0x00; // Dummy data for reading
    }

    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write a register via SPI
int spi_write_register(int reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear read bit (bit 7) for write
    tx_buf[1] = data;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to reset the sensor
int reset_sensor() {
    if (spi_write_register(RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to check sensor presence
int check_sensor_presence() {
    uint8_t partid;
    if (spi_read_register(PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    return 0;
}

