int read_acceleration_data(int axis, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[3];
    int reg;

    switch (axis) {
        case 0: // X axis
            reg = XDATA;
            break;
        case 1: // Y axis
            reg = YDATA;
            break;
        case 2: // Z axis
            reg = ZDATA;
            break;
        default:
            fprintf(stderr, "Invalid axis: %d\n", axis);
            return -1;
    }

    if (spi_read_register(reg, data, 3) != 0) {
        fprintf(stderr, "Failed to read acceleration data for axis %d\n", axis);
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)data[2]; // Z data is in the third byte

    return 0;
}

// Function to log data to file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (check_sensor_presence() != 0) {
        fprintf(stderr, "Sensor check failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    if (reset_sensor() != 0) {
        fprintf(stderr, "Sensor reset failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (read_acceleration_data(0, &x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

