#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCEL_SCALE 0.0025 // g/LSB

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t address, uint16_t *data);
imu_data_t read_imu_data(int handle);
void log_data(FILE *fp, struct timespec ts, imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read a register from the ADIS16362
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Set MSB for read operation
    tx_buffer[0] = (address << 1) | 0x80; // Address + MSB
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "SPI read failed for address 0x%02X\n", address);
        return -1; // Indicate failure
    }

    *data = ((uint16_t)rx_buffer[1] << 8) | (uint16_t)rx_buffer[2];
    return 0; // Indicate success
}

// Function to read IMU data
imu_data_t read_imu_data(int handle) {
    imu_data_t data;
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(handle, X_GYRO, &raw_gyro_x) != 0) {
        data.x_gyro = 0.0;
        data.y_gyro = 0.0;
        data.z_gyro = 0.0;
    } else {
        data.x_gyro = (double)((int16_t)raw_gyro_x) * GYRO_SCALE;
