#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define the GPIO chip and line number
#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_NUMBER 17

// Global variables for GPIO chip and line
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release the GPIO line if it's open
    if (line) {
        gpiod_line_release(line);
    }

    // Close the GPIO chip if it's open
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int value;
    struct timespec sleep_time;
    struct tm *timeinfo;
    char timestamp[30];

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d from chip '%s'\n", GPIO_LINE_NUMBER, GPIO_CHIP_NAME);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for input\n", GPIO_LINE_NUMBER);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Set the sleep time to 1 second
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    // Main loop to read the sensor value
    while (1) {
        // Read the GPIO line value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read GPIO line value\n");
            break; // Exit the loop on error
        }

        // Check if an obstacle is detected (LOW signal)
        if (value == 0) {
            // Get current time
            time_t rawtime;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Format the timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the self-parking sequence start
            printf("%s Self-parking sequence started\n", timestamp);

            // Simulate the self-parking sequence (sleep for 5 seconds)
            nanosleep(&sleep_time, NULL);

            // Log the self-parking sequence completion
            printf("%s Self-parking sequence completed\n", timestamp);
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

