#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define GPIO chip name
#define GPIOCHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void log_status(int sensor1_status, int sensor2_status);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Release GPIO lines
        if (sensor1_line) {
            gpiod_line_release(sensor1_line);
        }
        if (sensor2_line) {
            gpiod_line_release(sensor2_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log sensor status with timestamp
void log_status(int sensor1_status, int sensor2_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %s, Sensor 2: %s\n",
           timestamp,
           sensor1_status == 0 ? "Obstacle Detected" : "Clear",
           sensor2_status == 0 ? "Obstacle Detected" : "Clear");
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting sensor 1 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting sensor 2 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_avoidance";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor1_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor 1 line: %s\n", strerror(errno));
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(sensor2_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor 2 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_status = read_sensor(sensor1_line);
        int sensor2_status = read_sensor(sensor2_line);

        if (sensor1_status == -1 || sensor2_status == -1) {
            // Error reading sensor, exit loop
            break;
        }

        // Log sensor status
        log_status(sensor1_status, sensor2_status);

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Release GPIO lines
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

