#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 register addresses
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int initialize_fxos8700() {
    int retries = 3;
    int status;

    // Verify sensor presence
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (status >= 0 && status == 0xC7) {
            break; // Sensor found
        } else {
            fprintf(stderr, "Error: Sensor not found. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Could not find sensor. Exiting.\n");
        return -1;
    }

    // Configure accelerometer and magnetometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) { // Active mode, 100 Hz
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) { // High resolution
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x1F) < 0) { // Hybrid mode, 100 Hz
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG2, 0x20) < 0) { // +/- 4 gauss
        fprintf(stderr, "Error writing to M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and magnetometer data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 12);
        if (status == 12) {
            break; // Data read successfully
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Could not read sensor data. Exiting.\n");
        return -1;
    }

    // Combine MSB and LSB for accelerometer data
    *accel_x = ((int16_t)buffer[0] << 6) | (buffer[1] >> 2);
    *accel_y = ((int16_t)buffer[2] << 6) | (buffer[3] >> 2);
    *accel_z = ((int16_t)buffer[4] << 6) | (buffer[5] >> 2);

    // Combine MSB and LSB for magnetometer data
    *mag_x = ((int16_t)buffer[6] << 8) | buffer[7];
    *mag_y = ((int16_t)buffer[8] << 8) | buffer[9];
    *mag_z = ((int16_t)buffer[10] << 8) | buffer[11];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_fxos8700() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            printf("Accel: X=%d, Y=%d, Z=%d  Mag: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before retrying
            i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C device\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (initialize_fxos8700() < 0) {
                    fprintf(stderr, "Error: Could not re-initialize sensor\n");
                    terminate = 1;
                }
            }
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

