#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Tilt angle threshold (degrees)
#define TILT_THRESHOLD 30.0

// Log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_adxl345();
accelerometer_data_t read_accelerometer_data();
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
int log_tilt_event(double angle_x, double angle_y, double angle_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADXL345
int configure_adxl345() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate tilt angle using atan2
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double angle = atan2((double)x, sqrt((double)y * (double)y + (double)z * (double)z)) * 180.0 / M_PI;
    return angle;
}

// Log tilt event to file
int log_tilt_event(double angle_x, double angle_y, double angle_z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Tilt event: X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, angle_x, angle_y, angle_z);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADXL345
    if (configure_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Calculate tilt angles
        double angle_x = calculate_tilt_angle(data.x, 0, 0); // Z-axis is the only axis for tilt calculation
        double angle_y = calculate_tilt_angle(0, data.y, 0); // Y-axis is the only axis for tilt calculation
        double angle_z = calculate_tilt_angle(0, 0, data.z); // X-axis is the only axis for tilt calculation

        // Log tilt event if angle exceeds threshold
        if (fabs(angle_x) > TILT_THRESHOLD || fabs(angle_y) > TILT_THRESHOLD || fabs(angle_z) > TILT_THRESHOLD) {
            log_tilt_event(angle_x, angle_y, angle_z);
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

