#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define SAMPLE_DURATION_S 5
#define DEFAULT_THRESHOLD 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int high_count = 0;
    int i;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int pigpio_init_result;

    // Parse command-line argument
    if (argc > 1) {
        char *endptr;
        long parsed_threshold = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || parsed_threshold <= 0) {
            fprintf(stderr, "Error: Invalid threshold value. Please provide a positive integer.\n");
            return 1;
        }

        threshold = (int)parsed_threshold;
    }

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

