#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Define code length
#define CODE_LENGTH 6

// Define code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Global variables
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int generate_code(int *code);
int unlock_door(int door_pin);
int lock_door(int door_pin);
int check_code(int *code, const char *input);
int log_access(int code);
void signal_handler(int signum);
int initialize_gpio();
void cleanup_gpio();

// Function to generate a random 6-digit code
int generate_code(int *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Invalid code pointer in generate_code\n");
        return -1;
    }

    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0;
}

// Function to unlock a door (set GPIO pin HIGH)
int unlock_door(int door_pin) {
    if (door_pin != DOOR_A_PIN && door_pin != DOOR_B_PIN) {
        fprintf(stderr, "Error: Invalid door pin in unlock_door: %d\n", door_pin);
        return -1;
    }

    struct gpiod_line *line = (door_pin == DOOR_A_PIN) ? door_a_line : door_b_line;
    if (line == NULL) {
        fprintf(stderr, "Error: Invalid line pointer in unlock_door\n");
        return -1;
    }

    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value (unlock): %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to lock a door (set GPIO pin LOW)
int lock_door(int door_pin) {
    if (door_pin != DOOR_A_PIN && door_pin != DOOR_B_PIN) {
        fprintf(stderr, "Error: Invalid door pin in lock_door: %d\n", door_pin);
        return -1;
    }

    struct gpiod_line *line = (door_pin == DOOR_A_PIN) ? door_a_line : door_b_line;
    if (line == NULL) {
        fprintf(stderr, "Error: Invalid line pointer in lock_door\n");
        return -1;
    }

    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value (lock): %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to check if the entered code matches the generated code
int check_code(int *code, const char *input) {
    if (code == NULL || input == NULL) {
        fprintf(stderr, "Error: Invalid code or input pointer in check_code\n");
        return -1;
    }

    int entered_code = atoi(input);
    if (entered_code == *code) {
        return 0; // Code matches
    } else {
        return -1; // Code does not match
    }
}

// Function to log access to the log file
int log_access(int code) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open in log_access\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting gracefully...\n", signum);
        program_running = 0;
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return -1;
    }

    // Get GPIO line for Door A
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", DOOR_A_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for Door B
    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", DOOR_B_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        return -1;
    }

    // Request GPIO line for Door A as output
    struct gpiod_line_request_config config_a;
    memset(&config_a, 0, sizeof(config_a));
    config_a.consumer = "door_access";
    config_a.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret_a = gpiod_line_request(door_a_line, &config_a, 0);
    if (ret_a < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for Door A: %d\n", DOOR_A_PIN, ret_a);
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    // Request GPIO line for Door B as output
    struct gpiod_line_request_config config_b;
    memset(&config_b, 0, sizeof(config_b));
    config_b.consumer = "door_access";
    config_b.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret_b = gpiod_line_request(door_b_line, &config_b, 0);
    if (ret_b < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for Door B: %d\n", DOOR_B_PIN, ret_b);
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        gpiod_line_release(door_a_line);
        return -1;
    }

    // Initialize both doors to locked (LOW)
    if (lock_door(DOOR_A_PIN) < 0 || lock_door(DOOR_B_PIN) < 0) {
        fprintf(stderr, "Error: Failed to initialize doors\n");
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        gpiod_line_release(door_a_line);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    // Lock both doors
    lock_door(DOOR_A_PIN);
    lock_door(DOOR_B_PIN);

    // Release GPIO lines
    if (door_a_line) {
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_release(door_b_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Generate initial code
    int code;
    if (generate_code(&code) < 0) {
        fprintf(stderr, "Error: Code generation failed\n");
        cleanup_gpio();
        return 1;
    }

    printf("Initial code: %d\n", code);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Prompt user for code
        char input[CODE_LENGTH + 1]; // +1 for null terminator
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Error: Failed to read input\n");
            break; // Exit loop on error
        }

        // Remove trailing newline character
        input[strcspn(input, "\n")] = 0;

        // Validate input
        if (strlen(input) != CODE_LENGTH) {
            fprintf(stderr, "Error: Invalid input length\n");
            continue; // Skip to next iteration
        }

        for (int i = 0; i < CODE_LENGTH; i++) {
            if (!isdigit(input[i])) {
                fprintf(stderr, "Error: Invalid input character\n");
                continue; // Skip to next iteration
            }
        }

        // Check code
        if (check_code(&code, input) == 0) {
            printf("Access granted!\n");

            // Unlock Door A
            if (unlock_door(DOOR_A_PIN) < 0) {
                fprintf(stderr, "Error: Failed to unlock Door A\n");
            }

            // Wait for 5 seconds
            sleep(5);

            // Lock Door A
            if (lock_door(DOOR_A_PIN) < 0) {
                fprintf(stderr, "Error: Failed to lock Door A\n");
            }

            // Log access
            if (log_access(code) < 0) {
                fprintf(stderr, "Error: Failed to log access\n");
            }

            // Generate new code
            if (generate_code(&code) < 0) {
                fprintf(stderr, "Error: Code generation failed\n");
                break; // Exit loop on error
            }

            printf("New code: %d\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Cleanup
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

