#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x21
#define LUX_CONVERSION_FACTOR 1.2
#define LOG_FILE "light_log.txt"
#define MAX_RETRIES 3

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(const char *bus);
int write_i2c(int fd, uint8_t reg, uint8_t value);
int read_i2c(int fd, uint8_t reg, uint8_t *data, int len);
float read_illuminance(int fd);
void log_data(float lux);
void signal_handler(int sig);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    const char *i2c_bus;
    const char *log_file_name;
} config_t;

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
