#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PORT 12345
#define SECRET_KEY "MySecretKey"
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define MOTION_DETECTED_LENGTH (sizeof(MOTION_DETECTED_PREFIX) - 1)
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_data);
float map_touch_to_frequency(int touch_value);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);
void cleanup();

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, terminating...\n", signum);
        terminate = 1;
    }
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0F) < 0) return -1; // Touch threshold
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) return -1; // Release threshold
    }

    // Configure filter settings (example values)
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) return -1; // Set Electrode Configuration

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // Set Electrode Configuration

    // Enable the MPR121
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) return -1; // Set Electrode Configuration

    return 0;
}

// Read touch data from MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    touch_data[0] = ((buf[1] & 0x03) << 8) | buf[0];
    touch_data[1] = ((buf[3] & 0x03) << 8) | buf[2];
    touch_data[2] = ((buf[5] & 0x03) << 8) | buf[4];
    touch_data[3] = ((buf[7] & 0x03) << 8) | buf[6];
    touch_data[4] = ((buf[9] & 0x03) << 8) | buf[8];
    touch_data[5] = ((buf[11] & 0x03) << 8) | buf[10];
    touch_data[6] = ((buf[13] & 0x03) << 8) | buf[12];
    touch_data[7] = ((buf[15] & 0x03) << 8) | buf[14];
    touch_data[8] = ((buf[17] & 0x03) << 8) | buf[16];
    touch_data[9] = ((buf[19] & 0x03) << 8) | buf[18];
    touch_data[10] = ((buf[21] & 0x03) << 8) | buf[20];
    touch_data[11] = ((buf[23] & 0x03) << 8) | buf[22];

    return 0;
}

// Map touch value to frequency using logarithmic scale
float map_touch_to_frequency(int touch_value) {
    float max_touch_value = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_value > max_touch_value) {
            max_touch_value = touch_value;
        }
    }

    // Clamp max_touch_value to a reasonable range
    if (max_touch_value > 4095) max_touch_value = 4095;

    // Map to frequency range 220Hz - 880Hz
    float frequency = 220.0 * pow(2.0, (max_touch_value / 4095.0) * (log(880.0 / 220.0) / log(2.0)));
    return frequency;
}

// Play tone using hardware PWM
void play_tone(float frequency) {
    int duty_cycle = (int)((frequency / PWM_FREQUENCY) * PWM_RANGE);
    gpioPWM(GPIO_PWM, duty_cycle);
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file);
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        return;
    }
    buffer[valread] = '\0';

    if (strstr(buffer, SECRET_KEY) != NULL) {
        printf("Motion detected!\n");
        int touch_data[12];
        float frequency;

        // Play tone for 5 seconds
        for (int i = 0; i < 50; i++) { // 5 seconds * 20ms interval
            if (read_touch_data(touch_data) == 0) {
                int max_touch_value = 0;
                for (int i = 0; i < 12; i++) {
                    if (touch_data[i] > max_touch_value) {
                        max_touch_value = touch_data[i];
                    }
                }
                frequency = map_touch_to_frequency(max_touch_value);
                play_tone(frequency);
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Error reading touch data, skipping tone.\n");
            }
            gpioDelay(20); // 20ms delay
        }

        // Stop PWM
        gpioPWM(GPIO_PWM, 0);

        // Send response to client
        const char *response = "Tone played successfully.\n";
        send(client_socket, response, strlen(response), 0);
    } else {
        printf("Invalid message received.\n");
        const char *response = "Invalid message.\n";
        send(client_socket, response, strlen(response), 0);
    }
    close(client_socket);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd > 0) {
        close(server_fd);
    }
    if (new_socket > 0) {
        close(new_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO_PWM as output
    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Main loop
    while (!terminate) {
        int addrlen = sizeof(address);
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening even if accept fails
        }

        handle_client(new_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

