        // Send response to client
        const char *response = "Tone played successfully.\n";
        send(client_socket, response, strlen(response), 0);
    } else {
        printf("Invalid message received.\n");
        const char *response = "Invalid message.\n";
        send(client_socket, response, strlen(response), 0);
    }
    close(client_socket);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd > 0) {
        close(server_fd);
    }
    if (new_socket > 0) {
        close(new_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO_PWM as output
    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Main loop
    while (!terminate) {
        int addrlen = sizeof(address);
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening even if accept fails
        }

        handle_client(new_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

