#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold hard-iron offsets
typedef struct {
    float x;
    float y;
    float z;
} offsets_t;

offsets_t offsets = {0.0, 0.0, 0.0};
int offset_index = 0;
const int offset_window_size = 100;

// Function prototypes
int init_hmc5883l();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
void update_offsets(int16_t x, int16_t y, int16_t z);
void apply_offsets(int16_t x, int16_t y, int16_t z, float *corrected_x, float *corrected_y, float *corrected_z);
void print_data(float corrected_x, float corrected_y, float corrected_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the HMC5883L
int init_hmc5883l() {
    // Configuration Register A: 8-sample averaging, 15 Hz output rate, normal measurement configuration
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configuration Register B: Gain setting of 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode Register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }

    return 0;
}

// Read raw X, Y, and Z data from the HMC5883L
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update the hard-iron offsets with the latest reading
void update_offsets(int16_t x, int16_t y, int16_t z) {
    offsets.x -= offsets.x / offset_window_size;
    offsets.y -= offsets.y / offset_window_size;
    offsets.z -= offsets.z / offset_window_size;

    offsets.x += x / offset_window_size;
    offsets.y += y / offset_window_size;
    offsets.z += z / offset_window_size;

    offset_index++;
    if (offset_index >= offset_window_size) {
        offset_index = 0;
    }
}

// Apply the hard-iron offsets to the raw data
void apply_offsets(int16_t x, int16_t y, int16_t z, float *corrected_x, float *corrected_y, float *corrected_z) {
    *corrected_x = (float)x - offsets.x;
    *corrected_y = (float)y - offsets.y;
    *corrected_z = (float)z - offsets.z;
}

// Print the corrected X, Y, and Z values
void print_data(float corrected_x, float corrected_y, float corrected_z) {
    printf("X: %.2f, Y: %.2f, Z: %.2f\n", corrected_x, corrected_y, corrected_z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float corrected_x, corrected_y, corrected_z;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Update offsets
            update_offsets(raw_x, raw_y, raw_z);

            // Apply offsets
            apply_offsets(raw_x, raw_y, raw_z, &corrected_x, &corrected_y, &corrected_z);

            // Print data
            print_data(corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Delay for 500 ms
        gpioDelay(500000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

