#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define INT1_CFG 0x30
#define OUT_X_L_A 0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Accelerometer sensitivity (mg/LSB) for +-2g range
#define ACCEL_SENSITIVITY 0.061

// Interrupt threshold (mg)
#define INTERRUPT_THRESHOLD 2000

// Interrupt duration (samples)
#define INTERRUPT_DURATION 0

// I2C file descriptor
int i2c_fd = -1;

// GPIO line
struct gpiod_line *gpio_line;

// Circular buffer
int16_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int read_register(int reg);
int write_register(int reg, int value);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(int16_t x, int16_t y, int16_t z);
void print_buffer();
void interrupt_handler(struct gpiod_line_event event);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1");
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio(int pin) {
    int ret;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(chip, pin);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(gpio_line, "lsm303d_mon", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_flags(gpio_line, GPIOD_LINE_FLAG_EDGE_RISING);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line flags: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read a single register
int read_register(int reg) {
    int ret = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (ret < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return ret;
}

// Function to write a single register
int write_register(int reg, int value) {
    int ret = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    int ret = i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A, 6, (char *)data);
    if (ret < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to add acceleration data to the circular buffer
void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    buffer[buffer_index] = (x << 16) | (y << 8) | z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Timestamp: %ld.%09ld\n", (long)time(NULL), (long)time(NULL) % 1000000000);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
        int16_t raw_data = buffer[index];
        int16_t x = (raw_data >> 16) & 0x3FFF; // Mask to 14 bits
        int16_t y = (raw_data >> 8) & 0x3FFF;  // Mask to 14 bits
        int16_t z = raw_data & 0x3FFF;         // Mask to 14 bits

        // Convert to mg
        float x_mg = x * ACCEL_SENSITIVITY;
        float y_mg = y * ACCEL_SENSITIVITY;
        float z_mg = z * ACCEL_SENSITIVITY;

        printf("  %d: X: %.2f mg, Y: %.2f mg, Z: %.2f mg\n", 10 - i, x_mg, y_mg, z_mg);
    }
}

// Interrupt handler function
void interrupt_handler(struct gpiod_line_event event) {
    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        print_buffer();
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;

    // Disable accelerometer
    write_register(CTRL_REG1_A, 0x00);

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

int main() {
    // Initialize I2C
    if (init_i2c(LSM303D_ADDR) < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = read_register(WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }

    // Configure accelerometer
    if (write_register(CTRL_REG1_A, 0x57) < 0) { // 50 Hz, all axes enabled
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }
    if (write_register(CTRL_REG4_A, 0x00) < 0) { // +-2g range
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }
    if (write_register(INT1_CFG, 0x2A) < 0) { // Interrupt on any-axis-high
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }
    if (write_register(0x31, INTERRUPT_THRESHOLD / 16) < 0) { // Interrupt threshold
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }
    if (write_register(0x32, INTERRUPT_DURATION) < 0) { // Interrupt duration
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    struct gpiod_line_event_consumer consumer;
    consumer.consumer = "lsm303d_mon";
    consumer.event_handler = interrupt_handler;

    struct gpiod_line_request_config config;
    config.consumer = "lsm303d_mon";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_DRAIN_DELAY;

    int ret = gpiod_line_request(gpio_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for event: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }

    ret = gpiod_line_event_config_set(gpio_line, &consumer);
    if (ret < 0) {
        fprintf(stderr, "Error setting event config: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    struct timespec sleep_time = {0, 10000000}; // 10 ms
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
        }
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

