// Define GPIO pins
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define delay in nanoseconds
#define DELAY_NS 500000000 // 500 ms

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *solenoid1_line;
struct gpiod_line *solenoid2_line;

// Function prototypes
int initialize_gpio();
void activate_solenoid(int solenoid_number);
void deactivate_solenoid(int solenoid_number);
void cleanup_gpio();
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, cleaning up and exiting...\n", signum);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return -1;
    }

    // Get GPIO line for solenoid 1
    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", SOLENOID_1_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for solenoid 2
    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", SOLENOID_2_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(solenoid1_line);
        return -1;
    }

    // Request GPIO line for solenoid 1
    struct gpiod_line_request_config config1;
    memset(&config1, 0, sizeof(config1));
    config1.consumer = "solenoid1";
    config1.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(solenoid1_line, &config1, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", SOLENOID_1_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(solenoid2_line);
        gpiod_line_release(solenoid1_line);
        return -1;
    }

    // Request GPIO line for solenoid 2
    struct gpiod_line_request_config config2;
    memset(&config2, 0, sizeof(config2));
    config2.consumer = "solenoid2";
    config2.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(solenoid2_line, &config2, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", SOLENOID_2_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        return -1;
    }

    // Set both solenoids to LOW initially
    deactivate_solenoid(1);
    deactivate_solenoid(2);

    return 0;
}

// Function to activate a solenoid
void activate_solenoid(int solenoid_number) {
    if (solenoid_number == 1) {
        if (gpiod_line_set_value(solenoid1_line, 1) < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d high\n", SOLENOID_1_PIN);
        }
    } else if (solenoid_number == 2) {
        if (gpiod_line_set_value(solenoid2_line, 1) < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d high\n", SOLENOID_2_PIN);
        }
    } else {
        fprintf(stderr, "Error: Invalid solenoid number: %d\n", solenoid_number);
    }
}

// Function to deactivate a solenoid
void deactivate_solenoid(int solenoid_number) {
    if (solenoid_number == 1) {
        if (gpiod_line_set_value(solenoid1_line, 0) < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d low\n", SOLENOID_1_PIN);
        }
    } else if (solenoid_number == 2) {
        if (gpiod_line_set_value(solenoid2_line, 0) < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d low\n", SOLENOID_2_PIN);
        }
    } else {
        fprintf(stderr, "Error: Invalid solenoid number: %d\n", solenoid_number);
    }
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio() {
    // Deactivate both solenoids
    deactivate_solenoid(1);
    deactivate_solenoid(2);

    // Release GPIO lines
    gpiod_line_release(solenoid1_line);
    gpiod_line_release(solenoid2_line);

    // Close GPIO chip
    gpiod_chip_close(chip);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Activate solenoid 1
        activate_solenoid(1);
        struct timespec delay1;
        delay1.tv_sec = 0;
        delay1.tv_nsec = DELAY_NS;
        nanosleep(&delay1, NULL);

        // Deactivate solenoid 1 and activate solenoid 2
        deactivate_solenoid(1);
        activate_solenoid(2);
        nanosleep(&delay1, NULL);

        // Deactivate solenoid 2
        deactivate_solenoid(2);
    }

    return 0;
}

