#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for the door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define the expected code
#define EXPECTED_CODE "123456"

// Define the timeout in seconds
#define TIMEOUT_SECONDS 5

// Define the code length
#define CODE_LENGTH 6

// Global variables for UART handles
int primary_uart_handle = -1;
int secondary_uart_handle = -1;

// Function prototypes
int initialize_gpio();
int open_serial_ports();
void close_serial_ports();
void unlock_doors();
void lock_doors();
void handle_signal(int signal);
int read_code(int uart_handle, char *buffer, int buffer_size);

// Signal handler for graceful shutdown
void handle_signal(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    lock_doors();
    close_serial_ports();
    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Initialize locks to locked state (LOW)
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Function to open the serial ports
int open_serial_ports() {
    primary_uart_handle = serOpen(PRIMARY_UART, 9600, 0); // 0 for no flags
    if (primary_uart_handle < 0) {
        fprintf(stderr, "Failed to open primary UART: %s\n", strerror(errno));
        return -1;
    }

    secondary_uart_handle = serOpen(SECONDARY_UART, 9600, 0);
    if (secondary_uart_handle < 0) {
        fprintf(stderr, "Failed to open secondary UART: %s\n", strerror(errno));
        serClose(primary_uart_handle);
        return -1;
    }

    return 0;
}

// Function to close the serial ports
void close_serial_ports() {
    if (primary_uart_handle >= 0) {
        serClose(primary_uart_handle);
    }
    if (secondary_uart_handle >= 0) {
        serClose(secondary_uart_handle);
    }
}

// Function to unlock the doors
void unlock_doors() {
    gpioWrite(LOCK1_GPIO, 1);
    gpioWrite(LOCK2_GPIO, 1);
    gpioDelay(2000); // Keep unlocked for 2 seconds
    lock_doors();
}

// Function to lock the doors
void lock_doors() {
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
}

// Function to read a code from a serial port
int read_code(int uart_handle, char *buffer, int buffer_size) {
    int i = 0;
    int c;

    while (i < buffer_size - 1) {
        c = serRead(uart_handle, 1);
        if (c < 0) {
            return -1; // Error reading from UART
        } else if (c == 0) {
            // Timeout occurred
            return 0;
        } else if (c >= '0' && c <= '9') {
            buffer[i++] = (char)c;
        } else {
            // Non-digit character, reset buffer
            i = 0;
        }
    }

    buffer[i] = '\0'; // Null-terminate the string
    return 1; // Code read successfully
}

