#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME_MS 1000
#define PIR_POLLING_INTERVAL_MS 50
#define PIR_TIMEOUT_SEC 10

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int read_pir_sensor();
void activate_relay();
void deactivate_relay();
void log_message(int priority, const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        terminate = 1;
    }
}

// Initialize GPIO lines
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_message(LOG_ERR, "Failed to get relay line");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_detector";

    // Request PIR line as input
    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    // Request relay line as output
    config.consumer = "relay_controller";
    if (gpiod_line_request(relay_line, &config, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to request relay line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Activate relay
void activate_relay() {
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to activate relay");
    } else {
        log_message(LOG_INFO, "Relay activated");
    }
}

// Deactivate relay
void deactivate_relay() {
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to deactivate relay");
    } else {
        log_message(LOG_INFO, "Relay deactivated");
    }
}

// Log message to syslog
void log_message(int priority, const char *message) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Cleanup GPIO resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up GPIO resources...");
    deactivate_relay();

    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_message(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.");
        return 1;
    }

    log_message(LOG_INFO, "Motion detector started");

    time_t last_motion_time = 0;
    int motion_detected = 0;

    while (!terminate) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            // Error reading PIR sensor, continue to next iteration
            usleep(PIR_POLLING_INTERVAL_MS * 1000); // Sleep for 50ms
            continue;
        }

        if (pir_value == 1) {
            if (!motion_detected) {
                log_message(LOG_INFO, "Motion detected");
                activate_relay();
                usleep(RELAY_ON_TIME_MS * 1000); // Wait for 1 second
                deactivate_relay();
                motion_detected = 1;
                last_motion_time = time(NULL);
            }
        } else {
            motion_detected = 0;
        }

        if (motion_detected) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) > PIR_TIMEOUT_SEC) {
                log_message(LOG_WARNING, "Potential malfunction: PIR sensor continuously HIGH for too long");
                deactivate_relay();
                motion_detected = 0; // Reset motion detection
            }
        }

        usleep(PIR_POLLING_INTERVAL_MS * 1000); // Sleep for 50ms
    }

    cleanup();
    return 0;
}

