#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <math.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Accelerometer range
#define ACCEL_RANGE_2G 0x00

// Circular buffer size
#define BUFFER_SIZE 100

// Sysfs path
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"

// Global variables
int i2c_fd = -1;
int buffer_index = 0;
double buffer[BUFFER_SIZE];
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mpu6050_init(int fd);
int read_accel_data(int fd, double *x, double *y, double *z);
void buffer_add(double value);
double buffer_get_latest();
void signal_handler(int sig);
int sysfs_init();
int sysfs_write(double value);
void sysfs_cleanup();

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, ACCEL_RANGE_2G) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data function
int read_accel_data(int fd, double *x, double *y, double *z) {
    int16_t raw_x, raw_y, raw_z;

    raw_x = (int16_t)((i2c_read_reg(fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 1));
    raw_y = (int16_t)((i2c_read_reg(fd, ACCEL_YOUT_H) << 8) | i2c_read_reg(fd, ACCEL_YOUT_H + 1));
    raw_z = (int16_t)((i2c_read_reg(fd, ACCEL_ZOUT_H) << 8) | i2c_read_reg(fd, ACCEL_ZOUT_H + 1));

    *x = (double)raw_x / 16384.0;
    *y = (double)raw_y / 16384.0;
    *z = (double)raw_z / 16384.0;

    return 0;
}

// Circular buffer add function
void buffer_add(double value) {
    buffer[buffer_index] = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Circular buffer get latest function
double buffer_get_latest() {
    int latest_index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer[latest_index];
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Sysfs initialization function
int sysfs_init() {
    // Create the directory if it doesn't exist
    if (mkdir("/sys/kernel", 0755) == -1 && errno != EEXIST) {
        perror("Failed to create /sys/kernel directory");
        return -1;
    }

    // Create the file if it doesn't exist
    FILE *fp = fopen(SYSFS_PATH, "w");
    if (fp == NULL) {
        perror("Failed to open sysfs file for writing");
        return -1;
    }
    fclose(fp);

    // Set permissions
    if (chmod(SYSFS_PATH, 0666) == -1) {
        perror("Failed to set permissions on sysfs file");
        return -1;
    }

    return 0;
}

// Sysfs write function
int sysfs_write(double value) {
    FILE *fp = fopen(SYSFS_PATH, "w");
    if (fp == NULL) {
        perror("Failed to open sysfs file for writing");
        return -1;
    }
    fprintf(fp, "%lf", value);
    fclose(fp);
    return 0;
}

// Sysfs cleanup function
void sysfs_cleanup() {
    // Remove the file
    if (remove(SYSFS_PATH) == -1) {
        perror("Failed to remove sysfs file");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize sysfs
    if (sysfs_init() < 0) {
        fprintf(stderr, "Sysfs initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Create timer
    struct sigevent sev;
    struct itimerspec its;
    struct sigaction sa;

