#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_line_t;

// Global variables
static volatile sig_atomic_t keep_running = 1;
static gpio_line_t relay_lines[4];
static struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int initialize_gpio(gpio_line_t *relay_lines);
int set_relay_state(gpio_line_t *relay_lines, int relay_number, int state);
void toggle_relay(gpio_line_t *relay_lines, int relay_number);
void cleanup_gpio(gpio_line_t *relay_lines);
void signal_handler(int sig);
void cleanup_handler(int sig);

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;
    }
}

// Signal handler for SIGTERM (cleanup)
void cleanup_handler(int sig) {
    printf("Cleaning up GPIO resources...\n");
    cleanup_gpio(relay_lines);
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_line_t *relay_lines) {
    int i;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Configure the GPIO lines for output
    for (i = 0; i < 4; i++) {
        // Get the GPIO line
        relay_lines[i].line = gpiod_chip_get_line(gpio_chip, i + RELAY1_PIN);
        if (!relay_lines[i].line) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        // Configure the line for output
        memset(&config, 0, sizeof(config));
        config.consumer = "relay_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(relay_lines[i].line, &config, 0) < 0) {
            perror("Error requesting GPIO line for output");
            goto cleanup;
        }

        // Initialize the line to LOW (off)
        if (gpiod_line_set_value(relay_lines[i].line, 0) < 0) {
            perror("Error setting initial GPIO line value");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    // Clean up any previously initialized lines
    for (i = 0; i < 4; i++) {
        if (relay_lines[i].line) {
            gpiod_line_release(relay_lines[i].line);
        }
    }
    gpiod_chip_close(gpio_chip);
    return -1;
}

// Function to set the state of a relay
int set_relay_state(gpio_line_t *relay_lines, int relay_number, int state) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }

    if (gpiod_line_set_value(relay_lines[relay_number - 1].line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Function to toggle a relay
void toggle_relay(gpio_line_t *relay_lines, int relay_number) {
    int current_state = gpiod_line_get_value(relay_lines[relay_number - 1].line);
    if (current_state < 0) {
        perror("Error getting GPIO line value");
        return;
    }
    set_relay_state(relay_lines, relay_number, !current_state);
}

// Function to cleanup GPIO resources
void cleanup_gpio(gpio_line_t *relay_lines) {
    int i;

    // Release the GPIO lines
    for (i = 0; i < 4; i++) {
        if (relay_lines[i].line) {
            gpiod_line_release(relay_lines[i].line);
        }
    }

    // Close the GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    struct timespec sleep_time1, sleep_time2, sleep_time3, sleep_time4;
    struct timespec remaining_time;
    struct timespec current_time;
    int i;

    // Initialize the relay lines
    for (i = 0; i < 4; i++) {
        relay_lines[i].line = NULL; // Initialize to NULL
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(relay_lines) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set up sleep times (in nanoseconds)
    sleep_time1.tv_sec = 0;
    sleep_time1.tv_nsec = 2000000000; // 2 seconds

    sleep_time2.tv_sec = 0;
    sleep_time2.tv_nsec = 3000000000; // 3 seconds

    sleep_time3.tv_sec = 0;
    sleep_time3.tv_nsec = 5000000000; // 5 seconds

    sleep_time4.tv_sec = 0;
    sleep_time4.tv_nsec = 7000000000; // 7 seconds

    // Main loop
    while (keep_running) {
        // Toggle relay 1 every 2 seconds
        toggle_relay(relay_lines, 1);
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        nanosleep(&sleep_time1, &remaining_time);

        // Toggle relay 2 every 3 seconds
        toggle_relay(relay_lines, 2);
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        nanosleep(&sleep_time2, &remaining_time);

        // Toggle relay 3 every 5 seconds
        toggle_relay(relay_lines, 3);
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        nanosleep(&sleep_time3, &remaining_time);

        // Toggle relay 4 every 7 seconds
        toggle_relay(relay_lines, 4);
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        nanosleep(&sleep_time4, &remaining_time);
    }

    // Clean up GPIO resources
    cleanup_gpio(relay_lines);

    return 0;
}

