#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define sound threshold (HIGH)
#define SOUND_THRESHOLD 1

// Define cooldown time (milliseconds)
#define COOLDOWN_TIME 500

// Global variables
static volatile int relay_active = 0; // Flag to track relay state
static FILE *log_file = NULL;          // File pointer for the log file

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm();
void cooldown();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sound sensor pin as input
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially off
    gpioWrite(RELAY_PIN, 0);

    return 0; // Indicate success
}

// Read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay for 3 seconds
void activate_relay() {
    if (!relay_active) {
        gpioWrite(RELAY_PIN, 1); // Turn on the relay
        relay_active = 1;         // Set the relay active flag
        printf("Relay activated\n");
    }
}

