#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for +-250 dps range
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity magnitude
#define THRESHOLD 50.0

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Function prototypes
int i2c_init(int bus);
int mpu6050_init(int fd);
int mpu6050_read_gyro_data(int fd, gyro_data_t *data);
float calculate_magnitude(gyro_data_t data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(float magnitude);
void callback_function();
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int i2c_init(int bus) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep bit
    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Verify WHO_AM_I register
    data[0] = WHO_AM_I;
    if (write(fd, data, 1) != 1) {
        perror("Error writing to WHO_AM_I");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Error reading WHO_AM_I");
        return -1;
    }

    if (data[0] != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x68\n", data[0]);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int mpu6050_read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    uint8_t reg = GYRO_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to register");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading data");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (buffer[0] << 8) | buffer[1];
    int16_t gyro_y = (buffer[2] << 8) | buffer[3];
    int16_t gyro_z = (buffer[4] << 8) | buffer[5];

    // Convert to degrees per second
    data->x = (float)gyro_x / GYRO_SENSITIVITY;
    data->y = (float)gyro_y / GYRO_SENSITIVITY;
    data->z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Function to check if the magnitude exceeds the threshold
int check_threshold(float magnitude) {
    return (magnitude > THRESHOLD) ? 1 : 0;
}

// Callback function
void callback_function() {
    printf("Threshold exceeded! Magnitude: %.2f deg/s\n", THRESHOLD);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(1);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_t buffer = {{0.0, 0.0, 0.0}, 0, 0, 0};

    // Main loop
    gyro_data_t gyro_data;
    while (program_running) {
        // Read gyroscope data
        if (mpu6050_read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Calculate magnitude
            float magnitude = calculate_magnitude(gyro_data);

            // Add data to buffer
            add_to_buffer(&buffer, gyro_data);

            // Check threshold
            if (check_threshold(magnitude)) {
                callback_function();
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Delay
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

