int initialize_pigpio();
int open_serial_port();
int send_command(int uart_handle, unsigned char *command, int command_size);
int read_response(int uart_handle, unsigned char *response, int response_size);
int validate_checksum(unsigned char *response, int response_size);
int extract_co2_ppm(unsigned char *response);
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);
void close_resources();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to open the serial port
int open_serial_port() {
    int handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (handle < 0) {
        log_error("Failed to open serial port");
        return -1;
    }
    return handle;
}

// Function to send a command to the sensor
int send_command(int uart_handle, unsigned char *command, int command_size) {
    if (serWrite(uart_handle, (char *)command, command_size) != command_size) {
        log_error("Failed to send command");
        return -1;
    }
    return 0;
}

// Function to read a response from the sensor
int read_response(int uart_handle, unsigned char *response, int response_size) {
    int bytes_read = 0;
    int start_time = time_time();
    while (bytes_read < response_size) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int to_read = (available > (response_size - bytes_read)) ? (response_size - bytes_read) : available;
            if (serRead(uart_handle, (char *)(response + bytes_read), to_read) != to_read) {
                log_error("Failed to read from serial port");
                return -1;
            }
            bytes_read += to_read;
        } else {
            // Wait for 10ms
            gpioDelay(10000); // 10000 microseconds = 10 milliseconds
            if (time_time() - start_time > 1000) { // Timeout after 1 second
                log_error("Timeout reading from serial port");
                return -1;
            }
        }
    }
    return 0;
}

// Function to validate the checksum
int validate_checksum(unsigned char *response, int response_size) {
    unsigned char checksum = 0;
    for (int i = 0; i < CHECKSUM_OFFSET; i++) {
        checksum ^= response[i];
    }
    if (checksum != response[CHECKSUM_OFFSET]) {
        log_error("Checksum mismatch");
        return -1;
    }
    return 0;
}

// Function to extract CO2 concentration from the response
int extract_co2_ppm(unsigned char *response) {
    return (response[2] << 8) | response[3];
}

// Function to log the data to a JSON file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(co2_log_fp, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, data.co2_ppm, data.error_flag);
    fflush(co2_log_fp);
    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, data.co2_ppm, data.error_flag);
    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_log_fp, "%s: %s\n", timestamp, message);
    fflush(error_log_fp);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to close resources
void close_resources() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (co2_log_fp != NULL) {
        fclose(co2_log_fp);
    }
    if (error_log_fp != NULL) {
        fclose(error_log_fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open serial port
    uart_handle = open_serial_port();
    if (uart_handle < 0) {
        close_resources();
        return 1;
    }

    // Open log files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
        log_error("Failed to open co2_log.json");
        close_resources();
        return 1;
    }

    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_log_fp == NULL) {
        log_error("Failed to open co2_error.log");
        close_resources();
        return 1;
    }

    // Main loop
    while (running) {
        unsigned char read_command[READ_COMMAND_SIZE] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
        unsigned char response[RESPONSE_SIZE];
        sensor_data_t sensor_data;

        // Send read command
        if (send_command(uart_handle, read_command, READ_COMMAND_SIZE) != 0) {
            sensor_data.co2_ppm = -1; // Indicate error
            sensor_data.error_flag = 1;
        } else {
            // Read response
            if (read_response(uart_handle, response, RESPONSE_SIZE) != 0) {
                sensor_data.co2_ppm = -1; // Indicate error
                sensor_data.error_flag = 1;
            } else {
                // Validate checksum
                if (validate_checksum(response, RESPONSE_SIZE) != 0) {
                    sensor_data.co2_ppm = -1; // Indicate error
                    sensor_data.error_flag = 1;
                } else {
                    // Extract CO2 concentration
                    sensor_data.co2_ppm = extract_co2_ppm(response);
                    sensor_data.error_flag = 0;
                }
            }
        }

        // Log data
        log_data(sensor_data);

        // Wait 5 seconds
        gpioDelay(5000000); // 5000000 microseconds = 5 seconds
    }

    // Close resources before exiting
    close_resources();

    return 0;
}

