#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define GPIO_PIN 17

// Global variables
int i2c_handle;
double x_offset = 100.0;
double y_offset = -50.0;
double buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
double compensate_heading(int16_t x, int16_t y);
int check_deviation(double compensated_heading);
void update_buffer(double heading);
void signal_handler(int signal);
void cleanup();

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize HMC5883L
    if (init_hmc5883l() != 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        magnetometer_data_t data;
        int16_t x, y, z;
        double compensated_heading;

        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
            continue; // Retry
        }

        // Compensate heading
        compensated_heading = compensate_heading(x, y);

        // Check deviation
        if (check_deviation(compensated_heading)) {
            gpioWrite(GPIO_PIN, 1); // Set GPIO high
        } else {
            gpioWrite(GPIO_PIN, 0); // Set GPIO low
        }

        // Update buffer
        update_buffer(compensated_heading);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configure register 0x00 (CONFIG_A)
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) != 0) {
        fprintf(stderr, "Error writing to CONFIG_A\n");
        return 1;
    }

    // Configure register 0x01 (CONFIG_B)
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) != 0) {
        fprintf(stderr, "Error writing to CONFIG_B\n");
        return 1;
    }

    // Configure register 0x02 (MODE)
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) != 0) {
        fprintf(stderr, "Error writing to MODE\n");
        return 1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_START, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return 1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Compensate heading
double compensate_heading(int16_t x, int16_t y) {
    double compensated_x = (double)x - x_offset;
    double compensated_y = (double)y - y_offset;
    return atan2(compensated_y, compensated_x) * 180 / M_PI;
}

// Check deviation
int check_deviation(double compensated_heading) {
    double deviation = fabs(compensated_heading - TARGET_HEADING);
    if (deviation > 180.0) {
        deviation = 360.0 - deviation; // Handle wrap-around
    }
    return (deviation > DEVIATION_THRESHOLD);
}

// Update circular buffer
void update_buffer(double heading) {
    buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    i2cClose(i2c_handle);
    gpioTerminate();
}

