#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_LOW 50
#define LUX_MEDIUM 150
#define LUX_HIGH 300

// Define log file path
#define LOG_FILE "lighting_log.txt"

// Global variables
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
float read_lux(void);
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    red_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request(red_line, "lighting", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for RED relay");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request(green_line, "lighting", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for GREEN relay");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request(blue_line, "lighting", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for BLUE relay");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize I2C bus
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Set BH1750 to continuous high-resolution mode
    uint8_t config_cmd = 0x10;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    // Wait for first conversion (at least 120 ms)
    usleep(120000);

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux(void) {
    uint8_t buffer[2];
    int ret;

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1.0;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_LOW) {
        red_state = 1;
    } else if (lux < LUX_MEDIUM) {
        green_state = 1;
    } else if (lux < LUX_HIGH) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpiod_line_set_value(red_line, red_state);
    gpiod_line_set_value(green_line, green_state);
    gpiod_line_set_value(blue_line, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file);
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");

    // Turn off all relays
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);

    // Close I2C device
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started.\n");

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value.\n");
        } else {
            control_relays(lux);
            log_data(lux, gpiod_line_get_value(red_line), gpiod_line_get_value(green_line), gpiod_line_get_value(blue_line));
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

