#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Distance range
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Function prototypes
int map_distance_to_pwm(int distance);
void set_motor_direction(int motor, int direction);
void set_motor_pwm(int motor, int pwm_value);
void control_motor(int motor, int distance);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main(int argc, char *argv[]) {
    int distance_a, distance_b;

    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (program_running) {
        // Control Motor A
        control_motor(0, distance_a);

        // Control Motor B
        control_motor(1, distance_b);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop motors
    set_motor_direction(0, 0); // Motor A
    set_motor_direction(1, 0); // Motor B

    // Clean up pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to map distance to PWM duty cycle
int map_distance_to_pwm(int distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to PWM duty cycle (0-255)
    return 255 - (int)(((float)(distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 255.0);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    int in1, in2, in3, in4;

    if (motor == 0) {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
        in3 = -1; // Not used for Motor A
        in4 = -1; // Not used for Motor A
    } else {
        in1 = -1; // Not used for Motor B
        in2 = -1; // Not used for Motor B
        in3 = MOTOR_B_IN3;
        in4 = MOTOR_B_IN4;
    }

    if (direction == 1) { // Forward
        if (in1 >= 0) gpioWrite(in1, 1);
        if (in2 >= 0) gpioWrite(in2, 0);
        if (in3 >= 0) gpioWrite(in3, 1);
        if (in4 >= 0) gpioWrite(in4, 0);
    } else { // Backward
        if (in1 >= 0) gpioWrite(in1, 0);
        if (in2 >= 0) gpioWrite(in2, 1);
        if (in3 >= 0) gpioWrite(in3, 0);
        if (in4 >= 0) gpioWrite(in4, 1);
    }
}

// Function to set motor PWM duty cycle
void set_motor_pwm(int motor, int pwm_value) {
    int in1, in2, in3, in4;

    if (motor == 0) {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
        in3 = -1; // Not used for Motor A
        in4 = -1; // Not used for Motor A
    } else {
        in1 = -1; // Not used for Motor B
        in2 = -1; // Not used for Motor B
        in3 = MOTOR_B_IN3;
        in4 = MOTOR_B_IN4;
    }

    if (in1 >= 0) gpioPWM(in1, pwm_value);
    if (in2 >= 0) gpioPWM(in2, pwm_value);
    if (in3 >= 0) gpioPWM(in3, pwm_value);
    if (in4 >= 0) gpioPWM(in4, pwm_value);
}

// Function to control a motor based on distance
void control_motor(int motor, int distance) {
    int pwm_value = map_distance_to_pwm(distance);
    int direction;

    if (distance < 50) {
        direction = 1; // Forward
    } else {
        direction = 0; // Backward
    }

    set_motor_direction(motor, direction);
    set_motor_pwm(motor, pwm_value);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Stopping motors and cleaning up...\n", signal);
    program_running = 0; // Stop the main loop
    set_motor_direction(0, 0); // Motor A
    set_motor_direction(1, 0); // Motor B
    gpioTerminate(); // Clean up pigpio
    exit(0); // Exit the program
}

