                if (step_sequence[j][2]) gpioWrite(IN3, 1);
                else gpioWrite(IN3, 0);
                if (step_sequence[j][3]) gpioWrite(IN4, 1);
                else gpioWrite(IN4, 0);
                gpioDelay(INTER_STEP_DELAY);
            }
        }
    }
}

// Function to handle button presses
void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick < 50000) return; // 50ms debounce
    last_tick = current_tick;

    if (gpio == LOCK_BUTTON && level == 0) { // Button pressed (active low)
        lock_door();
    } else if (gpio == UNLOCK_BUTTON && level == 0) { // Button pressed (active low)
        unlock_door();
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN1 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN2 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN3 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN4 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON as input\n");
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistors for the buttons
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Set up callback functions for button presses
    gpioSetAlertFunc(LOCK_BUTTON, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON, button_callback);

    printf("Automatic Door Lock System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100000); // Sleep for 0.1 seconds
    }

    return 0;
}

