#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_RANGE 2000
#define PWM_FREQUENCY 50
#define LOG_FILE "solar_tracker.log"
#define RETRY_DELAY_BASE 100000 // 100ms in microseconds
#define MAX_RETRIES 5
#define TILT_THRESHOLD 10.0 // degrees

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *pitch, float *roll);
int calculate_servo_position(float pitch, float roll);
int set_servo_position(int position);
int log_data(float pitch, float roll, int servo_position);
void signal_handler(int signal);

// Exponential backoff retry function
int retry_i2c(int (*func)(), int max_retries, int delay_base) {
    int retries = 0;
    int delay = delay_base;
    int result = -1;

    while (retries < max_retries) {
        result = func();
        if (result == 0) {
            return 0; // Success
        }

        fprintf(stderr, "I2C error, retrying (%d/%d)...\n", retries + 1, max_retries);
        usleep(delay);
        delay *= 2; // Exponential backoff
        retries++;
    }

    fprintf(stderr, "I2C error: max retries reached\n");
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_position;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (retry_i2c((int(*)())read_raw_data, MAX_RETRIES, RETRY_DELAY_BASE) == 0) {
            // Process sensor data
            process_sensor_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, &pitch, &roll);

            // Calculate servo position
            servo_position = calculate_servo_position(pitch, roll);

            // Set servo position
            if (set_servo_position(servo_position) != 0) {
                fprintf(stderr, "Error setting servo position\n");
            }

            // Log data
            if (log_data(pitch, roll, servo_position) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_mpu6050() {
    // Wake up the MPU6050 (set sleep bit to 0)
    if (retry_i2c((int(*)())(void*)write_byte_data, MAX_RETRIES, RETRY_DELAY_BASE, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }

    return 0;
}

int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    if (read(i2c_fd, buf, 14) != 14) {
        perror("Error reading sensor data");
        return -1;
    }

    *accel_x = (buf[0] << 8) | buf[1];
    *accel_y = (buf[2] << 8) | buf[3];
    *accel_z = (buf[4] << 8) | buf[5];
    *gyro_x = (buf[8] << 8) | buf[9];
    *gyro_y = (buf[10] << 8) | buf[11];
    *gyro_z = (buf[12] << 8) | buf[13];

    return 0;
}

void process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *pitch, float *roll) {
    // Convert raw data to degrees per second and degrees
    float accel_x_g = (float)accel_x / 16384.0; // Assuming sensitivity of +/- 2g
    float accel_y_g = (float)accel_y / 16384.0;
    float accel_z_g = (float)accel_z / 16384.0;
    float gyro_x_dps = (float)gyro_x / 131.0; // Assuming sensitivity of 250 dps
    float gyro_y_dps = (float)gyro_y / 131.0;
    float gyro_z_dps = (float)gyro_z / 131.0;

    // Calculate pitch and roll using accelerometer data
    *pitch = atan2(accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
    *roll = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * 180 / M_PI;
}

int calculate_servo_position(float pitch, float roll) {
    // Simple proportional control based on tilt angles
    int servo_position = 1500; // Initial position (center)
    int pitch_offset = (int)(TILT_THRESHOLD * (pitch / TILT_THRESHOLD));
    int roll_offset = (int)(TILT_THRESHOLD * (roll / TILT_THRESHOLD));

    servo_position += pitch_offset + roll_offset;

    // Clamp servo position to valid range
    if (servo_position < 1000) {
        servo_position = 1000;
    } else if (servo_position > 2000) {
        servo_position = 2000;
    }

    return servo_position;
}

int set_servo_position(int position) {
    char buf[4];
    buf[0] = 0x10; // PWM control register
    buf[1] = (position >> 8) & 0xFF; // MSB
    buf[2] = position & 0xFF;      // LSB

    if (write(i2c_fd, buf, 3) != 3) {
        perror("Error writing to servo control register");
        return -1;
    }

    return 0;
}

int log_data(float pitch, float roll, int servo_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}
int write_byte_data(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

