#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 100

// Define sunrise/sunset duration
#define SUNRISE_SUNSET_DURATION 1800 // seconds

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Global variables
FILE *schedule_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_schedule();
void set_relay_state(int relay_number, int state);
void fade_brightness(int relay_number, int target_brightness);
void handle_schedule_entry(const char *schedule_entry);
void signal_handler(int signal);
void cleanup();

// Structure to hold schedule entries
typedef struct {
    char time[7];
    int relay_number;
    int state;
} schedule_entry_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    gpioSetPWMrange(RELAY1_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY2_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY3_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY4_GPIO, PWM_RANGE);

    return 0;
}

// Function to read the schedule from the file
int read_schedule() {
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        // Parse the line
        char time_str[7];
        int relay_number;
        char state_str[5];

        if (sscanf(line, "%6s %d %4s", time_str, &relay_number, state_str) != 3) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            continue; // Skip invalid entries
        }

        // Convert state string to integer
        int state = (strcmp(state_str, "ON") == 0) ? 1 : 0;

        // Store the schedule entry
        handle_schedule_entry(line);
    }

    fclose(schedule_file);
    return 0;
}

// Function to handle a single schedule entry
void handle_schedule_entry(const char *schedule_entry) {
    char time_str[7];
    int relay_number;
    char state_str[5];

    if (sscanf(schedule_entry, "%6s %d %4s", time_str, &relay_number, state_str) != 3) {
        fprintf(stderr, "Invalid schedule entry: %s", schedule_entry);
        return;
    }

    // Convert state string to integer
    int state = (strcmp(state_str, "ON") == 0) ? 1 : 0;

    // Set the relay state
    set_relay_state(relay_number, state);
}

// Function to set the state of a relay
void set_relay_state(int relay_number, int state) {
    int gpio_pin;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(gpio_pin, state);
}

// Function to fade the brightness of a lamp
void fade_brightness(int relay_number, int target_brightness) {
    int gpio_pin;
