#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the color of the RGB LED
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a simulated proximity value (sine wave)
float generate_proximity_value() {
    static float time = 0.0;
    time += 0.01; // Increment time by 0.01 seconds
    return sin(time * 2 * M_PI); // Sine wave between -1 and 1
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Color-based proximity alert simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate proximity value
        float proximity = generate_proximity_value();

        // Map proximity value to RGB color components
        int red   = (int)(proximity * 255);   // Red component
        int green = (int)(proximity * 255);   // Green component
        int blue  = (int)(proximity * 255);   // Blue component

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

