        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert gyroscope data
            convert_gyro_data(gyro_x, gyro_y, gyro_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            if (log_data(log_file, gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

