#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody frequencies (Hz)
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int playing = 0; // Flag to control melody playback
volatile int button_pressed = 0; // Flag to indicate button press
volatile unsigned long last_press_time = 0; // Time of last button press

// Function prototypes
void play_melody();
void stop_melody();
void button_interrupt(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Function to play the melody
void play_melody() {
    playing = 1;
    for (int i = 0; i < melody_length && playing; i++) {
        gpioHardwarePWM(BUZZER_PIN, melody[i], 1500000); // 50% duty cycle
        gpioDelay(500000); // Wait for 0.5 seconds
    }
    playing = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the buzzer
}

// Function to stop the melody
void stop_melody() {
    playing = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the buzzer
}

// Interrupt handler for the button
void button_interrupt(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 0) { // Button pressed (active-low)
        unsigned long current_time = gpioTick();
        if (current_time - last_press_time > 50000) { // Debounce
            button_pressed = 1;
            last_press_time = current_time;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody(); // Stop the melody
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set interrupt handler for the button
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell system started. Press the button to play the melody.\n");

    // Main loop
    while (1) {
        if (button_pressed && !playing) {
            play_melody();
            button_pressed = 0; // Reset the flag
        }
        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    return 0; // This line will never be reached due to the infinite loop
}

