#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Structure to hold the sliding window
typedef struct {
    int events[WINDOW_SIZE];
    int count;
} EventWindow;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
void log_event(int value);
void earthquake_alert(void);
void signal_handler(int sig);
void cleanup(void);
char* iso8601_timestamp(void);

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Log event to file
void log_event(int value) {
    char *timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d\n", timestamp, value);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
    free(timestamp);
}

// Earthquake alert
void earthquake_alert(void) {
    char *timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
    free(timestamp);
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Get ISO 8601 timestamp
char* iso8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    EventWindow window = {{0}, 0};

    // Main loop
    while (!terminate) {
        int value = read_sensor();
        if (value < 0) {
            break; // Exit loop on error
        }

        // Update sliding window
        window.events[window.count] = value;
        window.count = (window.count + 1) % WINDOW_SIZE;

        // Check for earthquake alert
        int high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (window.events[i] == 1) {
                high_count++;
            }
        }

        if (high_count >= 3) {
            earthquake_alert();
        }

        // Log event
        log_event(value);

        // Wait for the next event
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = timeout_ms * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

