#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_I2C_ADDR 0x1E

// Magnetometer registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_L_M 0x03
#define OUT_X_H_M 0x04
#define OUT_Y_L_M 0x05
#define OUT_Y_H_M 0x06
#define OUT_Z_L_M 0x07
#define OUT_Z_H_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
#define N 0
#define NE 1
#define E 2
#define SE 3
#define S 4
#define SW 5
#define W 6
#define NW 7

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float calibrated_x, float calibrated_y);
void determine_compass_direction(float heading);
void log_data(FILE *fp, float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %d\n", reg);
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading register value: %d\n", reg);
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register: %d\n", reg);
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = i2c_read_reg(fd, OUT_X_L_M);
    x_h = i2c_read_reg(fd, OUT_X_H_M);
    y_l = i2c_read_reg(fd, OUT_Y_L_M);
    y_h = i2c_read_reg(fd, OUT_Y_H_M);
    z_l = i2c_read_reg(fd, OUT_Z_L_M);
    z_h = i2c_read_reg(fd, OUT_Z_H_M);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        return -1;
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Calibrate data
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Calculate heading
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2f(calibrated_y, calibrated_x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Determine compass direction
void determine_compass_direction(float heading) {
    int direction_index;
    if (heading >= 337.5 || heading < 22.5) {
        direction_index = N;
    } else if (heading >= 22.5 && heading < 67.5) {
        direction_index = NE;
    } else if (heading >= 67.5 && heading < 112.5) {
        direction_index = E;
    } else if (heading >= 112.5 && heading < 157.5) {
        direction_index = SE;
    } else if (heading >= 157.5 && heading < 202.5) {
        direction_index = S;
    } else if (heading >= 202.5 && heading < 247.5) {
        direction_index = SW;
    } else if (heading >= 247.5 && heading < 292.5) {
        direction_index = W;
    } else {
        direction_index = NW;
    }

    const char *directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    printf("Compass Direction: %s, Heading: %.2f degrees\n", directions[direction_index], heading);
}

// Log data to CSV file
void log_data(FILE *fp, float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure magnetometer (Continuous conversion mode, 15 Hz output data rate)
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calibrate data
            calibrate_data(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Determine compass direction
            determine_compass_direction(heading);

            // Log data
            log_data(log_file, calibrated_x, calibrated_y, calibrated_z, heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        sleep(1);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

