// Global variables
static volatile unsigned long last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state();
void debounce_touch();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int touch_pin;
    int relay_pin;
    int debounce_ms;
    char *log_file_name;
} Config;

Config config = {TOUCH_SENSOR_PIN, RELAY_PIN, DEBOUNCE_TIME, "relay_log.json"};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_touch_sensor()) {
            debounce_touch();
        }
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input with pull-down resistor
    gpioSetMode(config.touch_pin, PI_INPUT);
    gpioSetPullUpDown(config.touch_pin, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(config.relay_pin, PI_OUTPUT);
    gpioWrite(config.relay_pin, 0); // Initialize relay to OFF state

    // Set up interrupt on touch sensor pin
    if (gpioSetISRFunc(config.touch_pin, RISING_EDGE, 0, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(config.touch_pin);
}

// Toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(config.relay_pin, relay_state);
    log_relay_state();
}

// Log the relay state to a JSON object with ISO 8601 timestamp
void log_relay_state() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char json_string[100];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(json_string, sizeof(json_string), "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");

    if (fputs(json_string, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file); // Ensure data is written to disk
}

// Debounce the touch sensor reading
void debounce_touch() {
    unsigned long current_time = gpioTick();

    if (current_time - last_touch_time > config.debounce_ms * 1000) {
        toggle_relay();
        last_touch_time = current_time;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting.\n");
    cleanup();
    exit(0);
}

// Cleanup function to turn off relay and close log file
void cleanup() {
    gpioWrite(config.relay_pin, 0); // Turn off relay
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

