#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define relay activation duration (seconds)
#define RELAY_DURATION 5

// Define delay between relays (seconds)
#define RELAY_DELAY 1

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
int read_moisture(void);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO lines
int setup_gpio(void) {
    int ret = 0;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request GPIO lines
    lines[0] = gpiod_chip_get_line(chip, GPIO17);
    lines[1] = gpiod_chip_get_line(chip, GPIO23);
    lines[2] = gpiod_chip_get_line(chip, GPIO24);
    lines[3] = gpiod_chip_get_line(chip, GPIO25);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        ret = -1;
        goto cleanup_lines;
    }

    // Set GPIO line direction to output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "irrigation_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(lines[0], &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO17, strerror(errno));
        ret = -1;
        goto cleanup_lines;
    }

    ret = gpiod_line_request(lines[1], &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO23, strerror(errno));
        ret = -1;
        goto cleanup_lines;
    }

    ret = gpiod_line_request(lines[2], &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO24, strerror(errno));
        ret = -1;
        goto cleanup_lines;
    }

    ret = gpiod_line_request(lines[3], &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO25, strerror(errno));
        ret = -1;
        goto cleanup_lines;
    }

    return 0;

cleanup_lines:
    if (lines[0]) gpiod_line_release(lines[0]);
    if (lines[1]) gpiod_line_release(lines[1]);
    if (lines[2]) gpiod_line_release(lines[2]);
    if (lines[3]) gpiod_line_release(lines[3]);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

// Read simulated soil moisture value
int read_moisture(void) {
    return rand() % 101;
}

// Activate relay
void activate_relay(int relay_number) {
    if (lines[relay_number - 1]) {
        int ret = gpiod_line_set_value(lines[relay_number - 1], 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value to 0: %s\n", relay_number, strerror(errno));
        }
    } else {
        fprintf(stderr, "Error: Relay %d not initialized.\n", relay_number);
    }
}

// Deactivate relay
void deactivate_relay(int relay_number) {
    if (lines[relay_number - 1]) {
        int ret = gpiod_line_set_value(lines[relay_number - 1], 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value to 1: %s\n", relay_number, strerror(errno));
        }
    } else {
        fprintf(stderr, "Error: Relay %d not initialized.\n", relay_number);
    }
}

// Log event to file
void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Relay %d, Moisture %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);
}

// Cleanup function
void cleanup(void) {
    fprintf(stderr, "Cleaning up...\n");

    // Deactivate all relays
    for (int i = 0; i < 4; i++) {
        deactivate_relay(i + 1);
    }

    // Release GPIO lines
    if (lines[0]) gpiod_line_release(lines[0]);
    if (lines[1]) gpiod_line_release(lines[1]);
    if (lines[2]) gpiod_line_release(lines[2]);
    if (lines[3]) gpiod_line_release(lines[3]);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    // Close log file
    if (log_file) fclose(log_file);

    fprintf(stderr, "Cleanup complete.\n");
}

int main(void) {
    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(stderr, "Smart Irrigation System started.\n");

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_moisture();
        fprintf(stderr, "Moisture level: %d\n", moisture_level);

        // Check if moisture is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            fprintf(stderr, "Moisture level below threshold, activating relays.\n");

            // Activate relays sequentially
            for (int i = 0; i < 4; i++) {
                activate_relay(i + 1);
                log_event(i + 1, moisture_level);
                sleep(RELAY_DURATION);
                deactivate_relay(i + 1);
                if (i < 3) {
                    sleep(RELAY_DELAY);
                }
            }
        }

        // Wait 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

