#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD 50

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo angles (degrees)
#define SERVO_CLOSED_ANGLE 0
#define SERVO_OPEN_ANGLE 90

// Define nozzle angles (degrees)
#define NOZZLE_ANGLE_0 0
#define NOZZLE_ANGLE_45 45
#define NOZZLE_ANGLE_90 90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define NOZZLE_SWEEP_DURATION 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t valve_open = 0;

// Function prototypes
int initialize_gpio();
int set_servo_pulse_width(int gpio_pin, int pulse_width);
int open_valve();
int close_valve();
int sweep_nozzle();
int read_moisture();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, stopping program...\n", signal);
        program_running = 0;

        // Stop servos
        set_servo_pulse_width(VALVE_SERVO_PIN, 0);
        set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Set servo pulse width with retry mechanism
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    int attempts = 0;
    int result = 0;

    while (attempts < 3) {
        result = gpioServo(gpio_pin, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "gpioServo failed (attempt %d): %d\n", attempts + 1, result);
            attempts++;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }

    fprintf(stderr, "gpioServo failed after 3 attempts (GPIO %d, pulse width %d)\n", gpio_pin, pulse_width);
    return 1; // Indicate failure
}

// Open the water valve
int open_valve() {
    if (set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_OPEN_ANGLE * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180 + SERVO_MIN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to open valve\n");
        return 1;
    }
    valve_open = 1;
    return 0;
}

// Close the water valve
int close_valve() {
    if (set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_CLOSED_ANGLE * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180 + SERVO_MIN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to close valve\n");
        return 1;
    }
    valve_open = 0;
    return 0;
}

// Sweep the nozzle
int sweep_nozzle() {
    int angles[] = {NOZZLE_ANGLE_0, NOZZLE_ANGLE_45, NOZZLE_ANGLE_90, NOZZLE_ANGLE_135, NOZZLE_ANGLE_180};
    int num_angles = sizeof(angles) / sizeof(angles[0]);
    int i;

    for (i = 0; i < num_angles; i++) {
        if (set_servo_pulse_width(NOZZLE_SERVO_PIN, angles[i] * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180 + SERVO_MIN_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to set nozzle angle %d\n", angles[i]);
            return 1;
        }
        gpioDelay(NOZZLE_SWEEP_DURATION * 1000); // Convert seconds to milliseconds
    }
    return 0;
}

// Read moisture value
int read_moisture() {
    static int moisture_values[] = {20, 40, 60, 80, 100};
    static int current_index = 0;
    int moisture = moisture_values[current_index];
    current_index = (current_index + 1) % (sizeof(moisture_values) / sizeof(moisture_values[0]));
    return moisture;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Automated Plant Watering System started\n");

    while (program_running) {
        int moisture = read_moisture();
        printf("Moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold, watering...\n");

            // Open valve
            if (open_valve() != 0) {
                fprintf(stderr, "Failed to open valve, skipping watering\n");
                continue; // Skip to the next cycle
            }

            // Sweep nozzle
            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Failed to sweep nozzle, skipping watering\n");
                close_valve(); // Attempt to close valve even if nozzle fails
                continue; // Skip to the next cycle
            }

            // Hold for watering duration
            gpioDelay(WATERING_DURATION * 1000); // Convert seconds to milliseconds

            // Close valve
            if (close_valve() != 0) {
                fprintf(stderr, "Failed to close valve\n");
            }
        } else {
            printf("Moisture above threshold, skipping watering\n");
        }

        // Wait for the next cycle
        gpioDelay(5000); // 5 seconds
    }

    // Stop servos and terminate pigpio (should not reach here if signal handler works)
    set_servo_pulse_width(VALVE_SERVO_PIN, 0);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

