#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for motor control
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define number of steps for lock/unlock
#define STEPS 512

// Define delay between steps (in microseconds)
#define STEP_DELAY 3000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void lock_door();
void unlock_door();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set motor control pins as outputs
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < STEPS; i++) {
        // Full-step sequence (clockwise)
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 1);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 1);
        gpioDelay(STEP_DELAY);
    }
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    for (int i = 0; i < STEPS; i++) {
        // Full-step sequence (counter-clockwise)
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 1);
        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 1);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);
    }
    printf("Door unlocked.\n");
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // De-energize all coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    gpioTerminate();
    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock/unlock simulation started. Press LOCK (GPIO24) or UNLOCK (GPIO23) to rotate the motor.\n");

    // Main loop
    while (program_running) {
        // Check LOCK button
        if (gpioRead(LOCK_BUTTON) == 0) {
            // Debounce
            gpioDelay(50000); // 50ms
            if (gpioRead(LOCK_BUTTON) == 0) {
                lock_door();
                // Debounce
                gpioDelay(500000); // 500ms
            }
        }

        // Check UNLOCK button
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            // Debounce
            gpioDelay(50000); // 50ms
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                unlock_door();
                // Debounce
                gpioDelay(500000); // 500ms
            }
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    return 0;
}

