        gpioDelay(STEP_DELAY);

        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(STEP_DELAY);
    }
    printf("Door unlocked.\n");
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // De-energize all coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    gpioTerminate();
    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock/unlock simulation started. Press LOCK (GPIO24) or UNLOCK (GPIO23) to rotate the motor.\n");

    // Main loop
    while (program_running) {
        // Check LOCK button
        if (gpioRead(LOCK_BUTTON) == 0) {
            // Debounce
            gpioDelay(50000); // 50ms
            if (gpioRead(LOCK_BUTTON) == 0) {
                lock_door();
                // Debounce
                gpioDelay(500000); // 500ms
            }
        }

        // Check UNLOCK button
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            // Debounce
            gpioDelay(50000); // 50ms
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                unlock_door();
                // Debounce
                gpioDelay(500000); // 500ms
            }
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    return 0;
}

