#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "distance_log.txt"

// Define timeout duration (in microseconds)
#define TIMEOUT_US 50000

// Define speed of sound (in cm/us)
#define SPEED_OF_SOUND 0.01715

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int trigger_sensor(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
int log_distance(double distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, cleaning up...\n", sig);
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error: Could not get trigger line %d\n", TRIGGER_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error: Could not get echo line %d\n", ECHO_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trigger_line, "distance_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request trigger line as output: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "distance_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request echo line as input: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor(void) {
    int ret;

    // Set trigger line high for 10 microseconds
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set trigger line high: %d\n", ret);
        return -1;
    }
    usleep(10); // Wait for 10 microseconds
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set trigger line low: %d\n", ret);
        return -1;
    }

    return 0;
}

// Measure the pulse width on the echo line
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for echo line to go high (rising edge)
    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get start time\n");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 0) {
        ret = clock_gettime(CLOCK_MONOTONIC, &end);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not get end time\n");
            return -1;
        }
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Error: Timeout waiting for rising edge\n");
            return -1;
        }
    }

    // Get start time
    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get start time after rising edge\n");
        return -1;
    }

    // Wait for echo line to go low (falling edge)
    ret = clock_gettime(CLOCK_MONOTONIC, &end);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get end time\n");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 1) {
        ret = clock_gettime(CLOCK_MONOTONIC, &end);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not get end time\n");
            return -1;
        }
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Error: Timeout waiting for falling edge\n");
            return -1;
        }
    }

    // Get end time
    ret = clock_gettime(CLOCK_MONOTONIC, &end);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get end time after falling edge\n");
        return -1;
    }

    // Calculate pulse width in microseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000L + (end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return pulse_width * SPEED_OF_SOUND;
}

// Log distance to file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    int ret;
    double distance;
    long pulse_width;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file '%s'\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Distance sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor() < 0) {
            fprintf(stderr, "Error: Trigger sensor failed\n");
            log_distance(-1.0);
            sleep(1);
            continue;
        }

        // Measure the pulse width
        pulse_width = measure_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Error: Measure pulse width failed\n");
            log_distance(-1.0);
            sleep(1);
            continue;
        }

        // Calculate the distance
        distance = calculate_distance(pulse_width);

        // Log the distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Error: Log distance failed\n");
        }

        // Wait for 60 milliseconds
        usleep(60000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

