#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm
#define I2C_RETRY_COUNT 3

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);
int i2c_read_reg(int handle, int reg, char *buf, int count);
int i2c_write_reg(int handle, int reg, char *buf, int count);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// I2C read function with retry
int i2c_read_reg(int handle, int reg, char *buf, int count) {
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, buf, count);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, count %d): %d, retrying...\n", reg, count, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, count %d).\n", reg, count);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int handle, int reg, char *buf, int count) {
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cWriteI2CBlockData(handle, reg, buf, count);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, count %d): %d, retrying...\n", reg, count, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, count %d).\n", reg, count);
    return -1; // Indicate failure
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    char buf[2];

    // Reset sensor
    buf[0] = 0x00; // Reset value
    if (i2c_write_reg(i2c_handle, 0x0000, buf, 1) < 0) {
        fprintf(stderr, "Error resetting VL53L1X.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset to complete

    // Check sensor ID
    if (i2c_read_reg(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, buf, 1) < 0) {
        fprintf(stderr, "Error reading sensor ID.\n");
        return -1;
    }
    if (buf[0] != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", buf[0]);
        return -1;
    }

    // Configure sensor for short-range mode
    buf[0] = 0x01; // Enable short range mode
    if (i2c_write_reg(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, buf, 1) < 0) {
        fprintf(stderr, "Error configuring sensor for short-range mode.\n");
        return -1;
    }

    // Start continuous ranging
    buf[0] = 0x01; // Start continuous ranging
    if (i2c_write_reg(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, buf, 1) < 0) {
        fprintf(stderr, "Error starting continuous ranging.\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char buf[2];

    // Check if data is ready
    if (i2c_read_reg(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, buf, 1) < 0) {
        fprintf(stderr, "Error reading range status.\n");
        return -1;
    }
    if ((buf[0] & 0x01) == 0) {
        fprintf(stderr, "Data not ready.\n");
        return -1;
    }

    // Read distance
    if (i2c_read_reg(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, buf, 2) < 0) {
        fprintf(stderr, "Error reading distance.\n");
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Control relay based on distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Open door
    } else {
        gpioWrite(RELAY_GPIO, 0); // Close door
    }
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to LOW

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

