#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define GPIO chip name
#define GPIOCHIP_NAME "gpiochip0"

// Define GPIO line numbers
#define RELAY1_LINE 0
#define RELAY2_LINE 1
#define RELAY3_LINE 2
#define RELAY4_LINE 3

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define WATERING_INTERVAL 86400 // seconds (24 hours)

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int activate_relay(int pin);
int deactivate_relay(int pin);
int log_watering_cycle(void);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP_NAME);
        return -1;
    }

    // Get GPIO lines
    relay1_line = gpiod_chip_get_line(chip, RELAY1_LINE);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_LINE);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_LINE);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_LINE);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error: Could not get GPIO line\n");
        cleanup();
        return -1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(relay1_line, "watering", 1); // Active low
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", RELAY1_LINE, gpiod_line_get_name(relay1_line));
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "watering", 1); // Active low
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", RELAY2_LINE, gpiod_line_get_name(relay2_line));
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "watering", 1); // Active low
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", RELAY3_LINE, gpiod_line_get_name(relay3_line));
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "watering", 1); // Active low
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", RELAY4_LINE, gpiod_line_get_name(relay4_line));
        cleanup();
        return -1;
    }

    // Initialize all relays to inactive (HIGH)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    return 0;
}

// Function to activate a relay
int activate_relay(int pin) {
    int line_number;
    struct gpiod_line *line;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            line_number = RELAY1_LINE;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            line_number = RELAY2_LINE;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            line_number = RELAY3_LINE;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            line_number = RELAY4_LINE;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay pin %d\n", pin);
            return -1;
    }

    int ret = gpiod_line_set_value(line, 0); // Active low
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value: %s\n", line_number, gpiod_line_get_name(line));
        return -1;
    }

    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int pin) {
    int line_number;
    struct gpiod_line *line;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            line_number = RELAY1_LINE;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            line_number = RELAY2_LINE;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            line_number = RELAY3_LINE;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            line_number = RELAY4_LINE;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay pin %d\n", pin);
            return -1;
    }

    int ret = gpiod_line_set_value(line, 1); // Active low
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value: %s\n", line_number, gpiod_line_get_name(line));
        return -1;
    }

    return 0;
}

// Function to log a watering cycle
int log_watering_cycle(void) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open watering_log.txt for writing\n");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to release GPIO resources
void cleanup(void) {
    if (chip) {
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
    }
}

int main(void) {
    time_t last_watering_time = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        time_t current_time = time(NULL);

        // Check if it's time to water the plants
        if (current_time - last_watering_time >= WATERING_INTERVAL) {
            // Watering cycle
            printf("Starting watering cycle...\n");

            // Activate relays sequentially
            if (activate_relay(RELAY1_PIN) < 0) {
                fprintf(stderr, "Error: Failed to activate relay 1\n");
                break;
            }
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY1_PIN);

            if (activate_relay(RELAY2_PIN) < 0) {
                fprintf(stderr, "Error: Failed to activate relay 2\n");
                break;
            }
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY2_PIN);

            if (activate_relay(RELAY3_PIN) < 0) {
                fprintf(stderr, "Error: Failed to activate relay 3\n");
                break;
            }
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY3_PIN);

            if (activate_relay(RELAY4_PIN) < 0) {
                fprintf(stderr, "Error: Failed to activate relay 4\n");
                break;
            }
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY4_PIN);

            // Log the watering cycle
            if (log_watering_cycle() < 0) {
                fprintf(stderr, "Error: Failed to log watering cycle\n");
            }

            printf("Watering cycle complete.\n");

            // Update last watering time
            last_watering_time = current_time;
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

