#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define the number of steps for the sunrise simulation
#define NUM_STEPS 180

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_state(int relay_pin, int state);
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to set the state of a relay (HIGH or LOW)
void set_relay_state(int relay_pin, int state) {
    gpioWrite(relay_pin, state);
}

// Function to set the PWM duty cycle for a GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting.");
        return 1;
    }

    log_event("Smart lighting system started.");

    // Sunrise simulation loop
    for (int i = 0; i <= NUM_STEPS && program_running; ++i) {
        // Calculate duty cycle (linear increase from 0 to 255)
        int duty_cycle = i * 255 / NUM_STEPS;

        // Set PWM duty cycle for each relay
        set_pwm_duty_cycle(RELAY1_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY2_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY3_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY4_PIN, duty_cycle);

        // Log the current state
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Relay duty cycle: %d", duty_cycle);
        log_event(log_message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio uses microseconds
    }

    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    log_event("Smart lighting system stopped.");

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

