int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x75);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%x\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    // Get timestamp
    data->timestamp = gpioTick();

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Check if any axis exceeds the threshold
int check_threshold(gyro_data_t data) {
    if (fabs(data.x) > 250.0 || fabs(data.y) > 250.0 || fabs(data.z) > 250.0) {
        return 1;
    } else {
        return 0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);   // Close I2C handle
    gpioTerminate();        // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Open I2C handle
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050 with retry mechanism
    int init_attempts = 0;
    while (init_mpu6050() < 0 && init_attempts < 3) {
        fprintf(stderr, "Retrying MPU-6050 initialization...\n");
        gpioDelay(1000); // Wait 1 second before retrying
        init_attempts++;
    }

    if (init_attempts == 3) {
        fprintf(stderr, "Error: MPU-6050 initialization failed after multiple attempts\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold and control LED
            if (check_threshold(gyro_data)) {
                gpioWrite(LED_PIN, 1); // Turn on LED
            } else {
                gpioWrite(LED_PIN, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data, attempting re-initialisation...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before re-initialising
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C device\n");
                terminate = 1; // Exit loop if re-initialisation fails
            } else {
                if (init_mpu6050() < 0) {
                    fprintf(stderr, "Error: Could not re-initialise MPU-6050\n");
                    terminate = 1; // Exit loop if re-initialisation fails
                }
            }
        }

        gpioDelay(50); // 50 ms delay (20 Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

