#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define GYRO_SCALE 131.0
#define RETRY_COUNT 3
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_RATE_MS 10

// MPU-9250 Register Addresses
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double convert_to_dps(int16_t raw_value);
int log_data(FILE *fp, double timestamp, double x_rate, double y_rate, double z_rate);
void signal_handler(int sig);
int setup_gpio(void);
int setup_spi(void);
void cleanup(void);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[6] = {GYRO_XOUT_H, 0x00, 0x00, GYRO_YOUT_H, 0x00, 0x00};
    uint8_t rx_buf[6];

    if (spi_transfer(fd, tx_buf, rx_buf, 6) != 0) {
        return -1;
    }

    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Convert raw value to degrees per second
double convert_to_dps(int16_t raw_value) {
    return (double)raw_value / GYRO_SCALE;
}

// Log data to file
int log_data(FILE *fp, double timestamp, double x_rate, double y_rate, double z_rate) {
    if (fprintf(fp, "%.9f,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO for chip select
int setup_gpio(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gyro", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    cs_line = line;
    return 0;
}

// Setup SPI interface
int setup_spi(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure max speed hz
    uint32_t speed = 1000000; // 1 MHz
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Error setting max speed hz: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1); // Set CS high
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    struct timespec ts;
    int16_t raw_x, raw_y, raw_z;
    double x_rate, y_rate, z_rate;
    int retry;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        return 1;
    }

    // Initialize SPI
    if (setup_spi() != 0) {
        fprintf(stderr, "SPI setup failed, exiting\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (gpiod_line_set_value(cs_line, 0) < 0) {
                fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
                retry++;
                nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 10000000}, NULL); // 10ms
                continue;
            }

            if (read_gyro_data(spi_fd, &raw_x, &raw_y, &raw_z) == 0) {
                x_rate = convert_to_dps(raw_x);
                y_rate = convert_to_dps(raw_y);
                z_rate = convert_to_dps(raw_z);

                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    if (log_data(log_file, (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0, x_rate, y_rate, z_rate) != 0) {
                        fprintf(stderr, "Logging failed, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                }

                if (gpiod_line_set_value(cs_line, 1) < 0) {
                    fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
                    retry++;
                    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 10000000}, NULL); // 10ms
                    continue;
                }
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "SPI read failed, retrying...\n");
                retry++;
                nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 10000000}, NULL); // 10ms
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "SPI read failed after %d retries, continuing...\n", RETRY_COUNT);
        }

        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = SAMPLE_RATE_MS * 1000000}, NULL); // Sample rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

