#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define CS_PIN 8          // GPIO8 (CE0)
#define LED_PIN 17        // GPIO17
#define BUFFER_SIZE 64
#define SAMPLE_RATE 100   // Hz
#define BLINK_DURATION 500 // ms
#define ANGULAR_VELOCITY_THRESHOLD 200.0 // deg/s

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_init(int channel, int speed, int mode, int cs_pin);
int spi_read(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write(int handle, uint8_t reg, uint8_t data);
int read_gyro_data(int handle, float *x, float *y, float *z);
void add_to_buffer(gyro_data_t data);
