#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// LED GPIO pin
#define LED_PIN 21

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
double calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
double calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
void control_led(double roll, double pitch);
void log_data(double roll, double pitch);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    double roll;
    double pitch;
} sensor_data_t;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int16_t accel_x, accel_y, accel_z;

        // Read raw accelerometer data
        if (read_raw_data(&accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Failed to read raw data\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate roll and pitch
        sensor_data_t data;
        data.accel_x = accel_x;
        data.accel_y = accel_y;
        data.accel_z = accel_z;
        data.roll = calculate_roll(accel_x, accel_y, accel_z);
        data.pitch = calculate_pitch(accel_x, accel_y, accel_z);

        // Control LED
        control_led(data.roll, data.pitch);

        // Log data
        log_data(data.roll, data.pitch);

        // Print roll and pitch to console
        printf("Roll: %.2f, Pitch: %.2f\n", data.roll, data.pitch);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1\n");
        return -1;
    }

    // Set accelerometer full-scale range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to ACCEL_CONFIG\n");
        return -1;
    }

    // Verify configuration (read back and check)
    int accel_config = i2cReadByteData(i2c_handle, ACCEL_CONFIG);
    if (accel_config < 0) {
        fprintf(stderr, "Failed to read ACCEL_CONFIG\n");
        return -1;
    }
    if (accel_config != 0x00) {
        fprintf(stderr, "ACCEL_CONFIG readback failed: 0x%02X\n", accel_config);
        return -1;
    }

    return 0;
}

// Read raw accelerometer data from MPU-6050
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate roll angle
double calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    return atan2(accel_y, accel_z) * 180 / M_PI;
}

// Calculate pitch angle
double calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    return atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
}

// Control LED based on tilt angles
void control_led(double roll, double pitch) {
    if (fabs(roll) > 45 || fabs(pitch) > 45) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Log data to file
void log_data(double roll, double pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed, exiting...\n");
}

