#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define LED_GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 100

// Global variables
int i2c_fd = -1;
struct gpiod_line *led_gpio_line = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
int control_led(int gpio_line, int state);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_register(int fd, uint8_t reg) {
    int retries = 0;
    int result;
    uint8_t buf[1];

    while (retries < RETRY_COUNT) {
        if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            return -1;
        }

        buf[0] = reg;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write register address");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        if (read(fd, buf, 1) != 1) {
            perror("Failed to read register value");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        result = buf[0];
        return result;
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1;
}

// I2C write function with retry
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    uint8_t buf[2];

    while (retries < RETRY_COUNT) {
        if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            return -1;
        }

        buf[0] = reg;
        buf[1] = value;

        if (write(fd, buf, 2) != 2) {
            perror("Failed to write register value");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Failed to write register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1;
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int result;
    uint8_t buf[2];

    result = i2c_read_register(fd, AMBIENT_LIGHT_REG);
    if (result < 0) return -1;
    buf[0] = (uint8_t)result;

    result = i2c_read_register(fd, AMBIENT_LIGHT_REG + 1);
    if (result < 0) return -1;
    buf[1] = (uint8_t)result;

    *ambient_light = (buf[1] << 8) | buf[0];

    result = i2c_read_register(fd, PROXIMITY_REG);
    if (result < 0) return -1;
    buf[0] = (uint8_t)result;

    result = i2c_read_register(fd, PROXIMITY_REG + 1);
    if (result < 0) return -1;
    buf[1] = (uint8_t)result;

    *proximity = (buf[1] << 8) | buf[0];

    return 0;
}

// Log data function
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,AmbientLight:0x%04X,Proximity:0x%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Control LED function
int control_led(int gpio_line, int state) {
    int ret = gpiod_line_set_value(gpio_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (led_gpio_line != NULL) {
        control_led(led_gpio_line, 0); // Turn off LED
        gpiod_line_release(led_gpio_line);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int ret;
    uint16_t ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    led_gpio_line = gpiod_chip_get_line(chip, LED_GPIO_PIN);
    if (!led_gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    ret = gpiod_line_request_output(led_gpio_line, "biometric_sensor", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);

            if (proximity > 100) {
                control_led(led_gpio_line, 1); // Turn on LED
            } else {
                control_led(led_gpio_line, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(SLEEP_MS * 1000); // Sleep for 100 ms
    }

