#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_SENSITIVITY 200.0 // LSB/deg/s
#define SAMPLE_RATE 100.0 // Hz
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE) // Delay between samples in microseconds
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int init_spi();
int read_gyro_register(int reg_addr, int *data);
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from a gyroscope register
int read_gyro_register(int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    return 0;
}

// Read gyroscope data (X and Y axes)
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    if (read_gyro_register(0x02, (int*)&data.x_rate) != 0) {
        fprintf(stderr, "Error reading X axis data\n");
        data.x_rate = 0; // Set to 0 in case of error
    }
    if (read_gyro_register(0x04, (int*)&data.y_rate) != 0) {
        fprintf(stderr, "Error reading Y axis data\n");
        data.y_rate = 0; // Set to 0 in case of error
    }
    return data;
}

// Log data to CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(fp, "%.6f,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI with retry mechanism
    int reinit_attempts = 0;
    while (reinit_attempts < MAX_REINIT_ATTEMPTS) {
        if (init_spi() == 0) {
            break; // SPI initialized successfully
        } else {
            fprintf(stderr, "SPI initialization failed. Attempt %d/%d\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            reinit_attempts++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (reinit_attempts == MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "Failed to initialize SPI after %d attempts. Exiting.\n", MAX_REINIT_ATTEMPTS);
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,X_rate,Y_rate\n");

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_DELAY_US); // Delay for 10 ms (100 Hz sampling)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

