    while (reinit_attempts < MAX_REINIT_ATTEMPTS) {
        if (init_spi() == 0) {
            break; // SPI initialized successfully
        } else {
            fprintf(stderr, "SPI initialization failed. Attempt %d/%d\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            reinit_attempts++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (reinit_attempts == MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "Failed to initialize SPI after %d attempts. Exiting.\n", MAX_REINIT_ATTEMPTS);
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,X_rate,Y_rate\n");

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_DELAY_US); // Delay for 10 ms (100 Hz sampling)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

