#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100

// ADXRS290 Registers
#define RATE_XL 0x02
#define RATE_XH 0x03

// Data Structure
typedef struct {
    struct timespec timestamp;
    int16_t x_rate;
} GyroData;

// Circular Buffer
typedef struct {
    GyroData buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
static int spi_handle;
static volatile int running = 1;
static CircularBuffer gyro_buffer;
static int led_state = 0; // 0 = off, 1 = on

// Function Prototypes
int init_pigpio();
int init_spi();
int read_gyro_data(int16_t *x_rate);
void process_gyro_data(int16_t x_rate);
void add_to_buffer(CircularBuffer *buffer, struct timespec timestamp, int16_t x_rate);
void *buffer_thread(void *arg);
void signal_handler(int signal);
void cleanup();
void set_led(int state);

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read gyro data from ADXRS290
int read_gyro_data(int16_t *x_rate) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Construct the read command (MSB = 1 for read)
    tx_buf[0] = RATE_XL | 0x80; // Read command for RATE_XL
    tx_buf[1] = 0x00;           // Dummy byte for reading RATE_XH

    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 2) {
        fprintf(stderr, "SPI read failed: %d\n", status);
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    *x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Process gyro data (convert to degrees per second)
void process_gyro_data(int16_t x_rate) {
    // Sensitivity: 200 LSB/deg/s
    float dps = (float)x_rate / 200.0;
    printf("X-axis rate: %.2f deg/s\n", dps);
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, struct timespec timestamp, int16_t x_rate) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].x_rate = x_rate;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Thread function to process the circular buffer
void *buffer_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        struct timespec timestamp;
        int16_t x_rate;
        pthread_mutex_lock(&gyro_buffer.mutex);
        if (gyro_buffer.count > 0) {
            timestamp = gyro_buffer.buffer[gyro_buffer.tail].timestamp;
            x_rate = gyro_buffer.buffer[gyro_buffer.tail].x_rate;
            gyro_buffer.tail = (gyro_buffer.tail + 1) % BUFFER_SIZE;
            gyro_buffer.count--;
        } else {
            pthread_mutex_unlock(&gyro_buffer.mutex);
            gpioDelay(1000); // Sleep for 1ms if buffer is empty
            continue;
        }
        pthread_mutex_unlock(&gyro_buffer.mutex);

        // Process the data (e.g., print to console)
        process_gyro_data(x_rate);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

// Set the LED state
void set_led(int state) {
    if (state != led_state) {
        gpioWrite(LED_GPIO, state);
        led_state = state;
    }
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the circular buffer thread
    pthread_t buffer_thread_id;
    if (pthread_create(&buffer_thread_id, NULL, buffer_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create buffer thread\n");
        cleanup();
        return 1;
    }

    // Main loop
    int16_t x_rate;
    struct timespec ts;
    while (running) {
        if (read_gyro_data(&x_rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(&gyro_buffer, ts, x_rate);

            // Check threshold and control LED
            if (abs(x_rate) > (int16_t)(THRESHOLD * 200.0)) {
                set_led(1); // Turn on LED
            } else {
                set_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpioDelay(10); // Delay for 10ms
    }

    // Wait for the buffer thread to finish
    pthread_join(buffer_thread_id, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

