#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins for the relays
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the number of relays
#define NUM_RELAYS 4

// Structure to hold GPIO line information
struct gpio_line {
    struct gpiod_line *line;
    int pin;
};

// Array to hold the GPIO line information
struct gpio_line relays[NUM_RELAYS];

// Function prototypes
int initialize_gpio(struct gpio_line *relays);
void set_relay_state(struct gpio_line *relay, int state);
void traffic_light_cycle(struct gpio_line *relays);
void cleanup_gpio(struct gpio_line *relays);
void signal_handler(int sig);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(relays) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to cycle through traffic light states
    while (program_running) {
        traffic_light_cycle(relays);
    }

    // Cleanup GPIO lines before exiting
    cleanup_gpio(relays);

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpio_line *relays) {
    struct gpiod_chip *chip;
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Iterate through the relays and request the GPIO lines
    for (i = 0; i < NUM_RELAYS; i++) {
        relays[i].pin = (i == 0) ? RED_PIN : (i == 1) ? YELLOW_PIN : (i == 2) ? GREEN_PIN : BLUE_PIN;
        relays[i].line = gpiod_chip_get_line(chip, relays[i].pin);
        if (!relays[i].line) {
            perror("Failed to get GPIO line");
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(relays[j].line);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the GPIO line for output
        if (gpiod_line_request_output(relays[i].line, "traffic_light", 0) != 0) {
            perror("Failed to request GPIO line for output");
            // Release previously acquired lines before exiting
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(relays[j].line);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Close the GPIO chip
    if (gpiod_chip_close(chip) != 0) {
        perror("Failed to close GPIO chip");
        return 1;
    }

    return 0;
}

// Function to set the state of a relay (active-low)
void set_relay_state(struct gpio_line *relay, int state) {
    if (gpiod_line_set_value(relay->line, !state) != 0) {
        perror("Failed to set relay state");
    }
}

// Function to cycle through the traffic light states
void traffic_light_cycle(struct gpio_line *relays) {
    time_t start_time = time(NULL);

    // Red light
    set_relay_state(&relays[0], 1);
    set_relay_state(&relays[1], 0);
    set_relay_state(&relays[2], 0);
    set_relay_state(&relays[3], 0);
    printf("State: Red\n");
    sleep(10);
    set_relay_state(&relays[0], 0);

    // Red + Yellow light
    set_relay_state(&relays[0], 1);
    set_relay_state(&relays[1], 1);
    set_relay_state(&relays[2], 0);
    set_relay_state(&relays[3], 0);
    printf("State: Red + Yellow\n");
    sleep(2);
    set_relay_state(&relays[0], 0);
    set_relay_state(&relays[1], 0);

    // Green light
    set_relay_state(&relays[0], 0);
    set_relay_state(&relays[1], 0);
    set_relay_state(&relays[2], 1);
    set_relay_state(&relays[3], 0);
    printf("State: Green\n");
    sleep(10);
    set_relay_state(&relays[2], 0);

    // Yellow light
    set_relay_state(&relays[0], 0);
    set_relay_state(&relays[1], 1);
    set_relay_state(&relays[2], 0);
    set_relay_state(&relays[3], 0);
    printf("State: Yellow\n");
    sleep(3);
    set_relay_state(&relays[1], 0);
}

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpio_line *relays) {
    int i;

    // Release the GPIO lines
    for (i = 0; i < NUM_RELAYS; i++) {
        if (relays[i].line) {
            gpiod_line_release(relays[i].line);
        }
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received (%d).  Shutting down...\n", sig);
    program_running = 0;
}

