        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to configure the MPR121
int configure_mpr121() {
    // Reset the MPR121
    if (i2cWriteByteData(i2c_handle, RESET_REG, 0x63) < 0) {
        log_message("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Stop mode
    if (i2cWriteByteData(i2c_handle, RUN_MODE_REG, 0x00) < 0) {
        log_message("Failed to set MPR121 to stop mode");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Failed to enable electrode 0");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set touch threshold
    if (i2cWriteByteData(i2c_handle, TOUCH_THRESHOLD_REG, 0x0A) < 0) {
        log_message("Failed to set touch threshold");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set release threshold
    if (i2cWriteByteData(i2c_handle, RELEASE_THRESHOLD_REG, 0x08) < 0) {
        log_message("Failed to set release threshold");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set debounce time
    if (i2cWriteByteData(i2c_handle, DEBOUNCE_REG, 0x21) < 0) {
        log_message("Failed to set debounce time");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set charge time
    if (i2cWriteByteData(i2c_handle, CHARGE_TIME_REG, 0x0D) < 0) {
        log_message("Failed to set charge time");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Run mode
    if (i2cWriteByteData(i2c_handle, RUN_MODE_REG, 0x0D) < 0) {
        log_message("Failed to set MPR121 to run mode");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status() {
    int lsb = i2cReadByteData(i2c_handle, TOUCH_STATUS_REG);
    int msb = i2cReadByteData(i2c_handle, TOUCH_STATUS_REG_MSB);

    if (lsb < 0 || msb < 0) {
        log_message("Failed to read touch status");
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to control the relay based on touch status
void control_relay(int touch_status) {
    if (touch_status & 0x01) { // Check if electrode 0 is touched
        gpioWrite(RELAY_GPIO, 1); // Turn relay ON
    } else {
        gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, cleaning up...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed, exiting");
        cleanup();
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_message("I2C initialization failed, exiting");
        cleanup();
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        log_message("MPR121 configuration failed, exiting");
        cleanup();
    }

    log_message("Initialization complete");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status >= 0) {
            control_relay(touch_status);
        } else {
            log_message("Error reading touch status, retrying...");
        }
        gpioDelay(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

