// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration in milliseconds
#define DISPENSE_DURATION_MS 1000

// Define half of the dispense duration in microseconds
#define HALF_DURATION_US (DISPENSE_DURATION_MS * 1000 / 2)

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin);
int deactivate_solenoid(int pin);
int log_dispense_event(int solenoid_pin, int duration_ms);
void dispense_cycle();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Deactivating solenoids and exiting...\n");
        program_running = 0;
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to log a dispense event to a file
int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Solenoid GPIO%d - Duration: %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
    return 0;
}

// Function to perform a single dispense cycle
void dispense_cycle() {
    // Activate solenoid 1
    if (activate_solenoid(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Failed to activate solenoid 1\n");
        return;
    }
    gpioDelay(HALF_DURATION_US);

    // Deactivate solenoid 1
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1\n");
        return;
    }

    // Activate solenoid 2
    if (activate_solenoid(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Failed to activate solenoid 2\n");
        return;
    }
    gpioDelay(HALF_DURATION_US);

    // Deactivate solenoid 2
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2\n");
        return;
    }

    // Log the dispense event
    if (log_dispense_event(SOLENOID_1_PIN, DISPENSE_DURATION_MS) != 0) {
        fprintf(stderr, "Failed to log dispense event\n");
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        dispense_cycle();
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Terminate pigpio (should not reach here if signal handler works)
    gpioTerminate();

    return 0;
}

