#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable pins
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance distance
#define OBSTACLE_DISTANCE 20.0

// Log file name
#define LOG_FILE "balance_log.txt"

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
float pid_control(float error, float *integral, float *previous_error);
float simulate_tilt();
float simulate_distance();
void obstacle_avoidance(float distance, int *motor_a_speed, int *motor_b_speed);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Stop both motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(MOTOR_A_ENABLE, 0);
    gpioPWM(MOTOR_B_ENABLE, 0);
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// PID control function
float pid_control(float error, float *integral, float *previous_error) {
    float proportional = KP * error;
    *integral += KI * error;
    float derivative = KD * (error - *previous_error);
    float output = proportional + *integral + derivative;
    *previous_error = error;
    return output;
}

// Simulate tilt error
float simulate_tilt() {
    return (float)(rand() % 201 - 100) / 10.0; // -10.0 to 10.0 degrees
}

// Simulate distance sensor
float simulate_distance() {
    return 2.0 + (float)rand() / RAND_MAX * 398.0; // 2.0 to 400.0 cm
}

// Obstacle avoidance function
void obstacle_avoidance(float distance, int *motor_a_speed, int *motor_b_speed) {
