#include <time.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define BITS_PER_SAMPLE 16
#define CHANNELS 1
#define PERIOD_SIZE 1024

// Define PWM range
#define PWM_RANGE 255

// Define cool and warm color mapping parameters
#define COOL_START_HUE 0.0
#define COOL_END_HUE 120.0
#define WARM_START_HUE 120.0
#define WARM_END_HUE 240.0

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static double sensitivity = 1.0;
static int audio_available = 1; // Assume ALSA is available initially

// Function prototypes
void signal_handler(int signal);
int initialize_alsa();
void cleanup_alsa();
double calculate_rms(short *buffer, int buffer_size);
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void simulate_audio_input(short *buffer, int buffer_size);
void log_status(const char *message);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_status("Signal received, exiting...");
}

// Initialize ALSA audio capture
int initialize_alsa() {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        log_error("Error opening PCM device: ");
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        log_error("Error initializing hardware parameters: ");
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        log_error("Error setting access type: ");
        return -1;
    }

    // Set format to 16-bit little-endian
    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        log_error("Error setting format: ");
        return -1;
    }

    // Set channels to 1
    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, CHANNELS)) < 0) {
        log_error("Error setting channels: ");
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        log_error("Error setting sample rate: ");
        return -1;
    }

    // Set period size
    if ((err = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        log_error("Error setting period size: ");
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        log_error("Error setting hardware parameters: ");
        return -1;
    }

    return 0;
}

// Cleanup ALSA resources
void cleanup_alsa() {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
        pcm_handle = NULL;
    }
}

// Simulate audio input with a sine wave
void simulate_audio_input(short *buffer, int buffer_size) {
    double amplitude = 32767.0; // Maximum amplitude for 16-bit
    double frequency = 1000.0;  // Example frequency
    double period = 1.0 / frequency;
    double t;

    for (int i = 0; i < buffer_size; i++) {
        t = (double)i / SAMPLE_RATE;
        buffer[i] = (short)(amplitude * sin(2 * M_PI * frequency * t));
    }
}

// Calculate RMS amplitude of audio samples
double calculate_rms(short *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    double mean_square = sum_of_squares / buffer_size;
    return sqrt(mean_square);
}

// Map amplitude to RGB color values using a non-linear transition
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue) {
    double normalized_amplitude = amplitude / 32767.0; // Normalize to 0-1 range

    // Non-linear mapping
    double hue = 0.0;
    if (normalized_amplitude < 0.5) {
        // Cool colors (blue to green)
        hue = COOL_START_HUE + (normalized_amplitude * 2.0 * (COOL_END_HUE - COOL_START_HUE));
    } else {
        // Warm colors (yellow to red)
        hue = WARM_START_HUE + ((normalized_amplitude - 0.5) * 2.0 * (WARM_END_HUE - WARM_START_HUE));
    }

    // Convert hue to RGB (HSL to RGB conversion)
    double saturation = 1.0; // Full saturation
    double lightness = 0.5;  // Midlightness

    double r, g, b;

    if (hue >= 0 && hue < 60) {
        r = saturation * (hue / 60.0);
        g = saturation * (1.0 - (hue / 60.0));
        b = 0.0;
    } else if (hue >= 60 && hue < 120) {
        r = saturation * (1.0 - (hue - 60.0) / 60.0);
        g = saturation * (1.0 - (1.0 - (hue - 60.0) / 60.0));
        b = 0.0;
    } else if (hue >= 120 && hue < 180) {
        r = 0.0;
        g = saturation * (1.0 - (hue - 120.0) / 60.0);
        b = saturation * (1.0 - (1.0 - (hue - 120.0) / 60.0));
    } else if (hue >= 180 && hue < 240) {
        r = 0.0;
        g = 0.0;
        b = saturation * (1.0 - (hue - 180.0) / 60.0);
    } else if (hue >= 240 && hue < 300) {
        r = saturation * (1.0 - (hue - 240.0) / 60.0);
        g = 0.0;
        b = saturation * (1.0 - (1.0 - (hue - 240.0) / 60.0));
    } else {
        r = saturation * (1.0 - (hue - 300.0) / 60.0);
        g = saturation * (1.0 - (1.0 - (hue - 300.0) / 60.0));
        b = 0.0;
    }

    // Convert HSL to RGB (adjust for lightness)
    r = lightness + (saturation * (1.0 - lightness)) * r;
    g = lightness + (saturation * (1.0 - lightness)) * g;
    b = lightness + (saturation * (1.0 - lightness)) * b;

    // Scale to 0-255 range
    *red = (int)(r * PWM_RANGE);
    *green = (int)(g * PWM_RANGE);
    *blue = (int)(b * PWM_RANGE);
}

// Set the RGB LED color using pigpio PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Log status messages to stdout
void log_status(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Log error messages to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtod(argv[1], &endptr);
        if (sensitivity <= 0.0 || *endptr != '\0') {
            fprintf(stderr, "Invalid sensitivity value. Using default value of 1.0.\n");
            sensitivity = 1.0;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    if (initialize_alsa() != 0) {
        log_status("ALSA initialization failed, using simulated audio input.");
        audio_available = 0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_status("Mood light started. Press Ctrl+C to exit.");

    // Main loop
    while (running) {
        short *buffer;
        int buffer_size = PERIOD_SIZE * CHANNELS * (BITS_PER_SAMPLE / 8); // Calculate buffer size in bytes
        buffer = (short *)malloc(buffer_size);
        if (buffer == NULL) {
            log_error("Failed to allocate memory for audio buffer.");
            running = 0; // Exit loop on memory allocation failure
            break;
        }

        int err;
        if (audio_available) {
            // Read audio data from ALSA
            err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
            if (err < 0) {
                log_error("Error reading from ALSA: ");
                snd_pcm_prepare(pcm_handle);
                continue; // Retry reading
            } else if (err != PERIOD_SIZE) {
                log_status("Short read from ALSA");
            }
        } else {
            // Simulate audio input
            simulate_audio_input(buffer, PERIOD_SIZE);
        }

        // Calculate RMS amplitude
        double amplitude = calculate_rms(buffer, PERIOD_SIZE);

        // Map amplitude to RGB color
        int red, green, blue;
        map_amplitude_to_color(amplitude * sensitivity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Free allocated memory
        free(buffer);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    log_status("Cleaning up...");
    if (pcm_handle) {
        cleanup_alsa();
    }
    gpioTerminate();

    return 0;
}

