#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO chip name and line numbers
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES {11, 13, 15, 17}

// Define sunrise, daytime, sunset, and nighttime durations (in seconds)
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 86400 - (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION)

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_relay_state(int line_number, int state);
void sunrise_phase();
void daytime_phase();
void sunset_phase();
void nighttime_phase();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int initialize_gpio() {
    int i;
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "sunrise_sunset_simulator";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    int i;
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Set relay state (active-low)
void set_relay_state(int line_number, int state) {
    if (line_number < 0 || line_number > 3) {
        fprintf(stderr, "Invalid line number: %d\n", line_number);
        return;
    }

    int gpio_number = GPIO_LINES[line_number];
    struct gpiod_line *line = lines[line_number];

    if (!line) {
        fprintf(stderr, "Line %d not initialized\n", line_number);
        return;
    }

    int value = (state == 0) ? 1 : 0; // Active-low
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Sunrise phase
void sunrise_phase() {
    int i;
    for (i = 0; i < 4; i++) {
        set_relay_state(i, 1); // Turn on all relays
    }
    sleep(SUNRISE_DURATION);
}

// Daytime phase
void daytime_phase() {
    int i;
    for (i = 0; i < 4; i++) {
        set_relay_state(i, 0); // Turn off all relays
    }
    sleep(DAYTIME_DURATION);
}

// Sunset phase
void sunset_phase() {
    int i;
    for (i = 0; i < 4; i++) {
        set_relay_state(i, 1); // Turn on all relays
    }
    sleep(SUNSET_DURATION);
}

// Nighttime phase
void nighttime_phase() {
