#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define MOTION_SENSOR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a motion event to the log file
void log_motion_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s - Motion detected\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to capture a video using raspivid
void capture_video() {
    char timestamp[25];
    char filename[100];
    char command[200];

    // Get the current timestamp
    strcpy(timestamp, get_iso8601_timestamp());

    // Construct the filename
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    // Construct the raspivid command
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_SEC * 1000);

    // Execute the raspivid command
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: Failed to execute raspivid command.\n");
    } else {
        printf("Video captured: %s\n", filename);
    }
    free((void*)timestamp); // Free the allocated memory
}

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an input
    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the motion sensor value
        int motion_detected = gpioRead(MOTION_SENSOR_GPIO);

        // Debounce and capture video if motion is detected
        if (motion_detected == 0) { // LOW signal indicates motion
            // Log the motion event
            char *timestamp = get_iso8601_timestamp();
            log_motion_event(timestamp);
            free((void*)timestamp);

            // Capture the video
            capture_video();

            // Wait for the debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

