#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor for ±250°/s
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_degrees_per_second(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
int log_data(float x_dps, float y_dps, float z_dps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPU-6050
int initialize_mpu6050() {
    int retries = 0;
    int status;

    while (retries < 3) {
        // Wake up the MPU-6050
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set the sample rate divider
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x08); // Sample rate = 1kHz / (1 + 8) = 125 Hz
        if (status != 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set the gyroscope full-scale range
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00); // ±250°/s
        if (status != 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after 3 retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        return -1; // Failure
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0; // Success
}

// Function to convert raw gyroscope data to degrees per second
void convert_to_degrees_per_second(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / GYRO_SENSITIVITY;
    *y_dps = (float)y / GYRO_SENSITIVITY;
    *z_dps = (float)z / GYRO_SENSITIVITY;
}

// Function to log data to a CSV file
int log_data(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Format timestamp with millisecond precision
    snprintf(timestamp, sizeof(timestamp), "%ld.%03ld", ts.tv_sec, ts.tv_nsec / 1000000);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int status;
    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_degps,Y_degps,Z_degps\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            convert_to_degrees_per_second(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);

            // Log the data
            if (log_data(x_dps, y_dps, z_dps) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data, attempting re-initialization...\n");
            // Attempt to re-initialize the MPU-6050
            if (initialize_mpu6050() != 0) {
                fprintf(stderr, "MPU-6050 re-initialization failed\n");
            }
        }

        gpioDelay(10); // 10 ms delay (100 Hz sampling rate)
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

