    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            convert_to_degrees_per_second(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);

