#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default thresholds
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int configure_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration parameters
typedef struct {
    double freefall_threshold;
    double impact_threshold;
} Config;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the LIS3DH
int configure_lis3dh() {
    char buf[2];

    // Set data rate to 100 Hz and enable all axes
    buf[0] = CTRL_REG1;
    buf[1] = 0x77; // 0b01110111
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Set full scale to ±2g
    buf[0] = CTRL_REG4;
    buf[1] = 0x00; // 0b00000000
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    char data[6];

    // Read X, Y, and Z acceleration values
    buf[0] = OUT_X_L | 0x80; // Enable auto-increment
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to OUT_X_L for reading\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0; // Convert to g
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Set GPIO high
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // Set GPIO low
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    deactivate_buzzer();
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config;
    config.freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    config.impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        config.freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        config.impact_threshold = atof(argv[2]);
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh() != 0) {
        cleanup();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect freefall
            if (magnitude < config.freefall_threshold) {
                printf("Freefall detected! Magnitude: %.3f g\n", magnitude);
                activate_buzzer();
                gpioDelay(1000); // Activate buzzer for 1 second
                deactivate_buzzer();
            }

            // Detect impact
            if (magnitude > config.impact_threshold) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                activate_buzzer();
                gpioDelay(1000); // Activate buzzer for 1 second
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

