#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Define alert duration
#define ALERT_DURATION 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int alert_active = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int read_sensor(int gpio_pin);
void update_circular_buffer(CircularBuffer *cb, int value);
int check_circular_buffer(CircularBuffer *cb, int value);
void alert_user();
void move_forward();
void turn_left();
void turn_right();
void stop();

// Circular buffer functions
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void circular_buffer_add(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

int circular_buffer_get(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        return -1; // Indicate error
    }
    int i = cb->head - cb->count + 1 + index;
    if (i < 0) {
        i += BUFFER_SIZE;
    }
    return cb->buffer[i];
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
