#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 5.0
#define CONVERSION_REG 0xC1
#define DATA_REG_LSB 0xC0
#define DATA_REG_MSB 0xC0
#define DATA_REG_SIZE 2
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_DELAY_MS 10
#define POLL_TIMEOUT 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_si7210(float *field_mT);
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int relay_pin;
    float threshold;
} sensor_config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Could not open I2C device.");
        return -1;
    }
    return 0;
}

// Read magnetic field data from Si7210
int read_si7210(float *field_mT) {
    int lsb, msb, retries = 0;
    int status;

    // Start conversion
    if (i2cWriteByteData(i2c_handle, CONVERSION_REG, 0x01) < 0) {
        log_event("Error: Could not write to conversion register.");
        return -1;
    }

    // Wait for conversion to complete (polling)
    while (retries < POLL_TIMEOUT) {
        status = i2cReadByteData(i2c_handle, CONVERSION_REG);
        if (status < 0) {
            log_event("Error: Could not read conversion register.");
            return -1;
        }
        if (status == 0x00) break; // Conversion complete
        gpioDelay(POLL_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }

    if (retries == POLL_TIMEOUT) {
        log_event("Error: Timeout waiting for conversion.");
        return -1;
    }

    // Read data
    lsb = i2cReadByteData(i2c_handle, DATA_REG_LSB);
    msb = i2cReadByteData(i2c_handle, DATA_REG_MSB);

    if (lsb < 0 || msb < 0) {
        log_event("Error: Could not read data registers.");
        return -1;
    }

    // Combine data
    int16_t field_raw = (msb << 8) | lsb;

    // Convert to milliTesla
    *field_mT = (float)field_raw * 0.01;

    return 0;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Cleanup resources before exiting
void cleanup() {
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    log_event("Cleanup complete. Exiting.");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("Error: I2C initialization failed.");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    log_event("System started.");

    while (!terminate) {
        if (read_si7210(&field_mT) == 0) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Field strength: %.2f mT", field_mT);
            log_event(log_message);

            if (field_mT > FIELD_THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated.");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated.");
                }
            }
        } else {
            log_event("Error: Failed to read magnetic field data.");
        }

        gpioDelay(100 * 1000); // Delay for 100 ms
    }

    cleanup();
    return 0;
}

