#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int server_socket = -1;

// Function prototypes
int setup_gpio();
int setup_socket();
void handle_client(int client_socket);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Setup socket
    if (setup_socket() != 0) {
        fprintf(stderr, "Failed to setup socket. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Relay control server started on port %d. Listening for connections...\n", PORT);

    // Main server loop
    while (program_running) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);

        if (client_socket < 0) {
            perror("Error accepting connection");
            log_event("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_socket);

        close(client_socket);
    }

    // Cleanup and exit
    cleanup();
    printf("Relay control server stopped.\n");
    return 0;
}

// Setup GPIO pin as output
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Setup TCP socket
int setup_socket() {
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        return 1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        return 1;
    }

    if (listen(server_socket, 3) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        return 1;
    }

    return 0;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while (program_running) {
        bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            perror("Error receiving data");
            log_event("Error receiving data");
            break;
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            log_event("Client disconnected");
            break;
        }

        buffer[bytes_received] = '\0'; // Null-terminate the received data
        printf("Received: %s\n", buffer);

        // Process the command
        char *command = strtok(buffer, " \t\n"); // Tokenize the input
        if (command != NULL) {
            // Convert to lowercase
            for (int i = 0; command[i]; i++) {
                command[i] = tolower(command[i]);
            }

            if (strcmp(command, "on") == 0) {
                gpioWrite(GPIO_PIN, 1); // Activate relay
                log_event("Relay activated");
                printf("Relay activated\n");
            } else if (strcmp(command, "off") == 0) {
                gpioWrite(GPIO_PIN, 0); // Deactivate relay
                log_event("Relay deactivated");
                printf("Relay deactivated\n");
            } else {
                log_event("Invalid command");
                printf("Invalid command\n");
            }
        }
    }
}

// Log events to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Event: %s\n", event);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (server_socket != -1) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
}

