#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define START_MEASUREMENT_CMD 0x3608
#define GPIO_RELAY 18
#define FLOW_THRESHOLD 5.0
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_FINAL_XOR 0x00
#define LOG_FILE "flow_log.txt"
#define POLLING_INTERVAL_MS 100

// Global variables
static volatile int running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr);
int write_i2c(int handle, uint16_t data);
int read_i2c(int handle, char *buffer, int count);
uint8_t calculate_crc8(const char *data, int len);
float convert_flow_rate(int16_t raw_value);
void control_relay(int gpio, float flow_rate1, float flow_rate2);
void log_flow_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C handle
int open_i2c_handle(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to write data to I2C
int write_i2c(int handle, uint16_t data) {
    char buf[2];
    buf[0] = (data >> 8) & 0xFF; // MSB
    buf[1] = data & 0xFF;      // LSB

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from I2C
int read_i2c(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc8(const char *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw data to flow rate (ml/min)
float convert_flow_rate(int16_t raw_value) {
    return (float)raw_value / 1500.0;
}

// Function to control the relay
void control_relay(int gpio, float flow_rate1, float flow_rate2) {
    if (flow_rate1 < FLOW_THRESHOLD || flow_rate2 < FLOW_THRESHOLD) {
        gpioWrite(gpio, 1); // Energize relay
    } else {
        gpioWrite(gpio, 0); // De-energize relay
    }
}

// Function to log flow data to a file
void log_flow_data(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", timestamp, flow_rate1, flow_rate2);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // De-energize relay initially

    // Start measurement on both sensors
    if (write_i2c(i2c_handle1, START_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (write_i2c(i2c_handle2, START_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        char buffer1[3];
        char buffer2[3];
        int16_t raw_flow1, raw_flow2;
        float flow_rate1, flow_rate2;

        // Read data from sensor 1
        if (read_i2c(i2c_handle1, buffer1, 3) == 0) {
            // Validate CRC-8
            uint8_t crc1 = calculate_crc8(buffer1, 2);
            if (crc1 != buffer1[2]) {
                fprintf(stderr, "CRC mismatch for sensor 1\n");
            } else {
                // Convert raw data to flow rate
                raw_flow1 = (buffer1[0] << 8) | buffer1[1];
                flow_rate1 = convert_flow_rate(raw_flow1);
            }
        } else {
            flow_rate1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_i2c(i2c_handle2, buffer2, 3) == 0) {
            // Validate CRC-8
            uint8_t crc2 = calculate_crc8(buffer2, 2);
            if (crc2 != buffer2[2]) {
                fprintf(stderr, "CRC mismatch for sensor 2\n");
            } else {
                // Convert raw data to flow rate
                raw_flow2 = (buffer2[0] << 8) | buffer2[1];
                flow_rate2 = convert_flow_rate(raw_flow2);
            }
        } else {
            flow_rate2 = -1.0; // Indicate error
        }

        // Control relay based on flow rates
        control_relay(GPIO_RELAY, flow_rate1, flow_rate2);

        // Log flow data
        log_flow_data(flow_rate1, flow_rate2);

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioWrite(GPIO_RELAY, 0); // De-energize relay
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

