    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    gpioWrite(MOTOR_ENABLE_PIN, 0); // Ensure motor is initially off
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message(LOG_ERR, "Error reading rain sensor");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to close the window
void close_window() {
    log_message(LOG_INFO, "Closing window");
    gpioWrite(MOTOR_ENABLE_PIN, 1); // Enable motor
    gpioWrite(MOTOR_IN1_PIN, 1);    // Set IN1 HIGH
    gpioWrite(MOTOR_IN2_PIN, 0);    // Set IN2 LOW
    gpioDelay(MOTOR_RUN_DURATION);   // Run motor for 5 seconds
    stop_motor();                    // Stop the motor
    log_message(LOG_INFO, "Window closed");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_ENABLE_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0);    // Set IN1 LOW
    gpioWrite(MOTOR_IN2_PIN, 0);    // Set IN2 LOW
    log_message(LOG_INFO, "Motor stopped");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_message(LOG_INFO, "Rain window controller started");

    // Main loop
    while (running) {
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, continue to next iteration
            gpioDelay(200); // Wait 200ms before next poll
            continue;
        }

        if (sensor_value == 0 && !rain_detected) {
            // Rain detected (sensor value is LOW)
            rain_detected = 1;
            consecutive_rain_polls = 0; // Reset counter
            close_window();
        } else if (sensor_value == 1 && rain_detected) {
            // Rain stopped (sensor value is HIGH)
            rain_detected = 0;
            consecutive_rain_polls = 0; // Reset counter
        } else if (sensor_value == 0 && rain_detected) {
            // Rain still detected, increment counter
            consecutive_rain_polls++;
            if (consecutive_rain_polls >= (RAIN_DETECTION_DURATION / 200)) {
                // Rain has been detected for the required duration
                rain_detected = 0;
                consecutive_rain_polls = 0;
            }
        }

        gpioDelay(200); // Wait 200ms before next poll
    }

    return 0;
}

