        int lock_pressed = read_lock_button();
        int unlock_pressed = read_unlock_button();

        // Control servo based on button presses
        if (lock_pressed) {
            if (set_servo_position(LOCKED_PULSE_WIDTH) != 0) {
                fprintf(stderr, "Failed to set servo to locked position.\n");
            } else {
                printf("Door locked.\n");
            }
        } else if (unlock_pressed) {
            if (set_servo_position(UNLOCKED_PULSE_WIDTH) != 0) {
                fprintf(stderr, "Failed to set servo to unlocked position.\n");
            } else {
                printf("Door unlocked.\n");
            }
        }

        // Small sleep to avoid high CPU usage
        gpioDelay(10000); // 10ms
    }

    // Clean up and exit
    set_servo_position(0); // Stop the servo
    gpioTerminate();       // Terminate pigpio
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

