    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0;
}

// Set the servo pulse width
int set_servo_position(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width to %d\n", pulse_width);
        return 1;
    }
    return 0;
}

// Read the lock button state with debouncing
int read_lock_button() {
    int button_state = gpioRead(LOCK_BUTTON);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    return (button_state == 0); // Button is pressed when GPIO is low
}

// Read the unlock button state with debouncing
int read_unlock_button() {
    int button_state = gpioRead(UNLOCK_BUTTON);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    return (button_state == 0); // Button is pressed when GPIO is low
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, stopping program...\n");
}

