#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_DURATION 60 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_floodlight();
void deactivate_floodlight();
void log_event(const char *event_type, int duration);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int pir_state;
    time_t last_motion_time;
} sensor_data_t;

sensor_data_t sensor_data = {0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read PIR sensor
        int pir_value = read_pir_sensor();

        // Check for motion
        if (pir_value == 1) {
            // Debounce the sensor
            if (sensor_data.pir_state == 0) {
                sensor_data.pir_state = 1;
                sensor_data.last_motion_time = time(NULL);

                // Activate floodlight
                activate_floodlight();

                // Log event
                log_event("Motion Detected", 0); // Duration is 0 for motion detection
            }
        } else {
            // Reset PIR state if no motion is detected
            sensor_data.pir_state = 0;
        }

        // Sleep for polling interval
        gpioDelay(POLLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Smart Security Light System stopped.\n");
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate floodlight for 60 seconds
void activate_floodlight() {
    gpioWrite(LED_PIN, 1); // Turn on LED
    gpioDelay(LED_ON_DURATION * 1000000); // Delay for 60 seconds (microseconds)
    gpioWrite(LED_PIN, 0); // Turn off LED
}

// Deactivate floodlight
void deactivate_floodlight() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
}

// Log event to file
void log_event(const char *event_type, int duration) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        if (strcmp(event_type, "Motion Detected") == 0) {
            fprintf(log_file, "%s: Motion Detected\n", buf);
        } else {
            fprintf(log_file, "%s: Floodlight Deactivated, Duration: %d seconds\n", buf, duration);
        }
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    // Deactivate floodlight
    deactivate_floodlight();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

