// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// MPR121 Initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER, 0x05) < 0) { // MHD = 5
        fprintf(stderr, "Error: Baseline filter configuration failed\n");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE, 0x0A) < 0) { // NHD = 10, NCL = 10, FDL = 10
        fprintf(stderr, "Error: Debounce configuration failed\n");
        return -1;
    }

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, MPR121_FILT_CONFIG, 0x24) < 0) { // FFI = 36, SFI = 36, CDT = 36
        fprintf(stderr, "Error: FFI/SFI/CDT configuration failed\n");
        return -1;
    }

    // Set auto-config
    if (i2cWriteByteData(i2c_handle, MPR121_AUTO_CONFIG_1, 0x01) < 0) { // ELE0
        fprintf(stderr, "Error: Auto-config 1 failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_AUTO_CONFIG_2, 0x02) < 0) { // ELE1
        fprintf(stderr, "Error: Auto-config 2 failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_AUTO_CONFIG_3, 0x04) < 0) { // ELE2
        fprintf(stderr, "Error: Auto-config 3 failed\n");
        return -1;
    }

    // Enable electrodes 0-11
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode configuration failed\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status() {
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Failed to read touch status L\n");
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status H\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to toggle the relay
void toggle_relay() {
    gpioWrite(RELAY_GPIO, 1); // Turn relay ON
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially OFF

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
            break; // Exit loop on error
        }

        // Check for rising edge on electrode 0
        if ((touch_status & 0x01) && !(touch_status & 0x02)) {
            toggle_relay();
        }

        gpioDelay(50); // Small delay to avoid busy-waiting
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    printf("MPR121 relay control stopped.\n");
    return 0;
}

