#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define PORT 5000
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds
#define SERVO_MIN_PULSE_WIDTH 1000 // microseconds
#define SERVO_MAX_PULSE_WIDTH 2000 // microseconds
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define PIR_DEBOUNCE_DELAY 50 // milliseconds

// Global variables
static int socket_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void log_message(int priority, const char *format, ...);
int initialize_gpio();
void cleanup_gpio();
void handle_client(int client_fd);
void servo_thread(void *arg);
void *pir_thread(void *arg);
void *servo_thread(void *arg);
void *pir_thread(void *arg);
void signal_handler(int signum);
int parse_command(char *command, int *angle);

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);

    if (log_file != NULL) {
        va_start(args, format);
        vfprintf(log_file, format, args);
        va_end(args);
        fflush(log_file);
    }
}

// Initialize GPIO
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo GPIO line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR GPIO line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0); // Set to a safe state
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Handle client connection
void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received command: %s", buffer);
        if (parse_command(buffer, NULL) == 0) {
            log_message(LOG_INFO, "Command processed successfully.");
        } else {
            log_message(LOG_ERR, "Failed to process command.");
        }
    }

    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s", strerror(errno));
    }

    close(client_fd);
}

// Servo thread function
void *servo_thread(void *arg) {
    while (!terminate) {
        // Calculate pulse width for 0-180 degrees
        for (int angle = 0; angle <= 180; angle++) {
            int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * SERVO_RANGE);
            gpiod_line_set_value(servo_line, 1);
            usleep(pulse_width);
            gpiod_line_set_value(servo_line, 0);
            usleep(PWM_PERIOD - pulse_width);
        }
        for (int angle = 180; angle >= 0; angle--) {
            int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * SERVO_RANGE);
            gpiod_line_set_value(servo_line, 1);
            usleep(pulse_width);
            gpiod_line_set_value(servo_line, 0);
            usleep(PWM_PERIOD - pulse_width);
        }
    }
    return NULL;
}

// PIR thread function
void *pir_thread(void *arg) {
    int pir_state = 0;
    struct timespec last_change_time;
    clock_gettime(CLOCK_MONOTONIC, &last_change_time);

    while (!terminate) {
        int current_pir_state = gpiod_line_get_value(pir_line);

        if (current_pir_state != pir_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long time_diff_ns = (now.tv_sec - last_change_time.tv_sec) * 1000000000L + (now.tv_nsec - last_change_time.tv_nsec);

            if (time_diff_ns >= PIR_DEBOUNCE_DELAY * 1000000) {
                pir_state = current_pir_state;
                last_change_time = now;

                if (pir_state == 1) {
                    log_message(LOG_INFO, "PIR:1");
                    char pir_status[10];
                    snprintf(pir_status, sizeof(pir_status), "PIR:1");
                    send(socket_fd, pir_status, strlen(pir_status), 0);
                } else {
                    log_message(LOG_INFO, "PIR:0");
                    char pir_status[10];
                    snprintf(pir_status, sizeof(pir_status), "PIR:0");
                    send(socket_fd, pir_status, strlen(pir_status), 0);
                }
            }
        }
        usleep(10000); // Check every 10ms
    }
    return NULL;
}

// Parse command
int parse_command(char *command, int *angle) {
    if (strncmp(command, "SERVO ", 6) == 0) {
        if (sscanf(command + 6, "%d", angle) == 1) {
            if (*angle >= 0 && *angle <= 180) {
                return 0; // Success
            } else {
                log_message(LOG_ERR, "Invalid servo angle: %d", *angle);
                return -1; // Failure
            }
        } else {
            log_message(LOG_ERR, "Invalid servo command format.");
            return -1; // Failure
        }
    } else if (strcmp(command, "PIR") == 0) {
        return 0; // Success, handled in PIR thread
    } else {
        log_message(LOG_ERR, "Invalid command: %s", command);
        return -1; // Failure
    }
}

// Signal handler
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d. Terminating...", signum);
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("security_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        log_message(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Bind socket
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        log_message(LOG_ERR, "Failed to bind socket: %s", strerror(errno));
        close(socket_fd);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 5) < 0) {
        log_message(LOG_ERR, "Failed to listen on socket: %s", strerror(errno));
        close(socket_fd);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d...", PORT);

    // Create threads
    pthread_t servo_thread_id, pir_thread_id;
    if (pthread_create(&servo_thread_id, NULL, servo_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create servo thread: %s", strerror(errno));
        close(socket_fd);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }
    if (pthread_create(&pir_thread_id, NULL, pir_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PIR thread: %s", strerror(errno));
        close(socket_fd);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Accept connections
    struct sockaddr_in client_address;
    socklen_t client_len = sizeof(client_address);
    int client_fd;

    while (!terminate) {
        client_fd = accept(socket_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (terminate) break; // Exit loop if termination signal received
            log_message(LOG_ERR, "Failed to accept connection: %s", strerror(errno));
            continue; // Continue listening
        }

        log_message(LOG_INFO, "Accepted connection from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_fd);
    }

    // Join threads
    pthread_join(servo_thread_id, NULL);
    pthread_join(pir_thread_id, NULL);

    // Cleanup
    close(socket_fd);
    cleanup_gpio();
    fclose(log_file);
    closelog();

    log_message(LOG_INFO, "Exiting cleanly.");
    return 0;
}

