#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 100.0
#define DEFAULT_DURATION 500

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *hx711_dout;
static struct gpiod_line *hx711_sck;
static struct gpiod_line *solenoid_pin;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_hx711(void);
double calculate_weight(int raw_value, double tare_offset);
void activate_solenoid(double weight, double threshold);
void tare_load_cell(void);
void cleanup_gpio(void);
void signal_handler(int sig);
void log_message(int priority, const char *message);

// Helper function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    static char timestamp[20]; // Ensure buffer is large enough
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    hx711_dout = gpiod_chip_get_line(chip, HX711_DOUT);
    hx711_sck = gpiod_chip_get_line(chip, HX711_SCK);
    solenoid_pin = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!hx711_dout || !hx711_sck || !solenoid_pin) {
        log_message(LOG_ERR, "Failed to get GPIO line");
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_output(solenoid_pin, "solenoid", 0) < 0) {
        log_message(LOG_ERR, "Failed to request solenoid pin as output");
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_input(hx711_dout, "hx711_dout") < 0) {
        log_message(LOG_ERR, "Failed to request HX711 DOUT pin as input");
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_output(hx711_sck, "hx711_sck", 0) < 0) {
        log_message(LOG_ERR, "Failed to request HX711 SCK pin as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Read data from HX711
int read_hx711(void) {
    int32_t raw_value = 0;
    int i;

    // Wait for DOUT to go LOW
    int timeout = 0;
    while (gpiod_line_get_value(hx711_dout) == 1 && timeout < 1000) {
        usleep(1000); // Wait 1 ms
        timeout++;
    }

    if (timeout >= 1000) {
        log_message(LOG_ERR, "Timeout waiting for HX711 data");
        return -1;
    }

    // Clock out 24 bits
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(hx711_sck, 1);
        usleep(1); // Small delay
        raw_value = raw_value << 1;
        if (gpiod_line_get_value(hx711_dout)) {
            raw_value++;
        }
        gpiod_line_set_value(hx711_sck, 0);
        usleep(1); // Small delay
    }

    // Clock out one extra bit to select channel A / gain 128
    gpiod_line_set_value(hx711_sck, 1);
    usleep(1); // Small delay
    gpiod_line_set_value(hx711_sck, 0);
    usleep(1); // Small delay

    return raw_value;
}

// Calculate weight from raw value
double calculate_weight(int raw_value, double tare_offset) {
    return (raw_value - tare_offset) / scale;
}

// Activate solenoid lock
void activate_solenoid(double weight, double threshold) {
    if (weight > threshold) {
        log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid");
        gpiod_line_set_value(solenoid_pin, 1);
        usleep(duration * 1000); // Convert ms to us
        gpiod_line_set_value(solenoid_pin, 0);
        log_message(LOG_INFO, "Solenoid deactivated");
    }
}

// Tare the load cell
void tare_load_cell(void) {
    int i;
    int32_t sum = 0;
    int32_t raw_value;

    log_message(LOG_INFO, "Starting tare sequence");
    for (i = 0; i < 10; i++) {
        raw_value = read_hx711();
        if (raw_value < 0) {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return;
        }
        sum += raw_value;
        usleep(10000); // 10ms delay
    }
    double tare_offset = (double)sum / 10.0;
    log_message(LOG_INFO, "Tare offset: %f", tare_offset);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    log_message(LOG_INFO, "Cleaning up GPIO lines");
    if (hx711_dout) gpiod_line_release(hx711_dout);
    if (hx711_sck) gpiod_line_release(hx711_sck);
    if (solenoid_pin) gpiod_line_release(solenoid_pin);
    if (chip) gpiod_chip_close(chip);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s: %s", get_timestamp(), message);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    // Tare the load cell
    tare_load_cell();

    // Main loop
    int raw_value;
    double weight;
    while (!terminate) {
        raw_value = read_hx711();
        if (raw_value < 0) {
            log_message(LOG_ERR, "Error reading HX711, retrying...");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        weight = calculate_weight(raw_value, 0.0); // Use tare offset of 0.0
        char weight_str[50];
        snprintf(weight_str, sizeof(weight_str), "%.2f grams", weight);
        log_message(LOG_INFO, weight_str);

        activate_solenoid(weight, threshold);

        usleep(500000); // Poll every 500ms
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

