#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEPALIVE 60

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int sig);
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void gpio_control_callback(const char *payload);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// MQTT connect callback
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s, error: %s", MQTT_TOPIC, mosquitto_strerror(subscribe_result));
            mosquitto_disconnect(mosq);
            return 1;
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
        return 1;
    }
    return 0;
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker, reason code: %d", rc);
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        gpio_control_callback((char *)message->payload);
    } else {
        syslog(LOG_ERR, "Received empty message on topic: %s", message->topic);
    }
}

// GPIO control callback
void gpio_control_callback(const char *payload) {
    if (strcmp(payload, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1); // Energize relay
        syslog(LOG_INFO, "Received ON command, setting GPIO %d HIGH", GPIO_PIN);
    } else if (strcmp(payload, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0); // De-energize relay
        syslog(LOG_INFO, "Received OFF command, setting GPIO %d LOW", GPIO_PIN);
    } else {
        syslog(LOG_ERR, "Received invalid payload: %s, expected ON/OFF", payload);
    }
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    // Connect to MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        gpioTerminate();
        mosquitto_lib_cleanup();
        mosquitto_destroy(mosq);
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 for blocking, 1 for max 1 message processed
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Mosquitto loop error: %s, reconnecting...", mosquitto_strerror(rc));
            gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on reconnect
            mosquitto_disconnect(mosq);
            sleep(5);
            connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE);
            if (connect_result != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker: %s", mosquitto_strerror(connect_result));
                running = 0; // Exit loop if reconnect fails repeatedly
            }
        }
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

