#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_POS 1000
#define SERVO2_POS 1500
#define SERVO3_POS 2000
#define SERVO4_POS 500
#define SERVO5_POS 2500

int main() {
    int pigpio_init_result;

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set PWM frequency to 50 Hz (20 ms period)
    gpioSetPWMfrequency(SERVO1_PIN, 50);
    gpioSetPWMfrequency(SERVO2_PIN, 50);
    gpioSetPWMfrequency(SERVO3_PIN, 50);
    gpioSetPWMfrequency(SERVO4_PIN, 50);
    gpioSetPWMfrequency(SERVO5_PIN, 50);

    // Set PWM range to 20000 (0.05 ms resolution)
    gpioSetPWMrange(SERVO1_PIN, 20000);
    gpioSetPWMrange(SERVO2_PIN, 20000);
    gpioSetPWMrange(SERVO3_PIN, 20000);
    gpioSetPWMrange(SERVO4_PIN, 20000);
    gpioSetPWMrange(SERVO5_PIN, 20000);

    // Set pulse widths for each servo
    gpioPWM(SERVO1_PIN, SERVO1_POS);
    gpioPWM(SERVO2_PIN, SERVO2_POS);
    gpioPWM(SERVO3_PIN, SERVO3_POS);
    gpioPWM(SERVO4_PIN, SERVO4_POS);
    gpioPWM(SERVO5_PIN, SERVO5_POS);

    // Hold the signals for 3 seconds
    gpioDelay(3000000); // 3000000 microseconds = 3 seconds

    // Stop PWM and release resources
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    gpioTerminate();

    printf("Servos moved to predefined positions and program terminated.\n");

    return 0;
}

