#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target speed (RPM)
#define TARGET_SPEED 50.0

// PI controller gains
#define Kp 0.5
#define Ki 0.05

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Stall detection time (seconds)
#define STALL_TIME 2

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;
int running = 1;

// Function prototypes
void motor_a_forward(int duty_cycle);
void motor_a_reverse(int duty_cycle);
void motor_b_forward(int duty_cycle);
void motor_b_reverse(int duty_cycle);
void stop_motor_a();
void stop_motor_b();
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double pi_controller(double setpoint, double actual_value, double *integral, double last_error);
void signal_handler(int signal);

// Motor control functions
void motor_a_forward(int duty_cycle) {
    gpioWrite(MOTOR_A_IN2, 1);
    gpioPWM(MOTOR_A_IN1, duty_cycle);
}

void motor_a_reverse(int duty_cycle) {
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN1, duty_cycle);
}

void motor_b_forward(int duty_cycle) {
    gpioWrite(MOTOR_B_IN4, 1);
    gpioPWM(MOTOR_B_IN3, duty_cycle);
}

void motor_b_reverse(int duty_cycle) {
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN3, duty_cycle);
}

// Motor stop functions
void stop_motor_a() {
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN1, 0);
}

void stop_motor_b() {
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN3, 0);
}

// Encoder interrupt service routines
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (gpio == ENCODER_A_A) {
        if (gpioRead(ENCODER_A_B) == 0) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    } else if (gpio == ENCODER_A_B) {
        if (gpioRead(ENCODER_A_A) == 0) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (gpio == ENCODER_B_A) {
        if (gpioRead(ENCODER_B_B) == 0) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    } else if (gpio == ENCODER_B_B) {
        if (gpioRead(ENCODER_B_A) == 0) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    }
}

// RPM calculation function
double calculate_rpm(int encoder_count) {
    double rpm = (double)encoder_count * 60.0 / 64.0; // 64 ticks per revolution
    encoder_count = 0; // Reset encoder count after calculation
    return rpm;
}

// PI controller function
double pi_controller(double setpoint, double actual_value, double *integral, double last_error) {
    double error = setpoint - actual_value;
    *integral += error;
    double derivative = error - last_error;
    double output = Kp * error + Ki * (*integral);
    return output;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    running = 0;
    stop_motor_a();
    stop_motor_b();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQUENCY);

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_A_A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_A_B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_B_A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_B_B\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_count);
        double rpm_b = calculate_rpm(encoder_b_count);

        // PI controller
        double error_a = TARGET_SPEED - rpm_a;
        double output_a = pi_controller(TARGET_SPEED, rpm_a, &integral_a, last_error_a);
        last_error_a = error_a;

        double error_b = TARGET_SPEED - rpm_b;
        double output_b = pi_controller(TARGET_SPEED, rpm_b, &integral_b, last_error_b);
        last_error_b = error_b;

        // Clamp output to [0, 255]
        int duty_cycle_a = (int)output_a;
        if (duty_cycle_a < 0) duty_cycle_a = 0;
        if (duty_cycle_a > 255) duty_cycle_a = 255;

        int duty_cycle_b = (int)output_b;
        if (duty_cycle_b < 0) duty_cycle_b = 0;
        if (duty_cycle_b > 255) duty_cycle_b = 255;

        // Motor control
        motor_a_forward(duty_cycle_a);
        motor_b_forward(duty_cycle_b);

        // Stall detection
        if (encoder_a_count == 0) {
            printf("Encoder A stalled!\n");
        }
        if (encoder_b_count == 0) {
            printf("Encoder B stalled!\n");
        }

        // Print data
        printf("Motor A RPM: %.2f, Duty Cycle: %d, Motor B RPM: %.2f, Duty Cycle: %d\n", rpm_a, duty_cycle_a, rpm_b, duty_cycle_b);

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor_a();
    stop_motor_b();
