#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target speed (RPM)
#define TARGET_SPEED 50.0

// PI controller gains
#define Kp 0.5
#define Ki 0.05

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Stall detection time (seconds)
#define STALL_TIME 2

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;
int running = 1;

// Function prototypes
void motor_a_forward(int duty_cycle);
void motor_a_reverse(int duty_cycle);
void motor_b_forward(int duty_cycle);
void motor_b_reverse(int duty_cycle);
void stop_motor_a();
void stop_motor_b();
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double pi_controller(double setpoint, double actual_value, double *integral, double last_error);
void signal_handler(int signal);

// Motor control functions
void motor_a_forward(int duty_cycle) {
    gpioWrite(MOTOR_A_IN2, 1);
    gpioPWM(MOTOR_A_IN1, duty_cycle);
}

void motor_a_reverse(int duty_cycle) {
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN1, duty_cycle);
}

void motor_b_forward(int duty_cycle) {
    gpioWrite(MOTOR_B_IN4, 1);
    gpioPWM(MOTOR_B_IN3, duty_cycle);
}

void motor_b_reverse(int duty_cycle) {
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN3, duty_cycle);
}

// Motor stop functions
void stop_motor_a() {
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN1, 0);
}

void stop_motor_b() {
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN3, 0);
}

// Encoder interrupt service routines
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (gpio == ENCODER_A_A) {
        if (gpioRead(ENCODER_A_B) == 0) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    } else if (gpio == ENCODER_A_B) {
        if (gpioRead(ENCODER_A_A) == 0) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (gpio == ENCODER_B_A) {
        if (gpioRead(ENCODER_B_B) == 0) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    } else if (gpio == ENCODER_B_B) {
        if (gpioRead(ENCODER_B_A) == 0) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    }
}

