    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_A_A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_A_B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_B_A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_B_B\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_count);
        double rpm_b = calculate_rpm(encoder_b_count);

        // PI controller
        double error_a = TARGET_SPEED - rpm_a;
        double output_a = pi_controller(TARGET_SPEED, rpm_a, &integral_a, last_error_a);
        last_error_a = error_a;

        double error_b = TARGET_SPEED - rpm_b;
        double output_b = pi_controller(TARGET_SPEED, rpm_b, &integral_b, last_error_b);
        last_error_b = error_b;

        // Clamp output to [0, 255]
        int duty_cycle_a = (int)output_a;
        if (duty_cycle_a < 0) duty_cycle_a = 0;
        if (duty_cycle_a > 255) duty_cycle_a = 255;

        int duty_cycle_b = (int)output_b;
        if (duty_cycle_b < 0) duty_cycle_b = 0;
        if (duty_cycle_b > 255) duty_cycle_b = 255;

        // Motor control
        motor_a_forward(duty_cycle_a);
        motor_b_forward(duty_cycle_b);

        // Stall detection
        if (encoder_a_count == 0) {
            printf("Encoder A stalled!\n");
        }
        if (encoder_b_count == 0) {
            printf("Encoder B stalled!\n");
        }

        // Print data
        printf("Motor A RPM: %.2f, Duty Cycle: %d, Motor B RPM: %.2f, Duty Cycle: %d\n", rpm_a, duty_cycle_a, rpm_b, duty_cycle_b);

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor_a();
    stop_motor_b();
    gpioTerminate();

    return 0;
}

