#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS 20
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(int *lux);
void control_relay(int state);
void log_data(int lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int relay_pin;
    int dusk_threshold;
    int dawn_threshold;
    int hysteresis;
    char log_file_path[64];
} coop_config_t;

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int *lux) {
    char buf[2];
    int result;

    // Send One-Time High-Resolution Mode 2 command
    result = i2cWriteByte(i2c_handle, 0x21);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 180 ms
    gpioDelay(180000); // 180 ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Convert raw data to lux
    *lux = (buf[0] << 8 | buf[1]) / 1.2;
    return 0;
}

// Control the relay (ON/OFF)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(int lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    int lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_relay_state = 0; // Keep track of the last relay state

    // Initialize configuration
    coop_config_t config = {
        .relay_pin = RELAY_GPIO,
        .dusk_threshold = LUX_THRESHOLD_DUSK,
        .dawn_threshold = LUX_THRESHOLD_DAWN,
        .hysteresis = HYSTERESIS,
        .log_file_path = LOG_FILE
    };

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fprintf(stdout, "Chicken coop lighting system started\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Control relay based on lux value and hysteresis
            if (lux < config.dusk_threshold && relay_state == 0) {
                relay_state = 1;
                control_relay(relay_state);
                log_data(lux, relay_state);
                last_relay_state = relay_state; // Update last relay state
            } else if (lux > config.dawn_threshold && relay_state == 1) {
                relay_state = 0;
                control_relay(relay_state);
                log_data(lux, relay_state);
                last_relay_state = relay_state; // Update last relay state
            }

            // Log data even if the relay state didn't change
            log_data(lux, last_relay_state); // Use last_relay_state to log the relay state

            printf("Lux: %d, Relay: %s\n", lux, relay_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Failed to read lux value\n");
            control_relay(0); // Turn off relay on error
            log_data(-1, 0); // Log error
            last_relay_state = 0; // Update last relay state
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stdout, "Chicken coop lighting system stopped\n");
    return 0;
}

