#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int relay_pin;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {TOUCH_SENSOR_PIN, RELAY_PIN};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

            // Read touch sensor again after debounce
            if (read_touch_sensor() == 1) {
                // Toggle relay state
                toggle_relay();

                // Log relay state
                log_relay_state(relay_state);
            }
        }

        // Small delay to reduce CPU usage
        gpioDelay(10000); // 10 ms
    }

    return 0;
}

// Function to initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input
    if (gpioSetMode(gpio_config.touch_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_config.touch_pin);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    if (gpioSetMode(gpio_config.relay_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_config.relay_pin);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(gpio_config.relay_pin, 0);

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(gpio_config.touch_pin);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(gpio_config.relay_pin, relay_state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn relay OFF
    gpioWrite(gpio_config.relay_pin, 0);

    // Release pigpio resources
    gpioTerminate();

    printf("Exiting.\n");
    exit(0);
}

