#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS_THRESHOLD 0.5
#define DEBOUNCE_TIMEOUT 1000 // milliseconds
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
static volatile int pulse_count = 0;
static volatile int solenoid_state = 1; // 1 = open, 0 = closed
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for the flow sensor
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate liters per minute
double calculate_lpm(int pulses) {
    return (pulses / PULSES_PER_LITER) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        solenoid_state = 0; // Close the valve
        gpioWrite(SOLENOID_GPIO, 0);
        log_data(-1.0, solenoid_state); // Log the state change
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        solenoid_state = 1; // Open the valve
        gpioWrite(SOLENOID_GPIO, 1);
        log_data(-1.0, solenoid_state); // Log the state change
    }
}

// Function to log data to a file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (lpm != -1.0) {
            fprintf(log_file, "%s, LPM: %.2f, Solenoid State: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        } else {
            fprintf(log_file, "%s, Solenoid State: %s\n", timestamp, solenoid_state ? "OPEN" : "CLOSED");
        }
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop
    gpioWrite(SOLENOID_GPIO, 1); // Open the solenoid valve
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", SOLENOID_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set solenoid to open state initially
    gpioWrite(SOLENOID_GPIO, 1);
    solenoid_state = 1;

    // Open the log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Log the initial state
    log_data(-1.0, solenoid_state);

    // Set up interrupt service routine with debounce
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", FLOW_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(SOLENOID_GPIO, 1); // Open the solenoid valve
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    time_t last_sample_time = time(NULL);
    int current_pulse_count;
    double lpm;

    while (running) {
        time_t current_time = time(NULL);
        if (current_time - last_sample_time >= SAMPLE_INTERVAL) {
            // Sample the pulse count
            pthread_mutex_lock(&pulse_mutex);
            current_pulse_count = pulse_count;
            pulse_count = 0; // Reset the counter
            pthread_mutex_unlock(&pulse_mutex);

            // Calculate LPM
            lpm = calculate_lpm(current_pulse_count);

            // Control the solenoid
            control_solenoid(lpm);

            // Log the data
            log_data(lpm, solenoid_state);

            last_sample_time = current_time;
        }

        gpioDelay(100); // Check every 100ms
    }

    cleanup();
    return 0;
}

