#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_HX711_DATA_PIN 23
#define DEFAULT_HX711_SCK_PIN 24

// Global variables
double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;
int servo_pin = DEFAULT_SERVO_PIN;
int hx711_data_pin = DEFAULT_HX711_DATA_PIN;
int hx711_sck_pin = DEFAULT_HX711_SCK_PIN;
int socket_fd = -1;
int client_fd = -1;
FILE *log_file = NULL;

// Function prototypes
double read_hx711();
double calibrate_hx711(double known_weight);
void dispense_ingredient(double target_weight);
void log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int load_configuration();
void save_configuration();

// HX711 read function
double read_hx711() {
    int data_pin = hx711_data_pin;
    int sck_pin = hx711_sck_pin;
    int i;
    long count;
    double value;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 1000) {
        log_event(-1.0, -1.0, "HX711 timeout: Data pin did not go low");
        return -1.0; // Indicate error
    }

    count = 0;
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // 1 us pulse
        count = count << 1;
        if (gpioRead(data_pin)) {
            count++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // 1 us pulse
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    count = count ^ 0x800000; // Convert to signed 24-bit integer

    value = (double)count / 16.0; // Convert to grams (assuming 128 gain)

    return value;
}

// HX711 calibration function
double calibrate_hx711(double known_weight) {
    double sum = 0.0;
    int num_samples = 10;
    int i;

    printf("Calibrating HX711... Please ensure no weight is on the load cell.\n");
    for (i = 0; i < num_samples; i++) {
        double reading = read_hx711();
        if (reading < 0) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return -1.0; // Indicate error
        }
        sum += reading;
        gpioDelay(100); // Small delay between samples
    }
    double average_reading = sum / num_samples;

    printf("Calibration complete. Average reading: %.2f\n", average_reading);
    printf("Enter the known weight in grams: ");
    double entered_weight;
    if (scanf("%lf", &entered_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight.\n");
        return -1.0; // Indicate error
    }

    calibration_factor = (average_reading - entered_weight) / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);
    save_configuration();

    return calibration_factor;
}

// Servo control function
void dispense_ingredient(double target_weight) {
    int servo_pin = DEFAULT_SERVO_PIN;
    double actual_weight;
    int pulse_width;

    // Read actual weight from HX711
    actual_weight = read_hx711();
    if (actual_weight < 0) {
        log_event(target_weight, -1.0, "Error reading HX711 during dispensing");
        return;
    }

    // Map target weight to servo pulse width
    pulse_width = (int)((target_weight / calibration_factor) * 1000.0); // 1000-2000 us
    if (pulse_width < 1000) pulse_width = 1000;
    if (pulse_width > 2000) pulse_width = 2000;

    // Set servo pulse width
    gpioServo(servo_pin, pulse_width);
    gpioDelay(1000); // Wait for servo to move

    // Read actual weight again after servo movement
    actual_weight = read_hx711();
    if (actual_weight < 0) {
        log_event(target_weight, -1.0, "Error reading HX711 after dispensing");
        return;
    }

    // Log the event
    log_event(target_weight, actual_weight, NULL);

    printf("Target weight: %.2f g, Actual weight: %.2f g, Servo pulse width: %d us\n", target_weight, actual_weight, pulse_width);
}

// Logging function
void log_event(double target_weight, double actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    cJSON *root = cJSON_CreateObject();
    cJSON_AddStringToObject(root, "timestamp", timestamp);
    cJSON_AddNumberToObject(root, "target_weight", target_weight);
    cJSON_AddNumberToObject(root, "actual_weight", actual_weight);

    if (error_message != NULL) {
        cJSON_AddStringToObject(root, "error", error_message);
    }

    char *json_string = cJSON_PrintUnformatted(root);
    if (json_string != NULL) {
        fprintf(log_file, "%s\n", json_string);
        fflush(log_file);
        free(json_string);
    } else {
        fprintf(stderr, "Error creating JSON string.\n");
    }
    cJSON_Delete(root);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close socket
    if (client_fd != -1) {
        close(client_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Stop servo
    gpioServo(servo_pin, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Configuration loading function
int load_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file, using defaults.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strncmp(line, "calibration_factor", 17) == 0) {
            sscanf(line, "calibration_factor = %lf", &calibration_factor);
        } else if (strncmp(line, "server_ip", 9) == 0) {
            sscanf(line, "server_ip = %s", server_ip);
        } else if (strncmp(line, "server_port", 11) == 0) {
            sscanf(line, "server_port = %d", &server_port);
        }
    }

    fclose(fp);
    return 0;
}

// Configuration saving function
void save_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file for writing.\n");
        return;
    }

    fprintf(fp, "calibration_factor = %.6f\n", calibration_factor);
    fprintf(fp, "server_ip = %s\n", server_ip);
    fprintf(fp, "server_port = %d\n", server_port);

    fclose(fp);
}

int main() {
    // Load configuration
    if (load_configuration() != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error creating socket");
        log_event(-1.0, -1.0, "Error creating socket");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(server_ip);
    server_address.sin_port = htons(server_port);

    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        log_event(-1.0, -1.0, "Error binding socket");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        perror("Error listening on socket");
        log_event(-1.0, -1.0, "Error listening on socket");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on %s:%d...\n", server_ip, server_port);

    // Main loop
    while (1) {
        // Accept connection
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        client_fd = accept(socket_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            perror("Error accepting connection");
            log_event(-1.0, -1.0, "Error accepting connection");
            continue; // Continue listening
        }

        printf("Connection accepted\n");

        // Receive target weight
        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Error receiving data");
            log_event(-1.0, -1.0, "Error receiving data");
            close(client_fd);
            continue; // Continue listening
        }
        buffer[bytes_received] = '\0';
        double target_weight;
        if (sscanf(buffer, "%lf", &target_weight) != 1) {
            fprintf(stderr, "Invalid target weight received.\n");
            log_event(-1.0, -1.0, "Invalid target weight received");
            close(client_fd);
            continue; // Continue listening
        }

        // Dispense ingredient
        dispense_ingredient(target_weight);

        // Close connection
        close(client_fd);
