#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time (50ms)
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int debounce_time = DEFAULT_DEBOUNCE_TIME;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int relay_state;
} ProgramState;

ProgramState state = {0}; // Initialize relay state to OFF

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_time = atoi(argv[2]);
            if (debounce_time <= 0) {
                fprintf(stderr, "Error: Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
                debounce_time = DEFAULT_DEBOUNCE_TIME;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return 1;
        }
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0;
}

// Read the touch sensor with debouncing
int read_touch_sensor() {
    int stable_count = 0;
    int current_level = gpioRead(TOUCH_SENSOR_PIN);

    while (stable_count < (debounce_time * 1000) / 10) {
        if (gpioRead(TOUCH_SENSOR_PIN) == current_level) {
            stable_count++;
        } else {
            stable_count = 0; // Reset count if level changes
        }
        gpioDelay(10); // Check every 10ms
    }

    return current_level;
}

// Toggle the relay state
void toggle_relay() {
    state.relay_state = !state.relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, state.relay_state);
    log_relay_state(state.relay_state);
}

// Log the relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    gpioTerminate(); // Release pigpio resources
}

