#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90

static volatile int keepRunning = 1;
static struct termios orig_termios;

// Function to handle Ctrl+C signal
void intHandler(int dummy) {
    keepRunning = 0;
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-%d)\n", MAX_ANGLE);
        return -1;
    }

    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    gpioServo(GPIO_PIN, pulse_width);
    return 0;
}

// Function to read a single character from stdin without blocking
int getch() {
    int ch = getchar();
    if (ch == -1) {
        return -1; // Indicate error
    }
    return ch;
}

int main() {
    // Save the original terminal settings
    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        return 1;
    }

    // Set up the new terminal settings
    struct termios new_termios = orig_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 0;              // Read at least 0 characters
    new_termios.c_cc[VTIME] = 0;             // Wait indefinitely

    // Apply the new terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set initial angle
    if (set_servo_angle(DEFAULT_ANGLE) != 0) {
        gpioTerminate();
        tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, intHandler);

    int current_angle = DEFAULT_ANGLE;
    int ch;

    printf("Servo control. Press '+' to increase, '-' to decrease, 'q' to quit.\n");

    while (keepRunning) {
        ch = getch();
        if (ch == '+') {
            current_angle += 10;
            if (current_angle > MAX_ANGLE) {
                current_angle = MAX_ANGLE;
            }
            if (set_servo_angle(current_angle) != 0) {
                keepRunning = 0; // Exit on error
            }
        } else if (ch == '-') {
            current_angle -= 10;
            if (current_angle < MIN_ANGLE) {
                current_angle = MIN_ANGLE;
            }
            if (set_servo_angle(current_angle) != 0) {
                keepRunning = 0; // Exit on error
            }
        } else if (ch == 'q') {
            keepRunning = 0;
        }

        printf("Angle: %d\n", current_angle);
        fflush(stdout); // Ensure output is displayed immediately
    }

    // Stop PWM and terminate pigpio
    gpioServo(GPIO_PIN, 0); // Disable servo signal
    gpioTerminate();

    // Restore the original terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);

    printf("Exiting.\n");
    return 0;
}

