#include <errno.h>

// Define GPIO pin and chip
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"

// Define debounce time in nanoseconds
#define DEBOUNCE_TIME_NS 2000000 // 2 milliseconds

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
double calculate_rpm(long pulse_count);
int log_rpm(double rpm);
void print_rpm(double rpm);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold the last event time
struct last_event {
    struct timespec last_rising;
    struct timespec last_falling;
};

struct last_event last_event = {{0, 0}, {0, 0}};

// Function to initialize GPIO
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line as input with pull-up
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to calculate RPM
double calculate_rpm(long pulse_count) {
    return (double)pulse_count / 5.0 * 60.0;
}

// Function to log RPM to file
int log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);

    return 0;
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

