void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;
    struct gpiod_line_event event;
    long pulse_count = 0;
    struct timespec current_time;
    struct timespec diff;
    int debouncing = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for an event
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(-ret));
            break;
        }

        // Read the event
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading event: %s\n", strerror(-ret));
            break;
        }

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Debouncing logic
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            diff.tv_sec = current_time.tv_sec - last_event.last_rising.tv_sec;
            diff.tv_nsec = current_time.tv_nsec - last_event.last_rising.tv_nsec;
            if (diff.tv_nsec < 0) {
                diff.tv_sec--;
                diff.tv_nsec += 1000000000;
            }
            if (diff.tv_sec == 0 && diff.tv_nsec < DEBOUNCE_TIME_NS) {
                debouncing = 1;
            } else {
                debouncing = 0;
                pulse_count++;
                last_event.last_rising = current_time;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            diff.tv_sec = current_time.tv_sec - last_event.last_falling.tv_sec;
            diff.tv_nsec = current_time.tv_nsec - last_event.last_falling.tv_nsec;
            if (diff.tv_nsec < 0) {
                diff.tv_sec--;
                diff.tv_nsec += 1000000000;
            }
            if (diff.tv_sec == 0 && diff.tv_nsec < DEBOUNCE_TIME_NS) {
                debouncing = 1;
            } else {
                debouncing = 0;
                last_event.last_falling = current_time;
            }
        }

        // Log and print RPM every 5 seconds
        if (time(NULL) % 5 == 0 && !debouncing) {
            double rpm = calculate_rpm(pulse_count);
            log_rpm(rpm);
            print_rpm(rpm);
            pulse_count = 0; // Reset pulse count for the next 5-second interval
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

