#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON 1
#define RELAY_OFF 0
#define TOUCH_TIMEOUT_SEC 10

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t touch_detected = 0;
volatile sig_atomic_t touch_timeout = 0;
time_t last_touch_time;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void handle_signal(int signal);
void cleanup();

int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize last touch time
    time(&last_touch_time);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch sensor
        int touch_state = read_touch_sensor();

        // Check for touch
        if (touch_state == 1) {
            touch_detected = 1;
            touch_timeout = 0; // Reset timeout on touch
            time(&last_touch_time); // Update last touch time
        } else {
            touch_detected = 0;
        }

        // Check for timeout
        if (touch_detected && (time(NULL) - last_touch_time) > TOUCH_TIMEOUT_SEC) {
            touch_timeout = 1;
        }

        // Toggle relay if touch is detected and timeout hasn't expired
        if (touch_detected && !touch_timeout) {
            toggle_relay();
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated cleanly.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, RELAY_OFF);

    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    int touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_state < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        exit(1);
    }
    return touch_state;
}

// Toggle relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state == RELAY_ON) {
        gpioWrite(RELAY_PIN, RELAY_OFF);
    } else {
        gpioWrite(RELAY_PIN, RELAY_ON);
    }
}

// Signal handler
void handle_signal(int signal) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

// Cleanup function
void cleanup() {
    // Turn off relay
    gpioWrite(RELAY_PIN, RELAY_OFF);

    // Terminate pigpio
    gpioTerminate();
}

