#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PULSES_PER_LITER 450.0
#define TARGET_FLOW_RATE 5.0 // L/min
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void signal_handler(int signal);
void enable_valve();
void disable_valve();
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulses);
double proportional_control(double target_flow_rate, double current_flow_rate, double kp);
void log_data(double flow_rate, int valve_position);
void setup_gpio();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Enable the valve
void enable_valve() {
    gpioWrite(ENABLE_GPIO, 1); // Active-high
    printf("Valve enabled.\n");
}

// Disable the valve
void disable_valve() {
    gpioWrite(ENABLE_GPIO, 0); // Active-high
    printf("Valve disabled.\n");
}

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    pulse_count++;
}

// Calculate flow rate in L/min from pulse count
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0; // L/min
}

// Proportional control algorithm
double proportional_control(double target_flow_rate, double current_flow_rate, double kp) {
    double error = target_flow_rate - current_flow_rate;
    return kp * error;
}

// Log data to CSV file
void log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Setup GPIO pins
void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(ENABLE_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, 255);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        cleanup();
        exit(1);
    }

    enable_valve();
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    disable_valve();
    gpioPWM(VALVE_GPIO, 0); // Set PWM to 0
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    double target_flow_rate = TARGET_FLOW_RATE;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        target_flow_rate = strtod(argv[1], &endptr);
        if (*endptr != '\0' || target_flow_rate <= 0) {
            fprintf(stderr, "Invalid target flow rate: %s\n", argv[1]);
            fprintf(stderr, "Usage: %s [-t target_flow_rate]\n", argv[0]);
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    setup_gpio();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Sample flow rate
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        double current_flow_rate = calculate_flow_rate(current_pulse_count);

        // Proportional control
        double control_signal = proportional_control(target_flow_rate, current_flow_rate, 1.0);

        // Clamp control signal to [0, 255]
        int valve_position = (int)control_signal;
        if (valve_position < 0) {
            valve_position = 0;
        } else if (valve_position > 255) {
            valve_position = 255;
        }

        // Set valve position
        gpioPWM(VALVE_GPIO, valve_position);

        // Log data
        log_data(current_flow_rate, valve_position);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

