#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <errno.h>

// Configuration
#define RFID_TAG_LENGTH 10
#define RFID_TAG_VALID {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000 // 100 kHz
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define BUTTON_GPIO 22
#define LOCK_DEACTIVATION_TIME 5000 // milliseconds
#define DEBOUNCE_DELAY 50 // milliseconds
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
int spi_handle;
int server_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid_tag(unsigned char *tag);
int verify_rfid_tag(const unsigned char *tag);
int read_button();
int send_authentication_request(const unsigned char *rfid_tag);
int receive_authentication_response();
void log_access_attempt(int result, const unsigned char *rfid_tag);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read RFID tag from SPI
int read_rfid_tag(unsigned char *tag) {
    char tx_buf[10] = {0}; // Dummy data to initiate SPI transfer
    char rx_buf[10];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 10) != 0) {
        syslog(LOG_ERR, "SPI read failed: %s", strerror(errno));
        return -1; // Indicate failure
    }

    // Check for no tag present (all zeros)
    int no_tag = 1;
    for (int i = 0; i < RFID_TAG_LENGTH; i++) {
        if (rx_buf[i] != 0) {
            no_tag = 0;
            break;
        }
    }

    if (no_tag) {
        return -1; // No tag present
    }

    memcpy(tag, rx_buf, RFID_TAG_LENGTH);
    return 0; // Success
}

// Function to verify RFID tag against the valid tag
int verify_rfid_tag(const unsigned char *tag) {
    return (memcmp(tag, RFID_TAG_VALID, RFID_TAG_LENGTH) == 0);
}

// Function to read the button state
int read_button() {
    int button_state = gpioRead(BUTTON_GPIO);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
    return (button_state == 0); // Button is pressed if GPIO is LOW
}

// Function to send authentication request to the server
int send_authentication_request(const unsigned char *rfid_tag) {
    unsigned char buffer[RFID_TAG_LENGTH + 1]; // +1 for the command byte
    buffer[0] = 0x01; // Command byte: Authentication Request
    memcpy(buffer + 1, rfid_tag, RFID_TAG_LENGTH);

    ssize_t bytes_sent = send(server_socket, buffer, sizeof(buffer), 0);
    if (bytes_sent == -1) {
        syslog(LOG_ERR, "Failed to send authentication request: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to receive authentication response from the server
int receive_authentication_response() {
    unsigned char buffer[1];
    ssize_t bytes_received = recv(server_socket, buffer, 1, 0);
    if (bytes_received == -1) {
        syslog(LOG_ERR, "Failed to receive authentication response: %s", strerror(errno));
        return -1;
    } else if (bytes_received == 0) {
        syslog(LOG_WARNING, "Server disconnected");
        return -1;
    }

    if (buffer[0] == 0x02) { // Command byte: Authentication Success
        return 1;
    } else if (buffer[0] == 0x03) { // Command byte: Authentication Failure
        return 0;
    } else {
        syslog(LOG_WARNING, "Received unknown response from server: 0x%02X", buffer[0]);
        return -1;
    }
}

// Function to log access attempts
void log_access_attempt(int result, const unsigned char *rfid_tag) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (result == 1) {
        syslog(LOG_INFO, "%s - Authentication successful", timestamp);
    } else if (result == 0) {
        syslog(LOG_WARNING, "%s - Authentication failed", timestamp);
    } else {
        syslog(LOG_WARNING, "%s - RFID read failure", timestamp);
    }

    if (rfid_tag != NULL) {
        for (int i = 0; i < RFID_TAG_LENGTH; i++) {
            fprintf(log_file, "%02X", rfid_tag[i]);
        }
        fprintf(log_file, "\n");
        fflush(log_file);
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Setup function to initialize GPIO, SPI, and syslog
int setup() {
    // Initialize syslog
    openlog("door_access", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_GPIO_1, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO_2, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize SPI
    spi_handle = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        return -1;
    }

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_address.sin_port = htons(SERVER_PORT);

    if (connect(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(server_socket);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(server_socket);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    // Close SPI
    spiClose(spi_handle);

    // Close socket
    close(server_socket);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioWrite(LOCK_GPIO_1, 1); // Lock
    gpioWrite(LOCK_GPIO_2, 1); // Lock
    gpioTerminate();

    // Close syslog
    closelog();
}

int main() {
    if (setup() != 0) {
        return 1;
    }

    syslog(LOG_INFO, "Door access system started");

    while (!terminate) {
        unsigned char rfid_tag[RFID_TAG_LENGTH];
        int rfid_read_result = read_rfid_tag(rfid_tag);
        int button_pressed = read_button();

        if (rfid_read_result == 0 && verify_rfid_tag(rfid_tag)) {
            syslog(LOG_INFO, "RFID tag verified");
            if (button_pressed) {
                syslog(LOG_INFO, "Button pressed, sending authentication request");
                if (send_authentication_request(rfid_tag) == 0) {
                    int auth_result = receive_authentication_response();
                    if (auth_result != -1) {
                        log_access_attempt(auth_result, rfid_tag);
                        if (auth_result == 1) {
                            gpioWrite(LOCK_GPIO_1, 0); // Deactivate lock 1
                            gpioWrite(LOCK_GPIO_2, 0); // Deactivate lock 2
                            gpioDelay(LOCK_DEACTIVATION_TIME * 1000); // Wait 5 seconds
                            gpioWrite(LOCK_GPIO_1, 1); // Re-engage lock 1
                            gpioWrite(LOCK_GPIO_2, 1); // Re-engage lock 2
                        }
                    } else {
                        syslog(LOG_WARNING, "Failed to receive authentication response");
                    }
                } else {
                    syslog(LOG_WARNING, "Failed to send authentication request");
                }
            } else {
                syslog(LOG_WARNING, "Button not pressed");
            }
        } else if (rfid_read_result == -1) {
            syslog(LOG_WARNING, "RFID read failure");
        } else {
            syslog(LOG_WARNING, "Invalid RFID tag");
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    cleanup();
    return 0;
}

