void motor_forward(int en_pin, int in1_pin, int in2_pin, int duty_cycle);
void motor_backward(int en_pin, int in1_pin, int in2_pin, int duty_cycle);
void motor_stop(int en_pin, int in1_pin, int in2_pin);
void encoder1_isr(int gpio, int level, uint32_t tick, void *user_data);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int encoder_count);
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error, double dt);
void *encoder_thread(void *arg);
void signal_handler(int signal);

