void motor_forward(int en_pin, int in1_pin, int in2_pin, int duty_cycle) {
    gpioWrite(in1_pin, 1);
    gpioWrite(in2_pin, 0);
    gpioPWM(en_pin, duty_cycle);
}

void motor_backward(int en_pin, int in1_pin, int in2_pin, int duty_cycle) {
    gpioWrite(in1_pin, 0);
    gpioWrite(in2_pin, 1);
    gpioPWM(en_pin, duty_cycle);
}

void motor_stop(int en_pin, int in1_pin, int in2_pin) {
    gpioWrite(in1_pin, 0);
    gpioWrite(in2_pin, 0);
    gpioPWM(en_pin, 0);
}

// Encoder Interrupt Service Routines
void encoder1_isr(int gpio, int level, uint32_t tick, void *user_data) {
    int encoder1_count_local;
    pthread_mutex_lock(&encoder1_mutex);
    encoder1_count_local = encoder1_count;
    encoder1_count_local++;
    encoder1_count = encoder1_count_local;
    pthread_mutex_unlock(&encoder1_mutex);
}

void encoder2_isr(int gpio, int level, uint32_t tick, void *user_data) {
