        // Log data
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, motor1_rpm, motor2_rpm,
                KP, 0.0, 0.0, KP, 0.0, 0.0, (int)pid_output1, (int)pid_output2);
        fflush(log_file);

        gpioDelay(SAMPLING_TIME);
    }

