#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int activate_valve(int gpio_pin, int duration_ms);
int deactivate_valve(int gpio_pin);
int log_event(const char *event);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, cleaning up and exiting...\n", sig);
    }
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting GPIO line for Valve 1");
        gpiod_chip_close(chip);
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting GPIO line for Valve 2");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "valve_control";

    if (gpiod_line_request_output(valve1_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for Valve 1 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for Valve 2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    return 0;
}

// Activate a valve for a specified duration
int activate_valve(int gpio_pin, int duration_ms) {
    struct gpiod_line *line = (gpio_pin == VALVE1_GPIO) ? valve1_line : valve2_line;
    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO value to HIGH");
        return -1;
    }

    log_event("Valve activated");
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO value to LOW");
        return -1;
    }

    log_event("Valve deactivated");
    return 0;
}

// Deactivate a valve
int deactivate_valve(int gpio_pin) {
    struct gpiod_line *line = (gpio_pin == VALVE1_GPIO) ? valve1_line : valve2_line;
    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO value to LOW");
        return -1;
    }
    return 0;
}

// Log an event to the log file
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }
}

// Cleanup function to release GPIO lines and close log file
void cleanup() {
    printf("Cleaning up...\n");

    if (valve1_line) {
        deactivate_valve(VALVE1_GPIO);
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        deactivate_valve(VALVE2_GPIO);
        gpiod_line_release(valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Activate Valve 1 for 500ms
        if (activate_valve(VALVE1_GPIO, 500) < 0) {
            fprintf(stderr, "Error activating Valve 1\n");
        }

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2 for 1000ms
        if (activate_valve(VALVE2_GPIO, 1000) < 0) {
            fprintf(stderr, "Error activating Valve 2\n");
        }

        // Pause for 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

