#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELECTRODE_CURRENT 0x01
#define ELE_EN 0x20

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(int *touch_status);
void toggle_relay();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Initializes the MPR121
int initialize_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x80) < 0) {
        fprintf(stderr, "Error: Could not set MPR121 to stop mode.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set touch and release thresholds
    for (int i = 0x41; i <= 0x5A; i++) {
        if (i2cWriteByteData(i2c_handle, i, TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Could not set touch threshold for electrode %d.\n", i - 0x41);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, i + 1, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Could not set release threshold for electrode %d.\n", i - 0x41);
            return -1;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, 0x2C, FILTER_CHARGE_TIME) < 0) {
        fprintf(stderr, "Error: Could not set filter/charge time.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, ELECTRODE_CURRENT) < 0) {
        fprintf(stderr, "Error: Could not set electrode current.\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, 0x2B, ELE_EN) < 0) {
        fprintf(stderr, "Error: Could not set MPR121 to run mode.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Reads the touch status from the MPR121
int read_touch_status(int *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Could not read touch status.\n");
        return -1;
    }

    *touch_status = ((int)buf[1] << 8) | (int)buf[0];
    return 0;
}

// Toggles the relay state
void toggle_relay() {
    static int relay_state = 0; // Keep track of the relay state
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    printf("Relay toggled to %d\n", relay_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int touch_status;
    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status.\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

