#define PIR_SENSOR_2 22
#define PIR_SENSOR_3 23
#define RELAY_PIN 18

// Define unlock duration and rate limiting
#define UNLOCK_DURATION_MS 500
#define RATE_LIMITING_MS 2000

// Global variables
