// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR sensor pins as input with pull-down resistors
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_3, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read PIR sensor state
int read_pir_sensor(int gpio) {
    return gpioRead(gpio);
