#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define minimum and maximum PWM duty cycle values
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Define minimum and maximum step duration (ms)
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200

// Define minimum and maximum duty cycle values
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global flag to signal program shutdown
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    shutdown = 1;
    fprintf(stderr, "\nCaught signal, shutting down...\n");
}

// Function to initialize the pigpio library and GPIO pins
int initialize()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes for the vibration motors
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) != 0)
    {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) != 0)
    {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM range
    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) != 0)
    {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0)
    {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random duty cycle value
int generate_duty_cycle()
{
    return (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
}

// Function to generate a random step duration
int generate_step_duration()
{
    return (rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION + 1)) + MIN_STEP_DURATION;
}

// Function to generate a haptic feedback pattern
int generate_pattern(int *pattern, int pattern_length)
{
    for (int i = 0; i < pattern_length; i++)
    {
        // Generate random duty cycles for both motors
        pattern[i * 3] = generate_duty_cycle(); // Motor 1 duty cycle
        pattern[i * 3 + 1] = generate_duty_cycle(); // Motor 2 duty cycle
        pattern[i * 3 + 2] = generate_step_duration(); // Step duration
    }
    return 0;
}

// Function to play a haptic feedback pattern
void play_pattern(int *pattern, int pattern_length)
{
    for (int i = 0; i < pattern_length; i++)
    {
        // Set PWM duty cycles
        gpioPWM(MOTOR1_PIN, pattern[i * 3]);
        gpioPWM(MOTOR2_PIN, pattern[i * 3 + 1]);

        // Delay for the step duration
        gpioDelay(pattern[i * 3 + 2] * 1000); // Convert ms to microseconds
    }
}

// Function to clean up resources before exiting
void cleanup()
{
    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main()
{
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize() != 0)
    {
        return 1;
    }

    fprintf(stderr, "Haptic feedback generator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown)
    {
        // Generate a random pattern length between 5 and 15
        int pattern_length = (rand() % 11) + 5;

        // Allocate memory for the pattern
        int *pattern = (int *)malloc(pattern_length * 3 * sizeof(int));
        if (pattern == NULL)
        {
            fprintf(stderr, "Memory allocation failed\n");
            cleanup();
            return 1;
        }

        // Generate the pattern
        if (generate_pattern(pattern, pattern_length) != 0)
        {
            free(pattern);
            cleanup();
            return 1;
        }

        // Play the pattern
        play_pattern(pattern, pattern_length);

        // Free the allocated memory
        free(pattern);
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

