#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file path
#define CALIBRATION_FILE "calibration.txt"

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 10.0

// Define number of calibration readings
#define NUM_CALIBRATION_READINGS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Structure to hold calibration data
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
int read_hx711(long *raw_value);
double calculate_weight(long raw_value, CalibrationData calibration);
void control_solenoid(double weight);
void log_data(double weight);
void calibrate_hx711(CalibrationData *calibration);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    return 0;
}

// Function to read raw data from HX711
int read_hx711(long *raw_value) {
    long value = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay after clock low

    // Wait for data pin to go low (or timeout)
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < 500) {
        gpioDelay(1); // Wait 1ms
        timeout_count++;
    }

    if (timeout_count >= 500) {
        fprintf(stderr, "HX711 read timeout\n");
        return 1; // Indicate timeout
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay during clock high
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay during clock low
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0; // Indicate success
}

// Function to calculate weight from raw value
double calculate_weight(long raw_value, CalibrationData calibration) {
    return (raw_value - calibration.offset) / calibration.scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Lock
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Unlock
    }
}

// Function to log data to file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calibrate the HX711
void calibrate_hx711(CalibrationData *calibration) {
    long raw_value;
    double sum = 0.0;
    double average;
    int i;

    printf("Starting one-time calibration...\n");

    // Read 100 values and calculate the average
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        if (read_hx711(&raw_value) == 0) {
            sum += raw_value;
        } else {
            fprintf(stderr, "Error reading HX711 during calibration\n");
            return; // Exit calibration if there's an error
        }
        gpioDelay(10); // Small delay between readings
    }

    average = sum / NUM_CALIBRATION_READINGS;

    // Save the offset to the calibration data
    calibration->offset = average;

    printf("Calibration complete. Offset: %.2f\n", calibration->offset);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked on exit
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
}

int main() {
    long raw_value;
    double weight;
    CalibrationData calibration = {1.0, 0.0}; // Default values

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Open calibration file for reading and writing
    calibration_file = fopen(CALIBRATION_FILE, "r+");
    if (calibration_file == NULL) {
        // File doesn't exist, create it and write default values
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Error creating calibration file!\n");
            cleanup();
            return 1;
        }
        fprintf(calibration_file, "1.0 0.0\n");
        fclose(calibration_file);
        calibration_file = fopen(CALIBRATION_FILE, "r+");
        if (calibration_file == NULL) {
            fprintf(stderr, "Error opening calibration file after creation!\n");
            cleanup();
            return 1;
        }
    }

    // Read calibration data from file
    if (fscanf(calibration_file, "%lf %lf", &calibration.scale_factor, &calibration.offset) != 2) {
        // File is empty or invalid, use default values
        printf("Calibration file is invalid or empty, using default values.\n");
        calibration.scale_factor = 1.0;
        calibration.offset = 0.0;
    } else {
        printf("Calibration data loaded: scale_factor = %.2f, offset = %.2f\n", calibration.scale_factor, calibration.offset);
    }

    // Calibrate if the file is empty or invalid
