// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 0
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50

// Define motor run time
#define MOTOR_RUN_TIME_S 5

// Global variables
static volatile int running = 1;
static int last_rain_state = 1; // Initialize to dry

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    int i;

    // Take multiple readings with a short delay
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Check if rain is detected (LOW) in at least 3 readings
    int rain_detected = 0;
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) {
            rain_detected++;
        }
    }

    return (rain_detected >= (DEBOUNCE_READINGS / 2)); // Return true if rain is detected
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
    } else if (direction == MOTOR_REVERSE) {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
    } else {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
    }

    gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected && !last_rain_state) {
            // Rain detected
            log_event("Rain detected, closing window");
            control_motor(MOTOR_FORWARD);
            gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Run for 5 seconds
            stop_motor();
            last_rain_state = 0;
            gpioDelay(60 * 1000000); // Wait 60 seconds before next check
        } else if (!rain_detected && last_rain_state) {
            // Rain stopped
            log_event("Rain stopped, opening window");
            control_motor(MOTOR_REVERSE);
            gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Run for 5 seconds
            stop_motor();
            last_rain_state = 1;
            gpioDelay(60 * 1000000); // Wait 60 seconds before next check
        } else {
            gpioDelay(1000000); // Check every second
        }
    }

    // Cleanup (should not reach here if signal handler works)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

