#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define constants
#define WEIGHT_THRESHOLD 100.0  // grams
#define SOLENOID_DURATION 5      // seconds
#define CALIBRATION_FACTOR 100.0 // Example calibration factor
#define TIMEOUT_US 1000000       // 1 second timeout

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float convert_to_grams(int raw_value, float calibration_factor);
void activate_solenoid(int duration_seconds);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for the data line to go low
    while (gpioRead(HX711_DT) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Apply the 25th clock pulse to set the gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw data to grams
float convert_to_grams(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Function to activate the solenoid lock
void activate_solenoid(int duration_seconds) {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(duration_seconds * 1000); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Deactivate solenoid
    gpioWrite(SOLENOID_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Stock monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711, retrying in 1 second.\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        float weight = convert_to_grams(raw_value, CALIBRATION_FACTOR);

        printf("Weight: %.2f grams\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold! Activating solenoid.\n");
            activate_solenoid(SOLENOID_DURATION);
            log_event("Solenoid activated");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

