#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;
static double calibration_factor = 1.0; // Default calibration factor

// Function prototypes
int initialize_gpio();
int read_hx711();
double calculate_weight(int raw_value);
int calibrate_load_cell();
int log_event(double weight);
int unlock_solenoid();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw value from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);
    while (gpioRead(HX711_DATA_PIN) == 1) {
        timeout++;
        if (timeout > 100) { // Timeout after 100ms
            fprintf(stderr, "HX711 timeout\n");
            return -1; // Indicate timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to calibrate the load cell
int calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input\n");
        return 1;
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Failed to read HX711 during calibration\n");
        return 1;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return 1;
    }

    fprintf(calibration_file, "%lf", calibration_factor);
    fclose(calibration_file);

    return 0;
}

// Function to log an event to the security log
int log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to unlock the solenoid
int unlock_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(5000);            // Wait for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked
    gpioTerminate();            // Terminate pigpio

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open security log file
    log_file = fopen(SECURITY_LOG, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening security log file for appending\n");
        cleanup();
        return 1;
    }

    // Read calibration factor from file
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        printf("Calibration file not found. Calibrating...\n");
        if (calibrate_load_cell() != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return 1;
        }
        calibration_file = fopen(CALIBRATION_FILE, "r");
        if (calibration_file == NULL) {
            fprintf(stderr, "Error opening calibration file for reading\n");
            cleanup();
            return 1;
        }
        if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file\n");
            cleanup();
            return 1;
        }
        fclose(calibration_file);
    } else {
        if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file\n");
            cleanup();
            return 1;
        }
        fclose(calibration_file);
    }

    printf("Calibration factor: %lf\n", calibration_factor);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > 5.0) {
            log_event(weight);
            unlock_solenoid();
        }

        gpioDelay(100); // Delay between readings
    }

