#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
int toggle_relay();
int log_event(int relay_state);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Error getting relay line");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        return -1;
    }

    // Request sensor line as input
    struct gpiod_line_request_config sensor_config;
    memset(&sensor_config, 0, sizeof(sensor_config));
    sensor_config.consumer = "obstacle_sensor";
    sensor_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor_line, &sensor_config, 0) < 0) {
        perror("Error requesting sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    // Request relay line as output
    struct gpiod_line_request_config relay_config;
    memset(&relay_config, 0, sizeof(relay_config));
    relay_config.consumer = "relay_control";
    relay_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay_line, &relay_config, 0) < 0) {
        perror("Error requesting relay line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor() {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return (value == 0) ? 1 : 0; // Active-low
}

// Toggle relay state
int toggle_relay() {
    int current_state = gpiod_line_get_value(relay_line);
    if (current_state < 0) {
        perror("Error reading relay state");
        return -1;
    }

    int new_state = (current_state == 0) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, new_state) < 0) {
        perror("Error setting relay state");
        return -1;
    }

    return new_state;
}

// Log event to file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s Relay State: %s\n", timestamp, (relay_state == 1) ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (sensor_value == 1) {
            int relay_state = toggle_relay();
            if (relay_state < 0) {
                fprintf(stderr, "Error toggling relay, exiting.\n");
                break;
            }

            if (log_event(relay_state) < 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Obstacle avoidance system stopped.\n");
    return 0;
}

