#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define DEFAULT_DURATION 60 // seconds

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Function prototypes
int read_watering_duration(const char *filename, int *duration);
int set_valve_state(struct gpiod_line *line, int state);
int main(int argc, char *argv[]);

// Signal handler
void signal_handler(int sig)
{
    (void)argc;
    (void)argv;
    (void)sig;
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read watering duration from configuration file
int read_watering_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line_buffer[256];
    if (fgets(line_buffer, sizeof(line_buffer), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: Empty config file %s\n", filename);
            fclose(fp);
            return -1;
        } else {
            fprintf(stderr, "Error reading from config file %s: %s\n", filename, strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    char *token = strtok(line_buffer, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid format in config file %s\n", filename);
        fclose(fp);
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing value in config file %s\n", filename);
        fclose(fp);
        return -1;
    }

    char *endptr;
    long parsed_duration = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Error: Invalid duration value in config file %s\n", filename);
        fclose(fp);
        return -1;
    }

    if (parsed_duration < 1 || parsed_duration > 3600) {
        fprintf(stderr, "Error: Duration value out of range (1-3600) in config file %s\n", filename);
        fclose(fp);
        return -1;
    }

    *duration = (int)parsed_duration;
    fclose(fp);
    return 0;
}

// Function to set the valve state
int set_valve_state(struct gpiod_line *line, int state)
{
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting valve state: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read watering duration from configuration file
    int duration = DEFAULT_DURATION;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default watering duration: %d seconds\n", duration);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Activate valve
        if (set_valve_state(line, 1) == 0) {
            printf("Valve activated for %d seconds\n", duration);
            sleep(duration);
            printf("Valve deactivated\n");
        } else {
            fprintf(stderr, "Failed to activate valve\n");
        }

        // Deactivate valve
        if (set_valve_state(line, 0) != 0) {
            fprintf(stderr, "Failed to deactivate valve\n");
        }

        // Check for termination signal
        if (terminate) {
            break;
        }

        // Wait for a short period before the next watering cycle
        sleep(60); // Wait 60 seconds before the next cycle
    }

    // Cleanup
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Exiting cleanly\n");
    return EXIT_SUCCESS;
}

