#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_PWM 22
#define LEFT_MOTOR_DIR 23
#define RIGHT_MOTOR_PWM 24
#define RIGHT_MOTOR_DIR 25

// Define motor speeds
#define BASE_SPEED 150
#define HALF_SPEED (BASE_SPEED / 2)

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensors();
void set_motor_speed(int left_speed, int right_speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor values
int read_sensors() {
    int left = gpioRead(LEFT_SENSOR);
    int middle = gpioRead(MIDDLE_SENSOR);
    int right = gpioRead(RIGHT_SENSOR);
    return (left << 2) | (middle << 1) | right;
}

// Function to set motor speeds
void set_motor_speed(int left_speed, int right_speed) {
    if (left_speed > 255) left_speed = 255;
    if (left_speed < 0) left_speed = 0;
    if (right_speed > 255) right_speed = 255;
    if (right_speed < 0) right_speed = 0;

    gpioPWM(LEFT_MOTOR_PWM, left_speed);
    gpioPWM(RIGHT_MOTOR_PWM, right_speed);

    // Set motor direction based on speed sign
    if (left_speed > 0) {
        gpioWrite(LEFT_MOTOR_DIR, 1); // Forward
    } else {
        gpioWrite(LEFT_MOTOR_DIR, 0); // Backward
        left_speed = -left_speed; // Ensure speed is positive for PWM
    }

    if (right_speed > 0) {
        gpioWrite(RIGHT_MOTOR_DIR, 1); // Forward
    } else {
        gpioWrite(RIGHT_MOTOR_DIR, 0); // Backward
        right_speed = -right_speed; // Ensure speed is positive for PWM
    }
}

// Function to stop motors
void stop_motors() {
    set_motor_speed(0, 0);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

