#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data (optional)
typedef struct {
    float lux;
    int relay_state;
} SensorData;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
float read_lux() {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int result;

    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1.0f; // Indicate error
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1.0f; // Indicate error
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2f; // BH1750 datasheet conversion

    return lux;
}

// Control the relay (ON/OFF)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    control_relay(0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    while (program_running) {
        lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux, using previous value.\n");
        } else {
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_data(lux, relay_state);
            }
            log_data(lux, relay_state);
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

