#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo positions
#define SERVO_LOCKED_PULSE_WIDTH 1000
#define SERVO_UNLOCKED_PULSE_WIDTH 2000

// Global variable to store the current servo pulse width
int current_pulse_width = SERVO_UNLOCKED_PULSE_WIDTH;

// Function prototypes
int initialize_gpio();
void lock_door();
void unlock_door();
void handle_button_press(int button_pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initializes the pigpio library and sets up the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors on the button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Moves the servo to the locked position
void lock_door() {
    gpioServo(SERVO_PIN, SERVO_LOCKED_PULSE_WIDTH);
    current_pulse_width = SERVO_LOCKED_PULSE_WIDTH;
    printf("Door locked\n");
}

// Moves the servo to the unlocked position
void unlock_door() {
    gpioServo(SERVO_PIN, SERVO_UNLOCKED_PULSE_WIDTH);
    current_pulse_width = SERVO_UNLOCKED_PULSE_WIDTH;
    printf("Door unlocked\n");
}

// Handles button presses
void handle_button_press(int button_pin) {
    if (button_pin == LOCK_BUTTON_PIN) {
        lock_door();
    } else if (button_pin == UNLOCK_BUTTON_PIN) {
        unlock_door();
    }
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON_PIN) == 0) { // Button is active-low
            handle_button_press(LOCK_BUTTON_PIN);
            gpioDelay(100); // Debounce delay
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) { // Button is active-low
            handle_button_press(UNLOCK_BUTTON_PIN);
            gpioDelay(100); // Debounce delay
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0; // This line will never be reached due to the infinite loop
}

