    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error registering signal handler");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    for (int i = 0; i < NUM_PULSES; i++) {
