#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define alarm duration (in seconds)
#define ALARM_DURATION 1

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
void *zmq_context = NULL;
void *zmq_publisher = NULL;
void *zmq_subscriber = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *sound_sensor_line = NULL;
struct gpiod_line *alarm_led_line = NULL;

// Function prototypes
int init_gpio(void);
int init_zmq(void);
int init_alarm(void);
void sound_sensor_mode(void);
void alarm_node_mode(void);
void cleanup(void);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret = 0;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sound_sensor_line = gpiod_chip_get_line(gpio_chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor line");
        ret = -1;
        goto cleanup_chip;
    }

    alarm_led_line = gpiod_chip_get_line(gpio_chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED line");
        ret = -1;
        goto cleanup_sound_sensor;
    }

    ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Error requesting sound sensor line as input");
        ret = -1;
        goto cleanup_alarm_led;
    }

    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0); // Initially off
    if (ret < 0) {
        perror("Error requesting alarm LED line as output");
        ret = -1;
        goto cleanup_sound_sensor;
    }

    return 0;

cleanup_alarm_led:
    gpiod_line_release(sound_sensor_line);
cleanup_sound_sensor:
    gpiod_chip_close(gpio_chip);
cleanup_chip:
    gpiod_chip_close(gpio_chip);
    return ret;
}

// Initialize ZeroMQ
int init_zmq(void) {
    int ret = 0;

    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Error creating ZeroMQ context");
        return -1;
    }

    zmq_publisher = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_publisher) {
        perror("Error creating ZeroMQ publisher socket");
        ret = -1;
        goto cleanup_context;
    }

    if (zmq_bind(zmq_publisher, ZMQ_ENDPOINT) < 0) {
        perror("Error binding ZeroMQ publisher socket");
        ret = -1;
        goto cleanup_publisher;
    }

    zmq_subscriber = zmq_socket(zmq_context, ZMQ_SUB);
    if (!zmq_subscriber) {
        perror("Error creating ZeroMQ subscriber socket");
        ret = -1;
        goto cleanup_publisher;
    }

    if (zmq_connect(zmq_subscriber, ZMQ_ENDPOINT) < 0) {
        perror("Error connecting ZeroMQ subscriber socket");
        ret = -1;
        goto cleanup_subscriber;
    }

    if (zmq_setsockopt(zmq_subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        perror("Error setting ZeroMQ subscriber subscription");
        ret = -1;
        goto cleanup_subscriber;
    }

    return 0;

cleanup_subscriber:
    zmq_close(zmq_subscriber);
cleanup_publisher:
    zmq_close(zmq_publisher);
cleanup_context:
    zmq_ctx_destroy(zmq_context);
    return ret;
}

// Initialize alarm LED
int init_alarm(void) {
    int ret = 0;
    int value = 1; // Turn on the LED

    ret = gpiod_line_set_value(alarm_led_line, value);
    if (ret < 0) {
        perror("Error setting alarm LED value");
        return -1;
    }

    return 0;
}

// Sound sensor mode
void sound_sensor_mode(void) {
    int ret = 0;
    int sound_detected = 0;
    struct timespec sleep_time = {0, 10000000}; // 10 ms

    while (program_running) {
        ret = gpiod_line_get_value(sound_sensor_line);
        if (ret < 0) {
            perror("Error reading sound sensor value");
            break; // Exit loop on error
        }

        if (ret == 0) { // Sound detected (active low)
            if (!sound_detected) {
                printf("Sound detected!\n");
                // Publish alert via ZeroMQ
                char *message = strdup(ZMQ_TOPIC); // Allocate memory for the message
                if (message == NULL) {
                    perror("Error allocating memory for ZeroMQ message");
                    break; // Exit loop on error
                }

                if (zmq_send(zmq_publisher, message, strlen(message), 0) < 0) {
                    perror("Error sending ZeroMQ message");
                    free(message);
                    break; // Exit loop on error
                }
                free(message);

                sound_detected = 1;
            }
        } else {
            sound_detected = 0; // Reset sound detected flag
        }

        nanosleep(&sleep_time, NULL);
    }
}

// Alarm node mode
void alarm_node_mode(void) {
    int ret = 0;
    char *message = NULL;
    size_t message_size = 0;

    while (program_running) {
        ret = zmq_recv(zmq_subscriber, message, 256, 0); // Receive up to 255 bytes
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Error receiving ZeroMQ message");
            break; // Exit loop on error
        }

        message_size = ret; // Store the actual message size
        message[message_size] = '\0'; // Null-terminate the message

        if (strcmp(message, ZMQ_TOPIC) == 0) {
            printf("Received alert: %s\n", message);

            // Activate alarm LED
            ret = init_alarm();
            if (ret < 0) {
                fprintf(stderr, "Failed to initialize alarm, continuing...\n");
            } else {
                sleep(ALARM_DURATION);
                ret = gpiod_line_set_value(alarm_led_line, 0); // Turn off LED
                if (ret < 0) {
                    perror("Error setting alarm LED value");
                }
            }
        }
    }
}

// Cleanup function
void cleanup(void) {
    int ret = 0;

    printf("Cleaning up resources...\n");

    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (zmq_publisher) {
        zmq_close(zmq_publisher);
    }
    if (zmq_subscriber) {
        zmq_close(zmq_subscriber);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int ret = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    ret = init_gpio();
    if (ret < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Initialize ZeroMQ
    ret = init_zmq();
    if (ret < 0) {
        fprintf(stderr, "ZeroMQ initialization failed.\n");
        cleanup();
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        printf("Running in sound sensor mode...\n");
        sound_sensor_mode();
    } else {
        printf("Running in alarm node mode...\n");
        alarm_node_mode();
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

