#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define CHECKSUM_MASK 0x7F

// NEC Frame Structure
typedef struct {
    uint32_t address;
    uint32_t command;
} nec_frame_t;

// Global Variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static uint32_t pulse_buffer[MAX_PULSES];
static int pulse_count = 0;

// Function Prototypes
void signal_handler(int signal);
int initialize_pigpio();
int initialize_mqtt();
