}

// Initialize MQTT
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60)) {
