        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    gpioTerminate();
    closelog();
}

// IR Receiver Callback
void ir_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_length;

    if (level == FALLING_EDGE) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < MAX_PULSES) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
        }
    }
}

// Decode NEC IR signal
int decode_nec(uint32_t *pulses, int pulse_count, nec_frame_t *frame) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Not enough pulses received");
        return -1;
    }

    // Check for valid header
    if (pulses[0] < 8000 || pulses[0] > 9000 || pulses[1] < 4000 || pulses[1] > 5000) {
        syslog(LOG_ERR, "Invalid NEC header");
        return -1;
    }

    frame->address = 0;
    frame->command = 0;

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        frame->address <<= 1;
        if (pulses[2 * i] > 1600 && pulses[2 * i] < 2400) {
            frame->address |= 1;
        } else if (pulses[2 * i] > 500 && pulses[2 * i] < 1500) {
            frame->address |= 0;
        } else {
