    for (int i = 10; i < 18; i++) {
        frame->command <<= 1;
        if (pulses[2 * i] > 1600 && pulses[2 * i] < 2400) {
            frame->command |= 1;
        } else if (pulses[2 * i] > 500 && pulses[2 * i] < 1500) {
            frame->command |= 0;
        } else {
            syslog(LOG_ERR, "Invalid command bit");
            return -1;
        }
    }

    // Validate checksum
    if (!validate_checksum(frame->address, frame->command)) {
        syslog(LOG_ERR, "Invalid checksum");
        return -1;
    }

    return 0;
}

// Validate NEC checksum
int validate_checksum(uint32_t address, uint32_t command) {
    uint32_t inverted_address = ~address;
    uint32_t inverted_command = ~command;

    if ((inverted_address & CHECKSUM_MASK) != ((inverted_command >> 8) & CHECKSUM_MASK)) {
        return 0;
    }

    return 1;
}

