    while (running) {
        // Check for new messages
        mosquitto_loop(mosq, 0, 1); // Non-blocking loop

        // Process pulse buffer if it's full
        if (pulse_count >= 68) {
            nec_frame_t frame;
            if (decode_nec(pulse_buffer, pulse_count, &frame) == 0) {
