                    free(json_message);
                } else {
                    syslog(LOG_ERR, "Failed to create JSON message");
                }
            } else {
                syslog(LOG_ERR, "Failed to decode NEC frame");
            }
            pulse_count = 0; // Reset pulse buffer
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    cleanup();

    return 0;
}

