#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SENSOR_ADDRESSES {0x23, 0x24, 0x25, 0x26}
#define RETRY_COUNT 3

// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
    float lux;
} sensor_t;

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int udp_socket = -1;

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Function to set the I2C slave address
int set_i2c_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C address");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750 sensor
int read_bh1750(int fd, float *lux) {
    unsigned char data[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Write the One-Time High-Resolution mode command
        if (write(fd, (const void *)&(unsigned char){0x20}, 1) != 1) {
            perror("Error writing to BH1750");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(180000); // Wait for conversion (180ms)

        // Read 2 bytes of data
        if (read(fd, (void *)data, 2) != 2) {
            perror("Error reading from BH1750");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Convert the data to lux
        *lux = ((data[0] << 8) | data[1]) / 1.2;
        return 0; // Success
    }

    *lux = NAN; // Indicate failure
    return -1;  // Indicate failure
}

// Function to format sensor data into a string
int format_data(sensor_t sensors[], char *buffer, size_t buffer_size) {
    int offset = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        offset += snprintf(buffer + offset, buffer_size - offset, "%d,%.1f", i + 1, sensors[i].lux);
        if (i < NUM_SENSORS - 1) {
            offset += snprintf(buffer + offset, buffer_size - offset, ";");
        }
    }
    return 0;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Configure multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting multicast TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Sensor addresses
    int sensor_addresses[] = SENSOR_ADDRESSES;

    // Initialize sensors
    sensor_t sensors[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].address = sensor_addresses[i];
        sensors[i].lux = NAN;
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            // Set I2C address
            if (set_i2c_address(i2c_fd, sensors[i].address) < 0) {
                fprintf(stderr, "Error setting I2C address for sensor %d\n", i + 1);
                continue; // Try the next sensor
            }

            // Read sensor data
            if (read_bh1750(i2c_fd, &sensors[i].lux) < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
            }
        }

        // Format data
        char data_buffer[256]; // Adjust buffer size as needed
        if (format_data(sensors, data_buffer, sizeof(data_buffer)) < 0) {
            fprintf(stderr, "Error formatting data\n");
        }

        // Send data via UDP multicast
        if (send_udp_multicast(data_buffer) < 0) {
            fprintf(stderr, "Error sending UDP multicast\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    close(i2c_fd);
    close(udp_socket);

    return 0;
}

