// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define FLOW_SCALE_FACTOR 0.1
#define FLOW_OFFSET 3277
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_flow(int fd);
float convert_to_slpm(int raw_flow);
void log_flow_data(float flow_rate);
void signal_handler(int signal);
int i2c_write(int fd, uint8_t address, uint8_t *data, int length);
int i2c_read(int fd, uint8_t address, uint8_t *data, int length);

// I2C write function
int i2c_write(int fd, uint8_t address, uint8_t *data, int length) {
    if (write(fd, data, length) != length) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t address, uint8_t *data, int length) {
    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to read flow data from the sensor
int i2c_read_flow(int fd) {
    uint8_t write_data[1] = {0x00}; // Zero-length write
    uint8_t read_data[2];
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        if (i2c_write(fd, I2C_ADDRESS, write_data, 1) == 0) {
            if (i2c_read(fd, I2C_ADDRESS, read_data, 2) == 0) {
                int raw_flow = (read_data[0] << 8) | read_data[1];
                return raw_flow;
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C write failed, retrying...\n");
        }

        retries--;
        usleep(delay_ms * 1000); // Sleep for 100ms
        delay_ms *= 2; // Exponential backoff
    }

    fprintf(stderr, "Failed to read flow data after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert raw flow data to SLPM
float convert_to_slpm(int raw_flow) {
    return (raw_flow - FLOW_OFFSET) * FLOW_SCALE_FACTOR;
}

// Function to log flow data to a file
void log_flow_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_flow = i2c_read_flow(i2c_fd);
        if (raw_flow != -1) {
            float flow_rate = convert_to_slpm(raw_flow);
            log_flow_data(flow_rate);
            printf("Flow rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

