#include <errno.h>
#include <math.h>

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the AS7341 I2C address
#define AS7341_ADDR 0x39

// Define the AS7341 register addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_F1DATAH 0x60
#define AS7341_F1DATAL 0x61
#define AS7341_F2DATAH 0x62
#define AS7341_F2DATAL 0x63
#define AS7341_F3DATAH 0x64
#define AS7341_F3DATAL 0x65
#define AS7341_F4DATAH 0x66
#define AS7341_F4DATAL 0x67
#define AS7341_F5DATAH 0x68
#define AS7341_F5DATAL 0x69
#define AS7341_F6DATAH 0x6A
#define AS7341_F6DATAL 0x6B
#define AS7341_F7DATAH 0x6C
#define AS7341_F7DATAL 0x6D
#define AS7341_F8DATAH 0x6E
#define AS7341_F8DATAL 0x6F
#define AS7341_CDATAH 0x70
#define AS7341_CDATAL 0x71
#define AS7341_NIRDATAH 0x72
#define AS7341_NIRDATAL 0x73

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int as7341_init(int fd);
int as7341_read_channels(int fd, uint16_t *channels);
float as7341_approximate_lux(uint16_t *channels);
int log_data(FILE *fp, uint16_t *channels, float lux);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// AS7341 initialization function
int as7341_init(int fd) {
    uint8_t who_am_i;
    uint8_t enable_value = 0x03; // PON | AEN
    uint8_t cfg6_value = 0x00; // SMUX = 0

    // Verify WHO_AM_I register
    if (i2c_read_reg(fd, AS7341_WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_reg(fd, AS7341_ENABLE, enable_value) != 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Configure SMUX
    if (i2c_write_reg(fd, AS7341_CFG6, cfg6_value) != 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        return -1;
    }

    return 0;
}

// AS7341 read channels function
int as7341_read_channels(int fd, uint16_t *channels) {
    uint8_t data[2];

    if (i2c_read_reg(fd, AS7341_F1DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F1 data\n");
        return -1;
    }
    channels[0] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F2DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F2 data\n");
        return -1;
    }
    channels[1] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F3DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F3 data\n");
        return -1;
    }
    channels[2] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F4DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F4 data\n");
        return -1;
    }
    channels[3] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F5DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F5 data\n");
        return -1;
    }
    channels[4] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F6DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F6 data\n");
        return -1;
    }
    channels[5] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F7DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F7 data\n");
        return -1;
    }
    channels[6] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_F8DATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading F8 data\n");
        return -1;
    }
    channels[7] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_CDATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading Clear data\n");
        return -1;
    }
    channels[8] = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_read_reg(fd, AS7341_NIRDATAH, data, 2) != 0) {
        fprintf(stderr, "Error reading NIR data\n");
        return -1;
    }
    channels[9] = (uint16_t)((data[0] << 8) | data[1]);

    return 0;
}

// AS7341 approximate lux calculation function
float as7341_approximate_lux(uint16_t *channels) {
    float lux = 0.0f;
    // Simplified approximation formula (replace with the actual formula from the datasheet)
    lux = (float)channels[0] * 0.1f + (float)channels[1] * 0.2f + (float)channels[2] * 0.3f + (float)channels[3] * 0.4f +
           (float)channels[4] * 0.5f + (float)channels[5] * 0.6f + (float)channels[6] * 0.7f + (float)channels[7] * 0.8f +
           (float)channels[8] * 0.9f + (float)channels[9] * 1.0f;

    return lux;
}

// Log data function
int log_data(FILE *fp, uint16_t *channels, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                timestamp, channels[0], channels[1], channels[2], channels[3],
                channels[4], channels[5], channels[6], channels[7], channels[8],
                channels[9], lux) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    uint16_t channels[10];
    float lux;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize AS7341 sensor
    if (as7341_init(i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read spectral channels
        if (as7341_read_channels(i2c_fd, channels) == 0) {
            // Approximate lux value
            lux = as7341_approximate_lux(channels);

            // Log data
            if (log_data(log_file, channels, lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read spectral channels\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

