#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1 // seconds
#define DEFAULT_FILENAME "seismic_data.csv"
#define D7S_REG_X_L 0x28
#define D7S_REG_X_H 0x29
#define D7S_REG_Y_L 0x2A
#define D7S_REG_Y_H 0x2B
#define D7S_REG_Z_L 0x2C
#define D7S_REG_Z_H 0x2D
#define D7S_REG_STATUS 0x20
#define D7S_REG_RESET 0x06
#define D7S_RESET_VALUE 0x01
#define D7S_RESET_DELAY_MS 100
#define D7S_G_PER_LSB 0.000244

// Global variables
static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(int handle, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
int reset_sensor(int handle);
int detect_sensor_absent(int handle);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // I2C bus 1
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Sensor reset function
int reset_sensor(int handle) {
    char buf[2];
    buf[0] = D7S_REG_RESET;
    buf[1] = D7S_RESET_VALUE;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error resetting sensor: %d\n", result);
        return -1;
    }
    gpioDelay(D7S_RESET_DELAY_MS * 1000); // Delay in microseconds
    return 0;
}

// Detect sensor absent function
int detect_sensor_absent(int handle) {
    char buf[1];
    buf[0] = D7S_REG_STATUS;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to status register for absent check: %d\n", result);
        return -1;
    }

    char status;
    result = i2cReadDevice(handle, &status, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading status register for absent check: %d\n", result);
        return -1;
    }

    // Check if the sensor is absent based on the status register value
    // This is a placeholder, replace with the actual status register and bit
    if ((status & 0x01) != 0) { // Example: Bit 0 indicates sensor presence
        return 0; // Sensor present
    } else {
        return -1; // Sensor absent
    }
}

// Read sensor data function
int read_sensor_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    buf[0] = D7S_REG_X_L;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to register for reading data: %d\n", result);
        return -1;
    }

    char data[6];
    result = i2cReadDevice(handle, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Convert raw data to g function
float convert_to_g(int16_t raw_value) {
    return raw_value * D7S_G_PER_LSB;
}

// Log data function
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%f,%f,%f\n", timestamp, convert_to_g(x), convert_to_g(y), convert_to_g(z)) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(i2c_address);
    if (i2c_handle < 0) {
        fprintf(error_file, "I2C initialization failed\n");
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    if (reset_sensor(i2c_handle) != 0) {
        fprintf(error_file, "Sensor reset failed\n");
        i2cClose(i2c_handle);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Detect sensor absence
    if (detect_sensor_absent(i2c_handle) < 0) {
        fprintf(error_file, "Sensor absent check failed\n");
        i2cClose(i2c_handle);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Open data log file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file\n");
        i2cClose(i2c_handle);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Write header to data file if it's a new file
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }
    fflush(data_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &x, &y, &z) == 0) {
            if (log_data(data_file, x, y, z) != 0) {
                fprintf(error_file, "Error logging data\n");
            }
        } else {
            fprintf(error_file, "Error reading sensor data\n");
        }
        sleep(interval);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(data_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

