#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define RETRY_DELAY 1 // seconds

int i2c_fd = -1;
int udp_socket = -1;

// Function to initialize the BH1750 sensor
int init_bh1750(int i2c_fd) {
    if (i2cWriteByteData(i2c_fd, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set BH1750 to continuous high-resolution mode.\n");
        return -1;
    }
    return 0;
}

// Function to read the raw lux value from the BH1750 sensor
int read_bh1750(int i2c_fd, unsigned short *raw_value) {
    char buf[2];
    if (i2cReadDevice(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data from BH1750.\n");
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert the raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char lux_str[20];
    snprintf(lux_str, sizeof(lux_str), "%.2f", lux_value);

    if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error: Failed to send UDP multicast packet.\n");
        return -1;
    }
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

