    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

