    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error: Could not create UDP socket.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set TTL for multicast
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error: Could not set TTL for multicast.\n");
        close(udp_socket);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        unsigned short raw_value;
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            float lux_value = convert_to_lux(raw_value);
            if (send_udp_multicast(lux_value) != 0) {
                fprintf(stderr, "Error: Failed to send UDP multicast.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read BH1750.\n");
        }

        sleep(1);
    }

    return 0;
}

