        return -1;
    }
    return bytes_read;
}

// Validate magic word
int validate_magic_word(const char *buffer, int size) {
    if (size < MAGIC_WORD_SIZE) return 0; // Not enough data

    uint64_t received_magic_word = 0;
    for (int i = 0; i < MAGIC_WORD_SIZE / 4; i++) {
        received_magic_word |= ((uint64_t)buffer[i * 4 + 3] << (i * 8));
        received_magic_word |= ((uint64_t)buffer[i * 4 + 2] << ((i * 8) + 8));
        received_magic_word |= ((uint64_t)buffer[i * 4 + 1] << ((i * 8) + 16));
