    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    char buffer[MAX_FRAME_SIZE];
    radar_data_t radar_data;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        int bytes_read = read_uart_data(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            // Attempt to parse the TLV data
            if (parse_tlv(buffer, bytes_read, &radar_data) == 0) {
