#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for signal handling
static volatile int running = 1;
static int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void check_emergency_stop(int left, int middle, int right);
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to check for an emergency stop condition
void check_emergency_stop(int left, int middle, int right) {
    if (left == 0 && middle == 0 && right == 0) {
        char emergency_stop_message[] = "EMERGENCY STOP!\n";
        if (serial_fd != -1) {
            if (write(serial_fd, emergency_stop_message, strlen(emergency_stop_message)) < 0) {
                fprintf(stderr, "Error writing to serial port: %m\n");
            }
        } else {
            fprintf(stderr, "Serial port not initialized. Cannot send emergency stop message.\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close the serial port if it's open
    if (serial_fd != -1) {
        close(serial_fd);
        serial_fd = -1;
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open the serial port
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %m\n", SERIAL_PORT);
        gpioTerminate();
        return 1;
    }

    // Configure the serial port
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %m\n");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;
    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %m\n");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_value, middle_value, right_value);

        // Check for emergency stop
        check_emergency_stop(left_value, middle_value, right_value);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close the serial port
    if (serial_fd != -1) {
        close(serial_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

